import { GoogleGenAI } from "@google/genai";

export async function generateAffiliateScript(params: {
  productUrl: string;
  quantity: number;
  style: string;
  length: string;
}) {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const prompt = `
    Buatkan ${params.quantity} script konten affiliate dalam Bahasa Indonesia untuk link produk: ${params.productUrl}.
    Gaya bahasa: ${params.style}.
    Panjang tulisan: ${params.length}.
    Output harus kreatif, menarik (hook yang kuat), dan mengandung call-to-action (CTA).
    Sertakan juga hashtag yang relevan.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
    });

    return response.text || "Gagal menghasilkan script.";
  } catch (error) {
    console.error("Gemini Error:", error);
    return "Terjadi kesalahan saat menghubungi AI.";
  }
}

import React, { useState, useEffect, useCallback } from 'react';
import { ModuleType, AppState, LedgerItem } from './types';
import { INITIAL_STATE, STAFF_LIST, OT_RATE } from './constants';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import AffiliateGenerator from './components/AffiliateGenerator';
import GoogleReviewModule from './components/GoogleReviewModule';
import OvertimeModule from './components/OvertimeModule';
import QAModule from './components/QAModule';
import ExpensesModule from './components/ExpensesModule';
import ReportingModule from './components/ReportingModule';
import GuestCommentModule from './components/GuestCommentModule';

const App: React.FC = () => {
  const [activeModule, setActiveModule] = useState<ModuleType>(ModuleType.AFFILIATE);
  const [data, setData] = useState<AppState>(INITIAL_STATE);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [filters, setFilters] = useState({
    month: new Date().getMonth().toString(),
    startDate: '',
    endDate: ''
  });

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen();
      setIsFullScreen(true);
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen();
        setIsFullScreen(false);
      }
    }
  };

  const updateData = (path: keyof AppState, newValue: any) => {
    setData(prev => ({ ...prev, [path]: newValue }));
  };

  const renderModule = () => {
    switch (activeModule) {
      case ModuleType.AFFILIATE:
        return <AffiliateGenerator />;
      case ModuleType.GOOGLE_REVIEW:
        return <GoogleReviewModule data={data.googleReview} onUpdate={(v) => updateData('googleReview', v)} />;
      case ModuleType.GUEST_COMMENT:
        return <GuestCommentModule data={data.guestComments} onUpdate={(v) => updateData('guestComments', v)} />;
      case ModuleType.OVERTIME:
        return <OvertimeModule data={data.overtime} onUpdate={(v) => updateData('overtime', v)} />;
      case ModuleType.QUALITY_ASSURANCE:
        return <QAModule data={data.qa} onUpdate={(v) => updateData('qa', v)} />;
      case ModuleType.EXPENSES:
      case ModuleType.LEDGERS:
        return <ExpensesModule data={data} onUpdate={setData} />;
      case ModuleType.REKAPAN:
        return <ReportingModule data={data} filters={filters} />;
      default:
        return <div className="p-8 text-center text-2xl">Pilih Modul dari Dashboard</div>;
    }
  };

  return (
    <div className="flex min-h-screen perspective-container overflow-hidden">
      {/* 3D Sidebar */}
      <Sidebar active={activeModule} onSelect={setActiveModule} />

      <div className="flex-1 flex flex-col overflow-hidden">
        <Header 
          isFullScreen={isFullScreen} 
          onToggleFS={toggleFullScreen} 
          filters={filters}
          onFilterChange={setFilters}
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8">
          <div className="max-w-7xl mx-auto">
            <div className="three-d-card transform-gpu">
              {renderModule()}
            </div>
          </div>
        </main>
      </div>

      {/* Background 3D effects */}
      <div className="fixed inset-0 pointer-events-none z-[-1] overflow-hidden">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-600/20 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-pink-600/20 blur-[120px] rounded-full"></div>
      </div>
    </div>
  );
};

export default App;

