import React, { useMemo } from 'react';
import { GoogleReviewData } from '../types';

interface Props {
  data: GoogleReviewData;
  onUpdate: (v: GoogleReviewData) => void;
}

const GoogleReviewModule: React.FC<Props> = ({ data, onUpdate }) => {
  const currentAvg = useMemo(() => {
    const totalPoints = (data.stars1 * 1) + (data.stars2 * 2) + (data.stars3 * 3) + (data.stars4 * 4) + (data.stars5 * 5);
    const totalVotes = data.stars1 + data.stars2 + data.stars3 + data.stars4 + data.stars5;
    return totalVotes === 0 ? 0 : (totalPoints / totalVotes).toFixed(2);
  }, [data]);

  const totalVotes = useMemo(() => {
    return data.stars1 + data.stars2 + data.stars3 + data.stars4 + data.stars5;
  }, [data]);

  const varianceToTarget = useMemo(() => {
    // How many 5 star reviews needed to reach Target Rating?
    // (TotalPoints + 5*x) / (TotalVotes + x) = Target
    // TotalPoints + 5x = Target*TotalVotes + Target*x
    // x(5 - Target) = Target*TotalVotes - TotalPoints
    // x = (Target*TotalVotes - TotalPoints) / (5 - Target)
    const target = Number(data.targetRating);
    const totalPoints = (data.stars1 * 1) + (data.stars2 * 2) + (data.stars3 * 3) + (data.stars4 * 4) + (data.stars5 * 5);
    const totalVotes = data.stars1 + data.stars2 + data.stars3 + data.stars4 + data.stars5;

    if (target <= Number(currentAvg)) return 0;
    if (target >= 5) return "Infinity (Nearly impossible if any non-5 exists)";

    const x = (target * totalVotes - totalPoints) / (5 - target);
    return Math.ceil(x);
  }, [data, currentAvg]);

  const handleStarChange = (star: keyof GoogleReviewData, val: string) => {
    const num = parseInt(val) || 0;
    onUpdate({ ...data, [star]: num });
  };

  return (
    <div className="space-y-6">
      <div className="glass-card p-6 border-l-4 border-yellow-500">
        <h2 className="text-xl font-bold mb-6 flex items-center gap-2">
          <i className="fab fa-google text-blue-400"></i>
          Google Review Performance
        </h2>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          <div className="space-y-4 col-span-2">
            <div className="grid grid-cols-2 sm:grid-cols-5 gap-4">
              {[5, 4, 3, 2, 1].map(num => (
                <div key={num} className="bg-slate-800/50 p-3 rounded-xl border border-white/5 text-center">
                  <div className="text-yellow-400 mb-1">
                    {Array.from({length: num}).map((_, i) => <i key={i} className="fas fa-star text-[10px]"></i>)}
                  </div>
                  <input 
                    type="number" 
                    className="w-full bg-slate-900 border border-white/10 rounded px-2 py-1 text-center outline-none"
                    value={(data as any)[`stars${num}`]}
                    onChange={(e) => handleStarChange(`stars${num}` as any, e.target.value)}
                  />
                  <div className="text-[10px] uppercase text-slate-500 mt-1 font-bold">Bintang {num}</div>
                </div>
              ))}
            </div>

            <div className="grid grid-cols-2 gap-4">
              <div className="p-4 rounded-xl bg-slate-800/30 border border-white/5">
                <label className="text-xs font-bold text-slate-500 uppercase">Target Rating</label>
                <input 
                  type="number" step="0.1" max="5" min="1"
                  className="block w-full text-2xl font-black bg-transparent border-none outline-none text-purple-400"
                  value={data.targetRating}
                  onChange={(e) => onUpdate({...data, targetRating: Number(e.target.value)})}
                />
              </div>
              <div className="p-4 rounded-xl bg-slate-800/30 border border-white/5">
                <label className="text-xs font-bold text-slate-500 uppercase">Total Review</label>
                <div className="text-2xl font-black text-white">{totalVotes}</div>
              </div>
            </div>
          </div>

          <div className="flex flex-col gap-4">
            <div className="flex-1 glass-card bg-purple-600/10 border-purple-500/30 flex flex-col items-center justify-center p-6 text-center">
              <div className="text-sm font-bold text-slate-400 uppercase mb-2">Rating Saat Ini</div>
              <div className="text-6xl font-black text-yellow-400 drop-shadow-lg">{currentAvg}</div>
              <div className="mt-4 text-xs text-slate-400 italic">Average rating dari input bintang</div>
            </div>

            <div className="p-4 rounded-xl mix-gradient-bg shadow-xl">
              <div className="text-xs font-bold text-white/70 uppercase">Variance to Target</div>
              <div className="text-xl font-black text-white">+{varianceToTarget} <span className="text-xs font-normal">Review Bintang 5</span></div>
              <p className="text-[10px] text-white/60 mt-2">Dibutuhkan untuk mencapai target {data.targetRating}</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

