import React from 'react';
import { OvertimeEntry } from '../types';
import { STAFF_LIST, OT_RATE } from '../constants';

interface Props {
  data: OvertimeEntry[];
  onUpdate: (v: OvertimeEntry[]) => void;
}

const OvertimeModule: React.FC<Props> = ({ data, onUpdate }) => {
  const handleChange = (staffId: string, field: keyof OvertimeEntry, val: number) => {
    const newData = data.map(item => 
      item.staffId === staffId ? { ...item, [field]: val } : item
    );
    onUpdate(newData);
  };

  const calculateTotalOT = (item: OvertimeEntry) => {
    const netHours = Math.max(0, item.hours - (item.break1 + item.break2));
    return netHours * OT_RATE;
  };

  const totalExpenses = data.reduce((acc, item) => acc + calculateTotalOT(item), 0);

  return (
    <div className="space-y-6">
      <div className="glass-card p-6 border-l-4 border-indigo-500">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <i className="fas fa-clock text-indigo-400"></i>
            Overtime Attendance Tracker
          </h2>
          <div className="text-right">
            <div className="text-xs font-bold text-slate-500 uppercase">Total Biaya OT</div>
            <div className="text-2xl font-black text-indigo-400">Rp {totalExpenses.toLocaleString()}</div>
          </div>
        </div>

        <div className="overflow-x-auto rounded-xl border border-white/10">
          <table className="w-full text-left border-collapse">
            <thead className="bg-slate-800/50 text-slate-400 text-xs uppercase font-bold">
              <tr>
                <th className="p-4">Staff Name</th>
                <th className="p-4 text-center">OT Hours</th>
                <th className="p-4 text-center">Break 1 (h)</th>
                <th className="p-4 text-center">Break 2 (h)</th>
                <th className="p-4 text-right">Total (IDR)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {STAFF_LIST.map((staff) => {
                const entry = data.find(d => d.staffId === staff.id) || { hours: 0, break1: 0, break2: 0 };
                return (
                  <tr key={staff.id} className="hover:bg-white/5 transition-colors">
                    <td className="p-4">
                      <div className="font-bold">{staff.name}</div>
                      <div className="text-[10px] text-slate-500">{staff.role}</div>
                    </td>
                    <td className="p-4">
                      <input 
                        type="number" 
                        className="w-20 mx-auto bg-slate-900 border border-white/10 rounded-lg p-2 text-center text-sm outline-none focus:ring-1 ring-indigo-500"
                        value={entry.hours}
                        onChange={(e) => handleChange(staff.id, 'hours', Number(e.target.value))}
                      />
                    </td>
                    <td className="p-4">
                      <input 
                        type="number" 
                        className="w-20 mx-auto bg-slate-900 border border-white/10 rounded-lg p-2 text-center text-sm outline-none focus:ring-1 ring-indigo-500"
                        value={entry.break1}
                        onChange={(e) => handleChange(staff.id, 'break1', Number(e.target.value))}
                      />
                    </td>
                    <td className="p-4">
                      <input 
                        type="number" 
                        className="w-20 mx-auto bg-slate-900 border border-white/10 rounded-lg p-2 text-center text-sm outline-none focus:ring-1 ring-indigo-500"
                        value={entry.break2}
                        onChange={(e) => handleChange(staff.id, 'break2', Number(e.target.value))}
                      />
                    </td>
                    <td className="p-4 text-right font-black text-white">
                      Rp {calculateTotalOT(entry as any).toLocaleString()}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

