import React from 'react';
import { QAData } from '../types';
import { QA_PASSING_SCORES } from '../constants';

interface Props {
  data: QAData;
  onUpdate: (v: QAData) => void;
}

const QAModule: React.FC<Props> = ({ data, onUpdate }) => {
  const calcAvg = (vals: number[]) => {
    return vals.length === 0 ? 0 : (vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(2);
  };

  const kAvg = Number(calcAvg([data.kitchen.product, data.kitchen.cleanliness, data.kitchen.grooming]));
  const bAvg = Number(calcAvg([data.bar.product, data.bar.cleanliness, data.bar.grooming]));
  const sAvg = Number(calcAvg([data.service.service, data.service.grooming, data.service.cleanliness]));
  const outletAvg = Number(calcAvg([kAvg, bAvg, sAvg]));

  const renderSection = (title: string, fields: any, section: keyof QAData, icon: string) => (
    <div className="glass-card p-4 space-y-4 border-t-2 border-purple-500/30">
      <h3 className="text-lg font-bold flex items-center gap-2 text-purple-300">
        <i className={`fas ${icon}`}></i> {title}
      </h3>
      <div className="space-y-3">
        {Object.keys(fields).map((field) => (
          <div key={field} className="flex items-center justify-between gap-4">
            <label className="text-xs font-bold uppercase text-slate-400 flex-1">{field.replace(/([A-Z])/g, ' $1')}</label>
            <div className="flex items-center gap-2">
              <input 
                type="number" max="100" min="0"
                className="w-20 bg-slate-900 border border-white/10 rounded p-1 text-right outline-none text-sm"
                value={(fields as any)[field]}
                onChange={(e) => {
                  const val = Number(e.target.value);
                  onUpdate({
                    ...data,
                    [section]: { ...data[section], [field]: val }
                  });
                }}
              />
              <span className="text-xs text-slate-500">%</span>
            </div>
          </div>
        ))}
      </div>
      <div className="pt-2 border-t border-white/5 flex justify-between items-center">
        <span className="text-xs font-black uppercase text-purple-400">Section Average</span>
        <span className="text-xl font-black text-white">{calcAvg(Object.values(fields))}%</span>
      </div>
    </div>
  );

  return (
    <div className="space-y-6">
      <div className="glass-card p-6 border-l-4 border-green-500">
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-xl font-bold flex items-center gap-2">
            <i className="fas fa-tasks text-green-400"></i>
            Quality Assurance Report
          </h2>
          <div className="px-4 py-1 rounded-full bg-slate-800 border border-white/10 text-[10px] font-bold text-slate-400 uppercase">
            Monthly Audit Score
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
          {renderSection('KITCHEN', data.kitchen, 'kitchen', 'fa-utensils')}
          {renderSection('BAR', data.bar, 'bar', 'fa-cocktail')}
          {renderSection('SERVICE', data.service, 'service', 'fa-concierge-bell')}
        </div>

        <div className="mt-8 glass-card bg-white/5 p-6 grid grid-cols-2 md:grid-cols-4 gap-4">
          <div className="text-center p-3 border-r border-white/10 last:border-0">
            <div className="text-xs font-bold text-slate-500 uppercase mb-1">Kitchen Score</div>
            <div className={`text-2xl font-black ${kAvg >= QA_PASSING_SCORES.kitchen ? 'text-green-400' : 'text-red-400'}`}>
              {kAvg}%
            </div>
            <div className="text-[10px] text-slate-600 mt-1">Passing: {QA_PASSING_SCORES.kitchen}%</div>
          </div>
          <div className="text-center p-3 border-r border-white/10 last:border-0">
            <div className="text-xs font-bold text-slate-500 uppercase mb-1">Bar Score</div>
            <div className={`text-2xl font-black ${bAvg >= QA_PASSING_SCORES.bar ? 'text-green-400' : 'text-red-400'}`}>
              {bAvg}%
            </div>
            <div className="text-[10px] text-slate-600 mt-1">Passing: {QA_PASSING_SCORES.bar}%</div>
          </div>
          <div className="text-center p-3 border-r border-white/10 last:border-0">
            <div className="text-xs font-bold text-slate-500 uppercase mb-1">Service Score</div>
            <div className={`text-2xl font-black ${sAvg >= QA_PASSING_SCORES.service ? 'text-green-400' : 'text-red-400'}`}>
              {sAvg}%
            </div>
            <div className="text-[10px] text-slate-600 mt-1">Passing: {QA_PASSING_SCORES.service}%</div>
          </div>
          <div className="text-center p-3 last:border-0 mix-gradient-bg rounded-xl">
            <div className="text-xs font-bold text-white/70 uppercase mb-1">Outlet Average</div>
            <div className="text-3xl font-black text-white">
              {outletAvg}%
            </div>
            <div className="text-[10px] text-white/50 mt-1">Overall Performance</div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default QAModule;

import React, { useState } from 'react';
import { AppState, LedgerItem } from '../types';

interface Props {
  data: AppState;
  onUpdate: (v: AppState) => void;
}

const ExpensesModule: React.FC<Props> = ({ data, onUpdate }) => {
  const [activeSub, setActiveSub] = useState<'OPEX' | 'CITY' | 'SAT' | 'COMP'>('OPEX');

  const updateLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', item: LedgerItem, index?: number) => {
    const newList = [...data[key]];
    if (index !== undefined) {
      newList[index] = item;
    } else {
      newList.push({ ...item, id: Date.now().toString() });
    }
    onUpdate({ ...data, [key]: newList });
  };

  const removeLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', index: number) => {
    const newList = data[key].filter((_, i) => i !== index);
    onUpdate({ ...data, [key]: newList });
  };

  const LedgerTable = ({ title, dataKey, icon }: { title: string, dataKey: 'cityLedger' | 'customerSat' | 'complimentary', icon: string }) => {
    const [newItem, setNewItem] = useState<Partial<LedgerItem>>({ name: '', qty: 0, price: 0, reason: '', pic: '' });

    return (
      <div className="space-y-4">
        <h3 className="text-lg font-bold flex items-center gap-2 text-pink-400">
          <i className={`fas ${icon}`}></i> {title}
        </h3>
        <div className="glass-card p-4 grid grid-cols-2 md:grid-cols-6 gap-3 items-end">
          <div className="col-span-2 md:col-span-1">
            <label className="text-[10px] font-bold text-slate-500 uppercase">Item Name</label>
            <input className="w-full bg-slate-800 border border-white/10 rounded p-1 text-xs" value={newItem.name} onChange={e => setNewItem({...newItem, name: e.target.value})} />
          </div>
          <div>
            <label className="text-[10px] font-bold text-slate-500 uppercase">Qty</label>
            <input type="number" className="w-full bg-slate-800 border border-white/10 rounded p-1 text-xs" value={newItem.qty} onChange={e => setNewItem({...newItem, qty: Number(e.target.value)})} />
          </div>
          <div>
            <label className="text-[10px] font-bold text-slate-500 uppercase">Price</label>
            <input type="number" className="w-full bg-slate-800 border border-white/10 rounded p-1 text-xs" value={newItem.price} onChange={e => setNewItem({...newItem, price: Number(e.target.value)})} />
          </div>
          <div className="col-span-2 md:col-span-1">
            <label className="text-[10px] font-bold text-slate-500 uppercase">Reason</label>
            <input className="w-full bg-slate-800 border border-white/10 rounded p-1 text-xs" value={newItem.reason} onChange={e => setNewItem({...newItem, reason: e.target.value})} />
          </div>
          <div>
            <label className="text-[10px] font-bold text-slate-500 uppercase">PIC</label>
            <input className="w-full bg-slate-800 border border-white/10 rounded p-1 text-xs" value={newItem.pic} onChange={e => setNewItem({...newItem, pic: e.target.value})} />
          </div>
          <button 
            onClick={() => {
              if (newItem.name) {
                updateLedger(dataKey, newItem as LedgerItem);
                setNewItem({ name: '', qty: 0, price: 0, reason: '', pic: '' });
              }
            }}
            className="bg-green-600 hover:bg-green-700 text-white p-1 rounded font-bold text-xs"
          >
            Tambah
          </button>
        </div>

        <div className="overflow-x-auto rounded-xl border border-white/10">
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-800/80 text-slate-500 font-black uppercase">
              <tr>
                <th className="p-3">Item</th>
                <th className="p-3 text-center">Qty</th>
                <th className="p-3 text-right">Price</th>
                <th className="p-3 text-right">Total</th>
                <th className="p-3">Reason</th>
                <th className="p-3">PIC</th>
                <th className="p-3"></th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
              {data[dataKey].map((item, idx) => (
                <tr key={idx} className="hover:bg-white/5">
                  <td className="p-3 font-bold">{item.name}</td>
                  <td className="p-3 text-center">{item.qty}</td>
                  <td className="p-3 text-right">{item.price.toLocaleString()}</td>
                  <td className="p-3 text-right font-black text-white">{(item.qty * item.price).toLocaleString()}</td>
                  <td className="p-3 italic text-slate-400">{item.reason}</td>
                  <td className="p-3 font-semibold text-purple-300">{item.pic}</td>
                  <td className="p-3 text-center">
                    <button onClick={() => removeLedger(dataKey, idx)} className="text-red-500 hover:scale-110"><i className="fas fa-trash"></i></button>
                  </td>
                </tr>
              ))}
              {data[dataKey].length === 0 && (
                <tr><td colSpan={7} className="p-8 text-center text-slate-600 italic">Belum ada data ledger</td></tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    );
  };

  const totalOpex = Object.values(data.expenses).reduce((a, b) => a + b, 0);

  return (
    <div className="space-y-6">
      <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
        {['OPEX', 'CITY', 'SAT', 'COMP'].map(tab => (
          <button 
            key={tab}
            onClick={() => setActiveSub(tab as any)}
            className={`px-6 py-2 rounded-xl font-bold whitespace-nowrap transition-all ${
              activeSub === tab ? 'purple-gradient-bg text-white shadow-lg' : 'bg-slate-800 text-slate-500'
            }`}
          >
            {tab === 'OPEX' ? 'Operational Expense' : 
             tab === 'CITY' ? 'City Ledger' : 
             tab === 'SAT' ? 'Cust. Satisfaction' : 'Complimentary'}
          </button>
        ))}
      </div>

      <div className="glass-card p-6 border-l-4 border-red-500">
        {activeSub === 'OPEX' && (
          <div className="space-y-6">
            <div className="flex justify-between items-center mb-4">
              <h2 className="text-xl font-bold">Monthly Operational Expenses</h2>
              <div className="text-right">
                <div className="text-xs text-slate-500 font-bold uppercase">Total Pengeluaran</div>
                <div className="text-3xl font-black text-red-500">Rp {totalOpex.toLocaleString()}</div>
              </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {Object.keys(data.expenses).map((key) => (
                <div key={key} className="p-4 rounded-xl bg-slate-800/50 border border-white/5">
                  <label className="block text-xs font-black text-slate-500 uppercase mb-2">
                    {key.replace(/([A-Z])/g, ' $1')} EXPENSE
                  </label>
                  <div className="flex items-center gap-2">
                    <span className="text-slate-600">Rp</span>
                    <input 
                      type="number"
                      className="flex-1 bg-transparent text-xl font-black outline-none text-white border-b border-white/10 focus:border-purple-500"
                      value={(data.expenses as any)[key]}
                      onChange={(e) => {
                        const val = Number(e.target.value);
                        onUpdate({ ...data, expenses: { ...data.expenses, [key]: val }});
                      }}
                    />
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}

        {activeSub === 'CITY' && <LedgerTable title="City Ledger Report" dataKey="cityLedger" icon="fa-building" />}
        {activeSub === 'SAT' && <LedgerTable title="Customer Satisfaction Bill" dataKey="customerSat" icon="fa-smile" />}
        {activeSub === 'COMP' && <LedgerTable title="Complimentary Bill" dataKey="complimentary" icon="fa-gift" />}
      </div>
    </div>
  );
};

export default ExpensesModule;

