           <div className="space-y-1">
              <div className="text-[10px] font-black text-slate-600 uppercase">Kitchen Score</div>
              <div className="flex items-center gap-2">
                 <div className="text-3xl font-black text-white">{kAvg}%</div>
                 <i className={`fas ${kAvg >= QA_PASSING_SCORES.kitchen ? 'fa-caret-up text-green-500' : 'fa-caret-down text-red-500'}`}></i>
