import React, { useState } from 'react';
import { AppState, LedgerItem } from '../types';

interface Props {
  data: AppState;
  onUpdate: (v: AppState) => void;
}

const ExpensesModule: React.FC<Props> = ({ data, onUpdate }) => {
  const [activeSub, setActiveSub] = useState<'OPEX' | 'CITY' | 'SAT' | 'COMP'>('OPEX');

  const updateLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', item: LedgerItem, index?: number) => {
    const newList = [...data[key]];
    if (index !== undefined) {
      newList[index] = item;
    } else {
      newList.push({ ...item, id: Date.now().toString() });
    }
    onUpdate({ ...data, [key]: newList });
  };

  const removeLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', index: number) => {
    const newList = data[key].filter((_, i) => i !== index);
    onUpdate({ ...data, [key]: newList });
  };

  const LedgerTable = ({ title, dataKey, icon, colorClass }: { title: string, dataKey: 'cityLedger' | 'customerSat' | 'complimentary', icon: string, colorClass: string }) => {
    const [newItem, setNewItem] = useState<Partial<LedgerItem>>({ name: '', qty: 1, price: 0, reason: '', pic: '' });

    const handleAdd = () => {
      if (newItem.name && newItem.price! > 0) {
        updateLedger(dataKey, newItem as LedgerItem);
        setNewItem({ name: '', qty: 1, price: 0, reason: '', pic: '' });
      } else {
        alert("Mohon isi Nama Item dan Harga.");
      }
    };

    return (
      <div className="space-y-6 animate-fade-in">
        <div className="flex justify-between items-center mb-2">
          <h3 className={`text-xl font-black flex items-center gap-3 uppercase tracking-tight ${colorClass}`}>
            <i className={`fas ${icon}`}></i> {title}
          </h3>
          <div className="text-[10px] font-black uppercase text-slate-500 bg-white/5 px-3 py-1 rounded-full border border-white/10">
            Total Entry: {data[dataKey].length}
          </div>
        </div>

        <div className="glass-card p-6 grid grid-cols-1 md:grid-cols-6 gap-4 items-end bg-slate-900/60 border-white/10">
          <div className="md:col-span-2">
            <label className="text-[10px] font-black text-slate-500 uppercase mb-2 block">Item Name</label>
            <input 
              placeholder="Contoh: Bill #12345"
              className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-sm font-bold focus:ring-2 ring-purple-500 outline-none" 
              value={newItem.name} 
              onChange={e => setNewItem({...newItem, name: e.target.value})} 
            />
          </div>
          <div>
            <label className="text-[10px] font-black text-slate-500 uppercase mb-2 block">Qty</label>
