import React, { useState } from 'react';
import { generateAffiliateScript } from '../services/geminiService';

interface Props {
  filters: { month: string; startDate: string; endDate: string };
}

const AffiliateGenerator: React.FC<Props> = ({ filters }) => {
  const [productUrl, setProductUrl] = useState('');
  const [quantity, setQuantity] = useState(3);
  const [style, setStyle] = useState('Casual & Trendy');
  const [length, setLength] = useState('Medium');
  const [result, setResult] = useState('');
  const [loading, setLoading] = useState(false);

  const handleGenerate = async () => {
    if (!productUrl) return alert('Mohon masukkan link produk terlebih dahulu.');
    setLoading(true);
    try {
      const script = await generateAffiliateScript({ productUrl, quantity, style, length });
      setResult(script);
    } catch (err) {
      alert("Terjadi kesalahan sistem saat memproses AI.");
    } finally {
      setLoading(false);
    }
  };

  const copyToClipboard = () => {
    if (!result) return;
    navigator.clipboard.writeText(result);
    alert('Konten berhasil disalin ke clipboard!');
  };

  return (
    <div className="space-y-6 animate-fade-in no-blur">
      <div className="glass-card p-8 border-l-4 border-purple-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <i className="fas fa-magic text-[180px]"></i>
        </div>

        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10 relative z-10">
          <div>
            <h2 className="text-3xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-4">
              <i className="fas fa-wand-magic-sparkles text-purple-400"></i>
              AI Affiliate Content
            </h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-widest">Generator Script Konten Kreatif Berbasis AI</p>
          </div>
          <div className="flex gap-2">
             <button onClick={() => window.print()} className="px-6 py-3 bg-slate-800 hover:bg-slate-700 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all border border-white/5 active:scale-95">
                <i className="fas fa-print mr-2"></i> Print Script
             </button>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-5 gap-8 relative z-10">
          <div className="lg:col-span-2 space-y-6">
            <div className="glass-card bg-slate-950/40 p-6 space-y-5 border-white/5 shadow-inner">
