                  <p className="font-black uppercase tracking-widest text-xs">Menunggu Input Produk...</p>
                </div>
              )}

              {result && (
                <button 
                  onClick={copyToClipboard}
                  className="absolute bottom-6 right-6 bg-purple-600 hover:bg-purple-500 text-white px-8 py-4 rounded-xl shadow-2xl transition-all active:scale-90 font-black text-xs uppercase tracking-widest flex items-center gap-3 border border-white/20"
                >
                  <i className="fas fa-copy"></i> Copy Script
