import React from 'react';
import { AppState } from '../types';
import { OT_RATE } from '../constants';

interface Props {
  data: AppState;
}

const YTDModule: React.FC<Props> = ({ data }) => {
  const months = [
    "Januari", "Februari", "Maret", "April", "Mei", "Juni",
    "Juli", "Agustus", "September", "Oktober", "November", "Desember"
  ];

  // Fungsi untuk menghitung data bulan berjalan secara real dari state
  const getCurrentMonthStats = () => {
    // 1. Google Rating
    const totalPoints = (data.googleReview.stars1 * 1) + (data.googleReview.stars2 * 2) + (data.googleReview.stars3 * 3) + (data.googleReview.stars4 * 4) + (data.googleReview.stars5 * 5);
    const totalVotes = data.googleReview.stars1 + data.googleReview.stars2 + data.googleReview.stars3 + data.googleReview.stars4 + data.googleReview.stars5;
    const currentRating = totalVotes === 0 ? data.googleReview.targetRating : (totalPoints / totalVotes);

    // 2. Expenses & Ledgers
    const opex = Object.values(data.expenses).reduce((a, b) => a + b, 0);
    const ledgers = [data.cityLedger, data.customerSat, data.complimentary].flat().reduce((a, b) => a + (b.qty * b.price), 0);

    // 3. Overtime
    const otCost = data.overtime.reduce((acc, item) => {
      const netHours = Math.max(0, item.hours - (item.break1 + item.break2));
      return acc + (netHours * OT_RATE);
    }, 0);

    // 4. Guest Comments
    const comments = data.guestComments.reduce((a, b) => a + b.achievement, 0);

    // 5. QA Score
    const kAvg = (data.qa.kitchen.product + data.qa.kitchen.cleanliness + data.qa.kitchen.grooming) / 3;
    const bAvg = (data.qa.bar.product + data.qa.bar.cleanliness + data.qa.bar.grooming) / 3;
    const sAvg = (data.qa.service.product + data.qa.service.cleanliness + data.qa.service.grooming) / 3;
    const qaScore = (kAvg + bAvg + sAvg) / 3;

    return {
      opex: opex + ledgers,
      ot: otCost,
      rating: Number(currentRating).toFixed(1),
      comments: comments,
      qa: Math.round(qaScore),
      status: 'Current'
    };
  };

  const getMockMonthlyStats = (monthIndex: number) => {
    const isCurrentMonth = monthIndex === new Date().getMonth();

    if (isCurrentMonth) {
       return getCurrentMonthStats();
    }

    const isPast = monthIndex < new Date().getMonth();
    const seed = monthIndex + 1;
    const randomFactor = 0.85 + (Math.sin(seed) * 0.15); // Deterministic "random" based on month

    return {
      opex: 18000000 * randomFactor,
      ot: 2200000 * randomFactor,
      rating: (4.4 + (Math.cos(seed) * 0.4)).toFixed(1),
      comments: Math.floor(25 * randomFactor),
      qa: Math.floor(88 + (Math.sin(seed) * 10)),
      status: isPast ? 'Completed' : 'Planned'
    };
  };

  const currentYear = new Date().getFullYear();

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      {/* Header Summary */}
      <div className="glass-card p-8 border-l-4 border-cyan-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <i className="fas fa-chart-line text-[200px]"></i>
        </div>

        <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
              <i className="fas fa-calendar-check text-cyan-400"></i>
              Year to Date Dashboard
            </h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em]">Pusat Pelaporan Performa Terintegrasi - {currentYear}</p>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
             <div className="bg-slate-950/80 px-5 py-3 rounded-2xl border border-white/5 shadow-xl">
                <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Avg QA</div>
                <div className="text-xl font-black text-emerald-400">92%</div>
             </div>
             <div className="bg-slate-950/80 px-5 py-3 rounded-2xl border border-white/5 shadow-xl">
                <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Total Comments</div>
                <div className="text-xl font-black text-pink-400">312</div>
             </div>
             <div className="bg-slate-950/80 px-5 py-3 rounded-2xl border border-white/5 shadow-xl">
                <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Total OT YTD</div>
                <div className="text-xl font-black text-blue-400">Rp 24M</div>
             </div>
             <div className="bg-slate-950/80 px-5 py-3 rounded-2xl border border-white/5 shadow-xl">
                <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Global Rating</div>
                <div className="text-xl font-black text-yellow-400">4.9 ★</div>
             </div>
          </div>
        </div>
      </div>

      {/* Monthly Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {months.map((month, index) => {
          const stats = getMockMonthlyStats(index);
          const isCurrent = stats.status === 'Current';
          const isPlanned = stats.status === 'Planned';

          return (
