      ot: 2200000 * randomFactor,
      rating: (4.4 + (Math.cos(seed) * 0.4)).toFixed(1),
      comments: Math.floor(25 * randomFactor),
      qa: Math.floor(88 + (Math.sin(seed) * 10)),
      qaBreakdown: {
        kitchen: Math.floor(85 + (Math.sin(seed) * 5)),
        bar: Math.floor(90 + (Math.cos(seed) * 5)),
        service: Math.floor(92 + (Math.sin(seed) * 3))
