import React from 'react';
import { QAData } from '../types';
import { QA_PASSING_SCORES } from '../constants';

interface Props {
  data: QAData;
  onUpdate: (v: QAData) => void;
}

const QAModule: React.FC<Props> = ({ data, onUpdate }) => {
  const calcAvg = (vals: number[]) => {
    return vals.length === 0 ? "0.00" : (vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(2);
  };

  const kAvg = calcAvg([data.kitchen.product, data.kitchen.cleanliness, data.kitchen.grooming]);
  const bAvg = calcAvg([data.bar.product, data.bar.cleanliness, data.bar.grooming]);
  const sAvg = calcAvg([data.service.product, data.service.grooming, data.service.cleanliness]);
  const outletAvg = calcAvg([Number(kAvg), Number(bAvg), Number(sAvg)]);

  const renderSection = (title: string, fields: any, section: keyof QAData, icon: string, color: string) => (
    <div className={`glass-card p-5 space-y-5 border-t-4 ${color}`}>
      <h3 className="text-lg font-black flex items-center gap-3 text-white">
        <i className={`fas ${icon}`}></i> {title}
      </h3>
      <div className="space-y-4">
        {Object.keys(fields).map((field) => (
          <div key={field} className="space-y-1">
            <div className="flex justify-between items-center px-1">
               <label className="text-[10px] font-black uppercase text-slate-500">
                  {field === 'product' ? (section === 'service' ? 'Quality Service' : 'Quality Product') : field}
               </label>
               <span className="text-xs font-black text-slate-400">{Number((fields as any)[field]).toFixed(2)}%</span>
            </div>
            <div className="flex items-center gap-3">
              <input 
                type="range" max="100" min="0" step="1"
                className="flex-1 h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-purple-500"
                value={(fields as any)[field]}
                onChange={(e) => {
                  const val = Number(e.target.value);
                  onUpdate({
                    ...data,
                    [section]: { ...data[section], [field]: val }
                  });
                }}
              />
              <input 
                type="number" 
                className="w-14 bg-slate-900 border border-white/10 rounded p-1 text-right outline-none text-[10px] font-bold"
                value={(fields as any)[field]}
                onChange={(e) => {
                   const val = Math.min(100, Math.max(0, Number(e.target.value)));
                   onUpdate({ ...data, [section]: { ...data[section], [field]: val } });
                }}
              />
            </div>
          </div>
        ))}
      </div>
      <div className="pt-4 border-t border-white/5 flex justify-between items-center">
        <div className="text-[10px] font-black uppercase text-slate-500">Section Average</div>
        <div className="text-2xl font-black text-white">{calcAvg(Object.values(fields))}%</div>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in">
      <div className="flex flex-col md:flex-row justify-between items-center gap-4">
         <div>
            <h2 className="text-2xl font-black flex items-center gap-3">
               <i className="fas fa-clipboard-check text-emerald-400"></i>
               Quality Assurance Audit
            </h2>
            <p className="text-slate-500 text-xs font-bold uppercase tracking-wider">Pass standard monitoring & performance assessment</p>
         </div>
         <div className="mix-gradient-bg p-4 rounded-2xl shadow-xl flex items-center gap-4">
            <div className="text-right">
               <div className="text-[10px] font-black uppercase text-white/70">Outlet Score Average</div>
               <div className="text-3xl font-black text-white">{outletAvg}%</div>
            </div>
            <div className="h-12 w-px bg-white/20"></div>
            <div className={`w-14 h-14 rounded-xl flex items-center justify-center font-black text-xl shadow-inner ${Number(outletAvg) >= 90 ? 'bg-green-500/30' : 'bg-red-500/30'}`}>
               {Number(outletAvg) >= 90 ? 'PASS' : 'FAIL'}
            </div>
         </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {renderSection('KITCHEN', data.kitchen, 'kitchen', 'fa-fire-alt', 'border-orange-500')}
        {renderSection('BAR', data.bar, 'bar', 'fa-glass-martini-alt', 'border-blue-500')}
        {renderSection('SERVICE', data.service, 'service', 'fa-hand-sparkles', 'border-pink-500')}
      </div>

      <div className="glass-card p-8 bg-slate-950/40 relative overflow-hidden">
        <div className="absolute top-0 left-0 w-2 h-full bg-emerald-500"></div>
        <h3 className="text-sm font-black uppercase text-slate-500 mb-6 flex items-center gap-2">
           <i className="fas fa-chart-line text-emerald-500"></i> Monthly Outlet Performance actual input
        </h3>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
           <div className="space-y-1">
              <div className="text-[10px] font-black text-slate-600 uppercase">Kitchen Score</div>
              <div className="flex items-center gap-2">
                 <div className="text-3xl font-black text-white">{kAvg}%</div>
                 <i className={`fas ${Number(kAvg) >= QA_PASSING_SCORES.kitchen ? 'fa-caret-up text-green-500' : 'fa-caret-down text-red-500'}`}></i>
              </div>
              <div className="text-[9px] font-bold text-slate-700 uppercase">Target: {QA_PASSING_SCORES.kitchen.toFixed(2)}%</div>
           </div>
           <div className="space-y-1">
              <div className="text-[10px] font-black text-slate-600 uppercase">Bar Score</div>
              <div className="flex items-center gap-2">
                 <div className="text-3xl font-black text-white">{bAvg}%</div>
                 <i className={`fas ${Number(bAvg) >= QA_PASSING_SCORES.bar ? 'fa-caret-up text-green-500' : 'fa-caret-down text-red-500'}`}></i>
              </div>
              <div className="text-[9px] font-bold text-slate-700 uppercase">Target: {QA_PASSING_SCORES.bar.toFixed(2)}%</div>
           </div>
           <div className="space-y-1">
              <div className="text-[10px] font-black text-slate-600 uppercase">Service Score</div>
              <div className="flex items-center gap-2">
                 <div className="text-3xl font-black text-white">{sAvg}%</div>
                 <i className={`fas ${Number(sAvg) >= QA_PASSING_SCORES.service ? 'fa-caret-up text-green-500' : 'fa-caret-down text-red-500'}`}></i>
              </div>
              <div className="text-[9px] font-bold text-slate-700 uppercase">Target: {QA_PASSING_SCORES.service.toFixed(2)}%</div>
           </div>
           <div className="space-y-1">
              <div className="text-[10px] font-black text-slate-600 uppercase">Overall Avg (K,B,S)</div>
              <div className="text-3xl font-black text-emerald-400">{outletAvg}%</div>
              <div className="text-[9px] font-bold text-slate-700 uppercase">Calculated actual</div>
           </div>
        </div>
      </div>
    </div>
  );
};

