                    style={{ height: `${Math.max(5, height)}%` }}
                  >
                    {isCurrent && <div className={`absolute -top-1 left-1/2 -translate-x-1/2 w-2 h-2 rounded-full ${activeColor} animate-ping`}></div>}
                  </div>
