                  <span className={`text-2xl font-black uppercase tracking-tighter ${isCurrent ? 'text-cyan-400' : 'text-white'}`}>{month}</span>
                </div>
                <div className={`text-[8px] font-black px-3 py-1 rounded-full uppercase tracking-tighter border ${
                  isCurrent ? 'bg-cyan-500 text-white border-cyan-400' : 
                  isNoData ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-slate-800 text-slate-500 border-white/5'
                }`}>{stats.status}</div>
              </div>
              <div className={`space-y-3.5 ${isNoData ? 'opacity-30' : ''}`}>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-wallet text-red-500 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Total Expenses</span></div><span className="text-xs font-black text-white">Rp {Math.floor(stats.opex).toLocaleString()}</span></div>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-clock text-blue-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Overtime Cost</span></div><span className="text-xs font-black text-blue-400">Rp {Math.floor(stats.ot).toLocaleString()}</span></div>
                <div className="space-y-1.5"><div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-clipboard-check text-emerald-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Audit QA Score</span></div><span className="text-xs font-black text-emerald-400">{stats.qa}%</span></div><div className="h-1 bg-slate-900 rounded-full overflow-hidden"><div className={`h-full transition-all duration-1000 ${Number(stats.qa) >= 90 ? 'bg-emerald-500' : 'bg-orange-500'}`} style={{ width: `${stats.qa}%` }}></div></div></div>
                <div className="grid grid-cols-2 gap-4 mt-2">
                  <div className="p-2.5 rounded-xl bg-slate-950/50 border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Rating</div><div className="text-sm font-black text-yellow-400">{stats.rating} ★</div></div>
                  <div className="p-2.5 rounded-xl bg-slate-950/50 border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Comments</div><div className="text-sm font-black text-pink-400">{stats.comments}</div></div>
                </div>
              </div>
              <div className="mt-6 pt-4 border-t border-white/5 flex justify-end items-center">
                <button onClick={() => setSelectedMonth(index)} className="text-[9px] font-black uppercase tracking-widest text-slate-500 hover:text-cyan-400 transition-colors flex items-center gap-2">{isNoData ? 'Check Month' : 'Full Report'} <i className="fas fa-arrow-right text-[8px]"></i></button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

