}

const YTDModule: React.FC<Props> = ({ data }) => {
  const [selectedMonth, setSelectedMonth] = useState<number | null>(null);
  const [activeTrend, setActiveTrend] = useState<'OPEX' | 'QA' | 'RATING' | 'SALES'>('SALES');

  const months = [
    "Januari", "Februari", "Maret", "April", "Mei", "Juni",
    "Juli", "Agustus", "September", "Oktober", "November", "Desember"
  ];

  const getCurrentMonthStats = () => {
    const totalPoints = (data.googleReview.stars1 * 1) + (data.googleReview.stars2 * 2) + (data.googleReview.stars3 * 3) + (data.googleReview.stars4 * 4) + (data.googleReview.stars5 * 5);
    const totalVotes = data.googleReview.stars1 + data.googleReview.stars2 + data.googleReview.stars3 + data.googleReview.stars4 + data.googleReview.stars5;
    const currentRating = totalVotes === 0 ? "0.0" : (totalPoints / totalVotes).toFixed(1);

    const opex = Object.values(data.expenses).reduce((a, b) => a + b, 0);
    const ledgers = [data.cityLedger, data.customerSat, data.complimentary].flat().reduce((a, b) => a + (b.qty * b.price), 0);

    const otCost = data.overtime.reduce((acc, item) => {
      const netHours = Math.max(0, item.hours - (item.break1 + item.break2));
      return acc + (netHours * OT_RATE);
    }, 0);

    const comments = data.guestComments.reduce((a, b) => a + b.achievement, 0);

    const kAvg = (data.qa.kitchen.product + data.qa.kitchen.cleanliness + data.qa.kitchen.grooming) / 3;
    const bAvg = (data.qa.bar.product + data.qa.bar.cleanliness + data.qa.bar.grooming) / 3;
    const sAvg = (data.qa.service.product + data.qa.service.cleanliness + data.qa.service.grooming) / 3;
    const qaScore = (kAvg + bAvg + sAvg) / 3;

    return {
      sales: data.sales.revenue,
      covers: data.sales.covers,
      opex: opex + ledgers,
      opexBreakdown: data.expenses,
      ot: otCost,
      rating: currentRating,
      comments: comments,
      qa: qaScore.toFixed(2),
      qaBreakdown: {
        kitchen: kAvg.toFixed(2),
        bar: bAvg.toFixed(2),
        service: sAvg.toFixed(2)
      },
      status: 'Current'
    };
  };

  const getMonthlyStats = (monthIndex: number) => {
    const isCurrentMonth = monthIndex === new Date().getMonth();
    if (isCurrentMonth) return getCurrentMonthStats();

    const isPast = monthIndex < new Date().getMonth();
    return {
      sales: 0,
      covers: 0,
      opex: 0,
      opexBreakdown: { nonCommodity: 0, commodity: 0, maintenance: 0, asset: 0, casual: 0 },
      ot: 0,
      rating: "0.0",
      comments: 0,
      qa: "0.00",
      qaBreakdown: { kitchen: "0.00", bar: "0.00", service: "0.00" },
      status: isPast ? 'No Data' : 'Planned'
    };
  };

  const currentYear = new Date().getFullYear();
  const ytdStats = getCurrentMonthStats();
  const trendData = months.map((_, i) => getMonthlyStats(i));
  const maxOpex = Math.max(...trendData.map(d => d.opex), 1000000);
  const maxSales = Math.max(...trendData.map(d => d.sales), 1000000);

  if (selectedMonth !== null) {
    const stats = getMonthlyStats(selectedMonth);
    const avgCheck = stats.covers > 0 ? Math.floor(stats.sales / stats.covers) : 0;
    return (
      <div className="space-y-6 animate-fade-in no-blur">
        <div className="flex items-center justify-between glass-card p-6 border-l-4 border-cyan-500 bg-slate-900/90">
          <div className="flex items-center gap-6">
            <button 
              onClick={() => setSelectedMonth(null)}
              className="w-12 h-12 rounded-2xl bg-slate-800 hover:bg-slate-700 text-white flex items-center justify-center transition-all active:scale-90 border border-white/5"
            >
              <i className="fas fa-arrow-left"></i>
            </button>
            <div>
              <h2 className="text-3xl font-black text-white uppercase tracking-tighter leading-none">
                Detail Laporan: {months[selectedMonth]} {currentYear}
              </h2>
              <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-widest">Analisis Performa Mendalam Sesuai Modul</p>
            </div>
          </div>
          <div className={`px-6 py-2 rounded-xl text-xs font-black uppercase border ${
            stats.status === 'Current' ? 'bg-cyan-500 text-white border-cyan-400' : 
            stats.status === 'No Data' ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-slate-800 text-slate-400 border-white/5'
          }`}>
            {stats.status}
          </div>
        </div>

        {stats.opex === 0 && stats.qa === "0.00" && stats.status !== 'Current' ? (
          <div className="glass-card p-20 flex flex-col items-center justify-center text-center space-y-4 opacity-40">
            <i className="fas fa-folder-open text-6xl text-slate-700"></i>
            <h3 className="text-xl font-black text-white uppercase tracking-widest">Belum Ada Data Terinput</h3>
            <p className="text-xs text-slate-500 font-bold max-w-sm uppercase">Data untuk bulan {months[selectedMonth]} belum tersedia di sistem.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="glass-card p-8 border-t-2 border-emerald-500 bg-slate-900/60 flex flex-col justify-between">
              <div>
                <h3 className="text-sm font-black uppercase text-white mb-6 flex items-center gap-3">
                  <i className="fas fa-cash-register text-emerald-500"></i> Monthly Sales Summary
                </h3>
                <div className="space-y-4 text-xs font-bold border-white/5 pb-2">
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Total Revenue</span>
                      <span className="text-white">Rp {stats.sales.toLocaleString()}</span>
                   </div>
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Total Pax (Covers)</span>
                      <span className="text-white">{stats.covers} Pax</span>
                   </div>
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Average Check</span>
                      <span className="text-indigo-400">Rp {avgCheck.toLocaleString()}</span>
                   </div>
                </div>
              </div>
            </div>

            <div className="glass-card p-8 border-t-2 border-red-500 bg-slate-900/60">
              <h3 className="text-sm font-black uppercase text-white mb-6 flex items-center gap-3">
                <i className="fas fa-wallet text-red-500"></i> Expense & Audit
              </h3>
              <div className="space-y-4">
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">Opex Summary</span>
                    <span className="text-white">Rp {stats.opex.toLocaleString()}</span>
                 </div>
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">QA Score Avg</span>
                    <span className="text-emerald-400">{stats.qa}%</span>
                 </div>
              </div>
            </div>

            <div className="space-y-6">
              <div className="glass-card p-8 border-t-2 border-yellow-500 bg-slate-900/60">
                <h3 className="text-sm font-black uppercase text-white mb-4 flex items-center gap-3">
                  <i className="fab fa-google text-yellow-500"></i> Sentiment
                </h3>
                <div className="flex items-center gap-6">
                  <div className="text-5xl font-black text-yellow-400">{stats.rating} ★</div>
                </div>
              </div>
              <button className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase tracking-[0.2em] text-xs transition-all shadow-2xl active:scale-95 border border-white/10">
                <i className="fas fa-download mr-2"></i> Export Monthly PDF
              </button>
            </div>
          </div>
        )}
      </div>
    );
  }

  return (
