           </div>
           <div className="flex bg-slate-950/60 p-1.5 rounded-2xl border border-white/5 gap-2">
              {[
                { id: 'SALES', label: 'Revenue', icon: 'fa-cash-register' },
                { id: 'OPEX', label: 'Expenses', icon: 'fa-wallet' },
                { id: 'QA', label: 'Quality', icon: 'fa-clipboard-check' },
                { id: 'RATING', label: 'Rating', icon: 'fa-star' }
              ].map(tab => (
                <button 
                  key={tab.id}
                  onClick={() => setActiveTrend(tab.id as any)}
                  className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-3 ${
                    activeTrend === tab.id ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-white'
                  }`}
                >
                  <i className={`fas ${tab.icon}`}></i> {tab.label}
                </button>
              ))}
           </div>
        </div>

        <div className="h-64 flex items-end gap-3 md:gap-6 px-4 relative">
           <div className="absolute inset-0 flex flex-col justify-between pointer-events-none opacity-5 py-2">
              {[1,2,3,4].map(i => <div key={i} className="border-t border-white w-full"></div>)}
           </div>

           {trendData.map((stats, i) => {
             let height = 0;
             let label = "";
             let activeColor = "bg-indigo-500";

             if (activeTrend === 'SALES') {
                height = (stats.sales / maxSales) * 100;
                label = `Rp ${Math.round(stats.sales/1000000)}M`;
                activeColor = "bg-emerald-500";
             } else if (activeTrend === 'OPEX') {
               height = (stats.opex / maxOpex) * 100;
               label = `Rp ${Math.round(stats.opex/1000000)}M`;
               activeColor = "bg-red-500";
             } else if (activeTrend === 'QA') {
               height = Number(stats.qa);
               label = `${stats.qa}%`;
               activeColor = "bg-white";
             } else {
               height = (Number(stats.rating) / 5) * 100;
               label = `${stats.rating} ★`;
               activeColor = "bg-yellow-500";
