                    className={`w-full rounded-t-xl transition-all duration-1000 origin-bottom group-hover:scale-x-110 ${isCurrent ? `${activeColor} shadow-[0_0_30px_rgba(0,0,0,0.3)] ring-4 ring-white/10` : 'bg-slate-800/40 hover:bg-slate-700'}`}
                    style={{ height: `${Math.max(5, height)}%` }}
                  ></div>
                  <span className={`text-[9px] font-black uppercase tracking-tighter ${isCurrent ? 'text-white' : 'text-slate-600'}`}>
                    {months[i].substring(0, 3)}
                  </span>
               </div>
             );
           })}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {months.map((month, index) => {
          const stats = getMonthlyStats(index);
          const isCurrent = stats.status === 'Current';
          const isNoData = stats.status === 'No Data';

          return (
            <div 
              key={month} 
              className={`glass-card p-6 flex flex-col justify-between h-[340px] transition-all group border-white/10 relative overflow-hidden ${
                isCurrent ? 'ring-2 ring-cyan-500 border-transparent bg-cyan-900/10' : 
                isNoData ? 'opacity-50 grayscale-[0.5]' : 'hover:border-cyan-500/50 hover:-translate-y-1'
