import React, { useState, useCallback, useEffect } from 'react';
import { ModuleType, AppState } from './types';
import { INITIAL_STATE } from './constants';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import GoogleReviewModule from './components/GoogleReviewModule';
import OvertimeModule from './components/OvertimeModule';
import QAModule from './components/QAModule';
import ExpensesModule from './components/ExpensesModule';
import ReportingModule from './components/ReportingModule';
import GuestCommentModule from './components/GuestCommentModule';
import YTDModule from './components/YTDModule';
import SalesModule from './components/SalesModule';

const App: React.FC = () => {
  const [activeModule, setActiveModule] = useState<ModuleType>(ModuleType.DASHBOARD);
  const [data, setData] = useState<AppState>(INITIAL_STATE);
  const [isFullScreen, setIsFullScreen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [filters, setFilters] = useState({
    month: new Date().getMonth().toString(),
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0]
  });

  // Auto Refresh Logic when filters change
  useEffect(() => {
    setIsRefreshing(true);
    // Simulate fetching data for the new selected period
    const timer = setTimeout(() => {
      // In a real app, we would fetch data from an API here based on filters
      // For this demo, we reset to INITIAL_STATE to simulate a "new/empty" period context
      setData(INITIAL_STATE);
      setIsRefreshing(false);
    }, 600);
    return () => clearTimeout(timer);
  }, [filters.month, filters.startDate, filters.endDate]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().then(() => setIsFullScreen(true)).catch(e => console.error(e));
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen().then(() => setIsFullScreen(false));
      }
    }
  };

  const updateData = useCallback((path: keyof AppState, newValue: any) => {
    setData(prev => ({ ...prev, [path]: newValue }));
  }, []);

  const renderModule = () => {
    if (isRefreshing) {
      return (
        <div className="h-[60vh] flex flex-col items-center justify-center space-y-4 animate-pulse">
           <div className="w-16 h-16 border-4 border-purple-500/20 border-t-purple-500 rounded-full animate-spin"></div>
           <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Syncing Data for Selected Period...</p>
        </div>
      );
    }

    switch (activeModule) {
      case ModuleType.DASHBOARD:
        return <Dashboard onSelect={setActiveModule} />;
      case ModuleType.SALES:
        return <SalesModule data={data.sales} onUpdate={(v) => updateData('sales', v)} />;
      case ModuleType.GOOGLE_REVIEW:
        return <GoogleReviewModule data={data.googleReview} onUpdate={(v) => updateData('googleReview', v)} />;
      case ModuleType.GUEST_COMMENT:
        return <GuestCommentModule data={data.guestComments} onUpdate={(v) => updateData('guestComments', v)} />;
      case ModuleType.OVERTIME:
        return <OvertimeModule data={data.overtime} onUpdate={(v) => updateData('overtime', v)} />;
      case ModuleType.QUALITY_ASSURANCE:
        return <QAModule data={data.qa} onUpdate={(v) => updateData('qa', v)} />;
      case ModuleType.EXPENSES:
        return <ExpensesModule data={data} onUpdate={setData} />;
      case ModuleType.YTD_REPORT:
        return <YTDModule data={data} />;
      case ModuleType.REKAPAN:
        return <ReportingModule data={data} filters={filters} />;
      default:
        return <Dashboard onSelect={setActiveModule} />;
    }
  };

  return (
    <div className="flex min-h-screen perspective-container overflow-hidden bg-[#0f172a]">
      <Sidebar active={activeModule} onSelect={setActiveModule} />

      <div className="flex-1 flex flex-col overflow-hidden relative">
        <Header 
          isFullScreen={isFullScreen} 
          onToggleFS={toggleFullScreen} 
          filters={filters}
          onFilterChange={setFilters}
          onHome={() => setActiveModule(ModuleType.DASHBOARD)}
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto">
            <div className="animate-fade-in">
              {renderModule()}
            </div>
          </div>
        </main>
      </div>

      <div className="fixed inset-0 pointer-events-none z-[-1] overflow-hidden">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-900/10 rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-pink-900/10 rounded-full"></div>
      </div>
    </div>
  );
};

export default App;

import React, { useMemo, useState } from 'react';
import { GoogleReviewData } from '../types';

interface Props {
  data: GoogleReviewData;
  onUpdate: (v: GoogleReviewData) => void;
}

const GoogleReviewModule: React.FC<Props> = ({ data, onUpdate }) => {
  const [isSaving, setIsSaving] = useState(false);

  const currentAvg = useMemo(() => {
    const totalPoints = (data.stars1 * 1) + (data.stars2 * 2) + (data.stars3 * 3) + (data.stars4 * 4) + (data.stars5 * 5);
    const totalVotes = data.stars1 + data.stars2 + data.stars3 + data.stars4 + data.stars5;
    return totalVotes === 0 ? 0 : (totalPoints / totalVotes).toFixed(2);
  }, [data]);

  const totalVotes = useMemo(() => {
    return data.stars1 + data.stars2 + data.stars3 + data.stars4 + data.stars5;
  }, [data]);

  const varianceToTarget = useMemo(() => {
    const target = Number(data.targetRating);
    const totalPoints = (data.stars1 * 1) + (data.stars2 * 2) + (data.stars3 * 3) + (data.stars4 * 4) + (data.stars5 * 5);
    const totalVotes = data.stars1 + data.stars2 + data.stars3 + data.stars4 + data.stars5;

    if (target <= Number(currentAvg)) return 0;
    if (target >= 5) return "Infinity";

    const x = (target * totalVotes - totalPoints) / (5 - target);
    return Math.ceil(x);
  }, [data, currentAvg]);

  const handleStarChange = (star: keyof GoogleReviewData, val: string) => {
    const num = parseInt(val) || 0;
    onUpdate({ ...data, [star]: num });
  };

  const handleSubmit = () => {
    setIsSaving(true);
    setTimeout(() => setIsSaving(false), 1000);
  };

  return (
    <div className="space-y-6 animate-fade-in no-blur">
      <div className="glass-card p-8 border-l-4 border-yellow-500 bg-[#1e293b]/95 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <i className="fab fa-google text-[180px]"></i>
        </div>

        <div className="flex justify-between items-center mb-10 relative z-10">
          <h2 className="text-3xl font-black text-white uppercase tracking-tighter flex items-center gap-4 leading-none">
            <i className="fab fa-google text-yellow-500"></i>
            Google Review Performance
          </h2>
          <div className="px-4 py-2 rounded-xl bg-slate-950/80 border border-white/5 text-[10px] font-black uppercase text-slate-500 tracking-widest">
             Live Sync Enabled
          </div>
