  const sAvg = calcAvg([data.service.product, data.service.grooming, data.service.cleanliness]);
  const outletAvg = calcAvg([Number(kAvg), Number(bAvg), Number(sAvg)]);

  const handleSubmit = () => {
    setIsSaving(true);
