import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { ModuleType, AppState } from './types';
import { INITIAL_STATE } from './constants';
import Sidebar from './components/Sidebar';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import GoogleReviewModule from './components/GoogleReviewModule';
import OvertimeModule from './components/OvertimeModule';
import QAModule from './components/QAModule';
import ExpensesModule from './components/ExpensesModule';
import ReportingModule from './components/ReportingModule';
import GuestCommentModule from './components/GuestCommentModule';
import YTDModule from './components/YTDModule';
import SalesModule from './components/SalesModule';

const App: React.FC = () => {
  const [activeModule, setActiveModule] = useState<ModuleType>(ModuleType.DASHBOARD);
  // Store data for each month separately to allow "isi susulan"
  const [monthlyData, setMonthlyData] = useState<Record<string, AppState>>({
    [new Date().getMonth().toString()]: INITIAL_STATE
  });

  const [isFullScreen, setIsFullScreen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [filters, setFilters] = useState({
    month: new Date().getMonth().toString(),
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0]
  });

  // Get current active data based on filter, or INITIAL_STATE if month hasn't been accessed yet
  const currentData = useMemo(() => {
    return monthlyData[filters.month] || INITIAL_STATE;
  }, [monthlyData, filters.month]);

  // Auto Refresh UI when filters change
  useEffect(() => {
    setIsRefreshing(true);
    const timer = setTimeout(() => {
      setIsRefreshing(false);
    }, 400);
    return () => clearTimeout(timer);
  }, [filters.month, filters.startDate, filters.endDate]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().then(() => setIsFullScreen(true)).catch(e => console.error(e));
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen().then(() => setIsFullScreen(false));
      }
    }
  };

  const updateCurrentData = useCallback((path: keyof AppState, newValue: any) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: {
          ...currentMonthBase,
          [path]: newValue
        }
      };
    });
  }, [filters.month]);

  const updateFullState = useCallback((updater: (prev: AppState) => AppState) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: updater(currentMonthBase)
      };
    });
  }, [filters.month]);

  const renderModule = () => {
    if (isRefreshing) {
      return (
        <div className="h-[60vh] flex flex-col items-center justify-center space-y-4 animate-pulse">
           <div className="w-16 h-16 border-4 border-purple-500/20 border-t-purple-500 rounded-full animate-spin"></div>
           <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Loading Data For {new Date(2024, parseInt(filters.month)).toLocaleString('id-ID', {month: 'long'})}...</p>
        </div>
      );
    }

    switch (activeModule) {
      case ModuleType.DASHBOARD:
        return <Dashboard onSelect={setActiveModule} />;
      case ModuleType.SALES:
        return <SalesModule data={currentData.sales} onUpdate={(v) => updateCurrentData('sales', v)} />;
      case ModuleType.GOOGLE_REVIEW:
        return <GoogleReviewModule data={currentData.googleReview} onUpdate={(v) => updateCurrentData('googleReview', v)} />;
      case ModuleType.GUEST_COMMENT:
        return <GuestCommentModule data={currentData.guestComments} onUpdate={(v) => updateCurrentData('guestComments', v)} />;
      case ModuleType.OVERTIME:
        return <OvertimeModule data={currentData.overtime} onUpdate={(v) => updateCurrentData('overtime', v)} />;
      case ModuleType.QUALITY_ASSURANCE:
        return <QAModule data={currentData.qa} onUpdate={(v) => updateCurrentData('qa', v)} />;
      case ModuleType.EXPENSES:
        return <ExpensesModule data={currentData} onUpdate={updateFullState} />;
      case ModuleType.YTD_REPORT:
        return <YTDModule allMonthlyData={monthlyData} />;
      case ModuleType.REKAPAN:
        return <ReportingModule data={currentData} filters={filters} />;
      default:
        return <Dashboard onSelect={setActiveModule} />;
    }
  };

  return (
    <div className="flex min-h-screen perspective-container overflow-hidden bg-[#0f172a]">
      <Sidebar active={activeModule} onSelect={setActiveModule} />

      <div className="flex-1 flex flex-col overflow-hidden relative">
        <Header 
          isFullScreen={isFullScreen} 
          onToggleFS={toggleFullScreen} 
          filters={filters}
          onFilterChange={setFilters}
          onHome={() => setActiveModule(ModuleType.DASHBOARD)}
        />

        <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
          <div className="max-w-7xl mx-auto">
            <div className="animate-fade-in">
              {renderModule()}
            </div>
          </div>
        </main>
      </div>

      <div className="fixed inset-0 pointer-events-none z-[-1] overflow-hidden">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-900/10 rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-pink-900/10 rounded-full"></div>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { AppState } from '../types';
import { OT_RATE, INITIAL_STATE } from '../constants';

interface Props {
  allMonthlyData: Record<string, AppState>;
}

const YTDModule: React.FC<Props> = ({ allMonthlyData }) => {
  const [selectedMonth, setSelectedMonth] = useState<number | null>(null);
  const [activeTrend, setActiveTrend] = useState<'OPEX' | 'QA' | 'RATING' | 'SALES'>('SALES');

  const months = [
    "Januari", "Februari", "Maret", "April", "Mei", "Juni",
    "Juli", "Agustus", "September", "Oktober", "November", "Desember"
  ];

  const getStatsForMonth = (monthIndex: number) => {
    const data = allMonthlyData[monthIndex.toString()] || INITIAL_STATE;

    // Calculate Stats
    const totalPoints = (data.googleReview.stars1 * 1) + (data.googleReview.stars2 * 2) + (data.googleReview.stars3 * 3) + (data.googleReview.stars4 * 4) + (data.googleReview.stars5 * 5);
    const totalVotes = data.googleReview.stars1 + data.googleReview.stars2 + data.googleReview.stars3 + data.googleReview.stars4 + data.googleReview.stars5;
    const currentRating = totalVotes === 0 ? "0.0" : (totalPoints / totalVotes).toFixed(1);

    const opex = Object.values(data.expenses).reduce((a, b) => a + b, 0);
    const ledgers = [data.cityLedger, data.customerSat, data.complimentary].flat().reduce((a, b) => a + (b.qty * b.price), 0);

    const otCost = data.overtime.reduce((acc, item) => {
      const netHours = Math.max(0, item.hours - (item.break1 + item.break2));
      return acc + (netHours * OT_RATE);
    }, 0);

    const comments = data.guestComments.reduce((a, b) => a + b.achievement, 0);

    const kAvg = (data.qa.kitchen.product + data.qa.kitchen.cleanliness + data.qa.kitchen.grooming) / 3;
    const bAvg = (data.qa.bar.product + data.qa.bar.cleanliness + data.qa.bar.grooming) / 3;
    const sAvg = (data.qa.service.product + data.qa.service.cleanliness + data.qa.service.grooming) / 3;
    const qaScore = (kAvg + bAvg + sAvg) / 3;

    const hasData = data.sales.revenue > 0 || opex > 0 || totalVotes > 0 || qaScore > 0;

    return {
      sales: data.sales.revenue,
      covers: data.sales.covers,
      opex: opex + ledgers,
      opexBreakdown: data.expenses,
      ot: otCost,
      rating: currentRating,
      comments: comments,
      qa: qaScore.toFixed(2),
      qaBreakdown: {
        kitchen: kAvg.toFixed(2),
        bar: bAvg.toFixed(2),
        service: sAvg.toFixed(2)
      },
      status: hasData ? (monthIndex === new Date().getMonth() ? 'Current' : 'Filled') : (monthIndex < new Date().getMonth() ? 'No Data' : 'Planned')
    };
  };

  const currentYear = new Date().getFullYear();
  const trendData = months.map((_, i) => getStatsForMonth(i));
  const currentMonthStats = trendData[new Date().getMonth()];

  const maxOpex = Math.max(...trendData.map(d => d.opex), 1000000);
  const maxSales = Math.max(...trendData.map(d => d.sales), 1000000);

  if (selectedMonth !== null) {
    const stats = trendData[selectedMonth];
    const avgCheck = stats.covers > 0 ? Math.floor(stats.sales / stats.covers) : 0;
    return (
      <div className="space-y-6 animate-fade-in no-blur">
        <div className="flex items-center justify-between glass-card p-6 border-l-4 border-cyan-500 bg-slate-900/90">
          <div className="flex items-center gap-6">
            <button 
              onClick={() => setSelectedMonth(null)}
              className="w-12 h-12 rounded-2xl bg-slate-800 hover:bg-slate-700 text-white flex items-center justify-center transition-all active:scale-90 border border-white/5"
            >
              <i className="fas fa-arrow-left"></i>
            </button>
            <div>
              <h2 className="text-3xl font-black text-white uppercase tracking-tighter leading-none">
                Detail Laporan: {months[selectedMonth]} {currentYear}
