              <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-widest">Analisis Performa Historis</p>
            </div>
          </div>
          <div className={`px-6 py-2 rounded-xl text-xs font-black uppercase border ${
            stats.status === 'Current' || stats.status === 'Filled' ? 'bg-cyan-500 text-white border-cyan-400' : 
            stats.status === 'No Data' ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-slate-800 text-slate-400 border-white/5'
          }`}>
            {stats.status}
          </div>
        </div>

        {stats.status === 'No Data' || stats.status === 'Planned' ? (
          <div className="glass-card p-20 flex flex-col items-center justify-center text-center space-y-4 opacity-40">
            <i className="fas fa-folder-open text-6xl text-slate-700"></i>
            <h3 className="text-xl font-black text-white uppercase tracking-widest">Belum Ada Data Terinput</h3>
            <p className="text-xs text-slate-500 font-bold max-w-sm uppercase">Pilih bulan ini di filter atas untuk mulai mengisi data susulan.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="glass-card p-8 border-t-2 border-emerald-500 bg-slate-900/60 flex flex-col justify-between">
              <div>
                <h3 className="text-sm font-black uppercase text-white mb-6 flex items-center gap-3">
                  <i className="fas fa-cash-register text-emerald-500"></i> Sales Summary
                </h3>
                <div className="space-y-4 text-xs font-bold border-white/5 pb-2">
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Total Revenue</span>
                      <span className="text-white">Rp {stats.sales.toLocaleString()}</span>
                   </div>
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Total Pax (Covers)</span>
                      <span className="text-white">{stats.covers} Pax</span>
                   </div>
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Average Check</span>
                      <span className="text-indigo-400">Rp {avgCheck.toLocaleString()}</span>
                   </div>
                </div>
              </div>
            </div>

            <div className="glass-card p-8 border-t-2 border-red-500 bg-slate-900/60">
              <h3 className="text-sm font-black uppercase text-white mb-6 flex items-center gap-3">
                <i className="fas fa-wallet text-red-500"></i> Expense & Audit
              </h3>
              <div className="space-y-4">
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">Opex Summary</span>
                    <span className="text-white">Rp {stats.opex.toLocaleString()}</span>
                 </div>
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">QA Score Avg</span>
                    <span className="text-emerald-400">{stats.qa}%</span>
                 </div>
              </div>
            </div>

            <div className="space-y-6">
              <div className="glass-card p-8 border-t-2 border-yellow-500 bg-slate-900/60">
                <h3 className="text-sm font-black uppercase text-white mb-4 flex items-center gap-3">
                  <i className="fab fa-google text-yellow-500"></i> Sentiment
                </h3>
                <div className="flex items-center gap-6">
                  <div className="text-5xl font-black text-yellow-400">{stats.rating} ★</div>
                </div>
              </div>
              <button className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase tracking-[0.2em] text-xs transition-all shadow-2xl active:scale-95 border border-white/10">
                <i className="fas fa-download mr-2"></i> Export Monthly PDF
