  }

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="glass-card p-8 border-l-4 border-cyan-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <i className="fas fa-chart-line text-[200px]"></i>
        </div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
              <i className="fas fa-calendar-check text-cyan-400"></i>
              Year to Date Dashboard
            </h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em]">Pusat Pelaporan Performa Terintegrasi - {currentYear}</p>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
             <div className="bg-slate-950/80 px-5 py-3 rounded-2xl border border-white/5 shadow-xl text-center">
                <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Yearly Revenue</div>
                <div className="text-xl font-black text-emerald-400">Rp {Math.round(trendData.reduce((a,b)=>a+b.sales,0)/1000000)}M</div>
             </div>
             <div className="bg-slate-950/80 px-5 py-3 rounded-2xl border border-white/5 shadow-xl text-center">
                <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Avg QA</div>
                <div className="text-xl font-black text-white">{currentMonthStats.qa}%</div>
             </div>
             <div className="bg-slate-950/80 px-5 py-3 rounded-2xl border border-white/5 shadow-xl text-center">
                <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Global Rating</div>
                <div className="text-xl font-black text-yellow-400">{currentMonthStats.rating} ★</div>
