              <div className="w-1.5 h-8 bg-indigo-500 rounded-full"></div>
              <h3 className="text-lg font-black uppercase text-white tracking-widest">Performance Metrics Trend</h3>
           </div>
           <div className="flex bg-slate-950/60 p-1.5 rounded-2xl border border-white/5 gap-2">
              {[
                { id: 'SALES', label: 'Revenue', icon: 'fa-cash-register' },
                { id: 'OPEX', label: 'Expenses', icon: 'fa-wallet' },
                { id: 'QA', label: 'Quality', icon: 'fa-clipboard-check' },
                { id: 'RATING', label: 'Rating', icon: 'fa-star' }
              ].map(tab => (
                <button 
                  key={tab.id}
                  onClick={() => setActiveTrend(tab.id as any)}
                  className={`px-5 py-2.5 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all flex items-center gap-3 ${
                    activeTrend === tab.id ? 'bg-indigo-600 text-white shadow-xl' : 'text-slate-500 hover:text-white'
                  }`}
                >
                  <i className={`fas ${tab.icon}`}></i> {tab.label}
                </button>
              ))}
           </div>
        </div>

        <div className="h-64 flex items-end gap-3 md:gap-6 px-4 relative">
           <div className="absolute inset-0 flex flex-col justify-between pointer-events-none opacity-5 py-2">
              {[1,2,3,4].map(i => <div key={i} className="border-t border-white w-full"></div>)}
           </div>

           {trendData.map((stats, i) => {
             let height = 0;
             let label = "";
             let activeColor = "bg-indigo-500";

             if (activeTrend === 'SALES') {
                height = (stats.sales / maxSales) * 100;
                label = `Rp ${Math.round(stats.sales/1000000)}M`;
                activeColor = "bg-emerald-500";
             } else if (activeTrend === 'OPEX') {
               height = (stats.opex / maxOpex) * 100;
               label = `Rp ${Math.round(stats.opex/1000000)}M`;
               activeColor = "bg-red-500";
             } else if (activeTrend === 'QA') {
               height = Number(stats.qa);
               label = `${stats.qa}%`;
               activeColor = "bg-white";
             } else {
               height = (Number(stats.rating) / 5) * 100;
               label = `${stats.rating} ★`;
               activeColor = "bg-yellow-500";
             }

             const isCurrent = i === new Date().getMonth();

             return (
               <div key={i} className="flex-1 flex flex-col items-center gap-4 group cursor-help relative z-10">
                  <div className="absolute -top-10 opacity-0 group-hover:opacity-100 transition-all bg-slate-800 text-[10px] font-black px-3 py-1.5 rounded-xl border border-white/10 whitespace-nowrap shadow-2xl -translate-y-2">
                     {label}
                  </div>
                  <div 
                    className={`w-full rounded-t-xl transition-all duration-1000 origin-bottom group-hover:scale-x-110 ${isCurrent ? `${activeColor} shadow-[0_0_30px_rgba(0,0,0,0.3)] ring-4 ring-white/10` : 'bg-slate-800/40 hover:bg-slate-700'}`}
                    style={{ height: `${Math.max(5, height)}%` }}
                  ></div>
                  <span className={`text-[9px] font-black uppercase tracking-tighter ${isCurrent ? 'text-white' : 'text-slate-600'}`}>
                    {months[i].substring(0, 3)}
                  </span>
               </div>
             );
           })}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {months.map((month, index) => {
          const stats = trendData[index];
          const isCurrent = index === new Date().getMonth();
          const hasData = stats.status === 'Filled' || stats.status === 'Current';
          const isNoData = stats.status === 'No Data';

          return (
            <div 
              key={month} 
              className={`glass-card p-6 flex flex-col justify-between h-[340px] transition-all group border-white/10 relative overflow-hidden ${
                isCurrent ? 'ring-2 ring-cyan-500 border-transparent bg-cyan-900/10' : 
                isNoData ? 'opacity-50 grayscale-[0.5]' : 'hover:border-cyan-500/50 hover:-translate-y-1'
              }`}
            >
              {isCurrent && (
                <div className="absolute top-0 right-0 w-16 h-16">
                  <div className="absolute top-0 right-0 bg-cyan-500 text-white text-[8px] font-black uppercase py-1 px-8 rotate-45 translate-x-4 translate-y-2 shadow-lg">Live</div>
                </div>
              )}
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest block mb-0.5">Laporan Bulanan</span>
                  <span className={`text-2xl font-black uppercase tracking-tighter ${isCurrent ? 'text-cyan-400' : 'text-white'}`}>{month}</span>
                </div>
                <div className={`text-[8px] font-black px-3 py-1 rounded-full uppercase tracking-tighter border ${
                  hasData ? 'bg-emerald-500 text-white border-emerald-400' : 
                  isNoData ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-slate-800 text-slate-500 border-white/5'
                }`}>{stats.status}</div>
              </div>
              <div className={`space-y-3.5 ${isNoData ? 'opacity-30' : ''}`}>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-cash-register text-emerald-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Revenue</span></div><span className="text-xs font-black text-white">Rp {Math.floor(stats.sales).toLocaleString()}</span></div>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-wallet text-red-500 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Expenses</span></div><span className="text-xs font-black text-white">Rp {Math.floor(stats.opex).toLocaleString()}</span></div>
                <div className="space-y-1.5"><div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-clipboard-check text-emerald-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">QA Score</span></div><span className="text-xs font-black text-emerald-400">{stats.qa}%</span></div><div className="h-1 bg-slate-900 rounded-full overflow-hidden"><div className={`h-full ${Number(stats.qa) >= 90 ? 'bg-emerald-500' : 'bg-orange-500'}`} style={{ width: `${stats.qa}%` }}></div></div></div>
                <div className="grid grid-cols-2 gap-4 mt-2">
                  <div className="p-2.5 rounded-xl bg-slate-950/50 border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Rating</div><div className="text-sm font-black text-yellow-400">{stats.rating} ★</div></div>
                  <div className="p-2.5 rounded-xl bg-slate-950/50 border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Covers</div><div className="text-sm font-black text-indigo-400">{stats.covers}</div></div>
                </div>
              </div>
              <div className="mt-6 pt-4 border-t border-white/5 flex justify-end items-center">
                <button onClick={() => setSelectedMonth(index)} className="text-[9px] font-black uppercase tracking-widest text-slate-500 hover:text-cyan-400 transition-colors flex items-center gap-2">{hasData ? 'Full Report' : 'Check Month'} <i className="fas fa-arrow-right text-[8px]"></i></button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

