import React, { useState } from 'react';
import { OvertimeEntry } from '../types';
import { STAFF_LIST, OT_RATE } from '../constants';

interface Props {
  data: OvertimeEntry[];
  onUpdate: (v: OvertimeEntry[]) => void;
}

const OvertimeModule: React.FC<Props> = ({ data, onUpdate }) => {
  const [isSaving, setIsSaving] = useState(false);

  const handleChange = (staffId: string, field: keyof OvertimeEntry, val: number) => {
    const newData = data.map(item => 
      item.staffId === staffId ? { ...item, [field]: val } : item
    );
    onUpdate(newData);
  };

  const calculateTotalOT = (item: OvertimeEntry) => {
    // "Break 1+1 masing masing crew yang akan mengurangi jumlah overtime"
    const netHours = Math.max(0, item.hours - (item.break1 + item.break2));
    return netHours * OT_RATE;
  };

  const leaders = STAFF_LIST.filter(s => s.isLeader);
  const crews = STAFF_LIST.filter(s => !s.isLeader);

  const totalExpenses = data.reduce((acc, item) => acc + calculateTotalOT(item), 0);
  const totalHoursRaw = data.reduce((acc, item) => acc + item.hours, 0);
  const totalBreaks = data.reduce((acc, item) => acc + item.break1 + item.break2, 0);

  const handleSubmit = () => {
    setIsSaving(true);
    setTimeout(() => setIsSaving(false), 1000);
  };

  const StaffRow = ({ staff }: { staff: any }) => {
    const entry = data.find(d => d.staffId === staff.id) || { hours: 0, break1: 0, break2: 0 };
    const net = Math.max(0, entry.hours - (entry.break1 + entry.break2));
    return (
      <tr key={staff.id} className="hover:bg-white/5 transition-colors group">
        <td className="p-4">
          <div className="font-black text-white group-hover:text-blue-400 transition-colors">{staff.name}</div>
          <div className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">{staff.role}</div>
        </td>
        <td className="p-4">
          <div className="flex items-center gap-2 bg-slate-900/50 rounded-xl px-3 py-2 border border-white/5 focus-within:border-blue-500 transition-all">
             <i className="fas fa-hourglass-start text-xs text-slate-600"></i>
             <input 
                type="number" 
                className="w-full bg-transparent border-none text-center text-sm outline-none font-bold"
                value={entry.hours || ''}
                onChange={(e) => handleChange(staff.id, 'hours', Number(e.target.value))}
              />
              <span className="text-[10px] text-slate-600 font-bold">Hrs</span>
          </div>
        </td>
        <td className="p-4">
           <div className="flex items-center gap-1 bg-slate-900/50 rounded-xl px-2 py-2 border border-white/5 focus-within:border-pink-500 transition-all">
             <input 
                type="number" 
                className="w-full bg-transparent border-none text-center text-sm outline-none font-bold"
                value={entry.break1 || ''}
                onChange={(e) => handleChange(staff.id, 'break1', Number(e.target.value))}
              />
              <span className="text-[10px] text-slate-600 font-bold">B1</span>
          </div>
        </td>
        <td className="p-4">
           <div className="flex items-center gap-1 bg-slate-900/50 rounded-xl px-2 py-2 border border-white/5 focus-within:border-pink-500 transition-all">
             <input 
                type="number" 
                className="w-full bg-transparent border-none text-center text-sm outline-none font-bold"
                value={entry.break2 || ''}
                onChange={(e) => handleChange(staff.id, 'break2', Number(e.target.value))}
              />
              <span className="text-[10px] text-slate-600 font-bold">B2</span>
          </div>
        </td>
        <td className="p-4 text-center">
            <div className={`text-xs font-black ${net > 0 ? 'text-blue-400' : 'text-slate-600'}`}>{net}h Net</div>
        </td>
        <td className="p-4 text-right font-black text-white">
          <div className="text-sm">Rp {calculateTotalOT(entry as any).toLocaleString()}</div>
        </td>
      </tr>
    );
