    const qaScore = Number(((kAvg + bAvg + sAvg) / 3).toFixed(2));

    const hasData = data.sales.revenue > 0 || opex > 0 || totalVotes > 0 || qaScore > 0;

    return {
      sales: data.sales.revenue,
      covers: data.sales.covers,
      opex: opex + ledgers,
      rating: currentRating,
      qa: qaScore,
