  const mtdPerformance = data.budgetRevenue > 0 ? ((calculatedMTDRevenue / data.budgetRevenue) * 100).toFixed(1) : "0";

  // MTD FORECAST = BUDGET REVENUE - MTD REVENUE
  const mtdForecast = data.budgetRevenue - calculatedMTDRevenue; 
