const SalesModule: React.FC<Props> = ({ data, dailyTargets, filters, onUpdate }) => {
  const [isSaving, setIsSaving] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showCommitConfirm, setShowCommitConfirm] = useState(false);

  // Automatically sync daily target from admin settings if available
  useEffect(() => {
    const autoTarget = dailyTargets[filters.startDate];
    if (autoTarget !== undefined && autoTarget !== data.dailyTarget) {
      onUpdate({ ...data, dailyTarget: autoTarget });
    }
  }, [filters.startDate, dailyTargets]);

  // Computed Values (Kalkulasi Today)
  const todayAvgCheck = data.todayCovers > 0 ? Math.floor(data.todayRevenue / data.todayCovers) : 0;
  const todayVariance = data.todayRevenue - data.dailyTarget;
  const todayPerformance = data.dailyTarget > 0 ? ((data.todayRevenue / data.dailyTarget) * 100).toFixed(1) : "0";

  // MTD Accumulated Logic (Running Total + Today)
  const calculatedMTDRevenue = data.revenue + data.todayRevenue;
  const calculatedMTDCover = data.covers + data.todayCovers;
  const mtdAvgCheck = calculatedMTDCover > 0 ? Math.floor(calculatedMTDRevenue / calculatedMTDCover) : 0;

  const mtdVariance = calculatedMTDRevenue - data.budgetRevenue;
