               {Number(outletAvg) >= 90 ? 'PASS' : 'FAIL'}
            </div>
         </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {renderSection('KITCHEN OPS', data.kitchen, 'kitchen', 'fa-fire-alt', 'border-orange-500')}
        {renderSection('BAR OPS', data.bar, 'bar', 'fa-glass-martini-alt', 'border-blue-500')}
        {renderSection('SERVICE EXCELLENCE', data.service, 'service', 'fa-hand-sparkles', 'border-pink-500')}
      </div>

      <button 
        onClick={handleSubmit}
        disabled={isSaving}
        className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-95 border border-white/10 ${
          isSaving ? 'bg-slate-800 text-slate-600 cursor-wait' : 'bg-emerald-600 hover:bg-emerald-500 text-white'
        }`}
      >
        {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-check-circle"></i>}
        {isSaving ? 'Submitting Audit...' : 'Finalize & Submit QA Audit'}
      </button>

      <div className="glass-card p-8 bg-slate-950/40 relative overflow-hidden border border-white/5">
        <h3 className="text-[10px] font-black uppercase text-slate-600 mb-8 flex items-center gap-3 tracking-[0.2em]">
           <i className="fas fa-chart-bar text-emerald-500"></i> Section Compliance Comparison
        </h3>

        <div className="grid grid-cols-2 md:grid-cols-4 gap-8">
           {[
             { label: 'Kitchen', val: kAvg, target: QA_PASSING_SCORES.kitchen, icon: 'fa-utensils' },
             { label: 'Bar', val: bAvg, target: QA_PASSING_SCORES.bar, icon: 'fa-cocktail' },
             { label: 'Service', val: sAvg, target: QA_PASSING_SCORES.service, icon: 'fa-concierge-bell' },
             { label: 'Global', val: outletAvg, target: 90, icon: 'fa-globe' }
           ].map((item, i) => (
             <div key={i} className="space-y-3">
                <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest flex items-center gap-2">
                   <i className={`fas ${item.icon} opacity-50`}></i> {item.label}
                </div>
                <div className="flex items-baseline gap-2">
                   <div className={`text-3xl font-black ${Number(item.val) >= item.target ? 'text-emerald-400' : 'text-red-400'}`}>{item.val}%</div>
                   <div className="text-[9px] font-bold text-slate-700 uppercase italic">/ {Number(item.target).toFixed(2)}%</div>
                </div>
                <div className="h-1 bg-slate-900 rounded-full overflow-hidden">
                   <div className={`h-full ${Number(item.val) >= item.target ? 'bg-emerald-500' : 'bg-red-500'}`} style={{ width: `${item.val}%` }}></div>
                </div>
             </div>
           ))}
        </div>
      </div>
    </div>
  );
};

