import React, { useState } from 'react';
import { QAData } from '../types';
import { QA_PASSING_SCORES } from '../constants';

interface Props {
  data: QAData;
  onUpdate: (v: QAData) => void;
}

const QAModule: React.FC<Props> = ({ data, onUpdate }) => {
  const [isSaving, setIsSaving] = useState(false);

  const calcAvg = (vals: number[]) => {
    return vals.length === 0 ? "0.00" : (vals.reduce((a, b) => a + b, 0) / vals.length).toFixed(2);
  };

  const kAvg = calcAvg([data.kitchen.product, data.kitchen.cleanliness, data.kitchen.grooming]);
  const bAvg = calcAvg([data.bar.product, data.bar.cleanliness, data.bar.grooming]);
  const sAvg = calcAvg([data.service.product, data.service.grooming, data.service.cleanliness]);
  const outletAvg = calcAvg([Number(kAvg), Number(bAvg), Number(sAvg)]);

  const handleSubmit = () => {
    setIsSaving(true);
    setTimeout(() => setIsSaving(false), 1000);
  };

  const renderSection = (title: string, fields: any, section: keyof QAData, icon: string, color: string) => (
    <div className={`glass-card p-6 space-y-6 border-t-4 ${color} bg-slate-900/50 shadow-xl`}>
      <h3 className="text-sm font-black flex items-center gap-3 text-white uppercase tracking-widest">
        <i className={`fas ${icon}`}></i> {title}
      </h3>
      <div className="space-y-6">
        {Object.keys(fields).map((field) => (
          <div key={field} className="space-y-2">
            <div className="flex justify-between items-center px-1">
               <label className="text-[9px] font-black uppercase text-slate-500 tracking-widest">
                  {field === 'product' ? (section === 'service' ? 'Quality Service' : 'Quality Product') : field}
               </label>
               <span className="text-xs font-black text-white">{Number((fields as any)[field]).toFixed(2)}%</span>
            </div>
            <div className="flex items-center gap-4">
              <div className="flex-1 bg-slate-950/50 border border-white/5 rounded-2xl p-4 flex items-center gap-4 focus-within:ring-1 ring-emerald-500 transition-all">
                <i className="fas fa-hashtag text-[10px] text-slate-700"></i>
                <input 
                  type="number" 
                  max="100" min="0"
                  className="w-full bg-transparent border-none text-left outline-none text-base font-black text-white placeholder:text-slate-800"
                  placeholder="0"
                  value={(fields as any)[field] || ''}
                  onChange={(e) => {
                     const val = Math.min(100, Math.max(0, Number(e.target.value)));
                     onUpdate({ ...data, [section]: { ...data[section], [field]: val } });
                  }}
                />
                <span className="text-[10px] font-black text-slate-600">%</span>
              </div>
            </div>
          </div>
        ))}
      </div>
      <div className="pt-6 border-t border-white/5 flex justify-between items-center bg-slate-950/40 -mx-6 -mb-6 p-6 rounded-b-2xl">
        <div className="text-[9px] font-black uppercase text-slate-500 tracking-widest">Section Avg</div>
        <div className="text-xl font-black text-white">{calcAvg(Object.values(fields))}%</div>
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="flex flex-col md:flex-row justify-between items-center gap-6 glass-card p-8 border-l-4 border-emerald-500 bg-[#1e293b]/95 shadow-2xl relative overflow-hidden">
         <div className="relative z-10">
            <h2 className="text-3xl font-black flex items-center gap-4 text-white uppercase tracking-tighter leading-none">
               <i className="fas fa-clipboard-check text-emerald-400"></i>
               Quality Assurance Audit
            </h2>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-2">Compliance & operational standard monitoring</p>
         </div>
         <div className="mix-gradient-bg p-6 rounded-2xl shadow-2xl flex items-center gap-6 relative z-10 border border-white/10">
            <div className="text-right">
               <div className="text-[10px] font-black uppercase text-white/50 tracking-widest mb-1">Outlet Global Score</div>
               <div className="text-4xl font-black text-white">{outletAvg}%</div>
            </div>
            <div className="h-12 w-px bg-white/20"></div>
            <div className={`w-16 h-16 rounded-2xl flex items-center justify-center font-black text-lg shadow-inner ${Number(outletAvg) >= 90 ? 'bg-emerald-500 text-white' : 'bg-red-500 text-white'}`}>
               {Number(outletAvg) >= 90 ? 'PASS' : 'FAIL'}
            </div>
         </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {renderSection('KITCHEN OPS', data.kitchen, 'kitchen', 'fa-fire-alt', 'border-orange-500')}
        {renderSection('BAR OPS', data.bar, 'bar', 'fa-glass-martini-alt', 'border-blue-500')}
        {renderSection('SERVICE EXCELLENCE', data.service, 'service', 'fa-hand-sparkles', 'border-pink-500')}
      </div>

      <button 
        onClick={handleSubmit}
        disabled={isSaving}
        className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-95 border border-white/10 ${
          isSaving ? 'bg-slate-800 text-slate-600 cursor-wait' : 'bg-emerald-600 hover:bg-emerald-500 text-white'
        }`}
      >
        {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-check-circle"></i>}
