            <p className="text-xs text-slate-500 font-bold max-w-sm uppercase">Bulan ini belum memiliki input data performa.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="glass-card p-8 border-t-2 border-emerald-500 bg-slate-900/60 flex flex-col justify-between shadow-2xl">
              <div>
                <h3 className="text-sm font-black uppercase text-white mb-6 flex items-center gap-3">
                  <i className="fas fa-cash-register text-emerald-500"></i> Sales Breakdown
                </h3>
                <div className="space-y-4 text-xs font-bold border-white/5 pb-2">
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Revenue</span>
                      <span className="text-white font-black">Rp {stats.sales.toLocaleString()}</span>
                   </div>
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Covers</span>
                      <span className="text-white font-black">{stats.covers} Pax</span>
                   </div>
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Avg Check</span>
                      <span className="text-indigo-400 font-black">Rp {avgCheck.toLocaleString()}</span>
                   </div>
                </div>
              </div>
            </div>

            <div className="glass-card p-8 border-t-2 border-red-500 bg-slate-900/60 shadow-2xl">
              <h3 className="text-sm font-black uppercase text-white mb-6 flex items-center gap-3">
                <i className="fas fa-wallet text-red-500"></i> Financial Summary
              </h3>
              <div className="space-y-4">
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">Total Opex</span>
                    <span className="text-white font-black">Rp {stats.opex.toLocaleString()}</span>
                 </div>
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">Energy Cost</span>
                    <span className="text-yellow-400 font-black">Rp {stats.energy.toLocaleString()}</span>
                 </div>
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">Alat Saji Cost</span>
                    <span className="text-emerald-400 font-black">Rp {stats.alat_saji.toLocaleString()}</span>
                 </div>
              </div>
            </div>

            <div className="space-y-6">
              <div className="glass-card p-8 border-t-2 border-yellow-500 bg-slate-900/60 shadow-2xl">
                <h3 className="text-sm font-black uppercase text-white mb-4 flex items-center gap-3">
                  <i className="fab fa-google text-yellow-500"></i> Rating
                </h3>
                <div className="text-5xl font-black text-yellow-400">{stats.rating.toFixed(2)} <span className="text-lg">★</span></div>
              </div>
              <button className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase tracking-[0.2em] text-xs transition-all shadow-2xl active:scale-95 border border-white/10">
                <i className="fas fa-download mr-2"></i> Export Report
              </button>
            </div>
          </div>
        )}
      </div>
    );
  }

  const totalYtdSales = trendData.reduce((a,b) => a + b.sales, 0);

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="glass-card p-8 border-l-4 border-cyan-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <i className="fas fa-chart-line text-[200px]"></i>
        </div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
