                { id: 'ALAT_SAJI', label: 'Alat Saji', icon: 'fa-utensils' },
                { id: 'QA', label: 'QA', icon: 'fa-clipboard-check' },
                { id: 'RATING', label: 'Rating', icon: 'fa-star' },
                { id: 'COVERS', label: 'Covers', icon: 'fa-users' },
                { id: 'OVERTIME', label: 'Overtime', icon: 'fa-clock' },
                { id: 'COMMENTS', label: 'Comments', icon: 'fa-comments' },
              ].map(tab => (
                <button 
                  key={tab.id}
                  onClick={() => setActiveTrend(tab.id as TrendType)}
                  className={`px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all flex items-center gap-2 ${
                    activeTrend === tab.id ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-900/40' : 'text-slate-500 hover:text-white'
                  }`}
                >
                  <i className={`fas ${tab.icon}`}></i> {tab.label}
                </button>
              ))}
           </div>
        </div>

        {/* MODERN AREA CHART SVG */}
        <div className="w-full h-80 relative mt-10">
           <svg className="w-full h-full overflow-visible" viewBox="0 0 1000 300" preserveAspectRatio="none">
              <defs>
                 <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={chartConfig.color} stopOpacity="0.3" />
                    <stop offset="100%" stopColor={chartConfig.color} stopOpacity="0" />
                 </linearGradient>
              </defs>

              {[0, 0.25, 0.5, 0.75, 1].map((p, idx) => (
                <line 
                  key={idx}
                  x1="0" y1={300 - (p * 300)} 
                  x2="1000" y2={300 - (p * 300)} 
                  stroke="rgba(255,255,255,0.03)" 
                  strokeWidth="1"
                />
              ))}

              <path d={chartConfig.areaPath} fill="url(#chartGradient)" />
              <path d={chartConfig.linePath} fill="none" stroke={chartConfig.color} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />

              {hoveredIdx !== null && (
                <line 
                  x1={chartConfig.points[hoveredIdx].x} 
                  y1="0" 
                  x2={chartConfig.points[hoveredIdx].x} 
                  y2="300" 
                  stroke="rgba(255,255,255,0.1)" 
                  strokeWidth="1" 
                  strokeDasharray="4,4"
                />
              )}

              {chartConfig.points.map((p, i) => (
                <g 
                  key={i} 
                  onMouseEnter={() => setHoveredIdx(i)} 
                  onMouseLeave={() => setHoveredIdx(null)}
                  onClick={() => p.hasData && setSelectedMonth(i)}
                  className="cursor-pointer group"
                >
                  <circle 
                    cx={p.x} 
                    cy={p.y} 
                    r={hoveredIdx === i ? "6" : "4"} 
                    fill={p.hasData ? chartConfig.color : '#334155'} 
                    stroke="#1e293b" 
                    strokeWidth="2"
                    className="transition-all"
                  />
                  <rect x={p.x - 40} y="0" width="80" height="300" fill="transparent" />
                </g>
              ))}
           </svg>

           {hoveredIdx !== null && (
             <div 
               className="absolute z-50 pointer-events-none bg-[#0f172a] border border-white/10 p-3 rounded-xl shadow-2xl flex flex-col gap-1 -translate-x-1/2 -translate-y-full"
               style={{ 
                 left: `${chartConfig.points[hoveredIdx].x / 10}%`, 
                 top: `${chartConfig.points[hoveredIdx].y}px`,
                 marginTop: '-20px'
                }}
             >
                <div className="text-[10px] font-black uppercase text-slate-500">{months[hoveredIdx]}</div>
                <div className="text-sm font-black text-white whitespace-nowrap">
                  {['SALES', 'OPEX', 'ENERGY', 'ALAT_SAJI', 'OVERTIME'].includes(activeTrend) ? 'Rp ' : ''}
                  {chartConfig.points[hoveredIdx].val.toLocaleString(undefined, { minimumFractionDigits: activeTrend === 'QA' || activeTrend === 'RATING' ? 2 : 0, maximumFractionDigits: 2 })}
                  {activeTrend === 'QA' ? '%' : (activeTrend === 'RATING' ? ' ★' : (activeTrend === 'COVERS' ? ' Pax' : (activeTrend === 'COMMENTS' ? ' Mentions' : '')))}
                </div>
             </div>
           )}

           <div className="flex justify-between mt-6 px-4">
              {months.map((m, i) => (
                <div key={i} className={`text-[10px] font-black uppercase tracking-tighter w-12 text-center transition-colors ${i === new Date().getMonth() ? 'text-cyan-400' : (hoveredIdx === i ? 'text-white' : 'text-slate-600')}`}>
                   {m.substring(0, 3)}
                </div>
              ))}
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {months.map((month, index) => {
          const stats = trendData[index];
          const isCurrent = index === new Date().getMonth();
          const hasData = stats.hasData;
          const isNoData = stats.status === 'No Data';

          return (
            <div 
              key={month} 
              onClick={() => hasData && setSelectedMonth(index)}
              className={`glass-card p-6 flex flex-col justify-between h-[360px] transition-all group border-white/10 relative overflow-hidden cursor-pointer ${
                isCurrent ? 'ring-2 ring-cyan-500 border-transparent bg-cyan-900/10 shadow-2xl shadow-cyan-900/20' : 
                isNoData ? 'opacity-50 grayscale-[0.5]' : 'hover:border-indigo-500/50 hover:-translate-y-1'
              }`}
            >
              {isCurrent && (
                <div className="absolute top-0 right-0 w-16 h-16">
                  <div className="absolute top-0 right-0 bg-cyan-500 text-white text-[8px] font-black uppercase py-1 px-8 rotate-45 translate-x-4 translate-y-2 shadow-lg">LIVE</div>
                </div>
              )}
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest block mb-0.5">METRIK</span>
                  <span className={`text-2xl font-black uppercase tracking-tighter ${isCurrent ? 'text-cyan-400' : 'text-white'}`}>{month}</span>
                </div>
                <div className={`text-[8px] font-black px-3 py-1 rounded-full uppercase tracking-tighter border ${
                  hasData ? 'bg-emerald-500 text-white border-emerald-400 shadow-[0_0_10px_rgba(16,185,129,0.2)]' : 
                  isNoData ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-slate-800 text-slate-500 border-white/5'
                }`}>{stats.status}</div>
              </div>
              <div className={`space-y-3.5 ${isNoData ? 'opacity-30' : ''}`}>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-cash-register text-emerald-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Sales</span></div><span className="text-xs font-black text-white">Rp {Math.floor(stats.sales).toLocaleString()}</span></div>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-bolt text-yellow-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Energy</span></div><span className="text-xs font-black text-white">Rp {Math.floor(stats.energy).toLocaleString()}</span></div>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-utensils text-emerald-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Alat Saji</span></div><span className="text-xs font-black text-white">Rp {Math.floor(stats.alat_saji).toLocaleString()}</span></div>
                <div className="space-y-1.5"><div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-clipboard-check text-emerald-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">QA Score</span></div><span className="text-xs font-black text-emerald-400">{stats.qa.toFixed(2)}%</span></div><div className="h-1 bg-slate-900 rounded-full overflow-hidden"><div className={`h-full ${Number(stats.qa) >= 90 ? 'bg-emerald-500' : 'bg-orange-500'}`} style={{ width: `${stats.qa}%` }}></div></div></div>
                <div className="grid grid-cols-2 gap-4 mt-2">
                  <div className="p-2.5 rounded-xl bg-slate-950/50 border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Rating</div><div className="text-sm font-black text-yellow-400">{stats.rating.toFixed(2)} ★</div></div>
                  <div className="p-2.5 rounded-xl bg-slate-950/50 border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Pax</div><div className="text-sm font-black text-indigo-400">{stats.covers}</div></div>
                </div>
              </div>
              <div className="mt-6 pt-4 border-t border-white/5 flex justify-end items-center">
                <span className="text-[9px] font-black uppercase tracking-widest text-slate-500 group-hover:text-cyan-400 transition-colors flex items-center gap-2">{hasData ? 'Open Report' : 'No Data'} <i className="fas fa-arrow-right text-[8px]"></i></span>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default YTDModule;

