                      onChange={(e) => updateDailyData('covers', Number(e.target.value))}
                    />
                  </div>
                </div>
                <div className="space-y-2">
                  <div className="flex justify-between items-center">
                    <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">TARGET TODAY (AUTO FROM ADMIN)</label>
                    <span className="text-[8px] font-black text-indigo-400 uppercase tracking-tighter bg-indigo-400/10 px-2 py-0.5 rounded border border-indigo-400/20">Sync Active</span>
                  </div>
                  <div className="flex items-center gap-3 bg-slate-950/50 p-4 rounded-xl border border-white/5 opacity-80">
                    <span className="text-slate-700 text-xs font-black">RP.</span>
                    <div className="flex-1 bg-transparent text-slate-300 font-black text-xl">
                      {data.dailyTarget.toLocaleString()}
                    </div>
                    <i className="fas fa-lock text-[10px] text-slate-600"></i>
                  </div>
                </div>
              </div>

              <div className="pt-6 border-t border-white/10 space-y-1">
                <MetricBox label="AVERAGE CHECK" value={todayAvgCheck} prefix="RP. " colorClass="text-blue-400" isCalc />
                <MetricBox label="VARIANCE TODAY" value={todayVariance} prefix="RP. " colorClass={todayVariance >= 0 ? "text-emerald-400" : "text-red-400"} isCalc />
                <MetricBox label="PERFORMANCE RATE" value={`${todayPerformance}%`} colorClass={Number(todayPerformance) >= 100 ? "text-emerald-400" : "text-orange-400"} isCalc />
              </div>

              <button 
                onClick={handleSubmitData}
                disabled={isSubmitting}
                className={`w-full py-4 rounded-xl font-black text-[10px] uppercase tracking-[0.2em] transition-all flex items-center justify-center gap-3 active:scale-95 border border-white/10 ${
                  isSubmitting ? 'bg-slate-800 text-slate-600' : 'bg-emerald-600 hover:bg-emerald-500 text-white shadow-lg shadow-emerald-900/20'
