type TrendType = 'SALES' | 'OPEX' | 'ENERGY' | 'LOST_BREAKAGE' | 'QA' | 'RATING' | 'COVERS' | 'OVERTIME' | 'COMMENTS';

const YTDModule: React.FC<Props> = ({ allMonthlyData }) => {
  const [selectedMonth, setSelectedMonth] = useState<number | null>(null);
  const [activeTrend, setActiveTrend] = useState<TrendType>('SALES');
  const [hoveredIdx, setHoveredIdx] = useState<number | null>(null);

  const months = [
    "Januari", "Februari", "Maret", "April", "Mei", "Juni",
    "Juli", "Agustus", "September", "Oktober", "November", "Desember"
  ];

  const getStatsForMonth = (monthIndex: number) => {
    const data = allMonthlyData[monthIndex.toString()] || INITIAL_STATE;

    // Dynamic Calculation: MTD revenue kalkulasi dari Daily revenue setiap hari
    const calculatedRevenue = Object.values(data.sales.dailyRecording || {}).reduce((acc, curr) => acc + (Number(curr.revenue) || 0), 0);
    const calculatedCovers = Object.values(data.sales.dailyRecording || {}).reduce((acc, curr) => acc + (Number(curr.covers) || 0), 0);

    const totalPoints = (data.googleReview.stars1 * 1) + (data.googleReview.stars2 * 2) + (data.googleReview.stars3 * 3) + (data.googleReview.stars4 * 4) + (data.googleReview.stars5 * 5);
    const totalVotes = data.googleReview.stars1 + data.googleReview.stars2 + data.googleReview.stars3 + data.googleReview.stars4 + data.googleReview.stars5;
    const currentRating = totalVotes === 0 ? 0 : Number((totalPoints / totalVotes).toFixed(2));

    const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];
    const energyKeys = ['electricity', 'water', 'gas'];
    const lostBreakageKeys = ['lostBreakageBar', 'lostBreakageKitchen', 'lostBreakageService'];

    const opex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
    const energy = energyKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
    const lostBreakage = lostBreakageKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
    const ledgers = [data.cityLedger, data.customerSat, data.complimentary].flat().reduce((a, b) => a + (b.qty * b.price), 0);

    const kAvg = (data.qa.kitchen.product + data.qa.kitchen.cleanliness + data.qa.kitchen.grooming) / 3;
    const bAvg = (data.qa.bar.product + data.qa.bar.cleanliness + data.qa.bar.grooming) / 3;
    const sAvg = (data.qa.service.product + data.qa.service.cleanliness + data.qa.service.grooming) / 3;
    const qaScore = Number(((kAvg + bAvg + sAvg) / 3).toFixed(2));

    const overtimeCost = data.overtime.reduce((acc, item) => {
      const netHours = Math.max(0, item.hours - (item.break1 + item.break2));
      return acc + (netHours * OT_RATE);
    }, 0);

    const guestCommentsCount = data.guestComments.reduce((acc, curr) => acc + curr.achievement, 0);

    const hasData = calculatedRevenue > 0 || opex > 0 || energy > 0 || lostBreakage > 0 || totalVotes > 0 || qaScore > 0;

    return {
      sales: calculatedRevenue,
      covers: calculatedCovers,
      opex: opex + ledgers,
      energy: energy,
      lost_breakage: lostBreakage,
      rating: currentRating,
      qa: qaScore,
      overtime: overtimeCost,
      comments: guestCommentsCount,
      hasData,
      status: hasData ? (monthIndex === new Date().getMonth() ? 'Current' : 'Filled') : (monthIndex < new Date().getMonth() ? 'No Data' : 'Planned')
    };
  };

  const trendData = useMemo(() => months.map((_, i) => getStatsForMonth(i)), [allMonthlyData]);

  const chartConfig = useMemo(() => {
    const key = activeTrend.toLowerCase() as keyof ReturnType<typeof getStatsForMonth>;
    const values = trendData.map(d => Number(d[key]));
    const maxVal = Math.max(...values, 1) * 1.2; 

    let color = "#6366f1"; 
    if (activeTrend === 'SALES') color = "#10b981"; 
    if (activeTrend === 'OPEX') color = "#ef4444"; 
    if (activeTrend === 'ENERGY') color = "#facc15"; 
    if (activeTrend === 'LOST_BREAKAGE') color = "#34d399"; 
    if (activeTrend === 'RATING') color = "#f59e0b"; 
    if (activeTrend === 'COVERS') color = "#3b82f6"; 
    if (activeTrend === 'OVERTIME') color = "#8b5cf6"; 
    if (activeTrend === 'COMMENTS') color = "#ec4899"; 

    const points = trendData.map((d, i) => {
      const x = (i * 85) + 40;
      const y = 300 - (Number(d[key]) / maxVal * 260);
      return { x, y, val: Number(d[key]), hasData: d.hasData };
    });

    const linePath = points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x} ${p.y}`).join(' ');
    const areaPath = `${linePath} L ${points[points.length - 1].x} 300 L ${points[0].x} 300 Z`;

    return { points, linePath, areaPath, color, maxVal };
  }, [trendData, activeTrend]);

  if (selectedMonth !== null) {
    const stats = trendData[selectedMonth];
    const avgCheck = stats.covers > 0 ? Math.floor(stats.sales / stats.covers) : 0;
    return (
      <div className="space-y-6 animate-fade-in no-blur">
        <div className="flex items-center justify-between glass-card p-6 border-l-4 border-cyan-500 bg-[#1e293b]/95 shadow-2xl">
          <div className="flex items-center gap-6">
            <button 
              onClick={() => setSelectedMonth(null)}
              className="w-12 h-12 rounded-2xl bg-slate-800 hover:bg-slate-700 text-white flex items-center justify-center transition-all active:scale-90 border border-white/5 shadow-xl"
            >
              <i className="fas fa-arrow-left"></i>
            </button>
            <div>
              <h2 className="text-3xl font-black text-white uppercase tracking-tighter leading-none">
                Laporan Historis: {months[selectedMonth]}
              </h2>
              <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-widest">Detail Audit & Financial Summary</p>
            </div>
          </div>
          <div className={`px-6 py-2 rounded-xl text-xs font-black uppercase border ${
            stats.status === 'Current' || stats.status === 'Filled' ? 'bg-emerald-500 text-white border-emerald-400 shadow-[0_0_15px_rgba(16,185,129,0.3)]' : 
            stats.status === 'No Data' ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-slate-800 text-slate-400 border-white/5'
          }`}>
            {stats.status}
          </div>
        </div>

        {(!stats.hasData) ? (
          <div className="glass-card p-20 flex flex-col items-center justify-center text-center space-y-4 opacity-40">
            <i className="fas fa-folder-open text-6xl text-slate-700"></i>
            <h3 className="text-xl font-black text-white uppercase tracking-widest">Data Kosong</h3>
            <p className="text-xs text-slate-500 font-bold max-w-sm uppercase">Bulan ini belum memiliki input data performa.</p>
          </div>
        ) : (
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
            <div className="glass-card p-8 border-t-2 border-emerald-500 bg-slate-900/60 flex flex-col justify-between shadow-2xl">
              <div>
                <h3 className="text-sm font-black uppercase text-white mb-6 flex items-center gap-3">
                  <i className="fas fa-cash-register text-emerald-500"></i> Sales Breakdown
                </h3>
                <div className="space-y-4 text-xs font-bold border-white/5 pb-2">
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Revenue</span>
                      <span className="text-white font-black">Rp {stats.sales.toLocaleString()}</span>
                   </div>
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Covers</span>
                      <span className="text-white font-black">{stats.covers} Pax</span>
                   </div>
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Avg Check</span>
                      <span className="text-indigo-400 font-black">Rp {avgCheck.toLocaleString()}</span>
                   </div>
                </div>
              </div>
            </div>

            <div className="glass-card p-8 border-t-2 border-red-500 bg-slate-900/60 shadow-2xl">
              <h3 className="text-sm font-black uppercase text-white mb-6 flex items-center gap-3">
                <i className="fas fa-wallet text-red-500"></i> Financial Summary
              </h3>
              <div className="space-y-4">
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">Total Opex</span>
                    <span className="text-white font-black">Rp {stats.opex.toLocaleString()}</span>
                 </div>
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">Energy Cost</span>
                    <span className="text-yellow-400 font-black">Rp {stats.energy.toLocaleString()}</span>
                 </div>
                 <div className="flex justify-between items-center text-xs font-bold border-b border-white/5 pb-2">
                    <span className="text-slate-500 uppercase">Lost & Breakage</span>
                    <span className="text-emerald-400 font-black">Rp {stats.lost_breakage.toLocaleString()}</span>
                 </div>
              </div>
            </div>

            <div className="space-y-6">
              <div className="glass-card p-8 border-t-2 border-yellow-500 bg-slate-900/60 shadow-2xl">
                <h3 className="text-sm font-black uppercase text-white mb-4 flex items-center gap-3">
                  <i className="fab fa-google text-yellow-500"></i> Rating
                </h3>
                <div className="text-5xl font-black text-yellow-400">{stats.rating.toFixed(2)} <span className="text-lg">★</span></div>
              </div>
              <button className="w-full py-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase tracking-[0.2em] text-xs transition-all shadow-2xl active:scale-95 border border-white/10">
                <i className="fas fa-download mr-2"></i> Export Report
              </button>
            </div>
          </div>
        )}
      </div>
    );
  }

  const totalYtdSales = trendData.reduce((a,b) => a + b.sales, 0);

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="glass-card p-8 border-l-4 border-cyan-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <i className="fas fa-chart-line text-[200px]"></i>
        </div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
              <i className="fas fa-calendar-check text-cyan-400"></i>
              Year to Date Performance
            </h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em]">Visualisasi Grafik Tren Performa Outlet</p>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
             {[
               { label: 'YTD Revenue', val: `Rp ${totalYtdSales.toLocaleString()}`, color: 'text-emerald-400' },
               { label: 'Current QA', val: `${trendData[new Date().getMonth()].qa.toFixed(2)}%`, color: 'text-white' },
               { label: 'Current Rating', val: `${trendData[new Date().getMonth()].rating.toFixed(2)} ★`, color: 'text-yellow-400' },
               { label: 'Monitoring', val: '12 Months', color: 'text-pink-400' }
             ].map((stat, i) => (
               <div key={i} className="bg-slate-950/80 px-5 py-3 rounded-2xl border border-white/5 shadow-xl text-center">
                  <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">{stat.label}</div>
                  <div className={`text-xl font-black ${stat.color} leading-tight`}>{stat.val}</div>
               </div>
             ))}
          </div>
        </div>
      </div>

      <div className="glass-card p-8 bg-[#1e293b]/60 border border-white/10 shadow-2xl relative">
        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-12">
           <div className="flex items-center gap-4">
              <div className="w-1.5 h-8 bg-indigo-500 rounded-full"></div>
              <h3 className="text-lg font-black uppercase text-white tracking-widest">Analytical Chart Trend</h3>
           </div>
           <div className="flex flex-wrap bg-slate-950/60 p-1.5 rounded-2xl border border-white/5 gap-2 shadow-inner">
              {[
                { id: 'SALES', label: 'Sales', icon: 'fa-cash-register' },
                { id: 'OPEX', label: 'Opex', icon: 'fa-wallet' },
                { id: 'ENERGY', label: 'Energy', icon: 'fa-bolt' },
                { id: 'LOST_BREAKAGE', label: 'Lost & Breakage', icon: 'fa-trash-restore' },
                { id: 'QA', label: 'QA', icon: 'fa-clipboard-check' },
                { id: 'RATING', label: 'Rating', icon: 'fa-star' },
                { id: 'COVERS', label: 'Covers', icon: 'fa-users' },
                { id: 'OVERTIME', label: 'Overtime', icon: 'fa-clock' },
                { id: 'COMMENTS', label: 'Comments', icon: 'fa-comments' },
              ].map(tab => (
                <button 
                  key={tab.id}
                  onClick={() => setActiveTrend(tab.id as TrendType)}
                  className={`px-4 py-2.5 rounded-xl text-[9px] font-black uppercase tracking-widest transition-all flex items-center gap-2 ${
                    activeTrend === tab.id ? 'bg-indigo-600 text-white shadow-xl shadow-indigo-900/40' : 'text-slate-500 hover:text-white'
                  }`}
                >
                  <i className={`fas ${tab.icon}`}></i> {tab.label}
                </button>
              ))}
           </div>
        </div>

        {/* MODERN AREA CHART SVG */}
        <div className="w-full h-80 relative mt-10">
           <svg className="w-full h-full overflow-visible" viewBox="0 0 1000 300" preserveAspectRatio="none">
              <defs>
                 <linearGradient id="chartGradient" x1="0" y1="0" x2="0" y2="1">
                    <stop offset="0%" stopColor={chartConfig.color} stopOpacity="0.3" />
                    <stop offset="100%" stopColor={chartConfig.color} stopOpacity="0" />
                 </linearGradient>
              </defs>

              {[0, 0.25, 0.5, 0.75, 1].map((p, idx) => (
                <line 
                  key={idx}
                  x1="0" y1={300 - (p * 300)} 
                  x2="1000" y2={300 - (p * 300)} 
                  stroke="rgba(255,255,255,0.03)" 
                  strokeWidth="1"
                />
              ))}

              <path d={chartConfig.areaPath} fill="url(#chartGradient)" />
              <path d={chartConfig.linePath} fill="none" stroke={chartConfig.color} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />

              {hoveredIdx !== null && (
                <line 
                  x1={chartConfig.points[hoveredIdx].x} 
                  y1="0" 
                  x2={chartConfig.points[hoveredIdx].x} 
                  y2="300" 
                  stroke="rgba(255,255,255,0.1)" 
                  strokeWidth="1" 
                  strokeDasharray="4,4"
                />
              )}

              {chartConfig.points.map((p, i) => (
                <g 
                  key={i} 
                  onMouseEnter={() => setHoveredIdx(i)} 
                  onMouseLeave={() => setHoveredIdx(null)}
                  onClick={() => p.hasData && setSelectedMonth(i)}
                  className="cursor-pointer group"
                >
                  <circle 
                    cx={p.x} 
                    cy={p.y} 
                    r={hoveredIdx === i ? "6" : "4"} 
                    fill={p.hasData ? chartConfig.color : '#334155'} 
                    stroke="#1e293b" 
                    strokeWidth="2"
                    className="transition-all"
                  />
                  <rect x={p.x - 40} y="0" width="80" height="300" fill="transparent" />
                </g>
              ))}
           </svg>

           {hoveredIdx !== null && (
             <div 
               className="absolute z-50 pointer-events-none bg-[#0f172a] border border-white/10 p-3 rounded-xl shadow-2xl flex flex-col gap-1 -translate-x-1/2 -translate-y-full"
               style={{ 
                 left: `${chartConfig.points[hoveredIdx].x / 10}%`, 
                 top: `${chartConfig.points[hoveredIdx].y}px`,
                 marginTop: '-20px'
                }}
             >
                <div className="text-[10px] font-black uppercase text-slate-500">{months[hoveredIdx]}</div>
                <div className="text-sm font-black text-white whitespace-nowrap">
                  {['SALES', 'OPEX', 'ENERGY', 'LOST_BREAKAGE', 'OVERTIME'].includes(activeTrend) ? 'Rp ' : ''}
                  {chartConfig.points[hoveredIdx].val.toLocaleString(undefined, { minimumFractionDigits: activeTrend === 'QA' || activeTrend === 'RATING' ? 2 : 0, maximumFractionDigits: 2 })}
                  {activeTrend === 'QA' ? '%' : (activeTrend === 'RATING' ? ' ★' : (activeTrend === 'COVERS' ? ' Pax' : (activeTrend === 'COMMENTS' ? ' Mentions' : '')))}
                </div>
             </div>
           )}

           <div className="flex justify-between mt-6 px-4">
              {months.map((m, i) => (
                <div key={i} className={`text-[10px] font-black uppercase tracking-tighter w-12 text-center transition-colors ${i === new Date().getMonth() ? 'text-cyan-400' : (hoveredIdx === i ? 'text-white' : 'text-slate-600')}`}>
                   {m.substring(0, 3)}
                </div>
              ))}
           </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
        {months.map((month, index) => {
          const stats = trendData[index];
          const isCurrent = index === new Date().getMonth();
          const hasData = stats.hasData;
          const isNoData = stats.status === 'No Data';

          return (
            <div 
              key={month} 
              onClick={() => hasData && setSelectedMonth(index)}
              className={`glass-card p-6 flex flex-col justify-between h-[360px] transition-all group border-white/10 relative overflow-hidden cursor-pointer ${
                isCurrent ? 'ring-2 ring-cyan-500 border-transparent bg-cyan-900/10 shadow-2xl shadow-cyan-900/20' : 
                isNoData ? 'opacity-50 grayscale-[0.5]' : 'hover:border-indigo-500/50 hover:-translate-y-1'
              }`}
            >
              {isCurrent && (
                <div className="absolute top-0 right-0 w-16 h-16">
                  <div className="absolute top-0 right-0 bg-cyan-500 text-white text-[8px] font-black uppercase py-1 px-8 rotate-45 translate-x-4 translate-y-2 shadow-lg">LIVE</div>
                </div>
              )}
              <div className="flex justify-between items-start mb-6">
                <div>
                  <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest block mb-0.5">METRIK</span>
                  <span className={`text-2xl font-black uppercase tracking-tighter ${isCurrent ? 'text-cyan-400' : 'text-white'}`}>{month}</span>
                </div>
                <div className={`text-[8px] font-black px-3 py-1 rounded-full uppercase tracking-tighter border ${
                  hasData ? 'bg-emerald-500 text-white border-emerald-400 shadow-[0_0_10px_rgba(16,185,129,0.2)]' : 
                  isNoData ? 'bg-red-500/10 text-red-500 border-red-500/20' : 'bg-slate-800 text-slate-500 border-white/5'
                }`}>{stats.status}</div>
              </div>
              <div className={`space-y-3.5 ${isNoData ? 'opacity-30' : ''}`}>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-cash-register text-emerald-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Sales</span></div><span className="text-xs font-black text-white">Rp {Math.floor(stats.sales).toLocaleString()}</span></div>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-bolt text-yellow-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Energy</span></div><span className="text-xs font-black text-white">Rp {Math.floor(stats.energy).toLocaleString()}</span></div>
                <div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-trash-restore text-emerald-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">Lost/Breakage</span></div><span className="text-xs font-black text-white">Rp {Math.floor(stats.lost_breakage).toLocaleString()}</span></div>
                <div className="space-y-1.5"><div className="flex justify-between items-center"><div className="flex items-center gap-2"><i className="fas fa-clipboard-check text-emerald-400 text-[10px]"></i><span className="text-[9px] font-bold text-slate-500 uppercase">QA Score</span></div><span className="text-xs font-black text-emerald-400">{stats.qa.toFixed(2)}%</span></div><div className="h-1 bg-slate-900 rounded-full overflow-hidden"><div className={`h-full ${Number(stats.qa) >= 90 ? 'bg-emerald-500' : 'bg-orange-500'}`} style={{ width: `${stats.qa}%` }}></div></div></div>
                <div className="grid grid-cols-2 gap-4 mt-2">
                  <div className="p-2.5 rounded-xl bg-slate-950/50 border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Rating</div><div className="text-sm font-black text-yellow-400">{stats.rating.toFixed(2)} ★</div></div>
                  <div className="p-2.5 rounded-xl bg-slate-950/50 border border-white/5"><div className="text-[8px] font-black text-slate-600 uppercase mb-1">Pax</div><div className="text-sm font-black text-indigo-400">{stats.covers}</div></div>
