                <div className="space-y-4 text-xs font-bold border-white/5 pb-2">
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Revenue</span>
                      <span className="text-white font-black">Rp {stats.sales.toLocaleString()}</span>
                   </div>
                   <div className="flex justify-between items-center text-slate-500 uppercase pb-2 border-b border-white/5">
                      <span>Covers</span>
                      <span className="text-white font-black">{stats.covers} Pax</span>
