import React, { useState, useEffect } from 'react';
import { SalesData, DailySalesData } from '../types';

interface Props {
  data: SalesData;
  dailyTargets: Record<string, number>;
  filters: { month: string; startDate: string; endDate: string };
  onUpdate: (v: SalesData) => void;
}

const SalesModule: React.FC<Props> = ({ data, dailyTargets, filters, onUpdate }) => {
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Sync Daily Target
  useEffect(() => {
    const autoTarget = dailyTargets[filters.startDate] || 0;
    if (autoTarget !== data.dailyTarget) {
      onUpdate({ ...data, dailyTarget: autoTarget });
    }
  }, [filters.startDate, dailyTargets, data.dailyTarget, onUpdate, data]);

  // Load Daily Data when date changes
  useEffect(() => {
    const dailyRecord = data.dailyRecording?.[filters.startDate];
    const recordedRevenue = dailyRecord?.revenue || 0;
    const recordedCovers = dailyRecord?.covers || 0;

    // Only update if current transient state doesn't match recorded state for this date
    if (recordedRevenue !== data.todayRevenue || recordedCovers !== data.todayCovers) {
       onUpdate({
         ...data,
         todayRevenue: recordedRevenue,
         todayCovers: recordedCovers
       });
    }
  }, [filters.startDate, data.dailyRecording]);

  const updateDailyData = (field: 'revenue' | 'covers', value: number) => {
    const currentRecord = data.dailyRecording?.[filters.startDate] || { revenue: 0, covers: 0 };
    const newRecord = { ...currentRecord, [field]: value };

    const newDailyRecording = {
      ...(data.dailyRecording || {}),
      [filters.startDate]: newRecord
    };

    // Calculate new totals (MTD)
    const newTotalRevenue = Object.values(newDailyRecording).reduce((acc: number, curr: DailySalesData) => acc + (Number(curr.revenue) || 0), 0);
    const newTotalCovers = Object.values(newDailyRecording).reduce((acc: number, curr: DailySalesData) => acc + (Number(curr.covers) || 0), 0);

    onUpdate({
      ...data,
      dailyRecording: newDailyRecording,
      revenue: newTotalRevenue,
      covers: newTotalCovers,
      todayRevenue: field === 'revenue' ? value : data.todayRevenue,
      todayCovers: field === 'covers' ? value : data.todayCovers
    });
  };

  // Computed Values (Today)
  const todayAvgCheck = data.todayCovers > 0 ? Math.floor(data.todayRevenue / data.todayCovers) : 0;
  const todayVariance = data.todayRevenue - data.dailyTarget;
  const todayPerformance = data.dailyTarget > 0 ? ((data.todayRevenue / data.dailyTarget) * 100).toFixed(2) : "0.00";

  // MTD Accumulated Logic - Calculated dynamically from daily recordings
  const currentMTDRevenue = (Object.values(data.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.revenue) || 0), 0);
  const currentMTDCover = (Object.values(data.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.covers) || 0), 0);
  const mtdAvgCheck = currentMTDCover > 0 ? Math.floor(currentMTDRevenue / currentMTDCover) : 0;

  const mtdVariance = currentMTDRevenue - data.budgetRevenue;
  const mtdPerformance = data.budgetRevenue > 0 ? ((currentMTDRevenue / data.budgetRevenue) * 100).toFixed(2) : "0.00";

  // MTD FORECAST & BUDGET LOGIC
  // "Remaining budget adalah nominal Budget revenue tanpa di kurangi"
  const mtdForecast = data.budgetRevenue; 
  const forecastVariance = data.budgetRevenue - currentMTDRevenue; 
  const forecastPerformance = mtdPerformance;

  const handleSubmitData = () => {
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      // Data is already saved via updateDailyData, just visual feedback
      alert(`Data tanggal ${filters.startDate} tersimpan.`);
    }, 500);
