  const MetricBox = ({ label, value, prefix = "", colorClass = "text-white", isCalc = false }: { label: string, value: string | number, prefix?: string, colorClass?: string, isCalc?: boolean }) => (
    <div className="flex justify-between items-center py-2.5 border-b border-white/5 group">
      <div className="flex flex-col">
        <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">{label}</span>
        {isCalc && <span className="text-[7px] text-indigo-500 font-bold uppercase tracking-tighter">KALKULASI</span>}
      </div>
      <span className={`text-sm font-black transition-all ${colorClass}`}>
        {prefix}{typeof value === 'number' ? value.toLocaleString() : value}
      </span>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      {/* Dynamic Summary Bar */}
