import React, { useState } from 'react';
import { OvertimeEntry, Staff } from '../types';
import { OT_RATE } from '../constants';

interface Props {
  data: OvertimeEntry[];
  staffList: Staff[]; // New Prop
  onUpdate: (v: OvertimeEntry[]) => void;
}

const OvertimeModule: React.FC<Props> = ({ data, staffList, onUpdate }) => {
  const [isSaving, setIsSaving] = useState(false);

  const handleChange = (staffId: string, field: keyof OvertimeEntry, val: number) => {
    // If entry doesn't exist yet, create it implicitly by updating state
    const existingEntry = data.find(d => d.staffId === staffId);
    let newData: OvertimeEntry[];

    if (existingEntry) {
      newData = data.map(item => 
        item.staffId === staffId ? { ...item, [field]: val } : item
      );
    } else {
      // Create new entry
      const newEntry: OvertimeEntry = {
        staffId,
        hours: 0,
        break1: 0,
        break2: 0,
        [field]: val
      };
      newData = [...data, newEntry];
    }
    onUpdate(newData);
  };

  const calculateTotalOT = (item: OvertimeEntry) => {
    // "Break 1+1 masing masing crew yang akan mengurangi jumlah overtime"
    const netHours = Math.max(0, item.hours - (item.break1 + item.break2));
    return netHours * OT_RATE;
  };

  const leaders = staffList.filter(s => s.isLeader);
  const crews = staffList.filter(s => !s.isLeader);

  const totalExpenses = data.reduce((acc, item) => acc + calculateTotalOT(item), 0);
  const totalHoursRaw = data.reduce((acc, item) => acc + item.hours, 0);
  const totalBreaks = data.reduce((acc, item) => acc + item.break1 + item.break2, 0);

  const handleSubmit = () => {
    setIsSaving(true);
    setTimeout(() => setIsSaving(false), 1000);
  };

  const StaffRow: React.FC<{ staff: Staff }> = ({ staff }) => {
    const entry = data.find(d => d.staffId === staff.id) || { staffId: staff.id, hours: 0, break1: 0, break2: 0 };
    const net = Math.max(0, entry.hours - (entry.break1 + entry.break2));
    return (
      <tr className="hover:bg-white/5 transition-colors group">
        <td className="p-4">
          <div className="font-black text-white group-hover:text-blue-400 transition-colors">{staff.name}</div>
          <div className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">{staff.role}</div>
        </td>
        <td className="p-4">
          <div className="flex items-center gap-2 bg-slate-900/50 rounded-xl px-3 py-2 border border-white/5 focus-within:border-blue-500 transition-all">
             <i className="fas fa-hourglass-start text-xs text-slate-600"></i>
             <input 
                type="number" 
                className="w-full bg-transparent border-none text-center text-sm outline-none font-bold"
                value={entry.hours || ''}
                onChange={(e) => handleChange(staff.id, 'hours', Number(e.target.value))}
              />
              <span className="text-[10px] text-slate-600 font-bold">Hrs</span>
          </div>
        </td>
        <td className="p-4">
           <div className="flex items-center gap-1 bg-slate-900/50 rounded-xl px-2 py-2 border border-white/5 focus-within:border-pink-500 transition-all">
             <input 
                type="number" 
                className="w-full bg-transparent border-none text-center text-sm outline-none font-bold"
                value={entry.break1 || ''}
                onChange={(e) => handleChange(staff.id, 'break1', Number(e.target.value))}
              />
              <span className="text-[10px] text-slate-600 font-bold">B1</span>
          </div>
        </td>
        <td className="p-4">
           <div className="flex items-center gap-1 bg-slate-900/50 rounded-xl px-2 py-2 border border-white/5 focus-within:border-pink-500 transition-all">
             <input 
                type="number" 
                className="w-full bg-transparent border-none text-center text-sm outline-none font-bold"
                value={entry.break2 || ''}
                onChange={(e) => handleChange(staff.id, 'break2', Number(e.target.value))}
              />
              <span className="text-[10px] text-slate-600 font-bold">B2</span>
          </div>
        </td>
        <td className="p-4 text-center">
            <div className={`text-xs font-black ${net > 0 ? 'text-blue-400' : 'text-slate-600'}`}>{net}h Net</div>
        </td>
        <td className="p-4 text-right font-black text-white">
          <div className="text-sm">Rp {calculateTotalOT(entry as any).toLocaleString()}</div>
        </td>
      </tr>
    );
  };

  return (
    <div className="space-y-6 animate-fade-in no-blur">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="md:col-span-2 glass-card p-6 border-l-4 border-blue-500 shadow-xl overflow-hidden relative">
          <div className="absolute top-0 right-0 p-8 opacity-5">
             <i className="fas fa-clock text-9xl"></i>
          </div>
          <div className="flex justify-between items-center mb-6 relative">
            <h2 className="text-xl font-black flex items-center gap-3">
              <i className="fas fa-business-time text-blue-400"></i>
              Staff Overtime Entry
            </h2>
            <div className="px-4 py-1.5 rounded-full bg-blue-500/10 border border-blue-500/30 text-[10px] font-black text-blue-400 uppercase">
              Rate: Rp 15.000 / Jam
            </div>
          </div>

          <div className="overflow-x-auto rounded-2xl border border-white/10 bg-slate-950/30">
            <table className="w-full text-left border-collapse">
              <thead className="bg-slate-800/80 text-slate-500 text-[10px] uppercase font-black tracking-widest">
                <tr>
                  <th className="p-4">Staff Name / Role</th>
                  <th className="p-4 text-center">Total OT (Hrs)</th>
                  <th className="p-4 text-center">Break 1</th>
                  <th className="p-4 text-center">Break 2</th>
                  <th className="p-4 text-center">Net OT</th>
                  <th className="p-4 text-right">Amount (IDR)</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-white/5">
                <tr className="bg-blue-500/5">
                  <td colSpan={6} className="p-2 px-4 text-[9px] font-black text-blue-400 uppercase tracking-tighter">Leader Section</td>
                </tr>
                {leaders.map(staff => <StaffRow key={staff.id} staff={staff} />)}
                <tr className="bg-purple-500/5">
                  <td colSpan={6} className="p-2 px-4 text-[9px] font-black text-purple-400 uppercase tracking-tighter">Crew Section</td>
                </tr>
                {crews.map(staff => <StaffRow key={staff.id} staff={staff} />)}
              </tbody>
            </table>
          </div>

          <div className="mt-6">
            <button 
              onClick={handleSubmit}
              disabled={isSaving}
              className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-95 border border-white/10 ${
                isSaving ? 'bg-slate-800 text-slate-600 cursor-wait' : 'bg-blue-600 hover:bg-blue-500 text-white'
              }`}
            >
              {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-save"></i>}
              {isSaving ? 'Saving Overtime...' : 'Submit Overtime Data'}
            </button>
          </div>
        </div>

        <div className="space-y-6">
           <div className="glass-card p-6 bg-gradient-to-br from-blue-600 to-indigo-800 text-white shadow-2xl border-none">
              <div className="text-[10px] font-black uppercase opacity-60 mb-1">Total Overtime Cost</div>
              <div className="text-4xl font-black mb-4">Rp {totalExpenses.toLocaleString()}</div>
              <div className="space-y-2 border-t border-white/10 pt-4">
                 <div className="flex justify-between items-center text-xs">
                    <span className="opacity-70">Gross Hours</span>
                    <span className="font-bold">{totalHoursRaw}h</span>
                 </div>
                 <div className="flex justify-between items-center text-xs">
                    <span className="opacity-70">Total Deducted Breaks</span>
                    <span className="font-bold text-pink-300">-{totalBreaks}h</span>
                 </div>
                 <div className="flex justify-between items-center text-xs border-t border-white/5 mt-2 pt-2 font-black">
                    <span>Final Net Hours</span>
                    <span className="text-blue-200">{totalHoursRaw - totalBreaks}h</span>
                 </div>
              </div>
           </div>

           <div className="glass-card p-6 border-l-4 border-amber-500">
              <h3 className="text-sm font-black uppercase text-slate-400 mb-4 flex items-center gap-2">
                 <i className="fas fa-info-circle text-amber-500"></i> Quick Summary
              </h3>
              <div className="space-y-4">
                 <div className="flex items-center justify-between">
                    <div className="text-[10px] font-bold text-slate-500 uppercase">Leader OT</div>
                    <div className="text-lg font-black">Rp {leaders.reduce((a,s) => {
                      const entry = data.find(d=>d.staffId===s.id) || { hours: 0, break1: 0, break2: 0, staffId: s.id };
                      return a + calculateTotalOT(entry);
                    },0).toLocaleString()}</div>
                 </div>
                 <div className="flex items-center justify-between">
                    <div className="text-[10px] font-bold text-slate-500 uppercase">Crew OT</div>
                    <div className="text-lg font-black">Rp {crews.reduce((a,s) => {
                      const entry = data.find(d=>d.staffId===s.id) || { hours: 0, break1: 0, break2: 0, staffId: s.id };
                      return a + calculateTotalOT(entry);
                    },0).toLocaleString()}</div>
                 </div>
                 <button onClick={() => window.print()} className="w-full py-3 bg-slate-800 hover:bg-slate-700 rounded-xl text-xs font-black uppercase tracking-wider transition-all mt-2 border border-white/5">
                    Print Attendance
                 </button>
              </div>
           </div>
        </div>
      </div>
    </div>
  );
};

export default OvertimeModule;

import React, { useState } from 'react';
