const GuestCommentModule: React.FC<Props> = ({ data, staffList, onUpdate }) => {
  const [isSaving, setIsSaving] = useState(false);

  const handleChange = (staffId: string, val: number) => {
    // Check if entry exists, if not create logic (similar to Overtime)
    const existing = data.find(d => d.staffId === staffId);
    let newData: GuestCommentEntry[];

    if (existing) {
      newData = data.map(d => d.staffId === staffId ? { ...d, achievement: val } : d);
    } else {
      newData = [...data, { staffId, achievement: val }];
    }
    onUpdate(newData);
  };

  const totalAch = data.reduce((acc, curr) => acc + curr.achievement, 0);

  const handleSubmit = () => {
    setIsSaving(true);
    setTimeout(() => setIsSaving(false), 1000);
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="glass-card p-8 border-l-4 border-pink-500 bg-[#1e293b]/95 shadow-2xl relative overflow-hidden">
