           <i className="fas fa-comments text-[180px]"></i>
        </div>

        <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 mb-10 relative z-10">
          <div>
            <h2 className="text-3xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-4">
              <i className="fas fa-comment-alt text-pink-400"></i>
              Guest Comment Tracker
            </h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-widest">Monitoring Mention & Achievement Crew</p>
          </div>
          <div className="text-right p-6 bg-slate-950/80 border border-white/5 rounded-2xl shadow-xl min-w-[220px]">
            <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Total Achievements</div>
            <div className="text-4xl font-black text-pink-400">{totalAch} <span className="text-xs text-slate-600 font-bold uppercase tracking-widest">Mentions</span></div>
          </div>
        </div>

        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 mb-10 relative z-10">
          {staffList.map(staff => {
            const entry = data.find(d => d.staffId === staff.id) || { achievement: 0 };
            return (
              <div key={staff.id} className="p-5 rounded-2xl bg-slate-900 border border-white/5 hover:border-pink-500/30 transition-all group shadow-lg">
                <div className="text-[8px] font-black text-slate-600 uppercase mb-1 tracking-widest">{staff.role}</div>
                <div className="font-black text-white mb-4 group-hover:text-pink-400 transition-colors uppercase text-xs">{staff.name}</div>
                <div className="flex items-center gap-3 bg-slate-950 p-3 rounded-xl border border-white/5 focus-within:ring-1 ring-pink-500">
                  <i className="fas fa-award text-[10px] text-slate-700"></i>
                  <input 
                    type="number"
                    className="flex-1 bg-transparent border-none text-center font-black outline-none text-white text-sm"
                    value={entry.achievement || ''}
                    placeholder="0"
                    onChange={(e) => handleChange(staff.id, Number(e.target.value))}
                  />
                </div>
              </div>
            );
          })}
        </div>

        <button 
          onClick={handleSubmit}
          disabled={isSaving}
          className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-95 border border-white/10 ${
            isSaving ? 'bg-slate-800 text-slate-600 cursor-wait' : 'bg-pink-600 hover:bg-pink-500 text-white'
          }`}
        >
          {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-save"></i>}
          {isSaving ? 'Saving Achievements...' : 'Submit Achievement Data'}
        </button>
      </div>
    </div>
  );
};

