                {/* WBP Card */}
                <div className="bg-slate-900/50 p-6 rounded-2xl border border-orange-500/30 relative overflow-hidden group hover:border-orange-500/60 transition-colors">
                  <div className="absolute top-0 right-0 p-2 opacity-10"><i className="fas fa-sun text-6xl text-orange-500"></i></div>
                  <h3 className="text-sm font-black uppercase text-orange-400 mb-4 tracking-widest border-b border-orange-500/20 pb-2 flex items-center gap-2">
                    <i className="fas fa-sun"></i> WBP (Waktu Beban Puncak)
                  </h3>
                  <div className="grid grid-cols-2 gap-4 mb-4">
                     <div className="space-y-1">
                        <label className="text-[8px] font-black text-slate-500 uppercase">Open Kwh</label>
                        <input type="number" className="w-full bg-slate-950 border border-white/10 rounded-lg p-2 text-xs font-bold text-white focus:border-orange-500 outline-none" 
