                  <div className="space-y-2 bg-slate-950/30 p-3 rounded-xl border border-white/5">
                     <ElecRow label="Usage" val={Math.max(0, elecDetails.wbpClose - elecDetails.wbpOpen)} isCurrency={false} />
                     <ElecRow label="Biaya (x1499.7)" val={Math.max(0, elecDetails.wbpClose - elecDetails.wbpOpen) * KWH_RATE} />
                  </div>
