                    <div>
                      <div className="text-[9px] font-bold text-slate-500 uppercase mb-1">PPJU (3.7%)</div>
                      <div className="text-xl font-black text-blue-400">Rp {(((Math.max(0, elecDetails.lwbpClose - elecDetails.lwbpOpen) * KWH_RATE) + (Math.max(0, elecDetails.wbpClose - elecDetails.wbpOpen) * KWH_RATE)) * PPJU_RATE).toLocaleString(undefined, {maximumFractionDigits:0})}</div>
                    </div>
                    <div>
                      <div className="text-[9px] font-bold text-slate-500 uppercase mb-1">Maintenance (7%)</div>
                      <div className="text-xl font-black text-pink-400">Rp {(((Math.max(0, elecDetails.lwbpClose - elecDetails.lwbpOpen) * KWH_RATE) + (Math.max(0, elecDetails.wbpClose - elecDetails.wbpOpen) * KWH_RATE)) * MAINT_RATE).toLocaleString(undefined, {maximumFractionDigits:0})}</div>
                    </div>
                    <div className="bg-white/5 rounded-xl p-2 border border-white/10">
                      <div className="text-[9px] font-bold text-emerald-400 uppercase mb-1">GRAND TOTAL LISTRIK</div>
