            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 relative z-10">
              {/* Only map simple inputs for OPEX and LOST_BREAKAGE. For ENERGY, only map Water and Gas (Electricity is handled above) */}
