export default ExpensesModule;

import React, { useState, useEffect } from 'react';
import { AppState, LedgerItem } from '../types';

interface Props {
  data: AppState;
  onUpdate: (v: any) => void;
}

const ExpensesModule: React.FC<Props> = ({ data, onUpdate }) => {
  const [activeSub, setActiveSub] = useState<'OPEX' | 'ENERGY' | 'LOST_BREAKAGE' | 'CITY' | 'SAT' | 'COMP'>('OPEX');
  const [isSaving, setIsSaving] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  // State untuk Kalkulator Listrik
  const [elecDetails, setElecDetails] = useState({
    lwbpOpen: 0, lwbpClose: 0,
    wbpOpen: 0, wbpClose: 0
  });

  // Constants Listrik
  const KWH_RATE = 1499.7;
  const PPJU_RATE = 0.037; // 3.70%
  const MAINT_RATE = 0.07; // 7%

  // Efek samping untuk menghitung total listrik saat input berubah
  useEffect(() => {
    if (activeSub === 'ENERGY') {
      const lwbpUsage = Math.max(0, elecDetails.lwbpClose - elecDetails.lwbpOpen);
      const wbpUsage = Math.max(0, elecDetails.wbpClose - elecDetails.wbpOpen);

      const lwbpBase = lwbpUsage * KWH_RATE;
      const wbpBase = wbpUsage * KWH_RATE;

      const totalBase = lwbpBase + wbpBase;
      const ppju = totalBase * PPJU_RATE;
      const maint = totalBase * MAINT_RATE;

      const grandTotal = totalBase + ppju + maint;

      // Update global state hanya jika berbeda (mencegah infinite loop)
      if (Math.floor(data.expenses.electricity) !== Math.floor(grandTotal)) {
        onUpdate((prev: AppState) => ({
          ...prev,
          expenses: { ...prev.expenses, electricity: Math.floor(grandTotal) }
        }));
      }
    }
  }, [elecDetails, activeSub, data.expenses.electricity, onUpdate]);

  const handleSave = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
    }, 800);
  };

  const updateLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', item: LedgerItem) => {
    onUpdate((prev: AppState) => {
      const newList = [...prev[key], { ...item, id: Date.now().toString() }];
      return { ...prev, [key]: newList };
    });
  };

  const removeLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', index: number) => {
    onUpdate((prev: AppState) => {
      const newList = prev[key].filter((_, i) => i !== index);
      return { ...prev, [key]: newList };
    });
  };

  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];
  const otherEnergyKeys = ['water', 'gas']; 
  const energyKeys = ['electricity', 'water', 'gas']; 
