export default ExpensesModule;

import React, { useState, useEffect } from 'react';
import { AppState, LedgerItem } from '../types';

interface Props {
  data: AppState;
  onUpdate: (v: any) => void;
}

const ExpensesModule: React.FC<Props> = ({ data, onUpdate }) => {
  const [activeSub, setActiveSub] = useState<'OPEX' | 'ENERGY' | 'LOST_BREAKAGE' | 'CITY' | 'SAT' | 'COMP'>('OPEX');
  const [isSaving, setIsSaving] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  // State untuk Kalkulator Energi Detail
  const [energyDetails, setEnergyDetails] = useState({
    elecKwh: { lwbpOpen: 0, lwbpClose: 0, wbpOpen: 0, wbpClose: 0 },
    elecM3: { open: 0, close: 0 },
    gasM3: { open: 0, close: 0 }
  });

  // Constants Tarif
  const KWH_RATE = 1499.7;
  const M3_ELEC_RATE = 21250;
  const M3_GAS_RATE = 22000;
  const PPJU_RATE = 0.037; // 3.70%
  const MAINT_RATE = 0.07; // 7%

  // Efek samping untuk sinkronisasi total biaya energi ke state global
  useEffect(() => {
    if (activeSub === 'ENERGY') {
      // 1. Kalkulasi Listrik KWh (LWBP + WBP)
      const lwbpUsage = Math.max(0, energyDetails.elecKwh.lwbpClose - energyDetails.elecKwh.lwbpOpen);
      const wbpUsage = Math.max(0, energyDetails.elecKwh.wbpClose - energyDetails.elecKwh.wbpOpen);
      const kwhBase = (lwbpUsage + wbpUsage) * KWH_RATE;
      const kwhPpju = kwhBase * PPJU_RATE;
      const kwhMaint = kwhBase * MAINT_RATE;
      const totalKwh = kwhBase + kwhPpju + kwhMaint;

      // 2. Kalkulasi Listrik m³
      const elecM3Usage = Math.max(0, energyDetails.elecM3.close - energyDetails.elecM3.open);
      const totalElecM3 = elecM3Usage * M3_ELEC_RATE;

      // 3. Kalkulasi Gas Meter m³
      const gasUsage = Math.max(0, energyDetails.gasM3.close - energyDetails.gasM3.open);
      const totalGas = gasUsage * M3_GAS_RATE;

      // Gabungkan semua komponen Listrik (KWh + m³) ke expenses.electricity
      const combinedElec = Math.floor(totalKwh + totalElecM3);
      const finalGas = Math.floor(totalGas);

      // Update jika ada perubahan signifikan
      if (Math.floor(data.expenses.electricity) !== combinedElec || Math.floor(data.expenses.gas) !== finalGas) {
        onUpdate((prev: AppState) => ({
          ...prev,
          expenses: { 
            ...prev.expenses, 
            electricity: combinedElec,
            gas: finalGas
          }
        }));
      }
    }
  }, [energyDetails, activeSub, data.expenses.electricity, data.expenses.gas, onUpdate]);

  const handleSave = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
    }, 800);
  };

  const updateLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', item: LedgerItem) => {
    onUpdate((prev: AppState) => {
      const newList = [...prev[key], { ...item, id: Date.now().toString() }];
      return { ...prev, [key]: newList };
    });
  };

  const removeLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', index: number) => {
    onUpdate((prev: AppState) => {
      const newList = prev[key].filter((_, i) => i !== index);
      return { ...prev, [key]: newList };
    });
  };

  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];
  const lostBreakageKeys = ['lostBreakageBar', 'lostBreakageKitchen', 'lostBreakageService'];

  const totalOpex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalEnergy = data.expenses.electricity + data.expenses.water + data.expenses.gas;
  const totalLostBreakage = lostBreakageKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);

  const EnergyCard = ({ title, icon, color, children }: { title: string, icon: string, color: string, children: React.ReactNode }) => (
