              {/* WATER (SISA INPUT MANUAL JIKA DIBUTUHKAN) */}
              <div className="p-6 rounded-2xl bg-slate-900 border border-white/5 flex flex-col justify-center">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">Manual Water Adjustment / Cost</label>
                <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5 focus-within:ring-2 ring-indigo-500">
                  <span className="text-slate-700 font-black">Rp</span>
                  <input type="number" className="flex-1 bg-transparent text-xl font-black outline-none text-white" placeholder="0"
                    value={data.expenses.water || ''} onChange={e => onUpdate((p: AppState) => ({...p, expenses: {...p.expenses, water: Number(e.target.value)}}))} />
                </div>
