  <div className="flex justify-between items-center py-1.5 border-b border-white/5 text-[10px]">
    <span className="text-slate-500 font-bold uppercase tracking-wider">{label}</span>
    <span className="text-white font-black">
      {unit === "Rp" ? `Rp ${val.toLocaleString()}` : `${val.toLocaleString()} ${unit}`}
    </span>
  </div>
);

