                  <MetricRow label="PPJU (3.7%)" val={((Math.max(0, energyDetails.elecKwh.lwbpClose - energyDetails.elecKwh.lwbpOpen) + Math.max(0, energyDetails.elecKwh.wbpClose - energyDetails.elecKwh.wbpOpen)) * KWH_RATE) * PPJU_RATE} />
