        {activeSub === 'SAT' && <LedgerTable title="Cust. Satisfaction Ledger" dataKey="customerSat" icon="fa-smile-beam" colorClass="text-yellow-400" data={data} updateLedger={updateLedger} removeLedger={removeLedger} />}
        {activeSub === 'COMP' && <LedgerTable title="Complimentary Ledger" dataKey="complimentary" icon="fa-gift" colorClass="text-pink-400" data={data} updateLedger={updateLedger} removeLedger={removeLedger} />}
      </div>
    </div>
  );
};

