const EnergyCard = ({ title, icon, color, children }: { title: string, icon: string, color: string, children: React.ReactNode }) => (
  <div className={`bg-slate-900/50 p-6 rounded-2xl border ${color} relative overflow-hidden transition-all shadow-xl group`}>
    <div className="absolute top-0 right-0 p-4 opacity-5 group-hover:opacity-10 transition-opacity">
      <i className={`fas ${icon} text-6xl`}></i>
    </div>
    <h3 className={`text-sm font-black uppercase mb-6 tracking-widest border-b pb-2 flex items-center gap-3 ${color.replace('border-', 'text-')}`}>
      <i className={`fas ${icon}`}></i> {title}
    </h3>
    {children}
  </div>
);

const MetricRow = ({ label, val, unit = "Rp", precision = 0 }: { label: string, val: number, unit?: string, precision?: number }) => (
  <div className="flex justify-between items-center py-1.5 border-b border-white/5 text-[10px]">
    <span className="text-slate-500 font-bold uppercase tracking-wider">{label}</span>
    <span className="text-white font-black">
      {unit === "Rp" 
        ? `Rp ${val.toLocaleString(undefined, { minimumFractionDigits: precision, maximumFractionDigits: precision })}` 
        : `${val.toLocaleString(undefined, { minimumFractionDigits: precision, maximumFractionDigits: precision })} ${unit}`}
    </span>
  </div>
);

interface LedgerTableProps {
  title: string;
  dataKey: 'cityLedger' | 'customerSat' | 'complimentary';
  icon: string;
  colorClass: string;
  data: AppState;
  updateLedger: (key: any, item: LedgerItem) => void;
  removeLedger: (key: any, index: number) => void;
}

const LedgerTable = ({ title, dataKey, icon, colorClass, data, updateLedger, removeLedger }: LedgerTableProps) => {
  const [newItem, setNewItem] = useState<Partial<LedgerItem>>({ name: '', qty: 1, price: 0, reason: '', pic: '' });
  const [isAdding, setIsAdding] = useState(false);

  const handleAdd = () => {
    if (newItem.name && newItem.price && newItem.price > 0) {
      setIsAdding(true);
      setTimeout(() => {
        updateLedger(dataKey, newItem as LedgerItem);
        setNewItem({ name: '', qty: 1, price: 0, reason: '', pic: '' });
        setIsAdding(false);
      }, 500);
    } else {
      alert("Harap isi Nama Item dan Harga yang valid.");
    }
  };

  return (
    <div className="space-y-6 animate-fade-in no-blur">
      <div className="flex justify-between items-center">
        <h3 className={`text-xl font-black flex items-center gap-3 uppercase tracking-tight ${colorClass}`}>
          <i className={`fas ${icon}`}></i> {title}
        </h3>
        <div className="text-[9px] font-black uppercase text-slate-500 bg-white/5 px-3 py-1 rounded-full border border-white/10">
          {data[dataKey].length} Entri Tercatat
        </div>
      </div>

      <div className="glass-card p-6 grid grid-cols-1 md:grid-cols-12 gap-4 items-end bg-slate-900/80 border-white/10 shadow-2xl">
        <div className="md:col-span-3">
          <label className="text-[10px] font-black text-slate-500 uppercase mb-2 block tracking-widest">Item Name</label>
          <input 
            placeholder="Nama item..."
            className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-sm font-bold focus:ring-2 ring-indigo-500 outline-none" 
            value={newItem.name} 
            onChange={e => setNewItem({...newItem, name: e.target.value})} 
          />
        </div>
        <div className="md:col-span-1">
          <label className="text-[10px] font-black text-slate-500 uppercase mb-2 block tracking-widest text-center">Qty</label>
          <input 
            type="number" 
            className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-sm font-bold focus:ring-2 ring-indigo-500 outline-none text-center" 
            value={newItem.qty} 
            onChange={e => setNewItem({...newItem, qty: Number(e.target.value)})} 
          />
        </div>
        <div className="md:col-span-2">
          <label className="text-[10px] font-black text-slate-500 uppercase mb-2 block tracking-widest">Unit Price</label>
          <input 
            type="number" 
            placeholder="0"
            className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-sm font-bold focus:ring-2 ring-indigo-500 outline-none" 
            value={newItem.price === 0 ? '' : newItem.price} 
            onChange={e => setNewItem({...newItem, price: Number(e.target.value)})} 
          />
        </div>
        <div className="md:col-span-3">
          <label className="text-[10px] font-black text-slate-500 uppercase mb-2 block tracking-widest">Catatan / Keterangan</label>
          <input 
            placeholder="Alasan / Catatan..."
            className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-sm font-bold focus:ring-2 ring-indigo-500 outline-none" 
            value={newItem.reason} 
            onChange={e => setNewItem({...newItem, reason: e.target.value})} 
          />
        </div>
        <div className="md:col-span-1">
          <label className="text-[10px] font-black text-slate-500 uppercase mb-2 block tracking-widest">PIC</label>
          <input 
            placeholder="PIC"
            className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-sm font-bold focus:ring-2 ring-indigo-500 outline-none" 
            value={newItem.pic} 
            onChange={e => setNewItem({...newItem, pic: e.target.value})} 
          />
        </div>
        <div className="md:col-span-2">
          <button 
            onClick={handleAdd}
            disabled={isAdding}
            className="w-full py-3.5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-xl font-black text-xs uppercase tracking-widest transition-all shadow-lg active:scale-95 border border-white/10"
          >
            {isAdding ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-plus"></i>} Tambah
          </button>
        </div>
      </div>

      <div className="overflow-x-auto rounded-2xl border border-white/10 bg-slate-950/50">
        <table className="w-full text-left">
          <thead className="bg-slate-900/50 text-slate-500 font-black uppercase text-[9px] tracking-widest">
            <tr>
              <th className="p-5">Deskripsi Item</th>
              <th className="p-5 text-center">Qty</th>
              <th className="p-5 text-right">Harga Satuan</th>
              <th className="p-5 text-right">Total</th>
              <th className="p-5">Catatan</th>
              <th className="p-5">PIC</th>
              <th className="p-5 text-center">Aksi</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {data[dataKey].map((item, idx) => (
              <tr key={item.id} className="hover:bg-white/5 transition-colors">
                <td className="p-5 font-bold text-white uppercase text-xs">{item.name}</td>
                <td className="p-5 text-center text-slate-400 font-bold">{item.qty}</td>
                <td className="p-5 text-right text-slate-500">Rp {item.price.toLocaleString()}</td>
                <td className="p-5 text-right font-black text-white">Rp {(item.qty * item.price).toLocaleString()}</td>
                <td className="p-5 text-xs text-slate-400 italic max-w-[200px] truncate">{item.reason || '-'}</td>
                <td className="p-5 font-black text-indigo-400 uppercase text-[9px]">{item.pic || '-'}</td>
                <td className="p-5 text-center">
                  <button onClick={() => removeLedger(dataKey, idx)} className="text-red-500 hover:text-red-400 p-2"><i className="fas fa-trash-alt"></i></button>
                </td>
              </tr>
            ))}
            {data[dataKey].length === 0 && (
              <tr><td colSpan={7} className="p-10 text-center text-slate-600 font-black uppercase text-xs">Belum Ada Data</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
};

const ExpensesModule: React.FC<Props> = ({ data, onUpdate }) => {
  const [activeSub, setActiveSub] = useState<'OPEX' | 'ENERGY' | 'LOST_BREAKAGE' | 'CITY' | 'SAT' | 'COMP'>('OPEX');
  const [isSaving, setIsSaving] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  // State untuk Kalkulator Energi Detail
  const [energyDetails, setEnergyDetails] = useState({
    elecKwh: { lwbpOpen: 0, lwbpClose: 0, wbpOpen: 0, wbpClose: 0 },
    elecM3: { open: 0, close: 0 },
    gasM3: { open: 0, close: 0 }
  });

  // Constants Tarif
  const KWH_RATE = 1499.7;
  const M3_ELEC_RATE = 21250;
  const M3_GAS_RATE = 22000;
  const PPJU_RATE = 0.037; // 3.70%
  const MAINT_RATE = 0.07; // 7%

  // Efek samping untuk sinkronisasi total biaya energi ke state global
  useEffect(() => {
    if (activeSub === 'ENERGY') {
      const lwbpUsage = Math.max(0, energyDetails.elecKwh.lwbpClose - energyDetails.elecKwh.lwbpOpen);
      const wbpUsage = Math.max(0, energyDetails.elecKwh.wbpClose - energyDetails.elecKwh.wbpOpen);
      const kwhBase = (lwbpUsage + wbpUsage) * KWH_RATE;
      const kwhPpju = kwhBase * PPJU_RATE;
      const kwhMaint = kwhBase * MAINT_RATE;
      const totalKwh = kwhBase + kwhPpju + kwhMaint;

      const elecM3Usage = Math.max(0, energyDetails.elecM3.close - energyDetails.elecM3.open);
      const totalElecM3 = elecM3Usage * M3_ELEC_RATE;

      const gasUsage = Math.max(0, energyDetails.gasM3.close - energyDetails.gasM3.open);
      const totalGas = gasUsage * M3_GAS_RATE;

      const combinedElec = totalKwh + totalElecM3;
      const finalGas = totalGas;

      // Sinkronisasi data ke state global (tetap simpan angka asli/bulat sesuai kebutuhan database, tapi tampilan akan diatur via toFixed(3))
      if (data.expenses.electricity !== combinedElec || data.expenses.gas !== finalGas) {
        onUpdate((prev: AppState) => ({
          ...prev,
          expenses: { 
            ...prev.expenses, 
            electricity: combinedElec,
            gas: finalGas
          }
        }));
      }
    }
  }, [energyDetails, activeSub, onUpdate, data.expenses.electricity, data.expenses.gas]);

  const handleSave = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
    }, 800);
  };

  const updateLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', item: LedgerItem) => {
    onUpdate((prev: AppState) => {
      const newList = [...prev[key], { ...item, id: Date.now().toString() }];
      return { ...prev, [key]: newList };
    });
  };

  const removeLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', index: number) => {
    onUpdate((prev: AppState) => {
      const newList = prev[key].filter((_, i) => i !== index);
      return { ...prev, [key]: newList };
    });
  };

  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];
  const lostBreakageKeys = ['lostBreakageBar', 'lostBreakageKitchen', 'lostBreakageService'];

  const totalOpex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalEnergy = data.expenses.electricity + data.expenses.water + data.expenses.gas;
  const totalLostBreakage = lostBreakageKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
        {[
          { id: 'OPEX', label: 'Operational Expense', icon: 'fa-file-invoice-dollar' },
          { id: 'ENERGY', label: 'Energy Costs', icon: 'fa-bolt' },
          { id: 'LOST_BREAKAGE', label: 'Lost & Breakage', icon: 'fa-trash-restore' },
          { id: 'CITY', label: 'City Ledger', icon: 'fa-building' },
          { id: 'SAT', label: 'Customer Satisfaction', icon: 'fa-smile-beam' },
          { id: 'COMP', label: 'Complimentary', icon: 'fa-gift' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveSub(tab.id as any)}
            className={`px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest whitespace-nowrap transition-all flex items-center gap-3 border ${
              activeSub === tab.id ? 'purple-gradient-bg text-white border-white/20' : 'bg-slate-800 text-slate-500 border-white/5 hover:border-white/20'
            }`}
          >
            <i className={`fas ${tab.icon} text-xs`}></i> {tab.label}
          </button>
        ))}
      </div>

      <div className="glass-card p-8 border-l-4 shadow-2xl relative overflow-hidden bg-[#1e293b]/95 border-indigo-500">
        {activeSub === 'ENERGY' && (
          <div className="space-y-10 animate-fade-in relative z-10">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
              <div>
                <h2 className="text-3xl font-black text-white uppercase tracking-tighter flex items-center gap-4">
                  <i className="fas fa-plug text-yellow-500"></i> Energy Cost Calculation
                </h2>
                <p className="text-slate-500 text-[9px] font-black uppercase tracking-widest mt-2">Kalkulasi biaya listrik (KWh & m³) dan Gas</p>
              </div>
              <div className="text-right p-6 rounded-2xl bg-slate-950/80 border border-white/5 shadow-2xl min-w-[280px]">
                <div className="text-[10px] text-slate-500 font-black uppercase mb-2">Total Energy Cost (Monthly)</div>
                <div className="text-4xl font-black text-white">Rp {totalEnergy.toLocaleString(undefined, { minimumFractionDigits: 3, maximumFractionDigits: 3 })}</div>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <EnergyCard title="Listrik KWh (LWBP & WBP)" icon="fa-moon" color="border-cyan-500/30">
                <div className="grid grid-cols-2 gap-6 mb-6">
                  <div className="space-y-4">
                    <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest">LWBP Section</label>
                    <div className="grid grid-cols-2 gap-2">
                      <input type="number" placeholder="Open" className="bg-slate-950 border border-white/5 p-2 rounded text-xs font-bold" 
                        value={energyDetails.elecKwh.lwbpOpen || ''} 
                        onChange={e => setEnergyDetails({...energyDetails, elecKwh: {...energyDetails.elecKwh, lwbpOpen: Number(e.target.value)}})} />
                      <input type="number" placeholder="Close" className="bg-slate-950 border border-white/5 p-2 rounded text-xs font-bold" 
                        value={energyDetails.elecKwh.lwbpClose || ''} 
                        onChange={e => setEnergyDetails({...energyDetails, elecKwh: {...energyDetails.elecKwh, lwbpClose: Number(e.target.value)}})} />
                    </div>
                  </div>
                  <div className="space-y-4">
                    <label className="text-[9px] font-black text-orange-400 uppercase tracking-widest">WBP Section</label>
                    <div className="grid grid-cols-2 gap-2">
                      <input type="number" placeholder="Open" className="bg-slate-950 border border-white/5 p-2 rounded text-xs font-bold" 
                        value={energyDetails.elecKwh.wbpOpen || ''} 
                        onChange={e => setEnergyDetails({...energyDetails, elecKwh: {...energyDetails.elecKwh, wbpOpen: Number(e.target.value)}})} />
                      <input type="number" placeholder="Close" className="bg-slate-950 border border-white/5 p-2 rounded text-xs font-bold" 
                        value={energyDetails.elecKwh.wbpClose || ''} 
                        onChange={e => setEnergyDetails({...energyDetails, elecKwh: {...energyDetails.elecKwh, wbpClose: Number(e.target.value)}})} />
                    </div>
                  </div>
                </div>
                <div className="bg-slate-950/40 p-4 rounded-xl space-y-2">
                  <MetricRow label="Usage LWBP" val={Math.max(0, energyDetails.elecKwh.lwbpClose - energyDetails.elecKwh.lwbpOpen)} unit="KWh" precision={3} />
                  <MetricRow label="Usage WBP" val={Math.max(0, energyDetails.elecKwh.wbpClose - energyDetails.elecKwh.wbpOpen)} unit="KWh" precision={3} />
                  <MetricRow label="PPJU (3.7%)" val={((Math.max(0, energyDetails.elecKwh.lwbpClose - energyDetails.elecKwh.lwbpOpen) + Math.max(0, energyDetails.elecKwh.wbpClose - energyDetails.elecKwh.wbpOpen)) * KWH_RATE) * PPJU_RATE} precision={3} />
                  <MetricRow label="Maintenance (7%)" val={((Math.max(0, energyDetails.elecKwh.lwbpClose - energyDetails.elecKwh.lwbpOpen) + Math.max(0, energyDetails.elecKwh.wbpClose - energyDetails.elecKwh.wbpOpen)) * KWH_RATE) * MAINT_RATE} precision={3} />
                  <div className="pt-2 border-t border-white/10 flex justify-between font-black text-cyan-400 text-xs uppercase">
                    <span>Total Cost KWh</span>
                    <span>Rp {(((Math.max(0, energyDetails.elecKwh.lwbpClose - energyDetails.elecKwh.lwbpOpen) + Math.max(0, energyDetails.elecKwh.wbpClose - energyDetails.elecKwh.wbpOpen)) * KWH_RATE) * (1 + PPJU_RATE + MAINT_RATE)).toLocaleString(undefined, { minimumFractionDigits: 3, maximumFractionDigits: 3 })}</span>
                  </div>
                </div>
              </EnergyCard>

              <EnergyCard title="Listrik m³ (Rp 21.250)" icon="fa-tint" color="border-blue-500/30">
                <div className="grid grid-cols-2 gap-4 mb-6">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-slate-500 uppercase">Open m³</label>
                    <input type="number" className="w-full bg-slate-950 border border-white/5 p-3 rounded-xl text-xs font-bold" 
                      value={energyDetails.elecM3.open || ''} 
                      onChange={e => setEnergyDetails({...energyDetails, elecM3: {...energyDetails.elecM3, open: Number(e.target.value)}})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-slate-500 uppercase">Close m³</label>
                    <input type="number" className="w-full bg-slate-950 border border-white/5 p-3 rounded-xl text-xs font-bold" 
                      value={energyDetails.elecM3.close || ''} 
                      onChange={e => setEnergyDetails({...energyDetails, elecM3: {...energyDetails.elecM3, close: Number(e.target.value)}})} />
                  </div>
                </div>
                <div className="bg-slate-950/40 p-4 rounded-xl space-y-2">
                  <MetricRow label="Usage m³" val={Math.max(0, energyDetails.elecM3.close - energyDetails.elecM3.open)} unit="m³" precision={3} />
                  <MetricRow label="Rate Per Unit" val={M3_ELEC_RATE} precision={3} />
                  <div className="pt-2 border-t border-white/10 flex justify-between font-black text-blue-400 text-xs uppercase">
                    <span>Total Cost m³</span>
                    <span>Rp {(Math.max(0, energyDetails.elecM3.close - energyDetails.elecM3.open) * M3_ELEC_RATE).toLocaleString(undefined, { minimumFractionDigits: 3, maximumFractionDigits: 3 })}</span>
                  </div>
                </div>
              </EnergyCard>

              <EnergyCard title="Gas Meter m³ (Rp 22.000)" icon="fa-fire-alt" color="border-red-500/30">
                <div className="grid grid-cols-2 gap-4 mb-6">
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-slate-500 uppercase">Open Gas (m³)</label>
                    <input type="number" className="w-full bg-slate-950 border border-white/5 p-3 rounded-xl text-xs font-bold" 
                      value={energyDetails.gasM3.open || ''} 
                      onChange={e => setEnergyDetails({...energyDetails, gasM3: {...energyDetails.gasM3, open: Number(e.target.value)}})} />
                  </div>
                  <div className="space-y-2">
                    <label className="text-[9px] font-black text-slate-500 uppercase">Close Gas (m³)</label>
                    <input type="number" className="w-full bg-slate-950 border border-white/5 p-3 rounded-xl text-xs font-bold" 
                      value={energyDetails.gasM3.close || ''} 
                      onChange={e => setEnergyDetails({...energyDetails, gasM3: {...energyDetails.gasM3, close: Number(e.target.value)}})} />
                  </div>
                </div>
                <div className="bg-slate-950/40 p-4 rounded-xl space-y-2">
                  <MetricRow label="Usage Gas" val={Math.max(0, energyDetails.gasM3.close - energyDetails.gasM3.open)} unit="m³" precision={3} />
                  <MetricRow label="Rate Per Unit" val={M3_GAS_RATE} precision={3} />
                  <div className="pt-2 border-t border-white/10 flex justify-between font-black text-red-400 text-xs uppercase">
                    <span>Total Cost Gas</span>
                    <span>Rp {(Math.max(0, energyDetails.gasM3.close - energyDetails.gasM3.open) * M3_GAS_RATE).toLocaleString(undefined, { minimumFractionDigits: 3, maximumFractionDigits: 3 })}</span>
                  </div>
                </div>
              </EnergyCard>

              <div className="p-6 rounded-2xl bg-slate-900 border border-white/5 flex flex-col justify-center">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-4">Manual Water Adjustment / Cost</label>
                <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5 focus-within:ring-2 ring-indigo-500">
                  <span className="text-slate-700 font-black text-[10px]">Rp</span>
                  <input type="number" className="flex-1 bg-transparent text-xl font-black outline-none text-white" placeholder="0"
                    value={data.expenses.water || ''} 
                    onChange={e => onUpdate((p: AppState) => ({...p, expenses: {...p.expenses, water: Number(e.target.value)}}))} />
                </div>
                <div className="mt-2 text-[10px] text-right font-black text-white">
                  = Rp {(data.expenses.water || 0).toLocaleString(undefined, { minimumFractionDigits: 3, maximumFractionDigits: 3 })}
                </div>
              </div>
            </div>

            <div className="flex flex-col items-center gap-4 pt-6">
              <button 
                onClick={handleSave}
