                className={`px-16 py-4 rounded-2xl font-black uppercase tracking-widest text-xs transition-all shadow-2xl border active:scale-95 flex items-center gap-4 ${
                  showSuccess ? 'bg-emerald-600 border-emerald-400 text-white' : 'bg-indigo-600 border-white/10 text-white hover:bg-indigo-500'
                }`}
              >
                {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : (showSuccess ? <i className="fas fa-check-circle"></i> : <i className="fas fa-save"></i>)}
                {isSaving ? 'Menyimpan...' : (showSuccess ? 'Berhasil Tersimpan' : 'Simpan Seluruh Data Energi')}
              </button>
            </div>
          </div>
        )}

        {(activeSub === 'OPEX' || activeSub === 'LOST_BREAKAGE') && (
          <div className="space-y-10 animate-fade-in relative z-10">
