            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {(activeSub === 'OPEX' ? opexKeys : lostBreakageKeys).map(key => (
                <div key={key} className="p-6 rounded-2xl bg-slate-900 border border-white/5 transition-all shadow-lg hover:border-indigo-500/30">
