                </div>
              ))}
            </div>
            <div className="flex justify-center pt-6">
              <button onClick={handleSave} className="px-16 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase text-xs tracking-widest transition-all">
                {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : 'Simpan Data'}
              </button>
            </div>
          </div>
        )}

        {activeSub === 'CITY' && <LedgerTable title="City Ledger Tracking" dataKey="cityLedger" icon="fa-building" colorClass="text-blue-400" data={data} updateLedger={updateLedger} removeLedger={removeLedger} />}
        {activeSub === 'SAT' && <LedgerTable title="Cust. Satisfaction Ledger" dataKey="customerSat" icon="fa-smile-beam" colorClass="text-yellow-400" data={data} updateLedger={updateLedger} removeLedger={removeLedger} />}
        {activeSub === 'COMP' && <LedgerTable title="Complimentary Ledger" dataKey="complimentary" icon="fa-gift" colorClass="text-pink-400" data={data} updateLedger={updateLedger} removeLedger={removeLedger} />}
      </div>
    </div>
  );
};

