                  showSuccess ? 'bg-emerald-600 border-emerald-400 text-white' : 'bg-indigo-600 border-white/10 text-white hover:bg-indigo-500'
                }`}
              >
                {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : (showSuccess ? <i className="fas fa-check-circle"></i> : <i className="fas fa-save"></i>)}
                {isSaving ? 'Menyimpan...' : (showSuccess ? 'Berhasil Tersimpan' : 'Simpan Seluruh Data Energi')}
              </button>
            </div>
          </div>
        )}

        {(activeSub === 'OPEX' || activeSub === 'LOST_BREAKAGE') && (
          <div className="space-y-10 animate-fade-in relative z-10">
            <h2 className="text-3xl font-black text-white uppercase tracking-tighter flex items-center gap-4">
              <i className={`fas ${activeSub === 'OPEX' ? 'fa-chart-line text-red-500' : 'fa-trash-restore text-emerald-500'}`}></i>
              {activeSub === 'OPEX' ? 'Operational Expenses' : 'Lost & Breakage'}
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
              {(activeSub === 'OPEX' ? opexKeys : lostBreakageKeys).map(key => (
                <div key={key} className="p-6 rounded-2xl bg-slate-900 border border-white/5 transition-all shadow-lg hover:border-indigo-500/30">
                  <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest block mb-4">{key.replace('lostBreakage', '').toUpperCase()}</label>
                  <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5">
                    <span className="text-slate-700 font-black">Rp</span>
                    <input type="number" className="flex-1 bg-transparent text-xl font-black outline-none text-white" placeholder="0"
                      value={(data.expenses as any)[key] || ''} 
                      onChange={e => onUpdate((p: AppState) => ({...p, expenses: {...p.expenses, [key]: Number(e.target.value)}}))} />
                  </div>
                </div>
              ))}
            </div>
            <div className="flex justify-center pt-6">
              <button onClick={handleSave} className="px-16 py-4 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl font-black uppercase text-xs tracking-widest transition-all">
                {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : 'Simpan Data'}
              </button>
            </div>
          </div>
        )}

        {activeSub === 'CITY' && <LedgerTable title="City Ledger Tracking" dataKey="cityLedger" icon="fa-building" colorClass="text-blue-400" data={data} updateLedger={updateLedger} removeLedger={removeLedger} />}
        {activeSub === 'SAT' && <LedgerTable title="Cust. Satisfaction Ledger" dataKey="customerSat" icon="fa-smile-beam" colorClass="text-yellow-400" data={data} updateLedger={updateLedger} removeLedger={removeLedger} />}
        {activeSub === 'COMP' && <LedgerTable title="Complimentary Ledger" dataKey="complimentary" icon="fa-gift" colorClass="text-pink-400" data={data} updateLedger={updateLedger} removeLedger={removeLedger} />}
      </div>
    </div>
  );
};

