import React, { useState } from 'react';
import { GuestComplaint, Staff } from '../types';

interface Props {
  data: GuestComplaint[];
  staffList: Staff[];
  onUpdate: (v: GuestComplaint[]) => void;
}

const GuestComplaintModule: React.FC<Props> = ({ data, staffList, onUpdate }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newComplaint, setNewComplaint] = useState<Partial<GuestComplaint>>({
    date: new Date().toISOString().split('T')[0],
    guestName: '',
    staffInvolved: '',
    chronology: '',
    correctiveAction: '',
    status: 'PENDING'
  });

  const handleAdd = () => {
    if (!newComplaint.guestName || !newComplaint.chronology || !newComplaint.correctiveAction) {
      alert("Harap isi semua kolom wajib.");
      return;
    }
    const complaint: GuestComplaint = {
      ...newComplaint,
      id: Date.now().toString(),
    } as GuestComplaint;

    onUpdate([complaint, ...data]);
    setNewComplaint({
      date: new Date().toISOString().split('T')[0],
      guestName: '',
      staffInvolved: '',
      chronology: '',
      correctiveAction: '',
      status: 'PENDING'
    });
    setIsAdding(false);
  };

  const toggleStatus = (id: string) => {
    const updated = data.map(c => 
      c.id === id ? { ...c, status: (c.status === 'RESOLVED' ? 'PENDING' : 'RESOLVED') as 'RESOLVED' | 'PENDING' } : c
    );
    onUpdate(updated);
  };

  const removeComplaint = (id: string) => {
    onUpdate(data.filter(c => c.id !== id));
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 glass-card p-8 border-l-4 border-amber-500 bg-[#1e293b]/95 shadow-2xl relative overflow-hidden">
