                      complaint.status === 'RESOLVED' ? 'border-emerald-500/30 text-emerald-500 hover:bg-emerald-500/10' : 'border-amber-500/30 text-amber-500 hover:bg-amber-500/10'
                    }`}
                   >
                    Mark as {complaint.status === 'RESOLVED' ? 'Pending' : 'Resolved'}
                   </button>
                   <button 
                    onClick={() => removeComplaint(complaint.id)}
                    className="p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition-all"
                   >
                    <i className="fas fa-trash-alt"></i>
                   </button>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2">
                <div className="p-8 border-r border-white/5 space-y-4">
                  <h5 className="text-[10px] font-black text-amber-400 uppercase tracking-[0.2em] flex items-center gap-2">
                    <i className="fas fa-history"></i> Kronologi Kejadian
                  </h5>
                  <p className="text-sm text-slate-300 leading-relaxed font-medium italic">
                    "{complaint.chronology}"
