import React from 'react';
import { AppState, DailySalesData, LedgerItem, GuestComplaint } from '../types';
import { STAFF_LIST, OT_RATE } from '../constants';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

const ReportingModule: React.FC<Props> = ({ data, filters }) => {
  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthName = months[parseInt(filters.month)];

  // 1. SALES CALCULATIONS
  const dailyRecord = data.sales.dailyRecording?.[filters.startDate];
  const todayRevenue = dailyRecord?.revenue || 0;
  const todayCovers = dailyRecord?.covers || 0;
  const dailyTarget = data.dailyTargets?.[filters.startDate] || 0;

  const currentMTDRevenue = (Object.values(data.sales.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.revenue) || 0), 0);
  const currentMTDCover = (Object.values(data.sales.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.covers) || 0), 0);
  const avgCheck = currentMTDCover > 0 ? Math.floor(currentMTDRevenue / currentMTDCover) : 0;

  const dailyAchv = dailyTarget > 0 ? (todayRevenue / dailyTarget * 100).toFixed(2) : "0.00";
  const mtdAchv = data.sales.budgetRevenue > 0 ? (currentMTDRevenue / data.sales.budgetRevenue * 100).toFixed(2) : "0.00";

  // 2. EXPENSE & RATIO CALCULATIONS
  const energyKeys = ['electricity', 'water', 'gas'];
  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];
  const lostBreakageKeys = ['lostBreakageBar', 'lostBreakageKitchen', 'lostBreakageService'];

  const totalEnergy = energyKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalOpex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalLostBreakage = lostBreakageKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalLedgers = [data.cityLedger, data.customerSat, data.complimentary].flat().reduce((a, b) => a + (b.qty * b.price), 0);
  const grandTotalExpense = totalOpex + totalEnergy + totalLostBreakage + totalLedgers;

  const calcRatio = (val: number) => currentMTDRevenue > 0 ? (val / currentMTDRevenue * 100).toFixed(2) : "0.00";
  const totalCostRatio = calcRatio(grandTotalExpense);

  // 3. QA CALCULATIONS
  const calcSectionAvg = (sec: any) => ((sec.product + sec.cleanliness + sec.grooming) / 3).toFixed(2);
  const outletAvg = ((Number(calcSectionAvg(data.qa.kitchen)) + Number(calcSectionAvg(data.qa.bar)) + Number(calcSectionAvg(data.qa.service))) / 3).toFixed(2);

  // 4. STAFF PERFORMANCE CALCULATIONS
  const staffPerformance = data.staffList.map(staff => {
    const otEntry = data.overtime.find(o => o.staffId === staff.id);
    const commentEntry = data.guestComments.find(c => c.staffId === staff.id);
    const netOtHours = otEntry ? Math.max(0, otEntry.hours - (otEntry.break1 + otEntry.break2)) : 0;
    return {
      name: staff.name,
      role: staff.role,
      otCost: netOtHours * OT_RATE,
      otHours: netOtHours,
      mentions: commentEntry?.achievement || 0
    };
  });

  const totalOtCost = staffPerformance.reduce((a, b) => a + b.otCost, 0);
  const totalMentions = staffPerformance.reduce((a, b) => a + b.mentions, 0);

  // 5. COMPLAINT SUMMARY
  const totalComplaints = data.complaints.length;
  const resolvedComplaints = data.complaints.filter(c => c.status === 'RESOLVED').length;

  const shareWA = () => {
    const text = encodeURIComponent(
      `*SH THE BARN - EXECUTIVE REPORT*\n` +
      `*PERIODE: ${currentMonthName.toUpperCase()} ${new Date().getFullYear()}*\n` +
      `------------------------------------------\n\n` +
      `📈 *SALES PERFORMANCE*\n` +
      `- MTD Actual: Rp ${currentMTDRevenue.toLocaleString()}\n` +
      `- Achievement: ${mtdAchv}%\n` +
      `- Avg Check: Rp ${avgCheck.toLocaleString()}\n\n` +
      `💸 *FINANCIAL WEIGHT*\n` +
      `- Total Expense: Rp ${grandTotalExpense.toLocaleString()}\n` +
      `- Expense Ratio: ${totalCostRatio}% dari Revenue\n` +
      `- Energy Cost: Rp ${totalEnergy.toLocaleString()}\n\n` +
      `📋 *OPERATIONAL AUDIT*\n` +
      `- QA Outlet Score: ${outletAvg}%\n` +
      `- Total Guest Mentions: ${totalMentions}\n` +
      `- Guest Complaints: ${totalComplaints} (${resolvedComplaints} Resolved)\n\n` +
      `------------------------------------------\n` +
      `_Laporan PDF tersedia via Dashboard_\n` +
      `_Created by Christian_`
    );
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur print:p-0 print:m-0 print:bg-white">
      {/* 1. Header & Actions (Hidden on Print) */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 glass-card p-8 border-l-4 border-indigo-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95 no-print">
        <div className="relative z-10">
          <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
            <i className="fas fa-file-contract text-indigo-400"></i>
            Executive Summary
          </h2>
          <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em] opacity-80">
            Laporan Kinerja Outlet Terintegrasi • {currentMonthName} {new Date().getFullYear()}
          </p>
        </div>
        <div className="flex flex-wrap gap-3 w-full md:w-auto relative z-10">
          <button onClick={() => window.print()} className="flex-1 md:flex-none px-8 py-4 bg-indigo-600 hover:bg-indigo-500 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center gap-3 shadow-xl active:scale-95">
            <i className="fas fa-file-pdf"></i> Cetak Laporan PDF
          </button>
          <button onClick={shareWA} className="flex-1 md:flex-none px-8 py-4 bg-green-600 hover:bg-green-500 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center gap-3 shadow-2xl active:scale-95">
            <i className="fab fa-whatsapp"></i> Share Ringkasan
          </button>
        </div>
      </div>

      {/* 2. Print Specific Header */}
      <div className="hidden print:block text-center mb-10 border-b-4 border-black pb-8">
        <h1 className="text-5xl font-black uppercase tracking-tighter text-black">SH THE BARN</h1>
        <p className="text-lg font-bold uppercase tracking-[0.3em] text-black mt-2 italic">Performance Executive Report</p>
        <div className="flex justify-between mt-8 text-[10px] font-black uppercase text-black">
          <span>Periode: {filters.startDate} s/d {filters.endDate}</span>
          <span>Dibuat Oleh: Christian (System)</span>
          <span>Dicetak: {new Date().toLocaleString('id-ID')}</span>
