export interface AppState {
  staffList: Staff[];
  googleReview: GoogleReviewData;
  guestComments: GuestCommentEntry[];
  complaints: GuestComplaint[];
  overtime: OvertimeEntry[];
  qa: QAData;
  expenses: ExpenseData;
  cityLedger: LedgerItem[];
  customerSat: LedgerItem[];
  complimentary: LedgerItem[];
  sales: SalesData;
  dailyTargets: Record<string, number>;
}

import React from 'react';
import { AppState, DailySalesData, LedgerItem, GuestComplaint } from '../types';
import { STAFF_LIST, OT_RATE } from '../constants';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

const ReportingModule: React.FC<Props> = ({ data, filters }) => {
  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthName = months[parseInt(filters.month)];

  // 1. SALES CALCULATIONS
  const currentMTDRevenue = (Object.values(data.sales.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.revenue) || 0), 0);
  const currentMTDCover = (Object.values(data.sales.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.covers) || 0), 0);
  const avgCheck = currentMTDCover > 0 ? Math.floor(currentMTDRevenue / currentMTDCover) : 0;
  const mtdAchv = data.sales.budgetRevenue > 0 ? (currentMTDRevenue / data.sales.budgetRevenue * 100).toFixed(2) : "0.00";

  // 2. GOOGLE REVIEW CALCULATIONS
  const gr = data.googleReview;
  const totalVotes = gr.stars1 + gr.stars2 + gr.stars3 + gr.stars4 + gr.stars5;
  const totalPoints = (gr.stars1 * 1) + (gr.stars2 * 2) + (gr.stars3 * 3) + (gr.stars4 * 4) + (gr.stars5 * 5);
  const currentRating = totalVotes === 0 ? "0.00" : (totalPoints / totalVotes).toFixed(2);

  // 3. EXPENSE & RATIO CALCULATIONS
  const energyKeys = ['electricity', 'water', 'gas'];
  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];
  const lostBreakageKeys = ['lostBreakageBar', 'lostBreakageKitchen', 'lostBreakageService'];

  const totalEnergy = energyKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalOpex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalLostBreakage = lostBreakageKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);

  const sumLedger = (list: LedgerItem[]) => list.reduce((a, b) => a + (b.qty * b.price), 0);
  const totalCityLedger = sumLedger(data.cityLedger);
  const totalCustSat = sumLedger(data.customerSat);
  const totalComp = sumLedger(data.complimentary);

  const grandTotalExpense = totalOpex + totalEnergy + totalLostBreakage + totalCityLedger + totalCustSat + totalComp;
  const calcRatio = (val: number) => currentMTDRevenue > 0 ? (val / currentMTDRevenue * 100).toFixed(2) : "0.00";

  // 4. QA CALCULATIONS
  const calcSectionAvg = (sec: any) => ((sec.product + sec.cleanliness + sec.grooming) / 3).toFixed(2);
  const outletAvg = ((Number(calcSectionAvg(data.qa.kitchen)) + Number(calcSectionAvg(data.qa.bar)) + Number(calcSectionAvg(data.qa.service))) / 3).toFixed(2);

  // 5. STAFF PERFORMANCE
  const staffPerformance = data.staffList.map(staff => {
    const otEntry = data.overtime.find(o => o.staffId === staff.id);
    const commentEntry = data.guestComments.find(c => c.staffId === staff.id);
    const netOtHours = otEntry ? Math.max(0, otEntry.hours - (otEntry.break1 + otEntry.break2)) : 0;
    return {
      name: staff.name,
      role: staff.role,
      otCost: netOtHours * OT_RATE,
      otHours: netOtHours,
      mentions: commentEntry?.achievement || 0
    };
  });
  const totalMentions = staffPerformance.reduce((a, b) => a + b.mentions, 0);

  // 6. COMPLAINTS
  const complaints = data.complaints || [];

  const shareWA = () => {
    const text = encodeURIComponent(
      `*SH THE BARN - PERFORMANCE REPORT*\n` +
      `*PERIODE: ${currentMonthName.toUpperCase()}*\n` +
      `------------------------------------------\n\n` +
      `📈 *SALES: Rp ${currentMTDRevenue.toLocaleString()} (${mtdAchv}%)*\n` +
      `⭐ *RATING: ${currentRating} / Target: ${gr.targetRating}*\n` +
      `💸 *EXPENSES: Rp ${grandTotalExpense.toLocaleString()} (${calcRatio(grandTotalExpense)}%)*\n` +
      `📋 *QA AUDIT: ${outletAvg}%*\n` +
      `💬 *GUEST MENTIONS: ${totalMentions} Mentions*\n` +
      `⚠️ *COMPLAINTS: ${complaints.length} Cases*\n\n` +
      `_Generated by Management System_`
    );
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  const LedgerSection = ({ title, items, color }: { title: string, items: LedgerItem[], color: string }) => (
    <div className={`p-4 rounded-xl bg-slate-900/40 border border-white/5 print:border-black print:bg-white`}>
      <div className={`text-[10px] font-black uppercase tracking-widest mb-3 ${color} flex justify-between`}>
        <span>{title}</span>
        <span>Rp {sumLedger(items).toLocaleString()}</span>
      </div>
      <div className="space-y-2">
        {items.length === 0 ? (
          <div className="text-[9px] text-slate-600 italic">No entries recorded</div>
        ) : (
          items.map(item => (
            <div key={item.id} className="flex justify-between items-center text-[9px] border-b border-white/5 pb-1 print:border-black">
              <span className="text-slate-400 print:text-black">{item.qty}x {item.name}</span>
              <span className="font-bold text-white print:text-black">Rp {(item.qty * item.price).toLocaleString()}</span>
            </div>
          ))
        )}
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in no-blur print:p-0 print:m-0 print:bg-white">
      {/* HEADER SECTION */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 glass-card p-8 border-l-4 border-indigo-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95 no-print">
        <div className="relative z-10">
          <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
            <i className="fas fa-file-contract text-indigo-400"></i>
            Ultimate Summary
          </h2>
          <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em] opacity-80">
            Laporan Kinerja Terintegrasi Seluruh Fitur • {currentMonthName} {new Date().getFullYear()}
          </p>
        </div>
        <div className="flex flex-wrap gap-3 w-full md:w-auto relative z-10">
          <button onClick={() => window.print()} className="flex-1 md:flex-none px-8 py-4 bg-indigo-600 hover:bg-indigo-500 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center gap-3 shadow-xl active:scale-95">
            <i className="fas fa-print"></i> Cetak Laporan
          </button>
          <button onClick={shareWA} className="flex-1 md:flex-none px-8 py-4 bg-green-600 hover:bg-green-500 rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center gap-3 shadow-2xl active:scale-95">
            <i className="fab fa-whatsapp"></i> Share Report
          </button>
        </div>
      </div>

      <div className="hidden print:block text-center mb-10 border-b-4 border-black pb-8">
        <h1 className="text-5xl font-black uppercase tracking-tighter text-black">SH THE BARN</h1>
        <p className="text-lg font-bold uppercase tracking-[0.3em] text-black mt-2 italic">Official Comprehensive Performance Report</p>
        <div className="flex justify-between mt-8 text-[10px] font-black uppercase text-black">
          <span>Periode: {filters.startDate} - {filters.endDate}</span>
          <span>Dibuat Oleh: Christian (System)</span>
          <span>{new Date().toLocaleString()}</span>
        </div>
      </div>

      {/* TOP KPI GRID */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-4">
        {[
          { label: 'REVENUE', val: `Rp ${currentMTDRevenue.toLocaleString()}`, icon: 'fa-coins', color: 'text-emerald-400' },
          { label: 'ACHV', val: `${mtdAchv}%`, icon: 'fa-bullseye', color: 'text-indigo-400' },
          { label: 'RATING', val: `${currentRating} ★`, icon: 'fa-star', color: 'text-yellow-400' },
          { label: 'QA SCORE', val: `${outletAvg}%`, icon: 'fa-shield-check', color: 'text-cyan-400' },
          { label: 'EXP RATIO', val: `${calcRatio(grandTotalExpense)}%`, icon: 'fa-percentage', color: 'text-red-400' },
        ].map((kpi, i) => (
          <div key={i} className="glass-card p-5 bg-slate-900/50 border-white/5 print:border-black print:bg-white">
            <div className="flex justify-between items-center mb-2">
              <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">{kpi.label}</span>
              <i className={`fas ${kpi.icon} ${kpi.color} text-xs print:text-black`}></i>
            </div>
            <div className={`text-xl font-black ${kpi.color} print:text-black`}>{kpi.val}</div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* GOOGLE REVIEW PERFORMANCE */}
        <section className="glass-card p-6 bg-slate-900/40 border-t-2 border-yellow-500 print:border-black print:bg-white">
           <h3 className="text-[10px] font-black uppercase text-white mb-4 flex items-center gap-3 print:text-black">
            <i className="fab fa-google text-yellow-500 print:text-black"></i> Google Review Analytics
          </h3>
          <div className="space-y-3">
             {[5, 4, 3, 2, 1].map(star => {
               const val = (gr as any)[`stars${star}`] || 0;
               const pct = totalVotes > 0 ? (val / totalVotes * 100).toFixed(0) : 0;
               return (
                 <div key={star} className="flex items-center gap-3">
                    <span className="text-[9px] font-black text-slate-500 w-4">{star}★</span>
                    <div className="flex-1 h-1.5 bg-slate-950 rounded-full overflow-hidden print:border print:border-black">
                       <div className="h-full bg-yellow-500 print:bg-black" style={{ width: `${pct}%` }}></div>
                    </div>
                    <span className="text-[9px] font-bold text-slate-500 w-6">{pct}%</span>
                 </div>
               );
             })}
             <div className="pt-4 border-t border-white/5 mt-4 grid grid-cols-2 gap-4">
                <div className="text-center p-2 bg-slate-950/50 rounded-lg print:border print:border-black">
                   <div className="text-[8px] font-black text-slate-500 uppercase mb-1">Target</div>
                   <div className="text-sm font-black text-white print:text-black">{gr.targetRating} ★</div>
                </div>
                <div className="text-center p-2 bg-slate-950/50 rounded-lg print:border print:border-black">
                   <div className="text-[8px] font-black text-slate-500 uppercase mb-1">Total Review</div>
                   <div className="text-sm font-black text-white print:text-black">{totalVotes}</div>
                </div>
             </div>
