import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { ModuleType, AppState } from './types';
import { INITIAL_STATE } from './constants';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import GoogleReviewModule from './components/GoogleReviewModule';
import OvertimeModule from './components/OvertimeModule';
import QAModule from './components/QAModule';
import ExpensesModule from './components/ExpensesModule';
import ReportingModule from './components/ReportingModule';
import GuestCommentModule from './components/GuestCommentModule';
import GuestComplaintModule from './components/GuestComplaintModule';
import AffiliateGenerator from './components/AffiliateGenerator';
import YTDModule from './components/YTDModule';
import SalesModule from './components/SalesModule';
import AdminModule from './components/AdminModule';

const App: React.FC = () => {
  const [activeModule, setActiveModule] = useState<ModuleType>(ModuleType.DASHBOARD);
  const [isAdmin, setIsAdmin] = useState(false);
  const [monthlyData, setMonthlyData] = useState<Record<string, AppState>>({
    [new Date().getMonth().toString()]: INITIAL_STATE
  });

  const [isFullScreen, setIsFullScreen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [filters, setFilters] = useState({
    month: new Date().getMonth().toString(),
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0]
  });

  const currentData = useMemo(() => {
    return monthlyData[filters.month] || INITIAL_STATE;
  }, [monthlyData, filters.month]);

  useEffect(() => {
    setIsRefreshing(true);
    const timer = setTimeout(() => {
      setIsRefreshing(false);
    }, 400);
    return () => clearTimeout(timer);
  }, [filters.month, filters.startDate, filters.endDate]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().then(() => setIsFullScreen(true)).catch(e => console.error(e));
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen().then(() => setIsFullScreen(false));
      }
    }
  };

  const updateCurrentData = useCallback((path: keyof AppState, newValue: any) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: {
          ...currentMonthBase,
          [path]: newValue
        }
      };
    });
  }, [filters.month]);

  const updateFullState = useCallback((updater: (prev: AppState) => AppState) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: updater(currentMonthBase)
      };
    });
  }, [filters.month]);

  const toggleAdminMode = () => {
    setIsAdmin(!isAdmin);
    if (!isAdmin) {
       setActiveModule(ModuleType.ADMIN);
    } else {
       setActiveModule(ModuleType.DASHBOARD);
    }
  };

  const renderModule = () => {
    if (isRefreshing) {
      return (
        <div className="h-[60vh] flex flex-col items-center justify-center space-y-4 animate-pulse">
           <div className="w-16 h-16 border-4 border-purple-500/20 border-t-purple-500 rounded-full animate-spin"></div>
           <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Loading Data...</p>
        </div>
      );
    }

    switch (activeModule) {
      case ModuleType.DASHBOARD:
        return <Dashboard onSelect={setActiveModule} isAdmin={isAdmin} />;
      case ModuleType.SALES:
        return <SalesModule 
          data={currentData.sales} 
          dailyTargets={currentData.dailyTargets} 
          filters={filters}
          onUpdate={(v) => updateCurrentData('sales', v)} 
        />;
      case ModuleType.GOOGLE_REVIEW:
        return <GoogleReviewModule data={currentData.googleReview} onUpdate={(v) => updateCurrentData('googleReview', v)} />;
      case ModuleType.GUEST_COMMENT:
        return <GuestCommentModule 
          data={currentData.guestComments} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('guestComments', v)} 
        />;
      case ModuleType.GUEST_COMPLAINT:
        return <GuestComplaintModule 
          data={currentData.complaints} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('complaints', v)} 
        />;
      case ModuleType.OVERTIME:
        return <OvertimeModule 
          data={currentData.overtime} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('overtime', v)} 
        />;
      case ModuleType.QUALITY_ASSURANCE:
        return <QAModule data={currentData.qa} onUpdate={(v) => updateCurrentData('qa', v)} />;
      case ModuleType.EXPENSES:
        return <ExpensesModule data={currentData} onUpdate={updateFullState} />;
      case ModuleType.YTD_REPORT:
        return <YTDModule allMonthlyData={monthlyData} />;
      case ModuleType.REKAPAN:
        return <ReportingModule data={currentData} filters={filters} />;
      case ModuleType.ADMIN:
        return <AdminModule data={currentData} onUpdate={updateCurrentData} filters={filters} />;
      // Note: GUEST_COMPLAINT type might not exist yet in your earlier types, ensure it's in types.ts
      default:
        // Use a fallback or the dashboard
        return <Dashboard onSelect={setActiveModule} isAdmin={isAdmin} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col">
      <Header 
        isFullScreen={isFullScreen} 
        onToggleFS={toggleFullScreen} 
        filters={filters}
        onFilterChange={setFilters}
        onHome={() => setActiveModule(ModuleType.DASHBOARD)}
        onAdminToggle={toggleAdminMode}
        isAdmin={isAdmin}
      />

      <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
        <div className="max-w-7xl mx-auto">
          <div className="animate-fade-in">
            {renderModule()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React from 'react';
import { AppState, DailySalesData, LedgerItem, GuestComplaint, Staff } from '../types';
import { STAFF_LIST, OT_RATE } from '../constants';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

const ReportingModule: React.FC<Props> = ({ data, filters }) => {
  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthName = months[parseInt(filters.month)];

  // 1. SALES CALCULATIONS
  const currentMTDRevenue = (Object.values(data.sales.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.revenue) || 0), 0);
  const currentMTDCover = (Object.values(data.sales.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.covers) || 0), 0);
  const avgCheck = currentMTDCover > 0 ? Math.floor(currentMTDRevenue / currentMTDCover) : 0;
  const mtdAchv = data.sales.budgetRevenue > 0 ? (currentMTDRevenue / data.sales.budgetRevenue * 100).toFixed(2) : "0.00";
  const daysPassed = Object.keys(data.sales.dailyRecording || {}).length || 1;
  const dailyRunRate = currentMTDRevenue / daysPassed;

  // 2. GOOGLE REVIEW CALCULATIONS
  const gr = data.googleReview;
  const totalVotes = gr.stars1 + gr.stars2 + gr.stars3 + gr.stars4 + gr.stars5;
  const totalPoints = (gr.stars1 * 1) + (gr.stars2 * 2) + (gr.stars3 * 3) + (gr.stars4 * 4) + (gr.stars5 * 5);
  const currentRating = totalVotes === 0 ? "0.00" : (totalPoints / totalVotes).toFixed(2);

  // 3. EXPENSE & RATIO CALCULATIONS
  const energyKeys = ['electricity', 'water', 'gas'];
  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];
  const lostBreakageKeys = ['lostBreakageBar', 'lostBreakageKitchen', 'lostBreakageService'];

  const totalEnergy = energyKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalOpex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalLostBreakage = lostBreakageKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);

  const sumLedger = (list: LedgerItem[]) => list.reduce((a, b) => a + (b.qty * b.price), 0);
  const totalCityLedger = sumLedger(data.cityLedger);
  const totalCustSat = sumLedger(data.customerSat);
  const totalComp = sumLedger(data.complimentary);

  const grandTotalExpense = totalOpex + totalEnergy + totalLostBreakage + totalCityLedger + totalCustSat + totalComp;
  const calcRatio = (val: number) => currentMTDRevenue > 0 ? (val / currentMTDRevenue * 100).toFixed(2) : "0.00";

  // 4. QA CALCULATIONS
  const calcSectionAvg = (sec: any) => ((sec.product + sec.cleanliness + sec.grooming) / 3).toFixed(2);
  const outletAvg = ((Number(calcSectionAvg(data.qa.kitchen)) + Number(calcSectionAvg(data.qa.bar)) + Number(calcSectionAvg(data.qa.service))) / 3).toFixed(2);

  // 5. STAFF PERFORMANCE & OT AVERAGES
  const staffPerformance = data.staffList.map(staff => {
    const otEntry = data.overtime.find(o => o.staffId === staff.id);
    const commentEntry = data.guestComments.find(c => c.staffId === staff.id);
    const netOtHours = otEntry ? Math.max(0, otEntry.hours - (otEntry.break1 + otEntry.break2)) : 0;
    return {
      id: staff.id,
      name: staff.name,
      role: staff.role,
      isLeader: staff.isLeader,
      otCost: netOtHours * OT_RATE,
      otHours: netOtHours,
      mentions: commentEntry?.achievement || 0
    };
  });

  const leaders = staffPerformance.filter(s => s.isLeader);
  const crews = staffPerformance.filter(s => !s.isLeader);

  const avgLeaderOT = leaders.length > 0 ? (leaders.reduce((a, b) => a + b.otHours, 0) / leaders.length).toFixed(1) : "0.0";
  const avgCrewOT = crews.length > 0 ? (crews.reduce((a, b) => a + b.otHours, 0) / crews.length).toFixed(1) : "0.0";
  const totalMentions = staffPerformance.reduce((a, b) => a + b.mentions, 0);

  // 6. COMPLAINTS
  const complaints = data.complaints || [];
  const resolvedCount = complaints.filter(c => c.status === 'RESOLVED').length;

  const shareWA = () => {
    const text = encodeURIComponent(
