import React, { useState } from 'react';
import { GuestComplaint, Staff } from '../types';

interface Props {
  data: GuestComplaint[];
  staffList: Staff[];
  onUpdate: (v: GuestComplaint[]) => void;
}

const GuestComplaintModule: React.FC<Props> = ({ data, staffList, onUpdate }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newComplaint, setNewComplaint] = useState<Partial<GuestComplaint>>({
    date: new Date().toISOString().split('T')[0],
    guestName: '',
    staffInvolved: '',
    chronology: '',
    correctiveAction: '',
    status: 'PENDING'
  });

  const handleAdd = () => {
    if (!newComplaint.guestName || !newComplaint.chronology || !newComplaint.correctiveAction) {
      alert("Harap isi semua kolom wajib (Nama Tamu, Kronologi, & Corrective Action).");
      return;
    }
    const complaint: GuestComplaint = {
      ...newComplaint,
      id: Date.now().toString(),
      status: 'PENDING'
    } as GuestComplaint;

    onUpdate([complaint, ...data]);
    setNewComplaint({
      date: new Date().toISOString().split('T')[0],
      guestName: '',
      staffInvolved: '',
      chronology: '',
      correctiveAction: '',
      status: 'PENDING'
    });
    setIsAdding(false);
  };

  const toggleStatus = (id: string) => {
    const updated = data.map(c => 
      c.id === id ? { ...c, status: (c.status === 'RESOLVED' ? 'PENDING' : 'RESOLVED') as 'RESOLVED' | 'PENDING' } : c
    );
    onUpdate(updated);
  };

  const removeComplaint = (id: string) => {
    if (confirm("Hapus catatan komplain ini?")) {
      onUpdate(data.filter(c => c.id !== id));
    }
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 glass-card p-8 border-l-4 border-amber-500 bg-[#1e293b]/95 shadow-2xl relative overflow-hidden">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <i className="fas fa-exclamation-triangle text-[180px]"></i>
        </div>
        <div className="relative z-10">
          <h2 className="text-3xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-4">
            <i className="fas fa-user-injured text-amber-500"></i>
            Guest Complaint Issue
          </h2>
          <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-widest">Dokumentasi & Penyelesaian Masalah</p>
        </div>
        <button 
          onClick={() => setIsAdding(!isAdding)}
          className="relative z-10 px-8 py-4 bg-amber-600 hover:bg-amber-500 rounded-2xl text-xs font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 flex items-center gap-3"
        >
          <i className={`fas ${isAdding ? 'fa-times' : 'fa-plus'}`}></i>
          {isAdding ? 'Batal' : 'Tambah Komplain'}
        </button>
      </div>

      {isAdding && (
        <div className="glass-card p-8 border border-white/10 bg-slate-900/50 space-y-6 animate-slide-up">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Tanggal</label>
              <input 
                type="date"
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm font-bold text-white outline-none focus:ring-2 ring-amber-500"
                value={newComplaint.date}
                onChange={e => setNewComplaint({...newComplaint, date: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Nama Tamu</label>
              <input 
                type="text"
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm font-bold text-white outline-none focus:ring-2 ring-amber-500"
                placeholder="Nama Tamu..."
                value={newComplaint.guestName}
                onChange={e => setNewComplaint({...newComplaint, guestName: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Staff Terlibat</label>
              <select 
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm font-bold text-white outline-none focus:ring-2 ring-amber-500"
                value={newComplaint.staffInvolved}
                onChange={e => setNewComplaint({...newComplaint, staffInvolved: e.target.value})}
              >
                <option value="">Pilih Staff...</option>
                {staffList.map(s => <option key={s.id} value={s.name}>{s.name} ({s.role})</option>)}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Kronologi</label>
              <textarea 
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm text-white outline-none focus:ring-2 ring-amber-500 min-h-[120px]"
                placeholder="Apa yang terjadi?"
                value={newComplaint.chronology}
                onChange={e => setNewComplaint({...newComplaint, chronology: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Corrective Action</label>
              <textarea 
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm text-white outline-none focus:ring-2 ring-amber-500 min-h-[120px]"
                placeholder="Tindakan yang diambil?"
                value={newComplaint.correctiveAction}
                onChange={e => setNewComplaint({...newComplaint, correctiveAction: e.target.value})}
              />
            </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={handleAdd}
              className="px-10 py-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl transition-all active:scale-95"
            >
              Simpan Komplain
            </button>
          </div>
        </div>
      )}

      <div className="grid grid-cols-1 gap-4">
        {data.length === 0 ? (
          <div className="glass-card p-20 text-center opacity-30">
            <i className="fas fa-check-circle text-6xl text-emerald-500 mb-4"></i>
            <h3 className="text-xl font-black uppercase tracking-widest">No Active Complaints</h3>
          </div>
        ) : (
          data.map(complaint => (
            <div key={complaint.id} className="glass-card overflow-hidden border border-white/10 hover:border-amber-500/30 transition-all">
              <div className="bg-slate-950/50 p-6 flex flex-col md:flex-row justify-between items-start md:items-center gap-4 border-b border-white/5">
                <div className="flex items-center gap-4">
                  <div className={`w-10 h-10 rounded-full flex items-center justify-center ${complaint.status === 'RESOLVED' ? 'bg-emerald-500/20 text-emerald-500' : 'bg-amber-500/20 text-amber-500'}`}>
                    <i className={`fas ${complaint.status === 'RESOLVED' ? 'fa-check' : 'fa-clock'}`}></i>
                  </div>
                  <div>
                    <h4 className="text-lg font-black text-white uppercase tracking-tight">{complaint.guestName}</h4>
                    <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest">{complaint.date} • Staff: {complaint.staffInvolved || 'N/A'}</p>
                  </div>
                </div>
                <div className="flex gap-2">
                   <button 
                    onClick={() => toggleStatus(complaint.id)}
                    className={`px-4 py-2 rounded-xl text-[9px] font-black uppercase border transition-all ${
                      complaint.status === 'RESOLVED' ? 'border-emerald-500 text-emerald-500' : 'border-amber-500 text-amber-500'
                    }`}
                   >
                    {complaint.status}
                   </button>
                   <button onClick={() => removeComplaint(complaint.id)} className="p-2 text-red-500 hover:bg-red-500/10 rounded-xl transition-all">
                    <i className="fas fa-trash-alt"></i>
                   </button>
                </div>
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2">
                <div className="p-6 border-r border-white/5">
                  <h5 className="text-[9px] font-black text-amber-500 uppercase tracking-widest mb-2">Kronologi</h5>
                  <p className="text-sm text-slate-300 italic">"{complaint.chronology}"</p>
                </div>
                <div className="p-6 bg-slate-900/30">
                  <h5 className="text-[9px] font-black text-emerald-500 uppercase tracking-widest mb-2">Corrective Action</h5>
                  <p className="text-sm text-slate-300 font-bold">{complaint.correctiveAction}</p>
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default GuestComplaintModule;

import React, { useState, useCallback, useEffect, useMemo } from 'react';
import { ModuleType, AppState } from './types';
import { INITIAL_STATE } from './constants';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import GoogleReviewModule from './components/GoogleReviewModule';
import OvertimeModule from './components/OvertimeModule';
import QAModule from './components/QAModule';
import ExpensesModule from './components/ExpensesModule';
import ReportingModule from './components/ReportingModule';
import GuestCommentModule from './components/GuestCommentModule';
import GuestComplaintModule from './components/GuestComplaintModule';
import AffiliateGenerator from './components/AffiliateGenerator';
import YTDModule from './components/YTDModule';
import SalesModule from './components/SalesModule';
import AdminModule from './components/AdminModule';

const App: React.FC = () => {
  const [activeModule, setActiveModule] = useState<ModuleType>(ModuleType.DASHBOARD);
  const [isAdmin, setIsAdmin] = useState(false);
  const [monthlyData, setMonthlyData] = useState<Record<string, AppState>>({
    [new Date().getMonth().toString()]: INITIAL_STATE
  });

  const [isFullScreen, setIsFullScreen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [filters, setFilters] = useState({
    month: new Date().getMonth().toString(),
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0]
  });

  const currentData = useMemo(() => {
    return monthlyData[filters.month] || INITIAL_STATE;
  }, [monthlyData, filters.month]);

  useEffect(() => {
    setIsRefreshing(true);
    const timer = setTimeout(() => {
      setIsRefreshing(false);
    }, 400);
    return () => clearTimeout(timer);
  }, [filters.month, filters.startDate, filters.endDate]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().then(() => setIsFullScreen(true)).catch(e => console.error(e));
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen().then(() => setIsFullScreen(false));
      }
    }
  };

  const updateCurrentData = useCallback((path: keyof AppState, newValue: any) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: {
          ...currentMonthBase,
          [path]: newValue
        }
      };
    });
  }, [filters.month]);

  const updateFullState = useCallback((updater: (prev: AppState) => AppState) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: updater(currentMonthBase)
      };
    });
  }, [filters.month]);

  const toggleAdminMode = () => {
    setIsAdmin(!isAdmin);
    if (!isAdmin) {
       setActiveModule(ModuleType.ADMIN);
    } else {
       setActiveModule(ModuleType.DASHBOARD);
    }
  };

  const renderModule = () => {
    if (isRefreshing) {
      return (
        <div className="h-[60vh] flex flex-col items-center justify-center space-y-4 animate-pulse">
           <div className="w-16 h-16 border-4 border-purple-500/20 border-t-purple-500 rounded-full animate-spin"></div>
           <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Loading Data...</p>
        </div>
      );
    }

    switch (activeModule) {
      case ModuleType.DASHBOARD:
        return <Dashboard onSelect={setActiveModule} isAdmin={isAdmin} />;
      case ModuleType.SALES:
        return <SalesModule 
          data={currentData.sales} 
          dailyTargets={currentData.dailyTargets} 
          filters={filters}
          onUpdate={(v) => updateCurrentData('sales', v)} 
        />;
      case ModuleType.GOOGLE_REVIEW:
        return <GoogleReviewModule data={currentData.googleReview} onUpdate={(v) => updateCurrentData('googleReview', v)} />;
      case ModuleType.GUEST_COMMENT:
        return <GuestCommentModule 
          data={currentData.guestComments} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('guestComments', v)} 
        />;
      case ModuleType.GUEST_COMPLAINT:
        return <GuestComplaintModule 
          data={currentData.complaints} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('complaints', v)} 
        />;
      case ModuleType.AFFILIATE:
        return <AffiliateGenerator filters={filters} />;
      case ModuleType.OVERTIME:
        return <OvertimeModule 
          data={currentData.overtime} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('overtime', v)} 
        />;
      case ModuleType.QUALITY_ASSURANCE:
        return <QAModule data={currentData.qa} onUpdate={(v) => updateCurrentData('qa', v)} />;
      case ModuleType.EXPENSES:
        return <ExpensesModule data={currentData} onUpdate={updateFullState} />;
      case ModuleType.YTD_REPORT:
        return <YTDModule allMonthlyData={monthlyData} />;
      case ModuleType.REKAPAN:
        return <ReportingModule data={currentData} filters={filters} />;
      case ModuleType.ADMIN:
        return <AdminModule data={currentData} onUpdate={updateCurrentData} filters={filters} />;
      default:
        return <Dashboard onSelect={setActiveModule} isAdmin={isAdmin} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col">
      <Header 
        isFullScreen={isFullScreen} 
        onToggleFS={toggleFullScreen} 
        filters={filters}
        onFilterChange={setFilters}
        onHome={() => setActiveModule(ModuleType.DASHBOARD)}
        onAdminToggle={toggleAdminMode}
        isAdmin={isAdmin}
      />

      <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
        <div className="max-w-7xl mx-auto">
          <div className="animate-fade-in">
            {renderModule()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

