import { AppState, DailySalesData, LedgerItem, GuestComplaint, Staff } from '../types';
import { STAFF_LIST, OT_RATE } from '../constants';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

const ReportingModule: React.FC<Props> = ({ data, filters }) => {
  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthName = months[parseInt(filters.month)];

  // 1. SALES CALCULATIONS
  const currentMTDRevenue = (Object.values(data.sales.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.revenue) || 0), 0);
  const currentMTDCover = (Object.values(data.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.covers) || 0), 0); // Note: using data directly as its passed as whole state in App.tsx
  // Fixed a potential reference issue: data.sales.dailyRecording is what we need
  const dailyRecordings = data.sales.dailyRecording || {};
  const mtdRev = Object.values(dailyRecordings).reduce((acc, curr) => acc + (Number(curr.revenue) || 0), 0);
  const mtdCov = Object.values(dailyRecordings).reduce((acc, curr) => acc + (Number(curr.covers) || 0), 0);

  const avgCheck = mtdCov > 0 ? Math.floor(mtdRev / mtdCov) : 0;
  const mtdAchv = data.sales.budgetRevenue > 0 ? (mtdRev / data.sales.budgetRevenue * 100).toFixed(2) : "0.00";
  const daysPassed = Object.keys(dailyRecordings).length || 1;
  const dailyRunRate = mtdRev / daysPassed;

  // 2. GOOGLE REVIEW CALCULATIONS
  const gr = data.googleReview;
  const totalVotes = gr.stars1 + gr.stars2 + gr.stars3 + gr.stars4 + gr.stars5;
  const totalPoints = (gr.stars1 * 1) + (gr.stars2 * 2) + (gr.stars3 * 3) + (gr.stars4 * 4) + (gr.stars5 * 5);
  const currentRating = totalVotes === 0 ? "0.00" : (totalPoints / totalVotes).toFixed(2);

  // 3. EXPENSE & RATIO CALCULATIONS
  const energyKeys = ['electricity', 'water', 'gas'];
  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];
  const lostBreakageKeys = ['lostBreakageBar', 'lostBreakageKitchen', 'lostBreakageService'];

  const totalEnergy = energyKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalOpex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalLostBreakage = lostBreakageKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);

  const sumLedger = (list: LedgerItem[]) => list.reduce((a, b) => a + (b.qty * b.price), 0);
  const totalCityLedger = sumLedger(data.cityLedger);
  const totalCustSat = sumLedger(data.customerSat);
  const totalComp = sumLedger(data.complimentary);

  const grandTotalExpense = totalOpex + totalEnergy + totalLostBreakage + totalCityLedger + totalCustSat + totalComp;
  const calcRatio = (val: number) => mtdRev > 0 ? (val / mtdRev * 100).toFixed(2) : "0.00";

  // 4. QA CALCULATIONS
  const calcSectionAvg = (sec: any) => ((sec.product + sec.cleanliness + sec.grooming) / 3).toFixed(2);
  const outletAvg = ((Number(calcSectionAvg(data.qa.kitchen)) + Number(calcSectionAvg(data.qa.bar)) + Number(calcSectionAvg(data.qa.service))) / 3).toFixed(2);

  // 5. STAFF PERFORMANCE & OT AVERAGES
  const staffPerformance = data.staffList.map(staff => {
    const otEntry = data.overtime.find(o => o.staffId === staff.id);
    const commentEntry = data.guestComments.find(c => c.staffId === staff.id);
    const netOtHours = otEntry ? Math.max(0, otEntry.hours - (otEntry.break1 + otEntry.break2)) : 0;
    return {
      id: staff.id,
      name: staff.name,
      role: staff.role,
      isLeader: staff.isLeader,
      otCost: netOtHours * OT_RATE,
      otHours: netOtHours,
      mentions: commentEntry?.achievement || 0
    };
  });

  const leaders = staffPerformance.filter(s => s.isLeader);
  const crews = staffPerformance.filter(s => !s.isLeader);

  const avgLeaderOT = leaders.length > 0 ? (leaders.reduce((a, b) => a + b.otHours, 0) / leaders.length).toFixed(1) : "0.0";
  const avgCrewOT = crews.length > 0 ? (crews.reduce((a, b) => a + b.otHours, 0) / crews.length).toFixed(1) : "0.0";
  const totalMentions = staffPerformance.reduce((a, b) => a + b.mentions, 0);

  // 6. COMPLAINTS
  const complaints = data.complaints || [];
  const resolvedCount = complaints.filter(c => c.status === 'RESOLVED').length;

  const shareWA = () => {
    const text = encodeURIComponent(
      `*SH THE BARN - ULTIMATE PERFORMANCE REPORT*\n` +
      `*PERIODE: ${currentMonthName.toUpperCase()} ${new Date().getFullYear()}*\n` +
      `------------------------------------------\n\n` +
      `📈 *REVENUE:* Rp ${mtdRev.toLocaleString()} (${mtdAchv}%)\n` +
      `💸 *OPEX:* Rp ${totalOpex.toLocaleString()}\n` +
      `⚡ *ENERGY:* Rp ${totalEnergy.toLocaleString()}\n` +
      `💰 *TOTAL EXPENSES:* Rp ${grandTotalExpense.toLocaleString()} (${calcRatio(grandTotalExpense)}%)\n` +
      `📋 *QA SCORE:* ${outletAvg}%\n` +
      `⭐ *RATING:* ${currentRating} ★\n\n` +
      `_Generated by Intelligence Suite v3.2_`
    );
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  const LedgerSection = ({ title, items, color, icon }: { title: string, items: LedgerItem[], color: string, icon: string }) => (
    <div className={`p-5 rounded-2xl bg-slate-900/40 border border-white/5 print:border-black print:bg-white transition-all hover:bg-slate-900/60 shadow-xl`}>
      <div className={`text-[10px] font-black uppercase tracking-[0.2em] mb-4 ${color} flex justify-between items-center`}>
        <span className="flex items-center gap-2"><i className={`fas ${icon}`}></i> {title}</span>
        <span className="bg-white/5 px-3 py-1 rounded-full text-white print:text-black">Rp {sumLedger(items).toLocaleString()}</span>
      </div>
      <div className="space-y-2.5 max-h-[200px] overflow-y-auto no-scrollbar">
        {items.length === 0 ? (
          <div className="text-[9px] text-slate-600 italic py-4 text-center border-2 border-dashed border-white/5 rounded-xl">No entries recorded</div>
        ) : (
          items.map(item => (
            <div key={item.id} className="group">
              <div className="flex justify-between items-start text-[9px] pb-1 print:border-black">
                <div className="flex flex-col">
                  <span className="text-white font-black print:text-black uppercase tracking-tighter">{item.name}</span>
                  <span className="text-slate-500 font-bold italic tracking-widest">{item.qty} units @ Rp {item.price.toLocaleString()}</span>
                </div>
                <span className="font-black text-white print:text-black text-xs">Rp {(item.qty * item.price).toLocaleString()}</span>
              </div>
              <div className="text-[8px] text-slate-600 mb-2 pl-2 border-l border-white/10 group-hover:text-indigo-400 transition-colors uppercase">{item.reason || 'No specific note'}</div>
            </div>
          ))
        )}
      </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in no-blur print:p-0 print:m-0 print:bg-white pb-20">
      {/* 1. INTERACTIVE HEADER (Hidden on Print) */}
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 glass-card p-8 border-l-4 border-indigo-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95 no-print">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <i className="fas fa-file-contract text-[180px]"></i>
        </div>
        <div className="relative z-10">
          <div className="flex items-center gap-3 mb-2">
            <span className="px-3 py-1 bg-indigo-500 text-white text-[8px] font-black uppercase rounded-full tracking-widest">Executive v3.2</span>
            <span className="text-slate-500 font-black uppercase text-[10px] tracking-widest">Bulan {currentMonthName}</span>
          </div>
          <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
            Outlet Intelligence Report
          </h2>
          <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em] opacity-80">
            Analisis Data Performa, Finansial & Sentimen Pelanggan
          </p>
        </div>
        <div className="flex flex-wrap gap-3 w-full md:w-auto relative z-10">
          <button onClick={() => window.print()} className="flex-1 md:flex-none px-8 py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center gap-3 shadow-xl active:scale-95 border border-white/5">
            <i className="fas fa-print"></i> Print PDF
          </button>
          <button onClick={shareWA} className="flex-1 md:flex-none px-8 py-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl text-xs font-black uppercase tracking-widest transition-all flex items-center justify-center gap-3 shadow-2xl active:scale-95">
            <i className="fab fa-whatsapp"></i> WhatsApp Summary
          </button>
        </div>
      </div>

      {/* 2. PRINT HEADER */}
      <div className="hidden print:block text-center mb-10 border-b-8 border-double border-black pb-8">
        <h1 className="text-6xl font-black uppercase tracking-tighter text-black">SH THE BARN</h1>
        <p className="text-xl font-bold uppercase tracking-[0.4em] text-black mt-2 italic">Comprehensive Executive Performance Audit</p>
        <div className="flex justify-between mt-10 text-[10px] font-black uppercase text-black">
          <div className="text-left">
            <div>Periode: {filters.startDate} - {filters.endDate}</div>
            <div>Bulan Fiskal: {currentMonthName.toUpperCase()}</div>
          </div>
          <div className="text-right">
            <div>Dibuat Oleh: CHRISTIAN (SYSTEM)</div>
            <div>Waktu Cetak: {new Date().toLocaleString('id-ID')}</div>
          </div>
        </div>
      </div>

      {/* 3. CORE INTELLIGENCE GRID */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-5 gap-5">
        {[
          { label: 'MTD REVENUE', val: `Rp ${mtdRev.toLocaleString()}`, icon: 'fa-coins', color: 'text-emerald-400', bg: 'bg-emerald-500/10' },
          { label: 'PERFORMANCE', val: `${mtdAchv}%`, icon: 'fa-bullseye', color: 'text-indigo-400', bg: 'bg-indigo-500/10' },
          { label: 'OPEX TOTAL', val: `Rp ${totalOpex.toLocaleString()}`, icon: 'fa-file-invoice-dollar', color: 'text-red-400', bg: 'bg-red-500/10' },
          { label: 'AUDIT SCORE', val: `${outletAvg}%`, icon: 'fa-shield-check', color: 'text-cyan-400', bg: 'bg-cyan-500/10' },
          { label: 'SENTIMENT', val: `${currentRating} ★`, icon: 'fa-star', color: 'text-yellow-400', bg: 'bg-yellow-500/10' },
        ].map((kpi, i) => (
          <div key={i} className={`glass-card p-6 ${kpi.bg} border-t-4 border-white/5 flex flex-col justify-between h-40 print:border-black print:bg-white`}>
            <div className="flex justify-between items-start">
              <span className="text-[9px] font-black uppercase tracking-widest opacity-60 text-white print:text-black">{kpi.label}</span>
              <i className={`fas ${kpi.icon} ${kpi.color} text-lg print:text-black`}></i>
            </div>
            <div className={`text-2xl font-black ${kpi.color} tracking-tighter leading-none print:text-black`}>{kpi.val}</div>
            <div className="h-1 w-full bg-white/5 rounded-full mt-2 overflow-hidden print:border print:border-black">
               <div className={`h-full ${kpi.color.replace('text-', 'bg-')} opacity-60`} style={{ width: `${Math.min(100, (Number(kpi.val.replace(/[^0-9.]/g, '')) / 10000000) * 100)}%` }}></div>
            </div>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">

        {/* FINANCIAL INTELLIGENCE */}
        <div className="lg:col-span-2 space-y-8">
          <section className="glass-card p-8 bg-slate-900/40 border-t-2 border-indigo-500 print:border-black print:bg-white shadow-2xl">
            <h3 className="text-xs font-black uppercase text-white mb-8 flex items-center gap-3 print:text-black">
              <i className="fas fa-chart-line text-indigo-400 print:text-black"></i> Revenue & Efficiency Analysis
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-x-12 gap-y-6">
              <div className="space-y-4">
                <div className="flex justify-between items-center text-xs py-2 border-b border-white/5 print:border-black">
                  <span className="text-slate-500 font-bold uppercase tracking-widest">Total Pax Monthly</span>
                  <span className="text-white font-black print:text-black">{mtdCov.toLocaleString()} COVERS</span>
                </div>
                <div className="flex justify-between items-center text-xs py-2 border-b border-white/5 print:border-black">
                  <span className="text-slate-500 font-bold uppercase tracking-widest">Daily Run Rate</span>
                  <span className="text-emerald-400 font-black print:text-black">Rp {Math.round(dailyRunRate).toLocaleString()} / Day</span>
                </div>
                <div className="flex justify-between items-center text-xs py-2">
                  <span className="text-slate-500 font-bold uppercase tracking-widest">Budget Variance</span>
                  <span className={`font-black ${(mtdRev - data.sales.budgetRevenue) >= 0 ? 'text-emerald-400' : 'text-red-400'} print:text-black`}>
                    Rp {(mtdRev - data.sales.budgetRevenue).toLocaleString()}
                  </span>
                </div>
              </div>
              <div className="space-y-4">
                 <div className="flex justify-between items-center text-xs py-2 border-b border-white/5 print:border-black">
                    <span className="text-slate-500 font-bold uppercase tracking-widest">Total Expenses (All)</span>
                    <span className="text-white font-black print:text-black">Rp {grandTotalExpense.toLocaleString()}</span>
                 </div>
                 <div className="flex justify-between items-center text-xs py-2 border-b border-white/5 print:border-black">
                    <span className="text-slate-500 font-bold uppercase tracking-widest">Cost to Sales Ratio</span>
                    <span className={`font-black ${Number(calcRatio(grandTotalExpense)) > 25 ? 'text-red-400' : 'text-emerald-400'} print:text-black`}>
                       {calcRatio(grandTotalExpense)}%
                    </span>
                 </div>
                 <div className="flex justify-between items-center text-xs py-2">
                    <span className="text-slate-500 font-bold uppercase tracking-widest">Projected Gross Profit</span>
                    <span className="text-indigo-400 font-black print:text-black">Rp {(mtdRev - grandTotalExpense).toLocaleString()}</span>
                 </div>
              </div>
            </div>
          </section>

          {/* OPEX BREAKDOWN SECTION - NEW */}
          <section className="glass-card p-8 bg-slate-900/60 border-t-2 border-red-500 print:border-black print:bg-white shadow-2xl relative overflow-hidden">
             <div className="absolute top-0 right-0 p-8 opacity-5">
                <i className="fas fa-file-invoice-dollar text-7xl"></i>
             </div>
             <h3 className="text-xs font-black uppercase text-white mb-8 flex items-center gap-3 print:text-black">
                <i className="fas fa-search-dollar text-red-500 print:text-black"></i> Operational Expenses (OPEX) Detail
             </h3>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div className="space-y-4">
                   {opexKeys.map(key => (
                      <div key={key} className="space-y-1.5">
                         <div className="flex justify-between text-[8px] font-black text-slate-500 uppercase tracking-widest">
                            <span>{key.replace(/([A-Z])/g, ' $1').trim()}</span>
                            <span className="text-white print:text-black">Rp {((data.expenses as any)[key] || 0).toLocaleString()}</span>
                         </div>
                         <div className="h-1 bg-slate-950 rounded-full overflow-hidden print:border print:border-black">
                            <div 
                               className="h-full bg-red-500 opacity-60" 
                               style={{ width: `${totalOpex > 0 ? (((data.expenses as any)[key] || 0) / totalOpex * 100) : 0}%` }}
                            ></div>
                         </div>
                      </div>
                   ))}
                </div>
                <div className="flex flex-col justify-center items-center p-6 bg-slate-950/40 rounded-3xl border border-white/5 print:border-black print:bg-white">
                   <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-2">Total OPEX Cost</div>
                   <div className="text-3xl font-black text-red-400 print:text-black">Rp {totalOpex.toLocaleString()}</div>
                   <div className="text-[8px] font-bold text-slate-600 uppercase mt-2 italic tracking-widest">
                      Ratio to Sales: {calcRatio(totalOpex)}%
                   </div>
                </div>
             </div>
          </section>

          {/* FINANCIAL LEDGER BREAKDOWN */}
          <section className="space-y-5">
             <h3 className="text-xs font-black uppercase text-white flex items-center gap-3 print:text-black">
              <i className="fas fa-book-open text-indigo-400 print:text-black"></i> Operational Ledgers Inventory
            </h3>
            <div className="grid grid-cols-1 md:grid-cols-3 gap-5">
               <LedgerSection title="City Ledger" items={data.cityLedger} color="text-blue-400" icon="fa-building" />
               <LedgerSection title="Cust. Satisfaction" items={data.customerSat} color="text-yellow-400" icon="fa-smile-beam" />
               <LedgerSection title="Complimentary" items={data.complimentary} color="text-pink-400" icon="fa-gift" />
            </div>
          </section>
        </div>

        {/* HUMAN CAPITAL & SENTIMENT */}
        <div className="space-y-8">
          {/* STAFF KPI & OT AVERAGES */}
          <section className="glass-card p-8 bg-slate-900/40 border-t-2 border-pink-500 print:border-black print:bg-white shadow-2xl">
            <h3 className="text-xs font-black uppercase text-white mb-6 flex items-center gap-3 print:text-black">
              <i className="fas fa-users-cog text-pink-400 print:text-black"></i> Human Capital Management
            </h3>
            <div className="space-y-5 mb-8">
               <div className="flex justify-between items-center p-4 bg-slate-950/50 rounded-2xl border border-white/5 print:border-black print:bg-white">
                  <div className="flex flex-col">
                     <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Average OT (Leader)</span>
                     <span className="text-sm font-black text-white print:text-black">{avgLeaderOT} <span className="text-[9px] opacity-40 uppercase">Hrs / Person</span></span>
                  </div>
                  <i className="fas fa-crown text-yellow-500/20 text-2xl print:text-black"></i>
               </div>
               <div className="flex justify-between items-center p-4 bg-slate-950/50 rounded-2xl border border-white/5 print:border-black print:bg-white">
                  <div className="flex flex-col">
                     <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Average OT (Crew)</span>
                     <span className="text-sm font-black text-white print:text-black">{avgCrewOT} <span className="text-[9px] opacity-40 uppercase">Hrs / Person</span></span>
                  </div>
                  <i className="fas fa-user-shield text-blue-500/20 text-2xl print:text-black"></i>
               </div>
            </div>

            <div className="space-y-4">
              <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest border-b border-white/5 pb-2">High Impact Contribution</div>
              {staffPerformance.filter(s => s.mentions > 0).sort((a,b) => b.mentions - a.mentions).slice(0, 5).map((staff, i) => (
                <div key={i} className="flex justify-between items-center">
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-white uppercase print:text-black">{staff.name}</span>
                    <span className="text-[8px] font-bold text-slate-600 uppercase tracking-widest">{staff.role}</span>
                  </div>
                  <span className="text-[10px] font-black text-pink-400 print:text-black">{staff.mentions} Mentions</span>
                </div>
              ))}
            </div>
          </section>

          {/* GOOGLE REVIEW ANALYTICS */}
          <section className="glass-card p-8 bg-slate-900/40 border-t-2 border-yellow-500 print:border-black print:bg-white shadow-2xl">
            <h3 className="text-xs font-black uppercase text-white mb-6 flex items-center gap-3 print:text-black">
              <i className="fab fa-google text-yellow-500 print:text-black"></i> Brand Reputation Audit
            </h3>
            <div className="flex items-center justify-between mb-8">
               <div className="text-center">
                  <div className="text-4xl font-black text-white print:text-black leading-none">{currentRating}</div>
                  <div className="text-[8px] font-black text-slate-500 uppercase mt-2 tracking-widest">Avg Rating</div>
               </div>
               <div className="h-10 w-px bg-white/10 mx-4 print:bg-black"></div>
               <div className="flex-1 space-y-2">
                  {[5, 4, 3, 2, 1].map(star => {
                    const count = (gr as any)[`stars${star}`] || 0;
                    const pct = totalVotes > 0 ? (count / totalVotes * 100).toFixed(0) : 0;
                    return (
                      <div key={star} className="flex items-center gap-3">
                         <span className="text-[8px] font-black text-slate-600 w-4">{star}★</span>
                         <div className="flex-1 h-1 bg-slate-950 rounded-full overflow-hidden print:border print:border-black">
                            <div className="h-full bg-yellow-500 print:bg-black" style={{ width: `${pct}%` }}></div>
                         </div>
                      </div>
                    );
                  })}
               </div>
            </div>
            <div className="text-[9px] font-bold text-slate-500 text-center uppercase tracking-widest bg-slate-950/40 p-3 rounded-xl print:text-black print:border print:border-black">
               Target Score: {gr.targetRating} ★ • Total Reviews: {totalVotes}
            </div>
          </section>
        </div>
      </div>

      {/* 4. GUEST COMPLAINT LOGS (FULL WIDTH) */}
      <section className="glass-card p-8 bg-slate-900/40 border-t-2 border-amber-600 print:border-black print:bg-white shadow-2xl overflow-hidden">
        <h3 className="text-xs font-black uppercase text-white mb-8 flex items-center gap-3 print:text-black">
          <i className="fas fa-user-injured text-amber-500 print:text-black"></i> Guest Complaints & Remediation Logs
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {complaints.length === 0 ? (
            <div className="col-span-full py-20 text-center flex flex-col items-center gap-4 opacity-30">
               <i className="fas fa-check-circle text-5xl text-emerald-500"></i>
               <span className="text-sm font-black uppercase tracking-[0.3em]">No grievances recorded for this cycle</span>
            </div>
          ) : (
            complaints.map(complaint => (
              <div key={complaint.id} className="p-6 bg-slate-950/80 rounded-2xl border border-white/5 print:border-black print:bg-white flex flex-col justify-between">
                <div>
                  <div className="flex justify-between items-center mb-4">
                    <span className="text-xs font-black text-white print:text-black uppercase tracking-tighter">{complaint.guestName}</span>
                    <span className={`text-[8px] font-black px-2 py-0.5 rounded-full border ${complaint.status === 'RESOLVED' ? 'border-emerald-500 text-emerald-500' : 'border-amber-500 text-amber-500'} uppercase tracking-widest`}>
                      {complaint.status}
                    </span>
                  </div>
                  <div className="text-[9px] text-slate-500 italic mb-4 line-clamp-3 leading-relaxed">"{complaint.chronology}"</div>
