const OvertimeModule: React.FC<Props> = ({ data, staffList, onUpdate }) => {
  const [isSaving, setIsSaving] = useState(false);

  const handleEntryChange = (staffId: string, field: keyof OvertimeEntry, val: number) => {
    const existingEntry = data.find(d => d.staffId === staffId);
    let newData: OvertimeEntry[];

    if (existingEntry) {
      newData = data.map(item => 
        item.staffId === staffId ? { ...item, [field]: val } : item
      );
    } else {
      const newEntry: OvertimeEntry = {
        staffId,
        hours: 0,
        break1: 0,
        [field]: val
      };
      newData = [...data, newEntry];
    }
    onUpdate(newData);
  };

  const calculateTotalOT = (item: OvertimeEntry) => {
    const netHours = Math.max(0, item.hours - item.break1);
    return netHours * OT_RATE;
  };

  const leaders = staffList.filter(s => s.isLeader);
  const crews = staffList.filter(s => !s.isLeader);

  const totalExpenses = data.reduce((acc, item) => acc + calculateTotalOT(item), 0);
  const totalHoursRaw = data.reduce((acc, item) => acc + (item.hours || 0), 0);
  const totalBreaks = data.reduce((acc, item) => acc + (item.break1 || 0), 0);

  const totalLeaderNetHours = leaders.reduce((acc, s) => {
    const entry = data.find(d => d.staffId === s.id) || { hours: 0, break1: 0, staffId: s.id };
    return acc + Math.max(0, entry.hours - entry.break1);
  }, 0);

  const totalCrewNetHours = crews.reduce((acc, s) => {
    const entry = data.find(d => d.staffId === s.id) || { hours: 0, break1: 0, staffId: s.id };
    return acc + Math.max(0, entry.hours - entry.break1);
  }, 0);

  const avgLeaderHours = leaders.length > 0 ? (totalLeaderNetHours / leaders.length).toFixed(1) : "0.0";
  const avgCrewHours = crews.length > 0 ? (totalCrewNetHours / crews.length).toFixed(1) : "0.0";

