            <div className="p-4 bg-slate-950/40 rounded-xl text-center border border-white/5 print:border-black print:text-black">
               <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Total Reviews: {totalVotes}</span>
            </div>
          </section>

          {/* QA SCORE */}
          <section className="glass-card p-8 bg-slate-900/40 border-t-2 border-cyan-500 print:border-black print:bg-white shadow-2xl">
             <h3 className="text-xs font-black uppercase text-white mb-8 flex items-center gap-3 print:text-black">
              <i className="fas fa-tasks text-cyan-400"></i> QA Compliance Matrix
            </h3>
            <div className="space-y-6">
               {['kitchen', 'bar', 'service'].map(dept => {
                 const sec = (data.qa as any)[dept];
                 const avg = calcSectionAvg(sec);
                 return (
                   <div key={dept} className="space-y-2">
                      <div className="flex justify-between items-center text-[10px] font-black uppercase tracking-widest">
                         <span className="text-slate-500">{dept} Score</span>
                         <span className={`${Number(avg) >= 90 ? 'text-emerald-400' : 'text-amber-500'} print:text-black`}>{avg}%</span>
                      </div>
                      <div className="h-1.5 bg-slate-950 rounded-full overflow-hidden print:border print:border-black">
                         <div className={`h-full ${Number(avg) >= 90 ? 'bg-emerald-500' : 'bg-cyan-500'} opacity-60`} style={{ width: `${avg}%` }}></div>
                      </div>
                   </div>
                 );
               })}
               <div className="mt-6 pt-4 border-t border-white/5 flex justify-between items-center">
                  <span className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Global Outlet Score</span>
                  <span className="text-2xl font-black text-white print:text-black">{outletAvg}%</span>
               </div>
            </div>
          </section>
        </div>
      </div>

      {/* COMPLAINTS LOGS */}
      <section className="glass-card p-8 bg-slate-900/40 border-t-2 border-amber-600 print:border-black print:bg-white shadow-2xl">
        <h3 className="text-xs font-black uppercase text-white mb-8 flex items-center gap-3 print:text-black">
          <i className="fas fa-user-injured text-amber-500"></i> Guest Issue Remediation Log
        </h3>
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {complaints.length === 0 ? (
            <div className="col-span-full py-16 text-center opacity-30 italic text-sm font-black uppercase tracking-widest">No Active Complaints Recorded</div>
          ) : (
            complaints.map(c => (
              <div key={c.id} className="p-6 bg-slate-950/80 rounded-2xl border border-white/5 print:border-black print:bg-white flex flex-col justify-between shadow-xl">
                <div>
                  <div className="flex justify-between items-center mb-4">
                    <span className="text-[11px] font-black text-white uppercase print:text-black tracking-tight">{c.guestName}</span>
                    <span className={`text-[8px] font-black px-2 py-0.5 rounded border ${c.status === 'RESOLVED' ? 'border-emerald-500 text-emerald-500' : 'border-amber-500 text-amber-500'} uppercase`}>{c.status}</span>
                  </div>
                  <p className="text-[10px] text-slate-500 italic mb-6 leading-relaxed">"{c.chronology}"</p>
                </div>
                <div className="pt-4 border-t border-white/5 print:border-black">
                  <div className="text-[8px] font-black text-emerald-400 uppercase tracking-widest mb-1">Corrective Action:</div>
                  <p className="text-[10px] text-slate-300 print:text-black font-bold">{c.correctiveAction}</p>
                </div>
              </div>
            ))
          )}
        </div>
      </section>

      {/* FOOTER & SIGNATURES */}
      <footer className="space-y-12">
        <div className="p-12 text-center glass-card bg-slate-950/40 border border-white/5 print:border-black print:bg-white shadow-2xl relative overflow-hidden">
          <div className="absolute inset-0 bg-indigo-500/5 pointer-events-none"></div>
          <div className="relative z-10">
            <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.4em] mb-4">Official Verification Seal</div>
            <div className="text-5xl font-black text-white print:text-black mb-8 tracking-tighter leading-none">Rp {grandTotalExpense.toLocaleString()} <span className="text-xs text-slate-600">Total Exp</span></div>
            <div className="max-w-3xl mx-auto p-8 bg-white/5 rounded-3xl border border-white/5 print:border-black print:bg-white">
