            <p className="text-xs font-black uppercase tracking-[0.2em]">Operations Director / GM</p>
            <p className="text-[9px] text-slate-600 mt-2 uppercase italic font-bold">Authorized Approval & Stamp</p>
          </div>
          <div className="text-center flex flex-col items-center">
            <div className="h-28 w-64 border-b-2 border-black mb-4"></div>
