const ExpensesModule: React.FC<Props> = ({ data, onUpdate }) => {
  const [activeSub, setActiveSub] = useState<'OPEX' | 'ENERGY' | 'LOST_BREAKAGE' | 'CITY' | 'SAT' | 'COMP' | 'FLOOR'>('OPEX');
  const [isSaving, setIsSaving] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  // State untuk Kalkulator Energi Detail
  const [energyDetails, setEnergyDetails] = useState({
    elecKwh: { lwbpOpen: 0, lwbpClose: 0, wbpOpen: 0, wbpClose: 0 },
    waterM3: { open: 0, close: 0 },
    gasM3: { open: 0, close: 0 }
  });

  // Constants Tarif
  const KWH_RATE = 1499.7;
  const WATER_RATE = 21250;
  const M3_GAS_RATE = 22000;
  const PPJU_RATE = 0.037; // 3.70%
  const MAINT_RATE = 0.07; // 7%

  // Efek samping untuk sinkronisasi total biaya energi ke state global
  useEffect(() => {
    if (activeSub === 'ENERGY') {
      const lwbpUsage = Math.max(0, energyDetails.elecKwh.lwbpClose - energyDetails.elecKwh.lwbpOpen);
      const wbpUsage = Math.max(0, energyDetails.elecKwh.wbpClose - energyDetails.elecKwh.wbpOpen);
      const kwhBase = (lwbpUsage + wbpUsage) * KWH_RATE;
      const kwhPpju = kwhBase * PPJU_RATE;
      const kwhMaint = kwhBase * MAINT_RATE;
      const totalKwh = Math.round(kwhBase + kwhPpju + kwhMaint);

      const waterUsage = Math.max(0, energyDetails.waterM3.close - energyDetails.waterM3.open);
      const totalWater = Math.round(waterUsage * WATER_RATE);

      const gasUsage = Math.max(0, energyDetails.gasM3.close - energyDetails.gasM3.open);
      const totalGas = Math.round(gasUsage * M3_GAS_RATE);

      if (data.expenses.electricity !== totalKwh || data.expenses.water !== totalWater || data.expenses.gas !== totalGas) {
        onUpdate((prev: AppState) => ({
          ...prev,
          expenses: { 
            ...prev.expenses, 
            electricity: totalKwh,
            water: totalWater,
            gas: totalGas
          }
        }));
      }
    }
  }, [energyDetails, activeSub, onUpdate, data.expenses.electricity, data.expenses.water, data.expenses.gas]);

  const handleSave = () => {
    setIsSaving(true);
    setTimeout(() => {
      setIsSaving(false);
      setShowSuccess(true);
      setTimeout(() => setShowSuccess(false), 3000);
    }, 800);
  };

  const updateLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', item: LedgerItem) => {
    onUpdate((prev: AppState) => {
      const newList = [...prev[key], { ...item, id: Date.now().toString() }];
      return { ...prev, [key]: newList };
    });
  };

  const removeLedger = (key: 'cityLedger' | 'customerSat' | 'complimentary', index: number) => {
    onUpdate((prev: AppState) => {
      const newList = prev[key].filter((_, i) => i !== index);
      return { ...prev, [key]: newList };
    });
  };

  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];
  const lostBreakageKeys = ['lostBreakageBar', 'lostBreakageKitchen', 'lostBreakageService'];

  const totalOpex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalEnergy = data.expenses.electricity + data.expenses.water + data.expenses.gas;

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
        {[
          { id: 'OPEX', label: 'Operational Expense', icon: 'fa-file-invoice-dollar' },
          { id: 'ENERGY', label: 'Energy Costs', icon: 'fa-bolt' },
          { id: 'LOST_BREAKAGE', label: 'Lost & Breakage', icon: 'fa-trash-restore' },
          { id: 'CITY', label: 'City Ledger', icon: 'fa-building' },
          { id: 'SAT', label: 'Customer Satisfaction', icon: 'fa-smile-beam' },
          { id: 'COMP', label: 'Complimentary', icon: 'fa-gift' },
          { id: 'FLOOR', label: 'Floor Order & Supplies', icon: 'fa-receipt' }
        ].map(tab => (
          <button 
            key={tab.id}
            onClick={() => setActiveSub(tab.id as any)}
            className={`px-6 py-3 rounded-xl font-black text-[10px] uppercase tracking-widest whitespace-nowrap transition-all flex items-center gap-3 border ${
              activeSub === tab.id ? 'purple-gradient-bg text-white border-white/20' : 'bg-slate-800 text-slate-500 border-white/5 hover:border-white/20'
            }`}
          >
            <i className={`fas ${tab.icon} text-xs`}></i> {tab.label}
          </button>
        ))}
      </div>

      <div className="glass-card p-8 border-l-4 shadow-2xl relative overflow-hidden bg-[#1e293b]/95 border-indigo-500">
        {activeSub === 'ENERGY' && (
          <div className="space-y-10 animate-fade-in relative z-10">
            <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
              <div>
                <h2 className="text-3xl font-black text-white uppercase tracking-tighter flex items-center gap-4">
                  <i className="fas fa-plug text-yellow-500"></i> Energy Cost Calculation
                </h2>
                <p className="text-slate-500 text-[9px] font-black uppercase tracking-widest mt-2">Kalkulasi biaya listrik (KWh), Air (m³), dan Gas</p>
              </div>
              <div className="text-right p-6 rounded-2xl bg-slate-950/80 border border-white/5 shadow-2xl min-w-[280px]">
                <div className="text-[10px] text-slate-500 font-black uppercase mb-2">Total Energy Cost (Monthly)</div>
                <div className="text-4xl font-black text-white">Rp {Math.round(totalEnergy).toLocaleString()}</div>
              </div>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              {/* LISTRIK KWH */}
              <EnergyCard title="Listrik KWh (LWBP & WBP)" icon="fa-moon" color="border-cyan-500/30">
                <div className="grid grid-cols-2 gap-6 mb-6">
                  <div className="space-y-4">
                    <label className="text-[9px] font-black text-cyan-400 uppercase tracking-widest">LWBP Section</label>
                    <div className="grid grid-cols-2 gap-2">
                      <input type="number" step="0.001" placeholder="Open" className="bg-slate-950 border border-white/5 p-2 rounded text-xs font-bold" 
                        value={energyDetails.elecKwh.lwbpOpen || ''} 
                        onChange={e => setEnergyDetails({...energyDetails, elecKwh: {...energyDetails.elecKwh, lwbpOpen: Number(e.target.value)}})} />
                      <input type="number" step="0.001" placeholder="Close" className="bg-slate-950 border border-white/5 p-2 rounded text-xs font-bold" 
                        value={energyDetails.elecKwh.lwbpClose || ''} 
