import React, { useRef, useState } from 'react';
import { AppState, DailySalesData, LedgerItem, GuestComplaint, Staff } from '../types';
import { STAFF_LIST, OT_RATE } from '../constants';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

const ReportingModule: React.FC<Props> = ({ data, filters }) => {
  const reportRef = useRef<HTMLDivElement>(null);
  const [isProcessingPDF, setIsProcessingPDF] = useState(false);

  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthName = months[parseInt(filters.month)];
  const { complaints } = data;

  // 1. SALES CALCULATIONS
  const dailyRecordings = data.sales.dailyRecording || {};
  const mtdRev = Object.values(dailyRecordings).reduce((acc: number, curr: any) => acc + (Number(curr.revenue) || 0), 0);
  const mtdCov = Object.values(dailyRecordings).reduce((acc: number, curr: any) => acc + (Number(curr.covers) || 0), 0);

  const todayRevenue = dailyRecordings[filters.startDate]?.revenue || 0;
  const todayCovers = dailyRecordings[filters.startDate]?.covers || 0;
  const todayAvgCheck = todayCovers > 0 ? Math.floor(todayRevenue / todayCovers) : 0;

  const mtdAvgCheck = mtdCov > 0 ? Math.floor(mtdRev / mtdCov) : 0;
  const mtdAchv = data.sales.budgetRevenue > 0 ? (mtdRev / data.sales.budgetRevenue * 100).toFixed(2) : "0.00";
  const daysPassed = Object.keys(dailyRecordings).length || 1;
  const dailyRunRate = mtdRev / daysPassed;

  // 2. GOOGLE REVIEW CALCULATIONS
  const gr = data.googleReview;
  const totalVotes = gr.stars1 + gr.stars2 + gr.stars3 + gr.stars4 + gr.stars5;
  const totalPoints = (gr.stars1 * 1) + (gr.stars2 * 2) + (gr.stars3 * 3) + (gr.stars4 * 4) + (gr.stars5 * 5);
  const currentRating = totalVotes === 0 ? "0.00" : (totalPoints / totalVotes).toFixed(2);

  // 3. EXPENSE & RATIO CALCULATIONS
  const energyKeys = ['electricity', 'water', 'gas'];
  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];

  const totalEnergy = energyKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalOpex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalLostBreakage = (data.expenses.lostBreakageBar || 0) + (data.expenses.lostBreakageKitchen || 0) + (data.expenses.lostBreakageService || 0);

  const sumLedger = (list: LedgerItem[]) => list.reduce((a, b) => a + (b.qty * b.price), 0);
  const totalCityLedger = sumLedger(data.cityLedger);
  const totalCustSat = sumLedger(data.customerSat);
  const totalComp = sumLedger(data.complimentary);
  const totalFloorOrder = data.expenses.floorOrder || 0;
  const totalChemical = data.expenses.chemical || 0;
  const totalGuestSupplies = data.expenses.guestSupplies || 0;

  const totalAllLedgers = totalCityLedger + totalCustSat + totalComp + totalFloorOrder + totalChemical + totalGuestSupplies;

  const grandTotalExpense = totalOpex + totalEnergy + totalLostBreakage + totalAllLedgers;
  const calcRatio = (val: number) => mtdRev > 0 ? (val / mtdRev * 100).toFixed(2) : "0.00";

  // Food Cost Calculation (Total Revenue / Floor Order)
  const foodCostRatio = totalFloorOrder > 0 ? (mtdRev / totalFloorOrder).toFixed(2) : "0.00";

  // 4. QA CALCULATIONS
  const calcSectionAvg = (sec: any) => ((sec.product + sec.cleanliness + sec.grooming) / 3).toFixed(2);
  const outletAvg = ((Number(calcSectionAvg(data.qa.kitchen)) + Number(calcSectionAvg(data.qa.bar)) + Number(calcSectionAvg(data.qa.service))) / 3).toFixed(2);

  // 5. STAFF PERFORMANCE & OT CALCULATIONS
  const staffPerformance = data.staffList.map(staff => {
    const otEntry = data.overtime.find(o => o.staffId === staff.id);
    const commentEntry = data.guestComments.find(c => c.staffId === staff.id);
    const netOtHours = otEntry ? Math.max(0, otEntry.hours - otEntry.break1) : 0;
    return {
      id: staff.id,
      name: staff.name,
      role: staff.role,
      isLeader: staff.isLeader,
      otCost: netOtHours * OT_RATE,
      otHours: netOtHours,
      mentions: commentEntry?.achievement || 0
    };
  });

  const totalOvertimeHours = staffPerformance.reduce((a, b) => a + b.otHours, 0);
  const totalOvertimeCost = staffPerformance.reduce((a, b) => a + b.otCost, 0);

  const leaders = staffPerformance.filter(s => s.isLeader);
  const crews = staffPerformance.filter(s => !s.isLeader);
  const avgLeaderOT = leaders.length > 0 ? (leaders.reduce((a, b) => a + b.otHours, 0) / leaders.length).toFixed(1) : "0.0";
  const avgCrewOT = crews.length > 0 ? (crews.reduce((a, b) => a + b.otHours, 0) / crews.length).toFixed(1) : "0.0";

  const handleDownloadPDF = () => {
    if (!reportRef.current) return;
    setIsProcessingPDF(true);
    const element = reportRef.current;
    const filename = `Report_Performance_${currentMonthName}_${filters.startDate}.pdf`;

    const opt = {
      margin: 10,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    // @ts-ignore
    window.html2pdf().from(element).set(opt).save().then(() => {
      setIsProcessingPDF(false);
    });
  };

  const handleSharePDF = async () => {
    if (!reportRef.current) return;
    setIsProcessingPDF(true);
    const element = reportRef.current;
    const filename = `Performance_Report_${filters.startDate}.pdf`;

    const opt = {
      margin: 10,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    try {
      // @ts-ignore
      const blob = await window.html2pdf().from(element).set(opt).output('blob');
      const file = new File([blob], filename, { type: 'application/pdf' });

      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        await navigator.share({
          files: [file],
          title: 'SH THE BARN - Performance Report',
          text: `Berikut adalah laporan performa untuk periode ${filters.startDate}.`,
        });
      } else {
        // Fallback if sharing is not supported
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = filename;
        a.click();
        alert("Pembagian file secara langsung tidak didukung di browser ini. File telah diunduh, silakan lampirkan secara manual ke WhatsApp.");
      }
    } catch (err) {
      console.error("Error sharing PDF:", err);
      alert("Gagal memproses pembagian PDF.");
    } finally {
      setIsProcessingPDF(false);
    }
  };

  const shareWAText = () => {
    const text = encodeURIComponent(
      `*SH THE BARN - EXECUTIVE REPORT*\n` +
      `*PERIODE: ${currentMonthName.toUpperCase()} ${new Date().getFullYear()}*\n` +
      `------------------------------------------\n\n` +
      `💰 *TODAY REV:* Rp ${todayRevenue.toLocaleString()}\n` +
      `📈 *MTD REV:* Rp ${mtdRev.toLocaleString()} (${mtdAchv}%)\n` +
      `🍴 *FOOD COST RATIO:* ${foodCostRatio}\n` +
      `⏰ *TOTAL OT:* ${totalOvertimeHours}h (Rp ${totalOvertimeCost.toLocaleString()})\n` +
      `💸 *TOTAL EXP:* Rp ${grandTotalExpense.toLocaleString()} (${calcRatio(grandTotalExpense)}%)\n` +
      `⭐ *GOOGLE:* ${currentRating} ★\n` +
      `📋 *QA SCORE:* ${outletAvg}%\n\n` +
      `_Generated by Christian Intelligence v3.6_`
    );
    window.open(`https://wa.me/?text=${text}`, '_blank');
  };

  const LedgerSection = ({ title, items, color, icon }: { title: string, items: LedgerItem[], color: string, icon: string }) => {
    const total = sumLedger(items);
    return (
      <div className="flex flex-col border border-white/5 bg-slate-900/40 p-5 rounded-2xl print:border-black print:bg-white transition-all hover:bg-slate-900/60 shadow-xl">
        <div className={`flex items-center justify-between mb-4 ${color}`}>
          <div className="flex items-center gap-2">
            <i className={`fas ${icon}`}></i>
            <span className="text-[10px] font-black uppercase tracking-widest">{title}</span>
          </div>
        </div>
        <div className="flex-1 space-y-2 mb-4 max-h-[150px] overflow-y-auto no-scrollbar">
          {items.length === 0 ? (
            <div className="text-[9px] text-slate-600 italic py-2 text-center border border-dashed border-white/5 rounded-lg">No entries</div>
          ) : (
            items.map(item => (
              <div key={item.id} className="flex justify-between items-start text-[9px] border-b border-white/5 pb-1 print:border-black">
                <div className="flex flex-col">
                  <span className="text-white print:text-black font-bold uppercase">{item.name}</span>
                  <span className="text-slate-500 italic tracking-tighter">{item.qty} x Rp {item.price.toLocaleString()}</span>
                </div>
                <span className="text-white print:text-black font-black">Rp {(item.qty * item.price).toLocaleString()}</span>
              </div>
            ))
          )}
        </div>
        <div className="pt-2 border-t border-white/10 flex justify-between items-center print:border-black">
          <span className="text-[8px] font-black text-slate-500 uppercase">Sub-Total</span>
          <span className={`text-xs font-black ${color} print:text-black`}>Rp {total.toLocaleString()}</span>
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur pb-20 print:p-0 print:m-0" ref={reportRef}>
      {/* HEADER SECTION */}
      <div className="glass-card p-8 border-l-4 border-indigo-500 shadow-2xl bg-[#1e293b]/95 relative overflow-hidden no-print">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
          <i className="fas fa-file-contract text-[180px]"></i>
        </div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-6">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <span className="bg-indigo-500 text-white text-[8px] font-black uppercase px-3 py-1 rounded-full tracking-widest shadow-lg">Ultimate v3.6</span>
              <span className="text-slate-500 font-black text-[10px] uppercase tracking-widest">{currentMonthName} {new Date().getFullYear()}</span>
            </div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none">Performance Report</h2>
            <p className="text-slate-500 font-black text-[10px] uppercase tracking-[0.2em] mt-2">Executive Summary & Comprehensive Audit</p>
          </div>
          <div className="flex flex-wrap gap-3 justify-center md:justify-end">
            <button 
              onClick={handleDownloadPDF} 
              disabled={isProcessingPDF}
              className="px-6 py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 border border-white/5 flex items-center gap-3 disabled:opacity-50"
            >
              {isProcessingPDF ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-file-pdf text-red-400"></i>}
              {isProcessingPDF ? 'Processing...' : 'Download PDF'}
            </button>
            <div className="flex gap-2">
              <button 
                onClick={handleSharePDF} 
                disabled={isProcessingPDF}
                className="px-6 py-4 bg-emerald-700 hover:bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-2xl active:scale-95 border border-white/10 flex items-center gap-3 disabled:opacity-50"
              >
                <i className="fas fa-share-alt"></i> Share PDF
              </button>
              <button 
                onClick={shareWAText} 
                className="px-4 py-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-2xl active:scale-95 flex items-center gap-3"
                title="Share as Text"
              >
                <i className="fab fa-whatsapp"></i> Text
              </button>
            </div>
          </div>
        </div>
      </div>

      {/* PRINT-ONLY HEADER */}
      <div className="hidden print:block text-center border-b-8 border-double border-black pb-8 mb-10">
        <h1 className="text-6xl font-black uppercase tracking-tighter text-black">SH THE BARN</h1>
        <p className="text-xl font-bold uppercase tracking-[0.4em] text-black mt-2 italic">Ultimate Executive Performance Report</p>
        <div className="flex justify-between mt-10 text-[10px] font-black uppercase text-black">
          <div className="text-left">
            <div>Periode: {filters.startDate} - {filters.endDate}</div>
            <div>Bulan Fiskal: {currentMonthName.toUpperCase()}</div>
          </div>
          <div className="text-right">
            <div>Dibuat Oleh: CHRISTIAN (SYSTEM)</div>
            <div>Status Laporan: VALIDATED</div>
          </div>
        </div>
      </div>

      {/* CORE KPI GRID */}
      <div className="grid grid-cols-2 md:grid-cols-4 lg:grid-cols-8 gap-4">
        {[
          { label: 'TODAY REV', val: `Rp ${todayRevenue.toLocaleString()}`, icon: 'fa-calendar-day', color: 'text-indigo-400', bg: 'bg-indigo-500/10' },
          { label: 'MTD REVENUE', val: `Rp ${mtdRev.toLocaleString()}`, icon: 'fa-coins', color: 'text-emerald-400', bg: 'bg-emerald-500/10' },
          { label: 'PERF %', val: `${mtdAchv}%`, icon: 'fa-bullseye', color: 'text-pink-400', bg: 'bg-pink-500/10' },
          { label: 'FOOD COST', val: foodCostRatio, icon: 'fa-utensils', color: 'text-orange-400', bg: 'bg-orange-500/10' },
          { label: 'OPEX TOTAL', val: `Rp ${totalOpex.toLocaleString()}`, icon: 'fa-file-invoice-dollar', color: 'text-red-400', bg: 'bg-red-500/10' },
