/**
 * Layanan Sinkronisasi Cloud
 * Menggunakan pendekatan REST API (Simulasi menggunakan storage bin / backend)
 */

const CLOUD_API_BASE = 'https://api.jsonbin.io/v3/b'; // Contoh endpoint (Membutuhkan API Key untuk real prod)
// Untuk keperluan demo ini, kita menggunakan sistem simulasi online berbasis localStorage 
// yang terstruktur seperti API agar mudah dipindah ke Firebase/Supabase nanti.

export async function saveUserData(email: string, data: any): Promise<boolean> {
  try {
    // Simulasi Delay Network
    await new Promise(r => setTimeout(r, 800));

    // Simpan ke 'Cloud' (Simulasi menggunakan database identitas email)
    const dbKey = `BARN_DB_${email.toLowerCase()}`;
    localStorage.setItem(dbKey, JSON.stringify({
      lastUpdated: new Date().toISOString(),
      payload: data
    }));

    console.log(`[CloudSync] Data saved for ${email}`);
    return true;
  } catch (error) {
    console.error('[CloudSync] Save failed:', error);
    return false;
  }
}

export async function fetchUserData(email: string): Promise<any | null> {
  try {
    await new Promise(r => setTimeout(r, 1000));
    const dbKey = `BARN_DB_${email.toLowerCase()}`;
    const raw = localStorage.getItem(dbKey);

    if (!raw) return null;

    const parsed = JSON.parse(raw);
    return parsed.payload;
  } catch (error) {
    console.error('[CloudSync] Fetch failed:', error);
    return null;
  }
}

/**
 * Hook sederhana untuk mendeteksi perubahan dari perangkat lain (Simulasi)
 */
export function startRealtimeListener(email: string, onUpdate: (data: any) => void) {
  const check = () => {
    const dbKey = `BARN_DB_${email.toLowerCase()}`;
    const raw = localStorage.getItem(dbKey);
    if (raw) {
      const data = JSON.parse(raw);
      onUpdate(data.payload);
    }
  };

  // Cek setiap 15 detik jika ada update dari 'cloud'
  const interval = setInterval(check, 15000);
  return () => clearInterval(interval);
}

