import React, { useMemo } from 'react';
import { AppState, DailySalesData } from '../types';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

interface DayEntry {
  dateStr: string;
  dayNum: number;
  dayName: string;
  revenue: number;
  covers: number;
  avgCheck: number;
}

interface WeekData {
  id: number;
  label: string;
  range: string;
  revenue: number;
  covers: number;
  target: number;
  achievement: number;
  avgCheck: number;
  days: DayEntry[];
}

const WeeklyPerformanceModule: React.FC<Props> = ({ data, filters }) => {
  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthName = months[parseInt(filters.month)];
  const currentYear = new Date().getFullYear();

  const weeklyStats = useMemo(() => {
    const dailyRec = data.sales.dailyRecording || {};
    const targets = data.dailyTargets || {};

    const weeks: WeekData[] = [
      { id: 1, label: 'WEEK 1', range: 'Tanggal 1 - 7', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
      { id: 2, label: 'WEEK 2', range: 'Tanggal 8 - 15', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
      { id: 3, label: 'WEEK 3', range: 'Tanggal 16 - 23', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
      { id: 4, label: 'WEEK 4', range: 'Tanggal 24 - Akhir', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
    ];

    const daysInMonth = new Date(currentYear, parseInt(filters.month) + 1, 0).getDate();

    for (let day = 1; day <= daysInMonth; day++) {
      const monthStr = (parseInt(filters.month) + 1).toString().padStart(2, '0');
      const dayStr = day.toString().padStart(2, '0');
      const dateKey = `${currentYear}-${monthStr}-${dayStr}`;

      const record = dailyRec[dateKey] || { revenue: 0, covers: 0 };
      const dayName = new Intl.DateTimeFormat('id-ID', { weekday: 'long' }).format(new Date(currentYear, parseInt(filters.month), day));

      let weekIdx = -1;
      if (day >= 1 && day <= 7) weekIdx = 0;
      else if (day >= 8 && day <= 15) weekIdx = 1;
      else if (day >= 16 && day <= 23) weekIdx = 2;
      else if (day >= 24) weekIdx = 3;

      if (weekIdx !== -1) {
        const rev = Number(record.revenue) || 0;
        const cov = Number(record.covers) || 0;
        const avg = cov > 0 ? Math.floor(rev / cov) : 0;

        weeks[weekIdx].revenue += rev;
        weeks[weekIdx].covers += cov;
        weeks[weekIdx].target += targets[dateKey] || 0;
        weeks[weekIdx].days.push({
          dateStr: dateKey,
          dayNum: day,
          dayName: dayName,
          revenue: rev,
          covers: cov,
          avgCheck: avg
        });
      }
    }

    return weeks.map(w => ({
      ...w,
      achievement: w.target > 0 ? (w.revenue / w.target * 100) : 0,
      avgCheck: w.covers > 0 ? Math.floor(w.revenue / w.covers) : 0
    }));
  }, [data.sales.dailyRecording, data.dailyTargets, filters.month]);

  return (
    <div className="space-y-8 animate-fade-in no-blur pb-10">
      <div className="glass-card p-8 border-l-4 border-purple-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
          <i className="fas fa-calendar-week text-[180px]"></i>
        </div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-6">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <span className="bg-purple-500 text-white text-[8px] font-black uppercase px-3 py-1 rounded-full tracking-widest shadow-lg italic">Weekly Analytics</span>
              <span className="text-slate-500 font-black text-[10px] uppercase tracking-widest">{currentMonthName} {currentYear}</span>
            </div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none">Weekly Performance</h2>
            <p className="text-slate-500 font-black text-[10px] uppercase tracking-[0.2em] mt-2">Daftar Tanggal & Pencapaian Berdasarkan Grup Minggu</p>
          </div>
          <div className="flex gap-4">
             <div className="bg-slate-950/60 p-4 rounded-2xl border border-white/5 text-center min-w-[150px]">
                <div className="text-[8px] font-black text-slate-600 uppercase mb-1">Total Month Revenue</div>
                <div className="text-xl font-black text-emerald-400">Rp {weeklyStats.reduce((a,b)=>a+b.revenue,0).toLocaleString()}</div>
             </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-4 gap-6 items-start">
        {weeklyStats.map((week) => (
          <div key={week.id} className="glass-card group hover:border-purple-500/40 transition-all duration-300 overflow-hidden bg-slate-900/40 flex flex-col min-h-[700px] shadow-2xl">
            {/* Week Header */}
            <div className="p-6 border-b border-white/5 flex items-center gap-4 bg-slate-950/30">
               <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-purple-600 to-indigo-700 flex items-center justify-center text-white shadow-xl group-hover:scale-110 transition-transform">
                  <span className="text-xl font-black">{week.id}</span>
               </div>
               <div>
                  <h3 className="text-xl font-black text-white uppercase tracking-tight leading-none mb-1">{week.label}</h3>
                  <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">{week.range}</p>
               </div>
            </div>

            {/* Content List Section */}
            <div className="flex-1 flex flex-col">
              {/* Main Metrics Summary */}
              <div className="p-6 bg-slate-950/20 border-b border-white/5">
