                          <span className="text-[10px] font-black text-slate-300 leading-none">{day.covers}</span>
                        </div>
                        <div className="flex flex-col items-end">
                          <span className="text-[7px] font-black text-slate-500 uppercase tracking-tighter">Avg Check</span>
                          <span className="text-[10px] font-black text-indigo-400 leading-none">Rp {day.avgCheck.toLocaleString()}</span>
                        </div>
                      </div>
                    )}
