import React, { useMemo, useState } from 'react';
import { AppState, DailySalesData } from '../types';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

interface DayEntry {
  dateStr: string;
  dayNum: number;
  dayName: string;
  weekdayIdx: number; // 0 (Sen) - 6 (Min)
  revenue: number;
  covers: number;
  avgCheck: number;
  target: number;
  achievement: number;
}

interface WeekData {
  id: number;
  label: string;
  range: string;
  revenue: number;
  covers: number;
  target: number;
  achievement: number;
  avgCheck: number;
  days: DayEntry[];
}

const WeeklyPerformanceModule: React.FC<Props> = ({ data, filters }) => {
  const [hoveredDay, setHoveredDay] = useState<DayEntry | null>(null);

  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const weekdays = ["Sen", "Sel", "Rab", "Kam", "Jum", "Sab", "Min"];
  const currentMonthName = months[parseInt(filters.month)];
  const currentYear = new Date().getFullYear();

  const weeklyStats = useMemo(() => {
    const dailyRec = data.sales.dailyRecording || {};
    const targets = data.dailyTargets || {};

    const weeks: WeekData[] = [
      { id: 1, label: 'WEEK 1', range: 'Tanggal 1 - 7', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
      { id: 2, label: 'WEEK 2', range: 'Tanggal 8 - 15', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
      { id: 3, label: 'WEEK 3', range: 'Tanggal 16 - 23', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
      { id: 4, label: 'WEEK 4', range: 'Tanggal 24 - Akhir', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
    ];

    const daysInMonth = new Date(currentYear, parseInt(filters.month) + 1, 0).getDate();

    for (let day = 1; day <= daysInMonth; day++) {
      const monthStr = (parseInt(filters.month) + 1).toString().padStart(2, '0');
      const dayStr = day.toString().padStart(2, '0');
      const dateKey = `${currentYear}-${monthStr}-${dayStr}`;

      const record = dailyRec[dateKey] || { revenue: 0, covers: 0 };
      const dayTarget = targets[dateKey] || 0;
      const dateObj = new Date(currentYear, parseInt(filters.month), day);
      const dayName = new Intl.DateTimeFormat('id-ID', { weekday: 'long' }).format(dateObj);

      // Get weekday index: Monday is 0, Sunday is 6
      let weekdayIdx = dateObj.getDay() - 1;
      if (weekdayIdx === -1) weekdayIdx = 6; // Sunday

      let weekIdx = -1;
      if (day >= 1 && day <= 7) weekIdx = 0;
      else if (day >= 8 && day <= 15) weekIdx = 1;
      else if (day >= 16 && day <= 23) weekIdx = 2;
      else if (day >= 24) weekIdx = 3;

      if (weekIdx !== -1) {
        const rev = Number(record.revenue) || 0;
        const cov = Number(record.covers) || 0;
        const avg = cov > 0 ? Math.floor(rev / cov) : 0;
        const ach = dayTarget > 0 ? (rev / dayTarget * 100) : 0;

        weeks[weekIdx].revenue += rev;
        weeks[weekIdx].covers += cov;
        weeks[weekIdx].target += dayTarget;
        weeks[weekIdx].days.push({
          dateStr: dateKey,
          dayNum: day,
          dayName: dayName,
          weekdayIdx: weekdayIdx,
          revenue: rev,
          covers: cov,
          avgCheck: avg,
          target: dayTarget,
          achievement: ach
        });
      }
    }

    return weeks.map(w => ({
      ...w,
      achievement: w.target > 0 ? (w.revenue / w.target * 100) : 0,
      avgCheck: w.covers > 0 ? Math.floor(w.revenue / w.covers) : 0
    }));
  }, [data.sales.dailyRecording, data.dailyTargets, filters.month]);

  // Helper for matrix background color
  const getCellColor = (ach: number, revenue: number) => {
    if (revenue === 0) return 'bg-slate-800/20 border-white/5 opacity-40';
    if (ach >= 110) return 'bg-emerald-500/80 border-emerald-400 shadow-[inset_0_0_15px_rgba(16,185,129,0.3)]';
    if (ach >= 100) return 'bg-emerald-500/40 border-emerald-500/50';
    if (ach >= 80) return 'bg-amber-500/40 border-amber-500/50';
    return 'bg-red-500/40 border-red-500/50';
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur pb-10">
      {/* HEADER SECTION */}
      <div className="glass-card p-8 border-l-4 border-purple-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none text-white">
          <i className="fas fa-calendar-week text-[180px]"></i>
        </div>
        <div className="relative z-10 flex flex-col md:flex-row justify-between items-center gap-6">
          <div>
            <div className="flex items-center gap-3 mb-2">
              <span className="bg-purple-500 text-white text-[8px] font-black uppercase px-3 py-1 rounded-full tracking-widest shadow-lg italic">Weekly Analytics</span>
              <span className="text-slate-500 font-black text-[10px] uppercase tracking-widest">{currentMonthName} {currentYear}</span>
            </div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none">Weekly Performance</h2>
            <p className="text-slate-500 font-black text-[10px] uppercase tracking-[0.2em] mt-2">Audit & Visual Matrix of Revenue Achievement</p>
          </div>
          <div className="flex gap-4">
             <div className="bg-slate-950/60 p-5 rounded-2xl border border-white/5 text-center min-w-[180px] shadow-inner">
                <div className="text-[9px] font-black text-slate-500 uppercase mb-1 tracking-widest">MTD Gross Revenue</div>
                <div className="text-2xl font-black text-emerald-400 leading-none">Rp {weeklyStats.reduce((a,b)=>a+b.revenue,0).toLocaleString()}</div>
             </div>
          </div>
        </div>
      </div>

      {/* NEW: PERFORMANCE MATRIX (HEATMAP) */}
      <div className="glass-card p-8 bg-slate-900/40 border-t-2 border-indigo-500 shadow-2xl">
        <div className="flex items-center justify-between mb-8">
           <h3 className="text-xs font-black uppercase text-white flex items-center gap-3">
              <i className="fas fa-th text-indigo-400"></i> Performance Matrix Heatmap
           </h3>
           <div className="flex items-center gap-4">
              <div className="flex items-center gap-2">
                 <div className="w-3 h-3 rounded-sm bg-red-500/40 border border-red-500/50"></div>
                 <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">&lt; 80%</span>
              </div>
              <div className="flex items-center gap-2">
                 <div className="w-3 h-3 rounded-sm bg-amber-500/40 border border-amber-500/50"></div>
                 <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">80-100%</span>
              </div>
              <div className="flex items-center gap-2">
                 <div className="w-3 h-3 rounded-sm bg-emerald-500/40 border border-emerald-500/50"></div>
                 <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">100-110%</span>
              </div>
              <div className="flex items-center gap-2">
                 <div className="w-3 h-3 rounded-sm bg-emerald-500/80 border border-emerald-400"></div>
                 <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest">&gt; 110%</span>
              </div>
           </div>
        </div>

        <div className="relative">
          <div className="grid grid-cols-7 gap-4">
            {weekdays.map(day => (
              <div key={day} className="text-center text-[10px] font-black text-slate-600 uppercase tracking-[0.2em] mb-4">
                {day}
              </div>
            ))}

            {weeklyStats.map((week, wIdx) => {
              // Create an array for the row (7 days)
              const rowDays = Array(7).fill(null);
              week.days.forEach(day => {
                rowDays[day.weekdayIdx] = day;
              });

              return rowDays.map((day, dIdx) => (
                <div 
                  key={`${wIdx}-${dIdx}`} 
                  onMouseEnter={() => day && setHoveredDay(day)}
                  onMouseLeave={() => setHoveredDay(null)}
                  className={`relative h-24 rounded-2xl border transition-all duration-300 flex flex-col items-center justify-center cursor-help group/cell ${
                    day ? getCellColor(day.achievement, day.revenue) : 'bg-transparent border-dashed border-white/5 opacity-10'
                  }`}
                >
                  {day && (
                    <>
                      <span className="text-lg font-black text-white group-hover/cell:scale-110 transition-transform">{day.dayNum}</span>
                      <span className="text-[7px] font-black text-white/50 uppercase tracking-tighter mt-1">{day.achievement.toFixed(0)}% Achv</span>

                      {/* Interactive Tooltip logic could go here or floating */}
                      <div className="absolute top-1 right-2">
                        <div className={`w-1.5 h-1.5 rounded-full ${day.revenue > 0 ? (day.achievement >= 100 ? 'bg-white animate-pulse' : 'bg-white/40') : 'transparent'}`}></div>
                      </div>
                    </>
                  )}
                </div>
              ));
            })}
          </div>

          {/* Floating Tooltip for Matrix */}
          {hoveredDay && (
            <div className="absolute top-0 right-0 translate-x-4 -translate-y-4 z-50 animate-fade-in">
              <div className="bg-slate-950 border border-white/10 p-5 rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] min-w-[200px] backdrop-blur-xl">
                <div className="text-[9px] font-black text-indigo-400 uppercase tracking-widest mb-1">{hoveredDay.dayName}</div>
                <div className="text-lg font-black text-white mb-4 leading-none">Tanggal {hoveredDay.dayNum}</div>

                <div className="space-y-2 border-t border-white/5 pt-3">
                  <div className="flex justify-between items-center text-[9px] uppercase font-bold text-slate-500">
                    <span>Revenue</span>
                    <span className="text-white">Rp {hoveredDay.revenue.toLocaleString()}</span>
                  </div>
                  <div className="flex justify-between items-center text-[9px] uppercase font-bold text-slate-500">
                    <span>Target</span>
                    <span className="text-slate-400">Rp {hoveredDay.target.toLocaleString()}</span>
                  </div>
                  <div className="flex justify-between items-center text-[9px] uppercase font-bold text-slate-500">
                    <span>Covers</span>
                    <span className="text-indigo-300">{hoveredDay.covers} Pax</span>
                  </div>
                  <div className="flex justify-between items-center pt-2 mt-2 border-t border-white/5">
                    <span className="text-[9px] font-black text-indigo-500 uppercase">Achievement</span>
                    <span className={`text-xs font-black ${hoveredDay.achievement >= 100 ? 'text-emerald-400' : 'text-orange-400'}`}>{hoveredDay.achievement.toFixed(1)}%</span>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-2 xl:grid-cols-4 gap-6 items-start">
        {weeklyStats.map((week) => (
          <div key={week.id} className="glass-card group hover:border-purple-500/40 transition-all duration-300 overflow-hidden bg-slate-900/40 flex flex-col min-h-[750px] shadow-2xl">
            {/* Week Header */}
            <div className="p-6 border-b border-white/5 flex items-center gap-4 bg-slate-950/40">
               <div className="w-12 h-12 rounded-2xl bg-gradient-to-br from-purple-600 to-indigo-700 flex items-center justify-center text-white shadow-xl group-hover:scale-110 transition-transform">
                  <span className="text-xl font-black">{week.id}</span>
               </div>
               <div>
                  <h3 className="text-xl font-black text-white uppercase tracking-tight leading-none mb-1">{week.label}</h3>
                  <p className="text-[9px] font-bold text-slate-500 uppercase tracking-widest italic">{week.range}</p>
               </div>
            </div>

            {/* Content List Section */}
            <div className="flex-1 flex flex-col">
              {/* Main Metrics Summary */}
              <div className="p-6 bg-slate-950/20 border-b border-white/5">
                <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Accumulated Weekly Revenue</div>
                <div className="text-2xl font-black text-white mb-4">Rp {week.revenue.toLocaleString()}</div>

                <div className="flex justify-between items-center mb-2">
                   <span className="text-[9px] font-black text-slate-500 uppercase">Target Achievement</span>
