import React, { useState, useCallback, useEffect, useMemo, useRef } from 'react';
import { ModuleType, AppState, User, SyncStatus } from './types';
import { INITIAL_STATE } from './constants';
import { fetchUserData, saveUserData, startRealtimeListener } from './services/cloudService';
import Header from './components/Header';
import Dashboard from './components/Dashboard';
import LoginModule from './components/LoginModule';
import GoogleReviewModule from './components/GoogleReviewModule';
import OvertimeModule from './components/OvertimeModule';
import QAModule from './components/QAModule';
import ExpensesModule from './components/ExpensesModule';
import ReportingModule from './components/ReportingModule';
import MonthlyReportingModule from './components/MonthlyReportingModule';
import WeeklyPerformanceModule from './components/WeeklyPerformanceModule';
import GuestCommentModule from './components/GuestCommentModule';
import GuestComplaintModule from './components/GuestComplaintModule';
import YTDModule from './components/YTDModule';
import SalesModule from './components/SalesModule';
import AdminModule from './components/AdminModule';

const App: React.FC = () => {
  // State User & Sync
  const [user, setUser] = useState<User>({ email: '', isLoggedIn: false });
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('offline');
  const lastSyncHash = useRef<string>('');
  const syncTimeout = useRef<any>(null);

  const [activeModule, setActiveModule] = useState<ModuleType>(ModuleType.DASHBOARD);
  const [isAdmin, setIsAdmin] = useState(false);
  const [monthlyData, setMonthlyData] = useState<Record<string, AppState>>({
    [new Date().getMonth().toString()]: INITIAL_STATE
  });

  const [isFullScreen, setIsFullScreen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [filters, setFilters] = useState({
    month: new Date().getMonth().toString(),
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0]
  });

  const currentData = useMemo(() => {
    return monthlyData[filters.month] || INITIAL_STATE;
  }, [monthlyData, filters.month]);

  // Handle Login & Data Fetching
  const handleLogin = async (email: string) => {
    setIsRefreshing(true);
    const cloudData = await fetchUserData(email);

    if (cloudData) {
      setMonthlyData(cloudData);
      lastSyncHash.current = JSON.stringify(cloudData);
    }

    setUser({ email, isLoggedIn: true });
    setSyncStatus('online');
    setIsRefreshing(false);
  };

  // Logika Auto-Save (Sync ke Cloud)
  useEffect(() => {
    if (!user.isLoggedIn) return;

    const currentHash = JSON.stringify(monthlyData);
    if (currentHash === lastSyncHash.current) return;

    setSyncStatus('syncing');

    // Debounce save 2 detik
    if (syncTimeout.current) clearTimeout(syncTimeout.current);
    syncTimeout.current = setTimeout(async () => {
      const success = await saveUserData(user.email, monthlyData);
      if (success) {
        lastSyncHash.current = currentHash;
        setSyncStatus('online');
      } else {
        setSyncStatus('error');
      }
    }, 2000);

    return () => clearTimeout(syncTimeout.current);
  }, [monthlyData, user.email, user.isLoggedIn]);

  // Real-time Listener untuk Update dari Perangkat Lain
  useEffect(() => {
    if (!user.isLoggedIn) return;

    const unsubscribe = startRealtimeListener(user.email, (newData) => {
      const newHash = JSON.stringify(newData);
      if (newHash !== JSON.stringify(monthlyData)) {
        console.log('[App] Data updated from other device');
        setMonthlyData(newData);
        lastSyncHash.current = newHash;
      }
    });

    return unsubscribe;
  }, [user.isLoggedIn, user.email, monthlyData]);

  useEffect(() => {
    setIsRefreshing(true);
    const timer = setTimeout(() => {
      setIsRefreshing(false);
    }, 400);
    return () => clearTimeout(timer);
  }, [filters.month, filters.startDate, filters.endDate]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().then(() => setIsFullScreen(true)).catch(e => console.error(e));
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen().then(() => setIsFullScreen(false));
      }
    }
  };

  const updateCurrentData = useCallback((path: keyof AppState, newValue: any) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: {
          ...currentMonthBase,
          [path]: newValue
        }
      };
    });
  }, [filters.month]);

  const updateFullState = useCallback((updater: (prev: AppState) => AppState) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: updater(currentMonthBase)
      };
    });
  }, [filters.month]);

  const toggleAdminMode = () => {
    setIsAdmin(!isAdmin);
    if (!isAdmin) {
       setActiveModule(ModuleType.ADMIN);
    } else {
       setActiveModule(ModuleType.DASHBOARD);
    }
  };

  if (!user.isLoggedIn) {
    return <LoginModule onLogin={handleLogin} />;
  }

  const renderModule = () => {
    if (isRefreshing) {
      return (
        <div className="h-[60vh] flex flex-col items-center justify-center space-y-4 animate-pulse">
           <div className="w-16 h-16 border-4 border-purple-500/20 border-t-purple-500 rounded-full animate-spin"></div>
           <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Syncing Cloud Data...</p>
        </div>
      );
    }

    switch (activeModule) {
      case ModuleType.DASHBOARD:
        return <Dashboard onSelect={setActiveModule} isAdmin={isAdmin} />;
      case ModuleType.SALES:
        return <SalesModule 
          data={currentData.sales} 
          dailyTargets={currentData.dailyTargets} 
          filters={filters}
          onUpdate={(v) => updateCurrentData('sales', v)} 
        />;
      case ModuleType.GOOGLE_REVIEW:
        return <GoogleReviewModule data={currentData.googleReview} onUpdate={(v) => updateCurrentData('googleReview', v)} />;
      case ModuleType.GUEST_COMMENT:
        return <GuestCommentModule 
          data={currentData.guestComments} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('guestComments', v)} 
        />;
      case ModuleType.GUEST_COMPLAINT:
        return <GuestComplaintModule 
          data={currentData.complaints} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('complaints', v)} 
        />;
      case ModuleType.OVERTIME:
        return <OvertimeModule 
          data={currentData.overtime} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('overtime', v)} 
        />;
      case ModuleType.QUALITY_ASSURANCE:
        return <QAModule data={currentData.qa} onUpdate={(v) => updateCurrentData('qa', v)} />;
      case ModuleType.EXPENSES:
        return <ExpensesModule data={currentData} onUpdate={updateFullState} />;
      case ModuleType.YTD_REPORT:
        return <YTDModule allMonthlyData={monthlyData} />;
      case ModuleType.REKAPAN:
        return <ReportingModule data={currentData} filters={filters} />;
      case ModuleType.REKAPAN_BULANAN:
        return <MonthlyReportingModule data={currentData} filters={filters} />;
      case ModuleType.WEEKLY_REPORT:
        return <WeeklyPerformanceModule data={currentData} filters={filters} />;
      case ModuleType.ADMIN:
        return <AdminModule data={currentData} onUpdate={updateCurrentData} filters={filters} />;
      default:
        return <Dashboard onSelect={setActiveModule} isAdmin={isAdmin} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col">
      <Header 
        isFullScreen={isFullScreen} 
        onToggleFS={toggleFullScreen} 
        filters={filters}
        onFilterChange={setFilters}
        onHome={() => setActiveModule(ModuleType.DASHBOARD)}
        onAdminToggle={toggleAdminMode}
        isAdmin={isAdmin}
        user={user}
        syncStatus={syncStatus}
      />

      <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
        <div className="max-w-7xl mx-auto">
          <div className="animate-fade-in">
            {renderModule()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

