import React, { useRef, useState } from 'react';
import { AppState, DailySalesData, LedgerItem, GuestComplaint, Staff } from '../types';
import { STAFF_LIST, OT_RATE } from '../constants';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

const MonthlyReportingModule: React.FC<Props> = ({ data, filters }) => {
  const reportRef = useRef<HTMLDivElement>(null);
  const [isProcessingPDF, setIsProcessingPDF] = useState(false);

  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthName = months[parseInt(filters.month)];
  const { complaints } = data;

  // 1. SALES CALCULATIONS
  const dailyRecordings = data.sales.dailyRecording || {};
  const mtdRev = Object.values(dailyRecordings).reduce((acc: number, curr: any) => acc + (Number(curr.revenue) || 0), 0);
  const mtdCov = Object.values(dailyRecordings).reduce((acc: number, curr: any) => acc + (Number(curr.covers) || 0), 0);

  const revenueValues = Object.values(dailyRecordings).map((curr: any) => Number(curr.revenue) || 0);
  const monthMaxRevenue = revenueValues.length > 0 ? Math.max(...revenueValues) : 0;
  const daysPassed = Object.keys(dailyRecordings).length || 1;
  const dailyRunRate = mtdRev / daysPassed;

  const mtdAvgCheck = mtdCov > 0 ? Math.floor(mtdRev / mtdCov) : 0;
  const mtdBudget = data.sales.budgetRevenue || 0;
  const mtdVariance = mtdRev - mtdBudget;
  const mtdAchv = mtdBudget > 0 ? (mtdRev / mtdBudget * 100).toFixed(2) : "0.00";

  // 2. GOOGLE REVIEW CALCULATIONS
  const gr = data.googleReview;
  const totalVotes = gr.stars1 + gr.stars2 + gr.stars3 + gr.stars4 + gr.stars5;
  const totalPoints = (gr.stars1 * 1) + (gr.stars2 * 2) + (gr.stars3 * 3) + (gr.stars4 * 4) + (gr.stars5 * 5);
  const currentRating = totalVotes === 0 ? "0.00" : (totalPoints / totalVotes).toFixed(2);

  // 3. EXPENSE & RATIO CALCULATIONS
  const energyKeys = ['electricity', 'water', 'gas'];
  const opexKeys = ['nonCommodity', 'commodity', 'maintenance', 'asset', 'casual', 'atk'];

  const totalEnergy = energyKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalOpex = opexKeys.reduce((acc, key) => acc + ((data.expenses as any)[key] || 0), 0);
  const totalLostBreakage = (data.expenses.lostBreakageBar || 0) + (data.expenses.lostBreakageKitchen || 0) + (data.expenses.lostBreakageService || 0);

  const sumLedger = (list: LedgerItem[]) => list.reduce((a, b) => a + (b.qty * b.price), 0);
  const totalCityLedger = sumLedger(data.cityLedger);
  const totalCustSat = sumLedger(data.customerSat);
  const totalComp = sumLedger(data.complimentary);
  const totalFloorOrder = data.expenses.floorOrder || 0;
  const totalChemical = data.expenses.chemical || 0;
  const totalGuestSupplies = data.expenses.guestSupplies || 0;

  const totalAllLedgers = totalCityLedger + totalCustSat + totalComp + totalFloorOrder + totalChemical + totalGuestSupplies;

  const grandTotalExpense = totalOpex + totalEnergy + totalLostBreakage + totalAllLedgers;
  const calcRatio = (val: number) => mtdRev > 0 ? (val / mtdRev * 100).toFixed(2) : "0.00";
  const foodCostRatio = totalFloorOrder > 0 ? (mtdRev / totalFloorOrder).toFixed(2) : "0.00";

  // 4. QA CALCULATIONS
  const calcSectionAvg = (sec: any) => ((sec.product + sec.cleanliness + sec.grooming) / 3).toFixed(2);
  const outletAvg = ((Number(calcSectionAvg(data.qa.kitchen)) + Number(calcSectionAvg(data.qa.bar)) + Number(calcSectionAvg(data.qa.service))) / 3).toFixed(2);

  const staffPerformance = data.staffList.map(staff => {
    const otEntry = data.overtime.find(o => o.staffId === staff.id);
    const commentEntry = data.guestComments.find(c => c.staffId === staff.id);
    const netOtHours = otEntry ? Math.max(0, otEntry.hours - otEntry.break1) : 0;
    return {
      id: staff.id,
      name: staff.name,
      role: staff.role,
      isLeader: staff.isLeader,
      otCost: netOtHours * OT_RATE,
      otHours: netOtHours,
      mentions: commentEntry?.achievement || 0
    };
  });

