import React, { useMemo, useState } from 'react';
import { AppState, DailySalesData } from '../types';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

interface DayEntry {
  dateStr: string;
  dayNum: number;
  dayName: string;
  weekdayIdx: number; // 0 (Sen) - 6 (Min)
  revenue: number;
  covers: number;
  avgCheck: number;
  target: number;
  achievement: number;
  isRedDate: boolean;
}

interface WeekData {
  id: number;
  label: string;
  range: string;
  revenue: number;
  covers: number;
  target: number;
  achievement: number;
  avgCheck: number;
  days: DayEntry[];
}

const WeeklyPerformanceModule: React.FC<Props> = ({ data, filters }) => {
  const [hoveredDay, setHoveredDay] = useState<DayEntry | null>(null);

  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const weekdays = ["Sen", "Sel", "Rab", "Kam", "Jum", "Sab", "Min"];
  const currentMonthName = months[parseInt(filters.month)];
  const currentYear = new Date().getFullYear();

  const weeklyStats = useMemo(() => {
    const dailyRec = data.sales.dailyRecording || {};
    const targets = data.dailyTargets || {};
    const holidays = data.holidays || [];

    const weeks: WeekData[] = [
      { id: 1, label: 'WEEK 1', range: 'Tanggal 1 - 7', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
      { id: 2, label: 'WEEK 2', range: 'Tanggal 8 - 15', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
      { id: 3, label: 'WEEK 3', range: 'Tanggal 16 - 23', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
      { id: 4, label: 'WEEK 4', range: 'Tanggal 24 - Akhir', revenue: 0, covers: 0, target: 0, achievement: 0, avgCheck: 0, days: [] },
    ];

    const daysInMonth = new Date(currentYear, parseInt(filters.month) + 1, 0).getDate();

    for (let day = 1; day <= daysInMonth; day++) {
      const monthStr = (parseInt(filters.month) + 1).toString().padStart(2, '0');
      const dayStr = day.toString().padStart(2, '0');
      const dateKey = `${currentYear}-${monthStr}-${dayStr}`;

      const record = dailyRec[dateKey] || { revenue: 0, covers: 0 };
      const dayTarget = targets[dateKey] || 0;
      const dateObj = new Date(currentYear, parseInt(filters.month), day);
      const dayName = new Intl.DateTimeFormat('id-ID', { weekday: 'long' }).format(dateObj);

      let weekdayIdx = dateObj.getDay() - 1;
      if (weekdayIdx === -1) weekdayIdx = 6; 

      // Mark Saturday, Sunday or Admin Holidays as Red Dates
      const isWeekend = (dateObj.getDay() === 0 || dateObj.getDay() === 6);
      const isRedDate = isWeekend || holidays.includes(dateKey);

      let weekIdx = -1;
      if (day >= 1 && day <= 7) weekIdx = 0;
      else if (day >= 8 && day <= 15) weekIdx = 1;
      else if (day >= 16 && day <= 23) weekIdx = 2;
      else if (day >= 24) weekIdx = 3;

      if (weekIdx !== -1) {
        const rev = Number(record.revenue) || 0;
        const cov = Number(record.covers) || 0;
        const avg = cov > 0 ? Math.floor(rev / cov) : 0;
        const ach = dayTarget > 0 ? (rev / dayTarget * 100) : 0;

        weeks[weekIdx].revenue += rev;
        weeks[weekIdx].covers += cov;
        weeks[weekIdx].target += dayTarget;
        weeks[weekIdx].days.push({
          dateStr: dateKey,
          dayNum: day,
          dayName: dayName,
          weekdayIdx: weekdayIdx,
          revenue: rev,
          covers: cov,
          avgCheck: avg,
          target: dayTarget,
          achievement: ach,
          isRedDate: isRedDate
        });
      }
    }

    return weeks.map(w => ({
      ...w,
      achievement: w.target > 0 ? (w.revenue / w.target * 100) : 0,
      avgCheck: w.covers > 0 ? Math.floor(w.revenue / w.covers) : 0
    }));
  }, [data.sales.dailyRecording, data.dailyTargets, data.holidays, filters.month]);

  const getCellColor = (ach: number, revenue: number) => {
    if (revenue === 0) return 'bg-slate-800/20 border-white/5 opacity-40';
