import React, { useState, useMemo } from 'react';
import { AppState, Staff } from '../types';

interface Props {
  data: AppState;
  onUpdate: (path: keyof AppState, newValue: any) => void;
  filters: { month: string; startDate: string; endDate: string };
}

const AdminModule: React.FC<Props> = ({ data, onUpdate, filters }) => {
  const [activeTab, setActiveTab] = useState<'MASTER' | 'DATABASE' | 'CONFIG'>('CONFIG');
  const [isSaving, setIsSaving] = useState(false);

  // State for adding new staff
  const [newStaffName, setNewStaffName] = useState('');
  const [newStaffRole, setNewStaffRole] = useState('SERVICE');
  const [newStaffIsLeader, setNewStaffIsLeader] = useState(false);

  const months = [
    "Januari", "Februari", "Maret", "April", "Mei", "Juni",
    "Juli", "Agustus", "September", "Oktober", "November", "Desember"
  ];

  const currentYear = new Date().getFullYear();
  const selectedMonthIdx = parseInt(filters.month);

  const daysInMonth = useMemo(() => {
    return new Date(currentYear, selectedMonthIdx + 1, 0).getDate();
  }, [selectedMonthIdx, currentYear]);

  const handleUpdateBudget = (val: number) => {
    onUpdate('sales', { ...data.sales, budgetRevenue: val });
  };

  const handleUpdateDailyTarget = (day: number, val: number) => {
    const monthStr = (selectedMonthIdx + 1).toString().padStart(2, '0');
    const dayStr = day.toString().padStart(2, '0');
    const dateKey = `${currentYear}-${monthStr}-${dayStr}`;

    onUpdate('dailyTargets', { ...data.dailyTargets, [dateKey]: val });
  };

  const toggleHoliday = (day: number) => {
    const monthStr = (selectedMonthIdx + 1).toString().padStart(2, '0');
    const dayStr = day.toString().padStart(2, '0');
    const dateKey = `${currentYear}-${monthStr}-${dayStr}`;

    const currentHolidays = data.holidays || [];
    const isHoliday = currentHolidays.includes(dateKey);

    if (isHoliday) {
      onUpdate('holidays', currentHolidays.filter(h => h !== dateKey));
    } else {
      onUpdate('holidays', [...currentHolidays, dateKey]);
    }
  };

  const handleAddStaff = () => {
    if (!newStaffName.trim()) {
      alert("Nama Staff tidak boleh kosong");
      return;
    }

    const newStaff: Staff = {
      id: Date.now().toString(),
      name: newStaffName.toUpperCase(),
      role: newStaffRole,
      isLeader: newStaffIsLeader
    };

    onUpdate('staffList', [...data.staffList, newStaff]);
    setNewStaffName('');
    alert("Staff berhasil ditambahkan.");
  };

  const handleDeleteStaff = (id: string) => {
    const updatedList = data.staffList.filter(s => s.id !== id);
    onUpdate('staffList', updatedList);
  };

  const renderConfigTab = () => {
    const days = Array.from({ length: daysInMonth }, (_, i) => i + 1);

