interface Props {
  data: GuestComplaint[];
  staffList: Staff[];
  onUpdate: (v: GuestComplaint[]) => void;
}

const GuestComplaintModule: React.FC<Props> = ({ data, staffList, onUpdate }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [newComplaint, setNewComplaint] = useState<Partial<GuestComplaint>>({
    date: new Date().toISOString().split('T')[0],
    guestName: '',
    staffInvolved: '',
    chronology: '',
    correctiveAction: '',
    status: 'PENDING'
  });

  const handleAdd = () => {
    if (!newComplaint.guestName || !newComplaint.chronology || !newComplaint.correctiveAction) {
      alert("Harap isi semua kolom wajib (Nama Tamu, Kronologi, & Corrective Action).");
      return;
    }
    const complaint: GuestComplaint = {
      ...newComplaint,
      id: Date.now().toString(),
      status: 'PENDING'
    } as GuestComplaint;

    onUpdate([complaint, ...data]);
    setNewComplaint({
      date: new Date().toISOString().split('T')[0],
      guestName: '',
      staffInvolved: '',
      chronology: '',
      correctiveAction: '',
      status: 'PENDING'
    });
    setIsAdding(false);
  };

  const toggleStatus = (id: string) => {
    const updated = data.map(c => 
      c.id === id ? { ...c, status: (c.status === 'RESOLVED' ? 'PENDING' : 'RESOLVED') as 'RESOLVED' | 'PENDING' } : c
    );
    onUpdate(updated);
  };

  const removeComplaint = (id: string) => {
    if (confirm("Hapus catatan komplain ini?")) {
      onUpdate(data.filter(c => c.id !== id));
    }
  };

  const handleWhatsAppShare = (complaint: GuestComplaint) => {
    const message = `*GUEST COMPLAINT REPORT - SH THE BARN*\n` +
      `------------------------------------------\n` +
      `*Tanggal:* ${complaint.date}\n` +
      `*Tamu:* ${complaint.guestName}\n` +
      `*Staff Terlibat:* ${complaint.staffInvolved || 'N/A'}\n` +
      `*Status:* ${complaint.status}\n\n` +
      `*KRONOLOGI:*\n${complaint.chronology}\n\n` +
      `*CORRECTIVE ACTION:*\n${complaint.correctiveAction}`;

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encodedMessage}`, '_blank');
  };

  return (
