          <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-widest">Dokumentasi & Penyelesaian Masalah</p>
        </div>
        <button 
          onClick={() => setIsAdding(!isAdding)}
          className="relative z-10 px-8 py-4 bg-amber-600 hover:bg-amber-500 rounded-2xl text-xs font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 flex items-center gap-3"
        >
          <i className={`fas ${isAdding ? 'fa-times' : 'fa-plus'}`}></i>
          {isAdding ? 'Batal' : 'Tambah Komplain'}
        </button>
      </div>

      {isAdding && (
        <div className="glass-card p-8 border border-white/10 bg-slate-900/50 space-y-6 animate-slide-up">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Tanggal</label>
              <input 
                type="date"
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm font-bold text-white outline-none focus:ring-2 ring-amber-500"
                value={newComplaint.date}
                onChange={e => setNewComplaint({...newComplaint, date: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Nama Tamu</label>
              <input 
                type="text"
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm font-bold text-white outline-none focus:ring-2 ring-amber-500"
                placeholder="Nama Tamu..."
                value={newComplaint.guestName}
