                <option value="">Pilih Staff...</option>
                {staffList.map(s => <option key={s.id} value={s.name}>{s.name} ({s.role})</option>)}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Kronologi</label>
              <textarea 
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm text-white outline-none focus:ring-2 ring-amber-500 min-h-[120px]"
