import React, { useState } from 'react';
import { GuestComplaint, Staff } from '../types';

interface Props {
  data: GuestComplaint[];
  staffList: Staff[];
  onUpdate: (v: GuestComplaint[]) => void;
}

const GuestComplaintModule: React.FC<Props> = ({ data, staffList, onUpdate }) => {
  const [isAdding, setIsAdding] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [newComplaint, setNewComplaint] = useState<Partial<GuestComplaint>>({
    date: new Date().toISOString().split('T')[0],
    guestName: '',
    staffInvolved: '',
    chronology: '',
    correctiveAction: '',
    status: 'PENDING'
  });

  const handleAdd = () => {
    if (!newComplaint.guestName || !newComplaint.chronology || !newComplaint.correctiveAction) {
      alert("Harap isi semua kolom wajib (Nama Tamu, Kronologi, & Corrective Action).");
      return;
    }
    const complaint: GuestComplaint = {
      ...newComplaint,
      id: Date.now().toString(),
      status: 'PENDING'
    } as GuestComplaint;

    onUpdate([complaint, ...data]);
    setNewComplaint({
      date: new Date().toISOString().split('T')[0],
      guestName: '',
      staffInvolved: '',
      chronology: '',
      correctiveAction: '',
      status: 'PENDING'
    });
    setIsAdding(false);
  };

  const toggleStatus = (id: string) => {
    const updated = data.map(c => 
      c.id === id ? { ...c, status: (c.status === 'RESOLVED' ? 'PENDING' : 'RESOLVED') as 'RESOLVED' | 'PENDING' } : c
    );
    onUpdate(updated);
  };

  const removeComplaint = (id: string) => {
    if (confirm("Hapus catatan komplain ini?")) {
      const updated = data.filter(c => c.id !== id);
      onUpdate(updated);
    }
  };

  const downloadComplaintPDF = (complaint: GuestComplaint) => {
    const element = document.getElementById(`complaint-card-${complaint.id}`);
    if (!element) return;

    setIsProcessing(true);
    const options = {
      margin: 10,
      filename: `Complaint_${complaint.guestName}_${complaint.date}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };

    // @ts-ignore
    window.html2pdf().from(element).set(options).save().then(() => {
      setIsProcessing(false);
    });
  };

  const handleWhatsAppShare = (complaint: GuestComplaint) => {
    const message = `*GUEST COMPLAINT REPORT - SH THE BARN*\n` +
      `------------------------------------------\n` +
      `*Tanggal:* ${complaint.date}\n` +
      `*Tamu:* ${complaint.guestName}\n` +
      `*Staff Terlibat:* ${complaint.staffInvolved || 'N/A'}\n` +
      `*Status:* ${complaint.status}\n\n` +
      `*KRONOLOGI:*\n${complaint.chronology}\n\n` +
      `*CORRECTIVE ACTION:*\n${complaint.correctiveAction}\n\n` +
      `_Laporan lengkap telah diunduh dalam format PDF_`;

    const encodedMessage = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encodedMessage}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 glass-card p-8 border-l-4 border-amber-500 bg-[#1e293b]/95 shadow-2xl relative overflow-hidden no-print">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
           <i className="fas fa-exclamation-triangle text-[180px]"></i>
        </div>
        <div className="relative z-10">
          <h2 className="text-3xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-4">
            <i className="fas fa-user-injured text-amber-500"></i>
            Guest Complaint Issue
          </h2>
          <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-widest">Dokumentasi & Penyelesaian Masalah</p>
        </div>
        <button 
          onClick={() => setIsAdding(!isAdding)}
          className="relative z-10 px-8 py-4 bg-amber-600 hover:bg-amber-500 rounded-2xl text-xs font-black uppercase tracking-widest transition-all shadow-xl active:scale-95 flex items-center gap-3"
        >
          <i className={`fas ${isAdding ? 'fa-times' : 'fa-plus'}`}></i>
          {isAdding ? 'Batal' : 'Tambah Komplain'}
        </button>
      </div>

      {isAdding && (
        <div className="glass-card p-8 border border-white/10 bg-slate-900/50 space-y-6 animate-slide-up no-print">
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Tanggal</label>
              <input 
                type="date"
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm font-bold text-white outline-none focus:ring-2 ring-amber-500"
                value={newComplaint.date}
                onChange={e => setNewComplaint({...newComplaint, date: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Nama Tamu</label>
              <input 
                type="text"
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm font-bold text-white outline-none focus:ring-2 ring-amber-500"
                placeholder="Nama Tamu..."
                value={newComplaint.guestName}
                onChange={e => setNewComplaint({...newComplaint, guestName: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Staff Terlibat</label>
              <select 
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm font-bold text-white outline-none focus:ring-2 ring-amber-500"
                value={newComplaint.staffInvolved}
                onChange={e => setNewComplaint({...newComplaint, staffInvolved: e.target.value})}
              >
                <option value="">Pilih Staff...</option>
                {staffList.map(s => <option key={s.id} value={s.name}>{s.name} ({s.role})</option>)}
              </select>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Kronologi</label>
              <textarea 
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm text-white outline-none focus:ring-2 ring-amber-500 min-h-[120px]"
                placeholder="Apa yang terjadi?"
                value={newComplaint.chronology}
                onChange={e => setNewComplaint({...newComplaint, chronology: e.target.value})}
              />
            </div>
            <div className="space-y-2">
              <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Corrective Action</label>
              <textarea 
                className="w-full bg-slate-950 border border-white/10 rounded-xl p-4 text-sm text-white outline-none focus:ring-2 ring-amber-500 min-h-[120px]"
                placeholder="Tindakan yang diambil?"
                value={newComplaint.correctiveAction}
                onChange={e => setNewComplaint({...newComplaint, correctiveAction: e.target.value})}
              />
            </div>
          </div>

          <div className="flex justify-end">
            <button 
              onClick={handleAdd}
              className="px-10 py-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl font-black uppercase text-xs tracking-widest shadow-xl transition-all active:scale-95"
            >
              Simpan Komplain
