import React, { useState, useEffect, useMemo } from 'react';
import { OvertimeEntry, Staff } from '../types';
import { OT_RATE } from '../constants';

interface Props {
  data: OvertimeEntry[];
  staffList: Staff[];
  onUpdate: (v: OvertimeEntry[]) => void;
}

interface StaffRowProps {
  staff: Staff;
  entry: OvertimeEntry;
  onEntryChange: (staffId: string, field: keyof OvertimeEntry, val: number) => void;
}

const StaffRow: React.FC<StaffRowProps> = ({ staff, entry, onEntryChange }) => {
  const [localHours, setLocalHours] = useState<string>(entry.hours?.toString() || '');
  const [localBreak1, setLocalBreak1] = useState<string>(entry.break1?.toString() || '');

  useEffect(() => {
    setLocalHours(entry.hours?.toString() || '');
    setLocalBreak1(entry.break1?.toString() || '');
  }, [entry.hours, entry.break1]);

  const handleBlur = (field: keyof OvertimeEntry, value: string) => {
    const num = Number(value) || 0;
    onEntryChange(staff.id, field, num);
  };

  const net = Math.max(0, (Number(localHours) || 0) - (Number(localBreak1) || 0));
  const totalCost = net * OT_RATE;

  return (
    <tr className="hover:bg-white/5 transition-colors group">
      <td className="p-4">
        <div className="font-black text-white group-hover:text-blue-400 transition-colors uppercase">{staff.name}</div>
        <div className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">{staff.role}</div>
      </td>
      <td className="p-4">
        <div className="flex items-center gap-2 bg-slate-900/50 rounded-xl px-3 py-2 border border-white/5 focus-within:border-blue-500 transition-all">
          <i className="fas fa-hourglass-start text-xs text-slate-600"></i>
          <input 
            type="number" 
            className="w-full bg-transparent border-none text-center text-sm outline-none font-bold text-white placeholder:text-slate-800"
            value={localHours}
            placeholder="0"
            onChange={(e) => setLocalHours(e.target.value)}
            onBlur={(e) => handleBlur('hours', e.target.value)}
          />
          <span className="text-[10px] text-slate-600 font-bold">Hrs</span>
        </div>
      </td>
