};

const OvertimeModule: React.FC<Props> = ({ dailyOvertime, staffList, filters, onUpdate }) => {
  const [isSaving, setIsSaving] = useState(false);
  const [activeTab, setActiveTab] = useState<'ENTRY' | 'RECAP'>('ENTRY');
  const reportRef = useRef<HTMLDivElement>(null);

  const currentDateEntries = useMemo(() => {
    return dailyOvertime[filters.startDate] || [];
  }, [dailyOvertime, filters.startDate]);

  const handleEntryChange = (staffId: string, field: keyof OvertimeEntry, val: number) => {
    const existingEntries = dailyOvertime[filters.startDate] || [];
    const staffEntry = existingEntries.find(e => e.staffId === staffId);

    let newEntries: OvertimeEntry[];
    if (staffEntry) {
      newEntries = existingEntries.map(e => 
        e.staffId === staffId ? { ...e, [field]: val } : e
      );
    } else {
      newEntries = [...existingEntries, { staffId, hours: 0, break1: 0, [field]: val }];
    }

    onUpdate({
      ...dailyOvertime,
      [filters.startDate]: newEntries
    });
  };

  const calculateTotalOT = (item: OvertimeEntry) => {
    const netHours = Math.max(0, item.hours - item.break1);
    return netHours * OT_RATE;
  };

  const leaders = staffList.filter(s => s.isLeader);
  const crews = staffList.filter(s => !s.isLeader);

  const todayTotalCost = currentDateEntries.reduce((acc, item) => acc + calculateTotalOT(item), 0);
  const todayHoursRaw = currentDateEntries.reduce((acc, item) => acc + (item.hours || 0), 0);
  const todayBreaks = currentDateEntries.reduce((acc, item) => acc + (item.break1 || 0), 0);

  const staffRecap = useMemo(() => {
    const aggregation: Record<string, { gross: number, break: number, net: number, cost: number }> = {};
    Object.values(dailyOvertime).forEach(dayEntries => {
      dayEntries.forEach(entry => {
        if (!aggregation[entry.staffId]) {
          aggregation[entry.staffId] = { gross: 0, break: 0, net: 0, cost: 0 };
        }
        const net = Math.max(0, entry.hours - entry.break1);
        aggregation[entry.staffId].gross += entry.hours;
        aggregation[entry.staffId].break += entry.break1;
        aggregation[entry.staffId].net += net;
        aggregation[entry.staffId].cost += net * OT_RATE;
      });
    });
    return staffList.map(s => {
      const stats = aggregation[s.id] || { gross: 0, break: 0, net: 0, cost: 0 };
      return { ...s, ...stats };
    }).filter(s => s.gross > 0).sort((a, b) => b.cost - a.cost);
  }, [dailyOvertime, staffList]);

  const totalMonthlyCost = staffRecap.reduce((acc, s) => acc + s.cost, 0);

  const handleDownloadPDF = () => {
    if (!reportRef.current) return;
    const element = reportRef.current;
    const filename = `Overtime_Recap_${new Date().toISOString().split('T')[0]}.pdf`;
    const options = {
      margin: 10,
      filename: filename,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    };
    // @ts-ignore
    window.html2pdf().from(element).set(options).save();
  };

  const handleShareRecap = () => {
    handleDownloadPDF();
    let message = `*OVERTIME RECAP (PDF GENERATED) - SH THE BARN*\n`;
    message += `------------------------------------------\n`;
    message += `💰 *TOTAL PAYOUT: Rp ${totalMonthlyCost.toLocaleString()}*\n`;
    message += `📊 *Total Crew:* ${staffRecap.length}\n`;
    message += `_Silakan lampirkan file PDF yang baru saja diunduh._\n`;
    const encoded = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encoded}`, '_blank');
  };

  return (
    <div className="space-y-6 animate-fade-in no-blur pb-10">
      <div className="flex gap-4 mb-4 no-print">
        <button 
          onClick={() => setActiveTab('ENTRY')}
          className={`px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center gap-3 border ${
            activeTab === 'ENTRY' ? 'purple-gradient-bg text-white border-white/10 shadow-xl' : 'bg-slate-800 text-slate-500 border-white/5 hover:bg-slate-700'
          }`}
        >
          <i className="fas fa-edit"></i> Entry Hari Ini
        </button>
        <button 
          onClick={() => setActiveTab('RECAP')}
          className={`px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center gap-3 border ${
            activeTab === 'RECAP' ? 'purple-gradient-bg text-white border-white/10 shadow-xl' : 'bg-slate-800 text-slate-500 border-white/5 hover:bg-slate-700'
          }`}
        >
          <i className="fas fa-list-check"></i> Rekapan Per Crew
        </button>
      </div>

      {activeTab === 'ENTRY' ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 glass-card p-6 border-l-4 border-blue-500 shadow-xl overflow-hidden relative">
            <div className="absolute top-0 right-0 p-8 opacity-5">
