                Rp 15.000 / Jam
              </div>
            </div>

            <div className="overflow-x-auto rounded-2xl border border-white/10 bg-slate-950/30">
              <table className="w-full text-left border-collapse">
                <thead className="bg-slate-800/80 text-slate-500 text-[10px] uppercase font-black tracking-widest">
                  <tr>
                    <th className="p-4">Staff Details</th>
                    <th className="p-4 text-center">OT (Hrs)</th>
                    <th className="p-4 text-center">Break</th>
                    <th className="p-4 text-center">Net</th>
                    <th className="p-4 text-right">Amount</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  <tr className="bg-blue-500/5">
                    <td colSpan={5} className="p-2 px-4 text-[9px] font-black text-blue-400 uppercase tracking-tighter">Leader Section</td>
                  </tr>
                  {leaders.map(staff => (
                    <StaffRow 
                      key={staff.id} 
                      staff={staff} 
                      entry={currentDateEntries.find(d => d.staffId === staff.id) || { staffId: staff.id, hours: 0, break1: 0 }} 
                      onEntryChange={handleEntryChange}
                    />
                  ))}
                  <tr className="bg-purple-500/5">
                    <td colSpan={5} className="p-2 px-4 text-[9px] font-black text-purple-400 uppercase tracking-tighter">Crew Section</td>
                  </tr>
                  {crews.map(staff => (
                    <StaffRow 
                      key={staff.id} 
                      staff={staff} 
                      entry={currentDateEntries.find(d => d.staffId === staff.id) || { staffId: staff.id, hours: 0, break1: 0 }} 
                      onEntryChange={handleEntryChange}
                    />
                  ))}
                </tbody>
              </table>
            </div>

            <div className="mt-6">
              <button 
                onClick={() => { setIsSaving(true); setTimeout(()=>setIsSaving(false), 800); }}
                className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-95 border border-white/10 ${
                  isSaving ? 'bg-slate-800 text-slate-600 cursor-wait' : 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-500/20'
                }`}
              >
                {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-save"></i>}
                {isSaving ? 'Saving...' : 'Sync Data Harian'}
              </button>
            </div>
          </div>

          <div className="space-y-6">
             <div className="glass-card p-6 bg-gradient-to-br from-blue-600 to-indigo-800 text-white shadow-2xl border-none">
                <div className="text-[10px] font-black uppercase opacity-60 mb-1 tracking-widest">OT Cost ({filters.startDate})</div>
                <div className="text-4xl font-black mb-4">Rp {todayTotalCost.toLocaleString()}</div>
                <div className="space-y-2 border-t border-white/10 pt-4">
                   <div className="flex justify-between items-center text-xs">
                      <span className="opacity-70 uppercase font-bold text-[9px]">Gross</span>
