                    className="bg-slate-700 hover:bg-slate-600 text-white px-6 py-4 rounded-xl shadow-2xl transition-all active:scale-90 font-black text-[10px] uppercase tracking-widest flex items-center gap-3 border border-white/10"
                  >
                    <i className="fas fa-file-pdf"></i> PDF
                  </button>
                  <button 
                    onClick={shareToWhatsApp}
                    className="bg-emerald-600 hover:bg-emerald-500 text-white px-6 py-4 rounded-xl shadow-2xl transition-all active:scale-90 font-black text-[10px] uppercase tracking-widest flex items-center gap-3 border border-white/10"
                  >
                    <i className="fab fa-whatsapp"></i> WhatsApp
                  </button>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

