import React, { useRef, useState } from 'react';
import { GSIRow } from '../types';

interface Props {
  data: GSIRow[];
  filters: { month: string };
  onUpdate: (v: GSIRow[]) => void;
}

const GSIModule: React.FC<Props> = ({ data, filters, onUpdate }) => {
  const reportRef = useRef<HTMLDivElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const months = ["Jan", "Feb", "Mar", "Apr", "Mei", "Jun", "Jul", "Ags", "Sep", "Okt", "Nov", "Des"];
  const currentYearShort = new Date().getFullYear().toString().slice(-2);
  const currentMonthName = `${months[parseInt(filters.month)]}-${currentYearShort}`;

  const calculateRowStats = (row: GSIRow) => {
    const totalResponses = row.excellent + row.good + row.average + row.poor + row.abstain;
    const totalExceptAbstain = row.excellent + row.good + row.average + row.poor;

    const totalPoints = (row.excellent * 4) + (row.good * 3) + (row.average * 2) + (row.poor * 1);
    const maxPoints = totalExceptAbstain * 4;

    const mtdPct = maxPoints === 0 ? 0 : (totalPoints / maxPoints) * 100;

    return { totalResponses, mtdPct };
  };

  const handleInputChange = (id: string, field: keyof GSIRow, val: string) => {
    const num = parseInt(val) || 0;
    const updated = data.map(row => 
      row.id === id ? { ...row, [field]: num } : row
    );
    onUpdate(updated);
  };

  const totals = data.reduce((acc, row) => {
    const stats = calculateRowStats(row);
    acc.responses += stats.totalResponses;
    acc.sumPct += stats.mtdPct;
    return acc;
  }, { responses: 0, sumPct: 0 });

  const finalGSIScore = totals.sumPct / data.length;

  const handleDownloadPDF = () => {
    if (!reportRef.current) return;
    setIsProcessing(true);
    const element = reportRef.current;
    const options = {
      margin: 10,
      filename: `GSI_Report_${currentMonthName}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'landscape' }
    };
    // @ts-ignore
    window.html2pdf().from(element).set(options).save().then(() => setIsProcessing(false));
  };

  const handleWhatsAppShare = () => {
    handleDownloadPDF();
    const message = `*GUEST SATISFACTION INDEX (GSI) - SH THE BARN*\n` +
      `------------------------------------------\n` +
      `📅 *Periode:* ${currentMonthName}\n` +
      `📊 *Overall GSI Score:* ${finalGSIScore.toFixed(2)}%\n` +
      `🎯 *Target Score:* 85.00%\n\n` +
      `_Laporan detail PDF telah diunduh, silakan lampirkan._\n` +
      `_Generated via SH Performance Suite_`;
    const encoded = encodeURIComponent(message);
    window.open(`https://wa.me/?text=${encoded}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur pb-10">
      <div className="flex flex-col md:flex-row justify-between items-center gap-6 glass-card p-8 border-l-4 border-indigo-500 bg-[#1e293b]/95 shadow-2xl relative overflow-hidden no-print">
         <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none">
            <i className="fas fa-smile-beam text-[180px]"></i>
         </div>
         <div className="relative z-10">
            <h2 className="text-3xl font-black flex items-center gap-4 text-white uppercase tracking-tighter leading-none">
               <i className="fas fa-poll text-indigo-400"></i>
               GSI Performance Index
            </h2>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-2 italic">Monthly Guest Satisfaction Index & Response Rate</p>
         </div>
         <div className="flex gap-3 no-print">
            <button onClick={handleDownloadPDF} disabled={isProcessing} className="px-6 py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all border border-white/5 active:scale-95 flex items-center gap-3">
               <i className="fas fa-file-pdf"></i> Export PDF
            </button>
            <button onClick={handleWhatsAppShare} className="px-6 py-4 bg-emerald-700 hover:bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-2xl active:scale-95 flex items-center gap-3">
               <i className="fab fa-whatsapp"></i> WhatsApp
            </button>
         </div>
      </div>

      <div ref={reportRef} className="glass-card overflow-hidden border border-white/10 shadow-2xl bg-slate-900/40 p-0">
        {/* HEADER GSI */}
        <div className="bg-slate-950/80 p-8 border-b border-white/5">
           <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                 <div className="flex items-center gap-4">
                    <span className="text-[10px] font-black text-slate-500 uppercase w-32">Month</span>
                    <span className="text-sm font-black text-indigo-400 uppercase tracking-widest">{currentMonthName}</span>
                 </div>
                 <div className="flex items-center gap-4">
                    <span className="text-[10px] font-black text-slate-500 uppercase w-32">Outlet</span>
                    <span className="text-sm font-black text-white uppercase tracking-widest">SH THE BARN</span>
                 </div>
                 <div className="flex items-center gap-4">
                    <span className="text-[10px] font-black text-slate-500 uppercase w-32">No. of Responses</span>
                    <span className="text-sm font-black text-white">{totals.responses || '-'}</span>
                 </div>
              </div>
              <div className="flex flex-col justify-center items-end">
                  <div className="text-[10px] font-black text-slate-500 uppercase mb-2">Overall GSI Performance</div>
                  <div className={`text-6xl font-black ${finalGSIScore >= 85 ? 'text-emerald-400' : 'text-red-400'} drop-shadow-[0_0_15px_rgba(0,0,0,0.5)]`}>
                    {finalGSIScore.toFixed(2)}%
                  </div>
              </div>
           </div>
        </div>

        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-800 text-white text-[10px] font-black uppercase tracking-widest">
              <th className="p-4 text-center border border-white/5 w-12" rowSpan={2}>No</th>
              <th className="p-4 border border-white/5 min-w-[200px]" rowSpan={2}>Subject</th>
              <th className="p-4 text-center border border-white/5 bg-emerald-500/20" colSpan={5}>Rating Scale</th>
              <th className="p-4 text-center border border-white/5 bg-indigo-500/20" rowSpan={2}>Total Responses</th>
              <th className="p-4 text-center border border-white/5 bg-purple-500/20" rowSpan={2}>MTD (%)</th>
            </tr>
            <tr className="bg-slate-900 text-slate-500 text-[9px] font-black uppercase tracking-widest">
              <th className="p-2 text-center border border-white/5 text-emerald-400">Excellent (4)</th>
              <th className="p-2 text-center border border-white/5 text-blue-400">Good (3)</th>
              <th className="p-2 text-center border border-white/5 text-yellow-400">Average (2)</th>
              <th className="p-2 text-center border border-white/5 text-orange-400">Poor (1)</th>
              <th className="p-2 text-center border border-white/5 text-slate-400">Abstain (0)</th>
            </tr>
          </thead>
          <tbody className="divide-y divide-white/5">
            {data.map((row, idx) => {
              const { totalResponses, mtdPct } = calculateRowStats(row);
              return (
                <tr key={row.id} className="hover:bg-white/5 transition-colors group">
                  <td className="p-4 text-center text-slate-500 font-black border border-white/5">{idx + 1}</td>
                  <td className="p-4 font-bold text-white border border-white/5 uppercase text-xs">{row.subject}</td>

                  {/* Rating Inputs */}
                  {['excellent', 'good', 'average', 'poor', 'abstain'].map((field) => (
                    <td key={field} className="p-2 border border-white/5">
                       <input 
                        type="number"
                        className="w-full bg-slate-950/50 border border-white/10 rounded-lg p-2 text-center text-xs font-black text-white focus:ring-1 ring-indigo-500 outline-none placeholder:text-slate-800 no-print"
                        placeholder="0"
                        value={(row as any)[field] || ''}
                        onChange={(e) => handleInputChange(row.id, field as any, e.target.value)}
                       />
                       <div className="hidden print:block text-center text-xs font-black text-white">{(row as any)[field] || '-'}</div>
                    </td>
                  ))}

                  <td className="p-4 text-center text-indigo-300 font-black bg-indigo-500/5 border border-white/5">{totalResponses || '-'}</td>
                  <td className={`p-4 text-center font-black bg-purple-500/5 border border-white/5 ${mtdPct >= 85 ? 'text-emerald-400' : (mtdPct === 0 ? 'text-slate-700' : 'text-red-400')}`}>
                    {mtdPct === 0 ? '#DIV/0!' : `${mtdPct.toFixed(2)}%`}
