              );
            })}
          </tbody>
          <tfoot className="bg-slate-950">
             <tr>
               <td colSpan={7} className="p-6 font-black text-slate-500 uppercase tracking-[0.2em] text-[10px]">
                 Min. GSI Score Target: <span className="text-white">85.00%</span>
               </td>
               <td className="p-6 text-center font-black text-white uppercase text-[10px] bg-slate-900 border-x border-white/5">
