import React, { useState, useMemo, useEffect } from 'react';
import { AppState, Staff, GSIRow } from '../types';
import { INITIAL_GSI_STRUCTURE } from '../constants';

interface Props {
  data: AppState;
  onUpdate: (path: keyof AppState, newValue: any) => void;
  filters: { month: string; startDate: string; endDate: string };
}

const AdminModule: React.FC<Props> = ({ data, onUpdate, filters }) => {
  const [activeTab, setActiveTab] = useState<'MASTER' | 'DATABASE' | 'CONFIG' | 'GSI'>('CONFIG');
  const [isSaving, setIsSaving] = useState(false);
  const [gsiDate, setGsiDate] = useState(filters.startDate);
  const [localGSI, setLocalGSI] = useState<GSIRow[]>(INITIAL_GSI_STRUCTURE);

  const [newStaffName, setNewStaffName] = useState('');
  const [newStaffRole, setNewStaffRole] = useState('SERVICE');
  const [newStaffIsLeader, setNewStaffIsLeader] = useState(false);

  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentYear = new Date().getFullYear();
  const selectedMonthIdx = parseInt(filters.month);

  const daysInMonth = useMemo(() => new Date(currentYear, selectedMonthIdx + 1, 0).getDate(), [selectedMonthIdx, currentYear]);

  // Load GSI data when date changes
  useEffect(() => {
    const existing = data.dailyGSI?.[gsiDate];
    if (existing && existing.length > 0) {
      setLocalGSI(existing);
    } else {
      setLocalGSI(INITIAL_GSI_STRUCTURE);
    }
  }, [gsiDate, data.dailyGSI]);

  const handleGSIInputChange = (id: string, field: keyof GSIRow, val: string) => {
    const num = parseInt(val) || 0;
    setLocalGSI(prev => prev.map(row => row.id === id ? { ...row, [field]: num } : row));
  };

  const handleSaveGSI = () => {
    setIsSaving(true);
    setTimeout(() => {
      onUpdate('dailyGSI', { ...data.dailyGSI, [gsiDate]: localGSI });
      setIsSaving(false);
      alert(`Data GSI tanggal ${gsiDate} berhasil disimpan.`);
    }, 600);
  };

  const handleUpdateBudget = (val: number) => onUpdate('sales', { ...data.sales, budgetRevenue: val });

  const handleUpdateDailyTarget = (day: number, val: number) => {
    const monthStr = (selectedMonthIdx + 1).toString().padStart(2, '0');
    const dayStr = day.toString().padStart(2, '0');
    const dateKey = `${currentYear}-${monthStr}-${dayStr}`;
    onUpdate('dailyTargets', { ...data.dailyTargets, [dateKey]: val });
  };

  const toggleHoliday = (day: number) => {
    const monthStr = (selectedMonthIdx + 1).toString().padStart(2, '0');
    const dayStr = day.toString().padStart(2, '0');
    const dateKey = `${currentYear}-${monthStr}-${dayStr}`;
    const currentHolidays = data.holidays || [];
    if (currentHolidays.includes(dateKey)) {
      onUpdate('holidays', currentHolidays.filter(h => h !== dateKey));
    } else {
      onUpdate('holidays', [...currentHolidays, dateKey]);
    }
  };

  const handleAddStaff = () => {
    if (!newStaffName.trim()) return alert("Nama Staff tidak boleh kosong");
    const newStaff: Staff = { id: Date.now().toString(), name: newStaffName.toUpperCase(), role: newStaffRole, isLeader: newStaffIsLeader };
    onUpdate('staffList', [...data.staffList, newStaff]);
    setNewStaffName('');
  };

  const renderGSITab = () => (
    <div className="space-y-8 animate-fade-in relative z-10">
       <div className="glass-card p-8 border-l-4 border-indigo-500 bg-slate-900/60 shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><i className="fas fa-poll text-[180px]"></i></div>
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 relative z-10">
             <div>
                <h3 className="text-xl font-black text-white uppercase tracking-tighter">Input Guest Comment (GSI)</h3>
                <p className="text-slate-500 text-[10px] font-black uppercase mt-1 tracking-widest italic">Input data respon harian untuk Guest Satisfaction Index</p>
             </div>
             <div className="flex items-center gap-4">
                <label className="text-[10px] font-black text-slate-500 uppercase tracking-widest">Pilih Tanggal:</label>
                <input 
                  type="date" 
                  className="bg-slate-950 border border-white/10 rounded-xl p-3 text-sm font-bold text-white focus:ring-2 ring-indigo-500 outline-none"
                  value={gsiDate}
                  onChange={(e) => setGsiDate(e.target.value)}
                />
             </div>
          </div>
       </div>

       <div className="glass-card overflow-hidden border border-white/10 shadow-2xl bg-slate-950/40">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-950 text-slate-500 text-[9px] font-black uppercase tracking-widest border-b border-white/5">
                <th className="p-6">Performance Subject</th>
                <th className="p-6 text-center text-emerald-400">Excellent (4)</th>
                <th className="p-6 text-center text-blue-400">Good (3)</th>
                <th className="p-6 text-center text-yellow-400">Average (2)</th>
                <th className="p-6 text-center text-orange-400">Poor (1)</th>
                <th className="p-6 text-center text-slate-400">Abstain (0)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
               {localGSI.map(row => (
                 <tr key={row.id} className="hover:bg-white/5 transition-colors">
                    <td className="p-6 font-black text-white text-xs uppercase tracking-tight">{row.subject}</td>
                    {['excellent', 'good', 'average', 'poor', 'abstain'].map(field => (
                      <td key={field} className="p-4 text-center">
                        <input 
                          type="number" 
                          className="w-20 bg-slate-900 border border-white/5 rounded-xl p-3 text-center font-black text-white text-sm focus:ring-1 ring-indigo-500 outline-none"
                          placeholder="0"
                          value={(row as any)[field] || ''}
                          onChange={(e) => handleGSIInputChange(row.id, field as any, e.target.value)}
                        />
                      </td>
                    ))}
                 </tr>
               ))}
            </tbody>
          </table>
       </div>

       <button 
        onClick={handleSaveGSI}
        disabled={isSaving}
        className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-95 border border-white/10 ${
          isSaving ? 'bg-slate-800 text-slate-600 cursor-wait' : 'bg-indigo-600 hover:bg-indigo-500 text-white shadow-xl'
        }`}
       >
         {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-save"></i>}
         {isSaving ? 'MEMPROSES DATA...' : `SIMPAN GSI UNTUK TANGGAL ${gsiDate}`}
       </button>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="glass-card p-8 border-l-4 border-slate-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><i className="fas fa-user-shield text-[220px]"></i></div>
        <div className="relative z-10 mb-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
              <i className="fas fa-shield-alt text-slate-400"></i> Admin Control Center
            </h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em]">Pusat Konfigurasi Target & Input Guest Comments</p>
          </div>
        </div>

        <div className="flex gap-4 mb-10 relative z-10 overflow-x-auto no-scrollbar pb-2">
           {[
             { id: 'CONFIG', label: 'Revenue & Targets', icon: 'fa-sliders-h' },
             { id: 'GSI', label: 'GSI Daily Entry', icon: 'fa-poll' },
             { id: 'MASTER', label: 'Master Staff', icon: 'fa-users-cog' },
             { id: 'DATABASE', label: 'Security & Backup', icon: 'fa-history' }
           ].map(tab => (
             <button key={tab.id} onClick={() => setActiveTab(tab.id as any)}
               className={`px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest whitespace-nowrap transition-all flex items-center gap-3 border active:scale-95 ${
                 activeTab === tab.id ? 'bg-slate-700 text-white shadow-xl border-white/10' : 'bg-slate-900/40 text-slate-500 border-white/5 hover:bg-slate-800'
               }`}>
               <i className={`fas ${tab.icon}`}></i> {tab.label}
             </button>
           ))}
        </div>

