const App: React.FC = () => {
  // State User & Sync
  const [user, setUser] = useState<User>({ email: '', isLoggedIn: false });
  const [syncStatus, setSyncStatus] = useState<SyncStatus>('offline');
  const lastSyncHash = useRef<string>('');
  const syncTimeout = useRef<any>(null);

  const [activeModule, setActiveModule] = useState<ModuleType>(ModuleType.DASHBOARD);
  const [isAdmin, setIsAdmin] = useState(false);
  const [monthlyData, setMonthlyData] = useState<Record<string, AppState>>({
    [new Date().getMonth().toString()]: INITIAL_STATE
  });

  const [isFullScreen, setIsFullScreen] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [filters, setFilters] = useState({
    month: new Date().getMonth().toString(),
    startDate: new Date().toISOString().split('T')[0],
    endDate: new Date().toISOString().split('T')[0]
  });

  const currentData = useMemo(() => {
    return monthlyData[filters.month] || INITIAL_STATE;
  }, [monthlyData, filters.month]);

  // Handle Login & Data Fetching
  const handleLogin = async (email: string) => {
    setIsRefreshing(true);
    const cloudData = await fetchUserData(email);

    if (cloudData) {
      setMonthlyData(cloudData);
      lastSyncHash.current = JSON.stringify(cloudData);
    }

    setUser({ email, isLoggedIn: true });
    setSyncStatus('online');
    setIsRefreshing(false);
  };

  // Logika Auto-Save (Sync ke Cloud)
  useEffect(() => {
    if (!user.isLoggedIn) return;

    const currentHash = JSON.stringify(monthlyData);
    if (currentHash === lastSyncHash.current) return;

    setSyncStatus('syncing');

    // Debounce save 2 detik
    if (syncTimeout.current) clearTimeout(syncTimeout.current);
    syncTimeout.current = setTimeout(async () => {
      const success = await saveUserData(user.email, monthlyData);
      if (success) {
        lastSyncHash.current = currentHash;
        setSyncStatus('online');
      } else {
        setSyncStatus('error');
      }
    }, 2000);

    return () => clearTimeout(syncTimeout.current);
  }, [monthlyData, user.email, user.isLoggedIn]);

  // Real-time Listener untuk Update dari Perangkat Lain
  useEffect(() => {
    if (!user.isLoggedIn) return;

    const unsubscribe = startRealtimeListener(user.email, (newData) => {
      const newHash = JSON.stringify(newData);
      if (newHash !== JSON.stringify(monthlyData)) {
        setMonthlyData(newData);
        lastSyncHash.current = newHash;
      }
    });

    return unsubscribe;
  }, [user.isLoggedIn, user.email, monthlyData]);

  useEffect(() => {
    setIsRefreshing(true);
    const timer = setTimeout(() => {
      setIsRefreshing(false);
    }, 400);
    return () => clearTimeout(timer);
  }, [filters.month, filters.startDate, filters.endDate]);

  const toggleFullScreen = () => {
    if (!document.fullscreenElement) {
      document.documentElement.requestFullscreen().then(() => setIsFullScreen(true)).catch(e => console.error(e));
    } else {
      if (document.exitFullscreen) {
        document.exitFullscreen().then(() => setIsFullScreen(false));
      }
    }
  };

  const updateCurrentData = useCallback((path: keyof AppState, newValue: any) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: {
          ...currentMonthBase,
          [path]: newValue
        }
      };
    });
  }, [filters.month]);

  const updateFullState = useCallback((updater: (prev: AppState) => AppState) => {
    setMonthlyData(prev => {
      const monthKey = filters.month;
      const currentMonthBase = prev[monthKey] || INITIAL_STATE;
      return {
        ...prev,
        [monthKey]: updater(currentMonthBase)
      };
    });
  }, [filters.month]);

  const toggleAdminMode = () => {
    setIsAdmin(!isAdmin);
    if (!isAdmin) {
       setActiveModule(ModuleType.ADMIN);
    } else {
       setActiveModule(ModuleType.DASHBOARD);
    }
  };

  if (!user.isLoggedIn) {
    return <LoginModule onLogin={handleLogin} />;
  }

  const renderModule = () => {
    if (isRefreshing) {
      return (
        <div className="h-[60vh] flex flex-col items-center justify-center space-y-4 animate-pulse">
           <div className="w-16 h-16 border-4 border-purple-500/20 border-t-purple-500 rounded-full animate-spin"></div>
           <p className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Syncing Cloud Data...</p>
        </div>
      );
    }

    switch (activeModule) {
      case ModuleType.DASHBOARD:
        return <Dashboard onSelect={setActiveModule} isAdmin={isAdmin} />;
      case ModuleType.SALES:
        return <SalesModule 
          data={currentData.sales} 
          dailyTargets={currentData.dailyTargets} 
          filters={filters}
          onUpdate={(v) => updateCurrentData('sales', v)} 
        />;
      case ModuleType.GOOGLE_REVIEW:
        return <GoogleReviewModule data={currentData.googleReview} onUpdate={(v) => updateCurrentData('googleReview', v)} />;
      case ModuleType.GUEST_COMMENT:
        return <GuestCommentModule 
          data={currentData.guestComments} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('guestComments', v)} 
        />;
      case ModuleType.GUEST_COMPLAINT:
        return <GuestComplaintModule 
          data={currentData.complaints} 
          staffList={currentData.staffList}
          onUpdate={(v) => updateCurrentData('complaints', v)} 
        />;
      case ModuleType.GSI:
        return <GSIModule 
          dailyGSI={currentData.dailyGSI || {}} 
          filters={filters}
        />;
      case ModuleType.OVERTIME:
        return <OvertimeModule 
          dailyOvertime={currentData.dailyOvertime || {}} 
          staffList={currentData.staffList}
          filters={filters}
          onUpdate={(v) => updateCurrentData('dailyOvertime', v)} 
        />;
      case ModuleType.QUALITY_ASSURANCE:
        return <QAModule data={currentData.qa} onUpdate={(v) => updateCurrentData('qa', v)} />;
      case ModuleType.EXPENSES:
        return <ExpensesModule data={currentData} onUpdate={updateFullState} />;
      case ModuleType.YTD_REPORT:
        return <YTDModule allMonthlyData={monthlyData} />;
      case ModuleType.REKAPAN:
        return <ReportingModule data={currentData} filters={filters} />;
      case ModuleType.REKAPAN_BULANAN:
        return <MonthlyReportingModule data={currentData} filters={filters} />;
      case ModuleType.WEEKLY_REPORT:
        return <WeeklyPerformanceModule data={currentData} filters={filters} />;
      case ModuleType.ADMIN:
        return <AdminModule data={currentData} onUpdate={updateCurrentData} filters={filters} />;
      default:
        return <Dashboard onSelect={setActiveModule} isAdmin={isAdmin} />;
    }
  };

  return (
    <div className="min-h-screen bg-[#0f172a] flex flex-col">
      <Header 
        isFullScreen={isFullScreen} 
        onToggleFS={toggleFullScreen} 
        filters={filters}
        onFilterChange={setFilters}
        onHome={() => setActiveModule(ModuleType.DASHBOARD)}
        // Fixed: toggleAdminToggle was a typo for toggleAdminMode
        onAdminToggle={toggleAdminMode}
        isAdmin={isAdmin}
        user={user}
        syncStatus={syncStatus}
      />

      <main className="flex-1 overflow-y-auto p-4 md:p-8 custom-scrollbar">
        <div className="max-w-7xl mx-auto">
          <div className="animate-fade-in">
            {renderModule()}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo, useEffect } from 'react';
import { AppState, Staff, GSIRow } from '../types';
import { INITIAL_GSI_STRUCTURE } from '../constants';

interface Props {
  data: AppState;
  onUpdate: (path: keyof AppState, newValue: any) => void;
  filters: { month: string; startDate: string; endDate: string };
}

const AdminModule: React.FC<Props> = ({ data, onUpdate, filters }) => {
  const [activeTab, setActiveTab] = useState<'MASTER' | 'DATABASE' | 'CONFIG' | 'GSI'>('GSI');
  const [isSaving, setIsSaving] = useState(false);
  const [gsiDate, setGsiDate] = useState(filters.startDate);
  const [localGSI, setLocalGSI] = useState<GSIRow[]>(INITIAL_GSI_STRUCTURE);

  const [newStaffName, setNewStaffName] = useState('');
  const [newStaffRole, setNewStaffRole] = useState('SERVICE');
  const [newStaffIsLeader, setNewStaffIsLeader] = useState(false);

  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentYear = new Date().getFullYear();
  const selectedMonthIdx = parseInt(filters.month);

  const daysInMonth = useMemo(() => new Date(currentYear, selectedMonthIdx + 1, 0).getDate(), [selectedMonthIdx, currentYear]);

  // Load GSI data when date changes
  useEffect(() => {
    const existing = data.dailyGSI?.[gsiDate];
    if (existing && existing.length > 0) {
      setLocalGSI(existing);
    } else {
      setLocalGSI(INITIAL_GSI_STRUCTURE.map(item => ({...item, excellent: 0, good: 0, average: 0, poor: 0, abstain: 0})));
    }
  }, [gsiDate, data.dailyGSI]);

  const handleGSIInputChange = (id: string, field: keyof GSIRow, val: string) => {
    const num = parseInt(val) || 0;
    setLocalGSI(prev => prev.map(row => row.id === id ? { ...row, [field]: num } : row));
  };

  const handleSaveGSI = () => {
    if (isSaving) return;
    setIsSaving(true);

    // Sinkronisasi ke state utama (ini akan mentrigger auto-save ke cloud jika online)
    onUpdate('dailyGSI', { 
      ...data.dailyGSI, 
      [gsiDate]: localGSI 
    });

    setTimeout(() => {
      setIsSaving(false);
      // Feedback visual sederhana tanpa blocking alert yang mengganggu alur kerja cepat
    }, 400);
  };

  // Support untuk menekan tombol Enter pada keyboard
  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSaveGSI();
    }
  };

  const handleUpdateBudget = (val: number) => onUpdate('sales', { ...data.sales, budgetRevenue: val });

  const handleUpdateDailyTarget = (day: number, val: number) => {
    const monthStr = (selectedMonthIdx + 1).toString().padStart(2, '0');
    const dayStr = day.toString().padStart(2, '0');
    const dateKey = `${currentYear}-${monthStr}-${dayStr}`;
    onUpdate('dailyTargets', { ...data.dailyTargets, [dateKey]: val });
  };

  const handleAddStaff = () => {
    if (!newStaffName.trim()) return alert("Nama Staff tidak boleh kosong");
    const newStaff: Staff = { id: Date.now().toString(), name: newStaffName.toUpperCase(), role: newStaffRole, isLeader: newStaffIsLeader };
    onUpdate('staffList', [...data.staffList, newStaff]);
    setNewStaffName('');
  };

  const renderGSITab = () => (
    <div className="space-y-8 animate-fade-in relative z-10">
       <div className="glass-card p-8 border-l-4 border-indigo-500 bg-slate-900/60 shadow-2xl relative overflow-hidden">
          <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><i className="fas fa-poll text-[180px]"></i></div>
          <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-6 relative z-10">
             <div>
                <h3 className="text-xl font-black text-white uppercase tracking-tighter flex items-center gap-3">
                  <i className="fas fa-keyboard text-indigo-400"></i>
                  Quick GSI Input Panel
                </h3>
                <p className="text-slate-500 text-[10px] font-black uppercase mt-1 tracking-widest italic">Input angka lalu tekan tombol ENTER di bawah atau di keyboard</p>
             </div>
             <div className="flex items-center gap-4 bg-slate-950/50 p-2 rounded-2xl border border-white/5">
                <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest ml-2">Tanggal Entry:</label>
                <input 
                  type="date" 
                  className="bg-slate-900 border border-white/10 rounded-xl p-3 text-sm font-black text-white focus:ring-2 ring-indigo-500 outline-none"
                  value={gsiDate}
                  onChange={(e) => setGsiDate(e.target.value)}
                />
             </div>
          </div>
       </div>

       <div className="glass-card overflow-hidden border border-white/10 shadow-2xl bg-slate-950/40">
          <table className="w-full text-left">
            <thead>
              <tr className="bg-slate-950 text-slate-500 text-[9px] font-black uppercase tracking-widest border-b border-white/5">
                <th className="p-6">Performance Subject</th>
                <th className="p-6 text-center text-emerald-400">Excellent (4)</th>
                <th className="p-6 text-center text-blue-400">Good (3)</th>
                <th className="p-6 text-center text-yellow-400">Average (2)</th>
                <th className="p-6 text-center text-orange-400">Poor (1)</th>
                <th className="p-6 text-center text-slate-400">Abstain (0)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-white/5">
               {localGSI.map(row => (
                 <tr key={row.id} className="hover:bg-white/5 transition-colors group">
                    <td className="p-6 font-black text-white text-xs uppercase tracking-tight group-hover:text-indigo-400 transition-colors">{row.subject}</td>
                    {['excellent', 'good', 'average', 'poor', 'abstain'].map(field => (
                      <td key={field} className="p-4 text-center">
                        <input 
                          type="number" 
                          onKeyDown={handleKeyDown}
                          className="w-20 bg-slate-900 border border-white/5 rounded-xl p-3 text-center font-black text-white text-sm focus:ring-2 ring-indigo-500/50 outline-none transition-all placeholder:text-slate-800"
                          placeholder="0"
                          value={(row as any)[field] || ''}
                          onChange={(e) => handleGSIInputChange(row.id, field as any, e.target.value)}
                        />
                      </td>
                    ))}
                 </tr>
               ))}
            </tbody>
          </table>
       </div>

       <div className="flex gap-4">
         <button 
          onClick={handleSaveGSI}
          disabled={isSaving}
          className={`flex-1 py-6 rounded-3xl font-black text-sm uppercase tracking-[0.4em] shadow-2xl transition-all flex items-center justify-center gap-4 active:scale-95 border border-white/10 ${
            isSaving ? 'bg-slate-800 text-slate-600 cursor-wait' : 'bg-gradient-to-r from-indigo-600 to-blue-600 hover:from-indigo-500 hover:to-blue-500 text-white shadow-indigo-500/20'
          }`}
         >
           {isSaving ? (
             <i className="fas fa-circle-notch fa-spin"></i>
           ) : (
             <i className="fas fa-paper-plane"></i>
           )}
           {isSaving ? 'SYNCING DATA...' : 'ENTER & SAVE TO GSI INDEX'}
         </button>
       </div>

       <div className="flex justify-center">
          <div className="px-6 py-3 rounded-full bg-slate-900/80 border border-white/5 flex items-center gap-3">
             <div className={`w-2 h-2 rounded-full animate-pulse ${isSaving ? 'bg-amber-500' : 'bg-emerald-500'}`}></div>
             <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">
               {isSaving ? 'Sedang memproses data harian...' : 'Sistem siap menerima input harian'}
             </span>
          </div>
       </div>
    </div>
  );

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="glass-card p-8 border-l-4 border-slate-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><i className="fas fa-user-shield text-[220px]"></i></div>
        <div className="relative z-10 mb-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
              <i className="fas fa-shield-alt text-slate-400"></i> Admin Control Center
            </h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em]">Master Configuration & Data Entry Suite</p>
          </div>
        </div>

        <div className="flex gap-4 mb-10 relative z-10 overflow-x-auto no-scrollbar pb-2">
           {[
             { id: 'GSI', label: 'GSI Entry (New)', icon: 'fa-poll' },
             { id: 'CONFIG', label: 'Revenue & Targets', icon: 'fa-sliders-h' },
             { id: 'MASTER', label: 'Staff Database', icon: 'fa-users-cog' },
             { id: 'DATABASE', label: 'Security', icon: 'fa-history' }
           ].map(tab => (
             <button key={tab.id} onClick={() => setActiveTab(tab.id as any)}
               className={`px-8 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest whitespace-nowrap transition-all flex items-center gap-3 border active:scale-95 ${
                 activeTab === tab.id ? 'bg-indigo-600 text-white shadow-xl border-white/10' : 'bg-slate-900/40 text-slate-500 border-white/5 hover:bg-slate-800'
               }`}>
               <i className={`fas ${tab.icon}`}></i> {tab.label}
             </button>
           ))}
        </div>

        {activeTab === 'GSI' && renderGSITab()}
        {activeTab === 'CONFIG' && (
           <div className="space-y-10 animate-fade-in relative z-10">
           <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
             <div className="lg:col-span-1 space-y-6">
               <h3 className="text-xs font-black text-indigo-400 uppercase tracking-[0.2em] flex items-center gap-3 border-b border-indigo-500/20 pb-2"><i className="fas fa-money-bill-wave"></i> BUDGET BULANAN</h3>
               <div className="glass-card bg-slate-900/60 p-8 border-white/5 space-y-6">
                 <div className="space-y-4">
                   <div className="space-y-2">
                     <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">SET REVENUE BUDGET (MTD)</label>
                     <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5 focus-within:ring-2 ring-indigo-500 transition-all shadow-inner">
                       <span className="text-slate-700 text-xs font-black">RP.</span>
                       <input type="number" className="flex-1 bg-transparent text-white font-black outline-none text-xl" placeholder="0" value={data.sales.budgetRevenue || ''} onChange={(e) => handleUpdateBudget(Number(e.target.value))}/>
                     </div>
                   </div>
                 </div>
               </div>
             </div>
             <div className="lg:col-span-2 space-y-6">
               <h3 className="text-xs font-black text-emerald-400 uppercase tracking-[0.2em] flex items-center gap-3 border-b border-emerald-500/20 pb-2"><i className="fas fa-calendar-alt"></i> TARGET HARI: {months[selectedMonthIdx].toUpperCase()}</h3>
               <div className="glass-card bg-slate-900/60 p-8 border-white/5">
                 <div className="grid grid-cols-2 sm:grid-cols-4 md:grid-cols-5 xl:grid-cols-7 gap-3">
                    {Array.from({ length: daysInMonth }, (_, i) => i + 1).map(day => {
                      const monthStr = (selectedMonthIdx + 1).toString().padStart(2, '0');
                      const dateKey = `${currentYear}-${monthStr}-${day.toString().padStart(2, '0')}`;
                      const val = data.dailyTargets[dateKey] || 0;
                      return (
                        <div key={day} className="space-y-1 group">
                           <div className="flex justify-between items-center px-1"><span className="text-[8px] font-black text-slate-500">{day}</span></div>
                           <input type="number" className="w-full bg-slate-950 border border-white/5 rounded-lg p-2 text-[10px] font-black text-center text-white focus:ring-1 ring-emerald-500 outline-none" value={val || ''} onChange={(e) => handleUpdateDailyTarget(day, Number(e.target.value))}/>
                        </div>
                      );
                    })}
                 </div>
               </div>
             </div>
           </div>
         </div>
        )}
        {activeTab === 'MASTER' && (
           <div className="space-y-8 animate-fade-in relative z-10">
           <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
             <div className="lg:col-span-1 space-y-6">
                <h3 className="text-xs font-black text-emerald-400 uppercase tracking-[0.2em] flex items-center gap-3 border-b border-emerald-500/20 pb-2"><i className="fas fa-user-plus"></i> Tambah Staff</h3>
                <div className="glass-card bg-slate-900/60 p-8 border-white/5 space-y-5">
                   <input type="text" className="w-full bg-slate-950 border border-white/10 rounded-xl p-3 text-sm font-bold text-white outline-none" placeholder="Nama..." value={newStaffName} onChange={(e) => setNewStaffName(e.target.value)}/>
                   <button onClick={handleAddStaff} className="w-full py-4 bg-emerald-600 text-white rounded-xl font-black uppercase text-xs">Tambah Staff</button>
                </div>
             </div>
             <div className="lg:col-span-2 space-y-6">
                <h3 className="text-xs font-black text-indigo-400 uppercase tracking-[0.2em] flex items-center gap-3 border-b border-indigo-500/20 pb-2"><i className="fas fa-users"></i> Daftar Staff</h3>
                <div className="glass-card bg-slate-900/60 p-0 border-white/5 overflow-hidden">
                   <div className="max-h-[500px] overflow-y-auto">
                      <table className="w-full text-left">
                         <tbody className="divide-y divide-white/5">
                            {data.staffList.map((staff) => (
                               <tr key={staff.id} className="hover:bg-white/5"><td className="p-4 font-black text-white">{staff.name}</td><td className="p-4 text-xs font-bold text-slate-400">{staff.role}</td></tr>
                            ))}
                         </tbody>
                      </table>
                   </div>
                </div>
             </div>
           </div>
         </div>
        )}
      </div>
    </div>
  );
};

export default AdminModule;

import React, { useState, useMemo, useEffect } from 'react';
import { AppState, Staff, GSIRow } from '../types';
import { INITIAL_GSI_STRUCTURE } from '../constants';

interface Props {
  data: AppState;
  onUpdate: (path: keyof AppState, newValue: any) => void;
  filters: { month: string; startDate: string; endDate: string };
}

const AdminModule: React.FC<Props> = ({ data, onUpdate, filters }) => {
  const [activeTab, setActiveTab] = useState<'MASTER' | 'DATABASE' | 'CONFIG' | 'GSI'>('GSI');
  const [isSaving, setIsSaving] = useState(false);
  const [gsiDate, setGsiDate] = useState(filters.startDate);

  // localInput digunakan untuk menampung angka yang sedang diketik user sekarang
  const [localInput, setLocalInput] = useState<GSIRow[]>(
    INITIAL_GSI_STRUCTURE.map(item => ({...item, excellent: 0, good: 0, average: 0, poor: 0, abstain: 0}))
  );

  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentYear = new Date().getFullYear();
  const selectedMonthIdx = parseInt(filters.month);

  const daysInMonth = useMemo(() => new Date(currentYear, selectedMonthIdx + 1, 0).getDate(), [selectedMonthIdx, currentYear]);

  const handleGSIInputChange = (id: string, field: keyof GSIRow, val: string) => {
    const num = parseInt(val) || 0;
    setLocalInput(prev => prev.map(row => row.id === id ? { ...row, [field]: num } : row));
  };

  // Logika kumulatif: Menambahkan input saat ini ke data yang sudah tersimpan di database harian
  const handleSaveGSI = () => {
    if (isSaving) return;

    // Cek apakah ada data yang diinput (agar tidak simpan kosong)
    const hasInput = localInput.some(row => 
      row.excellent > 0 || row.good > 0 || row.average > 0 || row.poor > 0 || row.abstain > 0
    );
    if (!hasInput) return;

    setIsSaving(true);

    // Ambil data yang sudah ada di tanggal tersebut (jika ada)
    const existingDailyData = data.dailyGSI?.[gsiDate] || INITIAL_GSI_STRUCTURE.map(item => ({...item, excellent: 0, good: 0, average: 0, poor: 0, abstain: 0}));

    // Gabungkan (Jumlahkan) data lama dengan input baru
    const updatedDailyData = existingDailyData.map(existingRow => {
      const inputRow = localInput.find(r => r.id === existingRow.id);
      if (inputRow) {
        return {
