import React, { useState, useEffect } from 'react';
import { SalesData, DailySalesData } from '../types';

interface Props {
  data: SalesData;
  dailyTargets: Record<string, number>;
  filters: { month: string; startDate: string; endDate: string };
  onUpdate: (v: SalesData) => void;
}

const SalesModule: React.FC<Props> = ({ data, dailyTargets, filters, onUpdate }) => {
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Sync Daily Target
  useEffect(() => {
    const autoTarget = dailyTargets[filters.startDate] || 0;
    if (autoTarget !== data.dailyTarget) {
      onUpdate({ ...data, dailyTarget: autoTarget });
    }
  }, [filters.startDate, dailyTargets, data.dailyTarget, onUpdate]);

  // Load Daily Data when date changes
  useEffect(() => {
    const dailyRecord = data.dailyRecording?.[filters.startDate] || { revenue: 0, covers: 0, lunchRevenue: 0, lunchCovers: 0, dinnerRevenue: 0, dinnerCovers: 0 };

    onUpdate({
      ...data,
      todayRevenue: dailyRecord.revenue,
      todayCovers: dailyRecord.covers,
      todayLunchRevenue: dailyRecord.lunchRevenue || 0,
      todayLunchCovers: dailyRecord.lunchCovers || 0,
      todayDinnerRevenue: dailyRecord.dinnerRevenue || 0,
      todayDinnerCovers: dailyRecord.dinnerCovers || 0
    });
  }, [filters.startDate]);

  const updateSessionData = (session: 'lunch' | 'dinner', field: 'Revenue' | 'Covers', value: number) => {
    const fieldKey = `${session}${field}` as 'lunchRevenue' | 'lunchCovers' | 'dinnerRevenue' | 'dinnerCovers';

    // Ambil data state sekarang (transient)
    const currentLunchRev = session === 'lunch' && field === 'Revenue' ? value : (data.todayLunchRevenue || 0);
    const currentLunchCov = session === 'lunch' && field === 'Covers' ? value : (data.todayLunchCovers || 0);
    const currentDinnerRev = session === 'dinner' && field === 'Revenue' ? value : (data.todayDinnerRevenue || 0);
    const currentDinnerCov = session === 'dinner' && field === 'Covers' ? value : (data.todayDinnerCovers || 0);

    const totalRev = currentLunchRev + currentDinnerRev;
    const totalCov = currentLunchCov + currentDinnerCov;

    // Update state transient sekaligus rekam ke dailyRecording
    const newRecord: DailySalesData = {
      revenue: totalRev,
      covers: totalCov,
      lunchRevenue: currentLunchRev,
      lunchCovers: currentLunchCov,
      dinnerRevenue: currentDinnerRev,
      dinnerCovers: currentDinnerCov
    };

    const newDailyRecording = {
      ...(data.dailyRecording || {}),
      [filters.startDate]: newRecord
    };

    // Kalkulasi MTD
    const newTotalMTDRevenue = Object.values(newDailyRecording).reduce((acc: number, curr: DailySalesData) => acc + (Number(curr.revenue) || 0), 0);
    const newTotalMTDCovers = Object.values(newDailyRecording).reduce((acc: number, curr: DailySalesData) => acc + (Number(curr.covers) || 0), 0);

    onUpdate({
      ...data,
      dailyRecording: newDailyRecording,
      revenue: newTotalMTDRevenue,
      covers: newTotalMTDCovers,
      todayRevenue: totalRev,
      todayCovers: totalCov,
      todayLunchRevenue: currentLunchRev,
      todayLunchCovers: currentLunchCov,
      todayDinnerRevenue: currentDinnerRev,
      todayDinnerCovers: currentDinnerCov
    });
  };

  const todayAvgCheck = data.todayCovers > 0 ? Math.floor(data.todayRevenue / data.todayCovers) : 0;
  const todayLunchAvg = (data.todayLunchCovers || 0) > 0 ? Math.floor((data.todayLunchRevenue || 0) / (data.todayLunchCovers || 1)) : 0;
  const todayDinnerAvg = (data.todayDinnerCovers || 0) > 0 ? Math.floor((data.todayDinnerRevenue || 0) / (data.todayDinnerCovers || 1)) : 0;

  const todayPerformance = data.dailyTarget > 0 ? ((data.todayRevenue / data.dailyTarget) * 100).toFixed(2) : "0.00";
  const mtdBudget = data.budgetRevenue || 0;
  const mtdRevenue = (Object.values(data.dailyRecording || {}) as DailySalesData[]).reduce((acc, curr) => acc + (Number(curr.revenue) || 0), 0);
  const mtdPerformance = mtdBudget > 0 ? ((mtdRevenue / mtdBudget) * 100).toFixed(2) : "0.00";

  const handleSubmitData = () => {
    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      alert(`Data Sales & Session ${filters.startDate} berhasil disinkronkan.`);
    }, 600);
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4 no-print">
        <div className="glass-card p-6 border-l-4 border-emerald-500 bg-slate-900/40">
           <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Total Sales (Today)</div>
           <div className="text-2xl font-black text-white">Rp {data.todayRevenue.toLocaleString()}</div>
        </div>
        <div className="glass-card p-6 border-l-4 border-indigo-500 bg-slate-900/40">
           <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Total Covers</div>
           <div className="text-2xl font-black text-slate-300">{data.todayCovers} Pax</div>
        </div>
        <div className="glass-card p-6 border-l-4 border-amber-500 bg-slate-900/40">
           <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Average Check</div>
           <div className="text-2xl font-black text-amber-400">Rp {todayAvgCheck.toLocaleString()}</div>
        </div>
        <div className="glass-card p-6 border-l-4 border-pink-500 bg-slate-900/40">
           <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Daily Perf %</div>
           <div className="text-2xl font-black text-pink-400">{todayPerformance}%</div>
        </div>
      </div>

      <div className="glass-card p-8 border-l-4 border-emerald-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><i className="fas fa-cash-register text-[220px]"></i></div>

        <div className="relative z-10 mb-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
              <i className="fas fa-store text-emerald-400"></i> Session Sales Tracker
            </h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em]">Input revenue & covers per sesi (Lunch & Dinner)</p>
          </div>
          <div className="px-6 py-2 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[10px] font-black uppercase tracking-widest">
            {filters.startDate}
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 relative z-10">
          {/* LUNCH SESSION */}
          <div className="space-y-6">
            <h3 className="text-xs font-black text-blue-400 uppercase tracking-[0.25em] flex items-center gap-3 border-b border-blue-500/20 pb-2">
              <i className="fas fa-sun"></i> LUNCH SESSION (11:00 - 16:00)
            </h3>
            <div className="glass-card bg-slate-900/60 p-8 border-white/5 space-y-6">
              <div className="space-y-5">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest text-center">LUNCH REVENUE</label>
                  <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5 focus-within:ring-2 ring-blue-500 transition-all">
                    <span className="text-slate-700 text-xs font-black">RP.</span>
                    <input type="number" className="flex-1 bg-transparent text-white font-black outline-none text-2xl" placeholder="0" value={data.todayLunchRevenue || ''} onChange={(e) => updateSessionData('lunch', 'Revenue', Number(e.target.value))}/>
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">LUNCH COVERS</label>
                  <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5 focus-within:ring-2 ring-blue-500 transition-all">
                    <i className="fas fa-users text-slate-700 text-sm"></i>
                    <input type="number" className="flex-1 bg-transparent text-white font-black outline-none text-xl" placeholder="0" value={data.todayLunchCovers || ''} onChange={(e) => updateSessionData('lunch', 'Covers', Number(e.target.value))}/>
                  </div>
                </div>
                <div className="pt-4 border-t border-white/5 flex justify-between items-center">
                   <span className="text-[9px] font-black text-slate-500 uppercase">Avg Check Lunch</span>
                   <span className="text-sm font-black text-blue-400 tracking-tighter">Rp {todayLunchAvg.toLocaleString()}</span>
                </div>
              </div>
            </div>
          </div>

          {/* DINNER SESSION */}
          <div className="space-y-6">
            <h3 className="text-xs font-black text-orange-400 uppercase tracking-[0.25em] flex items-center gap-3 border-b border-orange-500/20 pb-2">
              <i className="fas fa-moon"></i> DINNER SESSION (17:00 - 22:00)
            </h3>
            <div className="glass-card bg-slate-900/60 p-8 border-white/5 space-y-6">
              <div className="space-y-5">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest text-center">DINNER REVENUE</label>
                  <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5 focus-within:ring-2 ring-orange-500 transition-all">
                    <span className="text-slate-700 text-xs font-black">RP.</span>
                    <input type="number" className="flex-1 bg-transparent text-white font-black outline-none text-2xl" placeholder="0" value={data.todayDinnerRevenue || ''} onChange={(e) => updateSessionData('dinner', 'Revenue', Number(e.target.value))}/>
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">DINNER COVERS</label>
                  <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5 focus-within:ring-2 ring-orange-500 transition-all">
                    <i className="fas fa-users text-slate-700 text-sm"></i>
                    <input type="number" className="flex-1 bg-transparent text-white font-black outline-none text-xl" placeholder="0" value={data.todayDinnerCovers || ''} onChange={(e) => updateSessionData('dinner', 'Covers', Number(e.target.value))}/>
                  </div>
                </div>
                <div className="pt-4 border-t border-white/5 flex justify-between items-center">
                   <span className="text-[9px] font-black text-slate-500 uppercase">Avg Check Dinner</span>
                   <span className="text-sm font-black text-orange-400 tracking-tighter">Rp {todayDinnerAvg.toLocaleString()}</span>
                </div>
              </div>
            </div>
          </div>

          {/* TOTAL DAILY SUMMARY (AUTO) */}
          <div className="lg:col-span-2">
             <div className="glass-card bg-slate-950 p-10 border-indigo-500/30 border-2 shadow-2xl space-y-8">
                <div className="flex flex-col md:flex-row justify-between items-end gap-6">
                   <div className="space-y-2">
                      <div className="text-[10px] font-black text-indigo-400 uppercase tracking-[0.3em] mb-2">Total Accumulated Sales</div>
                      <div className="text-6xl font-black text-white leading-none tracking-tighter">Rp {data.todayRevenue.toLocaleString()}</div>
                      <div className="text-[9px] font-black text-slate-600 uppercase tracking-widest mt-2 flex items-center gap-2">
                         <i className="fas fa-info-circle"></i> Automatic Sum of Lunch & Dinner sessions
                      </div>
                   </div>
                   <div className="text-right space-y-4 min-w-[200px]">
                      <div className="flex justify-between items-center border-b border-white/5 pb-2">
                         <span className="text-[9px] font-black text-slate-500 uppercase">Total Pax</span>
                         <span className="text-lg font-black text-white">{data.todayCovers}</span>
                      </div>
                      <div className="flex justify-between items-center border-b border-white/5 pb-2">
                         <span className="text-[9px] font-black text-slate-500 uppercase">Overall Avg Check</span>
                         <span className="text-lg font-black text-amber-400">Rp {todayAvgCheck.toLocaleString()}</span>
                      </div>
                   </div>
                </div>

                <button 
                  onClick={handleSubmitData}
                  disabled={isSubmitting}
                  className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.5em] transition-all flex items-center justify-center gap-4 active:scale-95 border border-white/10 ${
                    isSubmitting ? 'bg-slate-800 text-slate-600' : 'bg-gradient-to-r from-emerald-600 to-indigo-600 text-white shadow-2xl hover:shadow-emerald-500/20'
                  }`}
                >
                  {isSubmitting ? <i className="fas fa-sync fa-spin"></i> : <i className="fas fa-check-double"></i>}
                  {isSubmitting ? 'SAVING DATA...' : 'ENTER & SYNC DAILY REVENUE'}
                </button>
             </div>
          </div>
        </div>
      </div>
    </div>
  );
};

