import React, { useRef, useState, useMemo } from 'react';
import { AppState, DailySalesData } from '../types';

interface Props {
  data: AppState;
  filters: { month: string; startDate: string; endDate: string };
}

const MonthlyReportingModule: React.FC<Props> = ({ data, filters }) => {
  const reportRef = useRef<HTMLDivElement>(null);
  const [isProcessingPDF, setIsProcessingPDF] = useState(false);

  const months = ["Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"];
  const currentMonthName = months[parseInt(filters.month)];

  const dailyRecordings = data.sales.dailyRecording || {};

  const sessionStats = useMemo(() => {
    let lunchRev = 0, lunchCov = 0, dinnerRev = 0, dinnerCov = 0;
    Object.values(dailyRecordings).forEach((rec: any) => {
      lunchRev += (rec.lunchRevenue || 0);
      lunchCov += (rec.lunchCovers || 0);
      dinnerRev += (rec.dinnerRevenue || 0);
      dinnerCov += (rec.dinnerCovers || 0);
    });
    return { lunchRev, lunchCov, dinnerRev, dinnerCov };
  }, [dailyRecordings]);

  const mtdRev = sessionStats.lunchRev + sessionStats.dinnerRev;
  const mtdBudget = data.sales.budgetRevenue || 0;
  const mtdAchv = mtdBudget > 0 ? (mtdRev / mtdBudget * 100).toFixed(2) : "0.00";

  const handleDownloadPDF = () => {
    if (!reportRef.current) return;
    setIsProcessingPDF(true);
    // @ts-ignore
    window.html2pdf().from(reportRef.current).set({
      margin: 10,
      filename: `Monthly_Closing_${currentMonthName}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2 },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'portrait' }
    }).save().then(() => setIsProcessingPDF(false));
  };

  return (
    <div className="space-y-8 animate-fade-in pb-20 print:p-0" ref={reportRef}>
      <div className="glass-card p-8 border-l-4 border-emerald-600 bg-[#1e293b]/95 shadow-2xl relative overflow-hidden no-print">
