          <div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none">Monthly Executive Summary</h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-widest">MTD Aggregated Performance Session Close</p>
          </div>
          <button onClick={handleDownloadPDF} disabled={isProcessingPDF} className="px-6 py-4 bg-emerald-600 hover:bg-emerald-500 text-white rounded-2xl text-[10px] font-black uppercase transition-all shadow-xl">
             <i className="fas fa-file-pdf mr-2"></i> Export Monthly PDF
          </button>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        <div className="lg:col-span-2 space-y-8">
          {/* MTD SESSION ANALYSIS */}
          <section className="glass-card p-8 bg-slate-900/60 border-t-2 border-emerald-500 shadow-2xl">
             <h3 className="text-xs font-black uppercase text-emerald-400 mb-8 flex items-center gap-3">
               <i className="fas fa-chart-pie"></i> Rekap Performa Sesi MTD ({currentMonthName})
             </h3>
             <div className="grid grid-cols-1 md:grid-cols-2 gap-8 mb-8">
                <div className="p-6 bg-slate-950/60 rounded-3xl border border-blue-500/10">
                   <div className="text-[9px] font-black text-blue-400 uppercase tracking-widest mb-3">Total MTD Lunch</div>
                   <div className="text-2xl font-black text-white mb-2">Rp {sessionStats.lunchRev.toLocaleString()}</div>
                   <div className="flex justify-between items-center text-[10px] font-bold text-slate-500">
                      <span>{sessionStats.lunchCov} Pax</span>
                      <span>Avg: Rp {sessionStats.lunchCov > 0 ? Math.floor(sessionStats.lunchRev / sessionStats.lunchCov).toLocaleString() : 0}</span>
                   </div>
                   <div className="mt-4 h-1.5 w-full bg-slate-900 rounded-full overflow-hidden">
                      <div className="h-full bg-blue-500" style={{ width: `${(sessionStats.lunchRev / mtdRev * 100) || 0}%` }}></div>
                   </div>
                </div>
                <div className="p-6 bg-slate-950/60 rounded-3xl border border-orange-500/10">
                   <div className="text-[9px] font-black text-orange-400 uppercase tracking-widest mb-3">Total MTD Dinner</div>
                   <div className="text-2xl font-black text-white mb-2">Rp {sessionStats.dinnerRev.toLocaleString()}</div>
                   <div className="flex justify-between items-center text-[10px] font-bold text-slate-500">
                      <span>{sessionStats.dinnerCov} Pax</span>
                      <span>Avg: Rp {sessionStats.dinnerCov > 0 ? Math.floor(sessionStats.dinnerRev / sessionStats.dinnerCov).toLocaleString() : 0}</span>
                   </div>
                   <div className="mt-4 h-1.5 w-full bg-slate-900 rounded-full overflow-hidden">
                      <div className="h-full bg-orange-500" style={{ width: `${(sessionStats.dinnerRev / mtdRev * 100) || 0}%` }}></div>
                   </div>
                </div>
             </div>

             <div className="pt-8 border-t border-white/5">
                <div className="flex justify-between items-end">
                   <div>
                      <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-1">Total MTD Combined Revenue</div>
                      <div className="text-4xl font-black text-emerald-400">Rp {mtdRev.toLocaleString()}</div>
                   </div>
                   <div className="text-right">
                      <div className="text-[10px] font-black text-slate-500 uppercase mb-1">MTD Performance</div>
                      <div className="text-3xl font-black text-white">{mtdAchv}%</div>
                   </div>
                </div>
             </div>
          </section>
        </div>

        <div className="space-y-8">
           <div className="glass-card p-8 bg-slate-900 border-emerald-500/20 shadow-xl">
