import React, { useState, useEffect, useMemo } from 'react';
import { SalesData, DailySalesData } from '../types';

interface Props {
  data: SalesData;
  dailyTargets: Record<string, number>;
  filters: { month: string; startDate: string; endDate: string };
  onUpdate: (v: SalesData) => void;
}

const SalesModule: React.FC<Props> = ({ data, dailyTargets, filters, onUpdate }) => {
  const [isSubmitting, setIsSubmitting] = useState(false);

  // localBatchInput: Digunakan untuk input baru (batch hari ini)
  const [localBatch, setLocalBatch] = useState({
    lunchRevenue: 0,
    lunchCovers: 0,
    dinnerRevenue: 0,
    dinnerCovers: 0
  });

  // Sync Daily Target
  useEffect(() => {
    const autoTarget = dailyTargets[filters.startDate] || 0;
    if (autoTarget !== data.dailyTarget) {
      onUpdate({ ...data, dailyTarget: autoTarget });
    }
  }, [filters.startDate, dailyTargets, data.dailyTarget, onUpdate]);

  // Ambil data yang sudah ada di database untuk ditampilkan sebagai preview
  const storedDailyRecord = useMemo(() => {
    return data.dailyRecording?.[filters.startDate] || { 
      revenue: 0, covers: 0, lunchRevenue: 0, lunchCovers: 0, dinnerRevenue: 0, dinnerCovers: 0 
    };
  }, [data.dailyRecording, filters.startDate]);

  const handleInputChange = (field: keyof typeof localBatch, value: string) => {
    const num = Number(value) || 0;
    setLocalBatch(prev => ({ ...prev, [field]: num }));
  };

  const handleSyncData = () => {
    if (isSubmitting) return;

    // Cek apakah ada data baru yang diinput
    const hasNewData = Object.values(localBatch).some(v => v > 0);
    if (!hasNewData) return alert("Silakan masukkan data baru di kolom input.");

    setIsSubmitting(true);

    // LOGIKA KUMULATIF: Tambahkan input batch ke data yang sudah ada di database
    const currentStored = storedDailyRecord;

    const updatedLunchRev = (currentStored.lunchRevenue || 0) + localBatch.lunchRevenue;
    const updatedLunchCov = (currentStored.lunchCovers || 0) + localBatch.lunchCovers;
    const updatedDinnerRev = (currentStored.dinnerRevenue || 0) + localBatch.dinnerRevenue;
    const updatedDinnerCov = (currentStored.dinnerCovers || 0) + localBatch.dinnerCovers;

    const totalRev = updatedLunchRev + updatedDinnerRev;
    const totalCov = updatedLunchCov + updatedDinnerCov;

    const updatedRecord: DailySalesData = {
      revenue: totalRev,
      covers: totalCov,
      lunchRevenue: updatedLunchRev,
      lunchCovers: updatedLunchCov,
      dinnerRevenue: updatedDinnerRev,
      dinnerCovers: updatedDinnerCov
    };

    const newDailyRecording = {
      ...(data.dailyRecording || {}),
      [filters.startDate]: updatedRecord
    };

    // Update MTD Summary
    const newTotalMTDRevenue = Object.values(newDailyRecording).reduce((acc: number, curr: DailySalesData) => acc + (Number(curr.revenue) || 0), 0);
    const newTotalMTDCovers = Object.values(newDailyRecording).reduce((acc: number, curr: DailySalesData) => acc + (Number(curr.covers) || 0), 0);

    // Sync ke state global
    onUpdate({
      ...data,
      dailyRecording: newDailyRecording,
      revenue: newTotalMTDRevenue,
      covers: newTotalMTDCovers,
      todayRevenue: totalRev,
      todayCovers: totalCov,
      todayLunchRevenue: updatedLunchRev,
      todayLunchCovers: updatedLunchCov,
      todayDinnerRevenue: updatedDinnerRev,
      todayDinnerCovers: updatedDinnerCov
    });

    // AUTO REFRESH: Reset input batch ke 0
    setTimeout(() => {
      setIsSubmitting(false);
      setLocalBatch({ lunchRevenue: 0, lunchCovers: 0, dinnerRevenue: 0, dinnerCovers: 0 });
    }, 600);
  };

  const todayAvgCheck = storedDailyRecord.covers > 0 ? Math.floor(storedDailyRecord.revenue / storedDailyRecord.covers) : 0;
  const todayPerformance = data.dailyTarget > 0 ? ((storedDailyRecord.revenue / data.dailyTarget) * 100).toFixed(2) : "0.00";

  return (
    <div className="space-y-8 animate-fade-in no-blur">
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-5 gap-4 no-print">
        <div className="glass-card p-5 border-l-4 border-slate-500 bg-slate-900/40">
           <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Daily Target Revenue</div>
           <div className="text-xl font-black text-white">Rp {data.dailyTarget.toLocaleString()}</div>
        </div>
        <div className="glass-card p-5 border-l-4 border-emerald-500 bg-slate-900/40">
           <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Cumulative Actual Sales</div>
           <div className={`text-xl font-black ${Number(todayPerformance) >= 100 ? 'text-emerald-400' : 'text-white'}`}>Rp {storedDailyRecord.revenue.toLocaleString()}</div>
        </div>
        <div className="glass-card p-5 border-l-4 border-indigo-500 bg-slate-900/40">
           <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Total Pax</div>
           <div className="text-xl font-black text-slate-300">{storedDailyRecord.covers} Pax</div>
        </div>
        <div className="glass-card p-5 border-l-4 border-amber-500 bg-slate-900/40">
           <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Avg Check</div>
           <div className="text-xl font-black text-amber-400">Rp {todayAvgCheck.toLocaleString()}</div>
        </div>
        <div className="glass-card p-5 border-l-4 border-pink-500 bg-slate-900/40">
           <div className="text-[9px] font-black text-slate-500 uppercase tracking-widest mb-1">Achv Rate (%)</div>
           <div className={`text-xl font-black ${Number(todayPerformance) >= 100 ? 'text-emerald-400' : 'text-pink-400'}`}>{todayPerformance}%</div>
        </div>
      </div>

      <div className="glass-card p-8 border-l-4 border-indigo-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><i className="fas fa-plus-circle text-[220px]"></i></div>

        <div className="relative z-10 mb-10 flex flex-col md:flex-row justify-between items-start md:items-center gap-6">
          <div>
            <h2 className="text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-5">
              <i className="fas fa-keyboard text-indigo-400"></i> Batch Revenue Entry
            </h2>
            <p className="text-slate-500 font-black uppercase text-[10px] mt-2 tracking-[0.2em]">Input data baru, maka sistem akan menjumlahkan secara kumulatif</p>
          </div>
          <div className="flex flex-col items-end gap-1">
             <div className="px-6 py-2 rounded-2xl bg-indigo-500/10 border border-indigo-500/20 text-indigo-400 text-[10px] font-black uppercase tracking-widest">
               Date: {filters.startDate}
             </div>
          </div>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-10 relative z-10">
          {/* INPUT BATCH LUNCH */}
          <div className="space-y-6">
            <h3 className="text-xs font-black text-blue-400 uppercase tracking-[0.25em] flex items-center gap-3 border-b border-blue-500/20 pb-2">
              <i className="fas fa-sun"></i> BATCH LUNCH (Entry Baru)
            </h3>
            <div className="glass-card bg-slate-900/60 p-8 border-white/5 space-y-6">
              <div className="space-y-5">
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">LUNCH REVENUE (+)</label>
                  <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5 focus-within:ring-2 ring-blue-500 transition-all">
                    <span className="text-slate-700 text-xs font-black">RP.</span>
                    <input type="number" className="flex-1 bg-transparent text-white font-black outline-none text-2xl" placeholder="0" value={localBatch.lunchRevenue || ''} onChange={(e) => handleInputChange('lunchRevenue', e.target.value)}/>
                  </div>
                </div>
                <div className="space-y-2">
                  <label className="text-[9px] font-black text-slate-500 uppercase tracking-widest">LUNCH COVERS (+)</label>
                  <div className="flex items-center gap-3 bg-slate-950 p-4 rounded-xl border border-white/5 focus-within:ring-2 ring-blue-500 transition-all">
                    <i className="fas fa-users text-slate-700 text-sm"></i>
