import React, { useState, useEffect, useMemo } from 'react';
import { SalesData, DailySalesData } from '../types';

interface Props {
  data: SalesData;
  dailyTargets: Record<string, number>;
  filters: { month: string; startDate: string; endDate: string };
  onUpdate: (v: SalesData) => void;
}

const SalesModule: React.FC<Props> = ({ data, dailyTargets, filters, onUpdate }) => {
  const [isSubmitting, setIsSubmitting] = useState(false);

  const [localBatch, setLocalBatch] = useState({
    lunchRevenue: 0,
    lunchCovers: 0,
    dinnerRevenue: 0,
    dinnerCovers: 0
  });

  useEffect(() => {
    const autoTarget = dailyTargets[filters.startDate] || 0;
    if (autoTarget !== data.dailyTarget) {
      onUpdate({ ...data, dailyTarget: autoTarget });
    }
  }, [filters.startDate, dailyTargets, data.dailyTarget, onUpdate]);

  const storedDailyRecord = useMemo(() => {
    return data.dailyRecording?.[filters.startDate] || { 
      revenue: 0, covers: 0, lunchRevenue: 0, lunchCovers: 0, dinnerRevenue: 0, dinnerCovers: 0 
    };
  }, [data.dailyRecording, filters.startDate]);

  const handleInputChange = (field: keyof typeof localBatch, value: string) => {
    const num = Number(value) || 0;
    setLocalBatch(prev => ({ ...prev, [field]: num }));
  };

  const handleSyncData = () => {
    if (isSubmitting) return;
    const hasNewData = Object.values(localBatch).some(v => v > 0);
    if (!hasNewData) return alert("Masukkan data baru.");
    setIsSubmitting(true);

    const currentStored = storedDailyRecord;
    const updatedLunchRev = (currentStored.lunchRevenue || 0) + localBatch.lunchRevenue;
    const updatedLunchCov = (currentStored.lunchCovers || 0) + localBatch.lunchCovers;
    const updatedDinnerRev = (currentStored.dinnerRevenue || 0) + localBatch.dinnerRev || 0;
    const updatedDinnerCov = (currentStored.dinnerCovers || 0) + localBatch.dinnerCovers;

    const totalRev = updatedLunchRev + updatedLunchRev;
    const totalCov = updatedLunchCov + updatedDinnerCov;

    const updatedRecord: DailySalesData = {
      revenue: totalRev,
      covers: totalCov,
      lunchRevenue: updatedLunchRev,
      lunchCovers: updatedLunchCov,
      dinnerRevenue: updatedDinnerRev,
      dinnerCovers: updatedDinnerCov
    };

    const newDailyRecording = {
      ...(data.dailyRecording || {}),
      [filters.startDate]: updatedRecord
    };

    const newTotalMTDRevenue = Object.values(newDailyRecording).reduce((acc: number, curr: DailySalesData) => acc + (Number(curr.revenue) || 0), 0);
    const newTotalMTDCovers = Object.values(newDailyRecording).reduce((acc: number, curr: DailySalesData) => acc + (Number(curr.covers) || 0), 0);

    onUpdate({
      ...data,
      dailyRecording: newDailyRecording,
      revenue: newTotalMTDRevenue,
      covers: newTotalMTDCovers,
      todayRevenue: totalRev,
      todayCovers: totalCov,
      todayLunchRevenue: updatedLunchRev,
      todayLunchCovers: updatedLunchCov,
      todayDinnerRevenue: updatedDinnerRev,
      todayDinnerCovers: updatedDinnerCov
    });

    setTimeout(() => {
      setIsSubmitting(false);
      setLocalBatch({ lunchRevenue: 0, lunchCovers: 0, dinnerRevenue: 0, dinnerCovers: 0 });
    }, 600);
  };

  const todayAvgCheck = storedDailyRecord.covers > 0 ? Math.floor(storedDailyRecord.revenue / storedDailyRecord.covers) : 0;
  const todayPerformance = data.dailyTarget > 0 ? ((storedDailyRecord.revenue / data.dailyTarget) * 100).toFixed(2) : "0.00";

  return (
    <div className="space-y-6 animate-fade-in no-blur pb-20 px-1">
      {/* Top Metrics: Slideable on Mobile */}
      <div className="flex gap-3 overflow-x-auto no-scrollbar pb-2 no-print">
        <div className="glass-card p-4 border-l-4 border-slate-500 bg-slate-900/40 shrink-0 min-w-[150px]">
           <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Target</div>
           <div className="text-sm font-black text-white">Rp {data.dailyTarget.toLocaleString()}</div>
        </div>
        <div className="glass-card p-4 border-l-4 border-emerald-500 bg-slate-900/40 shrink-0 min-w-[150px]">
           <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Actual</div>
           <div className={`text-sm font-black text-emerald-400`}>Rp {storedDailyRecord.revenue.toLocaleString()}</div>
        </div>
        <div className="glass-card p-4 border-l-4 border-indigo-500 bg-slate-900/40 shrink-0 min-w-[120px]">
           <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Pax</div>
           <div className="text-sm font-black text-slate-300">{storedDailyRecord.covers} Pax</div>
        </div>
        <div className="glass-card p-4 border-l-4 border-amber-500 bg-slate-900/40 shrink-0 min-w-[120px]">
           <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest mb-1">Avg Check</div>
           <div className="text-sm font-black text-amber-400">Rp {todayAvgCheck.toLocaleString()}</div>
        </div>
      </div>

      <div className="glass-card p-4 md:p-8 border-l-4 border-indigo-500 shadow-2xl relative overflow-hidden bg-[#1e293b]/95">
        <div className="absolute top-0 right-0 p-8 opacity-5 pointer-events-none"><i className="fas fa-plus-circle text-[150px]"></i></div>

        <div className="relative z-10 mb-6 md:mb-10">
          <h2 className="text-2xl md:text-4xl font-black text-white uppercase tracking-tighter leading-none flex items-center gap-4">
            <i className="fas fa-keyboard text-indigo-400 text-xl md:text-3xl"></i> Batch Revenue Entry
          </h2>
          <p className="text-slate-500 font-black uppercase text-[8px] md:text-[10px] mt-2 tracking-widest italic">Input data baru untuk diakumulasikan hari ini</p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 gap-6 relative z-10">
          {/* LUNCH */}
          <div className="space-y-4">
            <h3 className="text-[10px] font-black text-blue-400 uppercase tracking-widest flex items-center gap-2 border-b border-blue-500/20 pb-2">
              <i className="fas fa-sun"></i> LUNCH SESSION
            </h3>
            <div className="glass-card bg-slate-900/60 p-5 space-y-4">
                <div className="space-y-1">
                  <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest">REVENUE (+)</label>
                  <div className="flex items-center gap-3 bg-slate-950 p-3 rounded-xl border border-white/5 focus-within:ring-1 ring-blue-500">
                    <span className="text-slate-700 text-[10px] font-black">RP.</span>
                    <input type="number" className="flex-1 bg-transparent text-white font-black outline-none text-xl" placeholder="0" value={localBatch.lunchRevenue || ''} onChange={(e) => handleInputChange('lunchRevenue', e.target.value)}/>
                  </div>
                </div>
                <div className="space-y-1">
                  <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest">COVERS (+)</label>
                  <div className="flex items-center gap-3 bg-slate-950 p-3 rounded-xl border border-white/5 focus-within:ring-1 ring-blue-500">
                    <i className="fas fa-users text-slate-700 text-[10px]"></i>
                    <input type="number" className="flex-1 bg-transparent text-white font-black outline-none text-lg" placeholder="0" value={localBatch.lunchCovers || ''} onChange={(e) => handleInputChange('lunchCovers', e.target.value)}/>
                  </div>
                </div>
            </div>
          </div>

          {/* DINNER */}
          <div className="space-y-4">
            <h3 className="text-[10px] font-black text-orange-400 uppercase tracking-widest flex items-center gap-2 border-b border-orange-500/20 pb-2">
              <i className="fas fa-moon"></i> DINNER SESSION
            </h3>
            <div className="glass-card bg-slate-900/60 p-5 space-y-4">
                <div className="space-y-1">
                  <label className="text-[8px] font-black text-slate-500 uppercase tracking-widest">REVENUE (+)</label>
