import React, { useRef, useState, useMemo } from 'react';
import { GSIRow } from '../types';
import { INITIAL_GSI_STRUCTURE } from '../constants';

interface Props {
  dailyGSI: Record<string, GSIRow[]>;
  filters: { month: string };
}

const GSIModule: React.FC<Props> = ({ dailyGSI, filters }) => {
  const reportRef = useRef<HTMLDivElement>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  const months = ["Jan", "Feb", "Mar", "Apr", "Mei", "Jun", "Jul", "Ags", "Sep", "Okt", "Nov", "Des"];
  const currentYear = new Date().getFullYear();
  const currentYearShort = currentYear.toString().slice(-2);
  const currentMonthName = `${months[parseInt(filters.month)]}-${currentYearShort}`;

  // Aggregation Logic (MTD)
  const aggregatedData = useMemo(() => {
    // Start with a clone of the structure
    const results = INITIAL_GSI_STRUCTURE.map(base => ({ ...base, excellent: 0, good: 0, average: 0, poor: 0, abstain: 0 }));
    const monthKey = (parseInt(filters.month) + 1).toString().padStart(2, '0');

    Object.entries(dailyGSI).forEach(([dateStr, rows]) => {
      // Format YYYY-MM-DD
      const dateParts = dateStr.split('-');
      if (dateParts[1] === monthKey && parseInt(dateParts[0]) === currentYear) {
        rows.forEach(row => {
          const target = results.find(r => r.subject === row.subject);
          if (target) {
            target.excellent += (row.excellent || 0);
            target.good += (row.good || 0);
            target.average += (row.average || 0);
            target.poor += (row.poor || 0);
            target.abstain += (row.abstain || 0);
          }
        });
      }
    });
    return results;
  }, [dailyGSI, filters.month]);

  const calculateRowStats = (row: GSIRow) => {
    const totalResponses = row.excellent + row.good + row.average + row.poor + row.abstain;
    const totalExceptAbstain = row.excellent + row.good + row.average + row.poor;
    const totalPoints = (row.excellent * 4) + (row.good * 3) + (row.average * 2) + (row.poor * 1);
    const maxPoints = totalExceptAbstain * 4;
    const mtdPct = maxPoints === 0 ? 0 : (totalPoints / maxPoints) * 100;
    return { totalResponses, mtdPct };
  };

  const totals = aggregatedData.reduce((acc, row) => {
    const stats = calculateRowStats(row);
    acc.responses += stats.totalResponses;
    acc.sumPct += stats.mtdPct;
    return acc;
  }, { responses: 0, sumPct: 0 });

  const finalGSIScore = totals.sumPct / aggregatedData.length;

  const handleDownloadPDF = () => {
    if (!reportRef.current) return;
    setIsProcessing(true);
    // @ts-ignore
    window.html2pdf().from(reportRef.current).set({
      margin: 10,
      filename: `GSI_Report_${currentMonthName}.pdf`,
      image: { type: 'jpeg', quality: 0.98 },
      html2canvas: { scale: 2, useCORS: true },
      jsPDF: { unit: 'mm', format: 'a4', orientation: 'landscape' }
    }).save().then(() => setIsProcessing(false));
  };

  const handleWhatsAppShare = () => {
    handleDownloadPDF();
    const message = `*GUEST SATISFACTION INDEX (GSI) - SH THE BARN*\n` +
      `------------------------------------------\n` +
      `📅 *Periode:* ${currentMonthName}\n` +
      `📊 *Overall GSI Score:* ${finalGSIScore.toFixed(2)}%\n` +
      `🎯 *Target Score:* 85.00%\n\n` +
      `_Laporan detail PDF telah diunduh, silakan lampirkan._\n` +
      `_Generated via SH Performance Suite_`;
    window.open(`https://wa.me/?text=${encodeURIComponent(message)}`, '_blank');
  };

  return (
    <div className="space-y-8 animate-fade-in no-blur pb-10">
      <div className="flex flex-col md:flex-row justify-between items-center gap-6 glass-card p-8 border-l-4 border-indigo-500 bg-[#1e293b]/95 shadow-2xl relative overflow-hidden no-print">
         <div className="absolute top-0 right-0 p-12 opacity-5 pointer-events-none"><i className="fas fa-smile-beam text-[180px]"></i></div>
         <div className="relative z-10">
            <h2 className="text-3xl font-black flex items-center gap-4 text-white uppercase tracking-tighter leading-none">
               <i className="fas fa-poll text-indigo-400"></i> GSI Performance Index
            </h2>
            <p className="text-slate-500 text-[10px] font-black uppercase tracking-[0.2em] mt-2 italic">Geser tabel ke samping untuk melihat detail nilai</p>
         </div>
         <div className="flex gap-3 no-print">
            <button onClick={handleDownloadPDF} disabled={isProcessing} className="px-6 py-4 bg-slate-800 hover:bg-slate-700 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all border border-white/5 active:scale-95 flex items-center gap-3">
               <i className="fas fa-file-pdf"></i> Export PDF
            </button>
            <button onClick={handleWhatsAppShare} className="px-6 py-4 bg-emerald-700 hover:bg-emerald-600 text-white rounded-2xl text-[10px] font-black uppercase tracking-widest transition-all shadow-2xl active:scale-95 flex items-center gap-3">
               <i className="fab fa-whatsapp"></i> WhatsApp
            </button>
         </div>
      </div>

      <div ref={reportRef} className="glass-card border border-white/10 shadow-2xl bg-slate-900/40 p-0 overflow-hidden">
        <div className="bg-slate-950/80 p-8 border-b border-white/5">
           <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <div className="space-y-2">
                 <div className="flex items-center gap-4"><span className="text-[10px] font-black text-slate-500 uppercase w-32">Month</span><span className="text-sm font-black text-indigo-400 uppercase tracking-widest">{currentMonthName}</span></div>
                 <div className="flex items-center gap-4"><span className="text-[10px] font-black text-slate-500 uppercase w-32">Outlet</span><span className="text-sm font-black text-white uppercase tracking-widest">SH THE BARN</span></div>
                 <div className="flex items-center gap-4"><span className="text-[10px] font-black text-slate-500 uppercase w-32">No. of Responses</span><span className="text-sm font-black text-white">{totals.responses || '-'}</span></div>
              </div>
              <div className="flex flex-col justify-center items-end text-center md:text-right">
                  <div className="text-[10px] font-black text-slate-500 uppercase mb-2">Overall GSI Performance</div>
                  <div className={`text-5xl md:text-6xl font-black ${finalGSIScore >= 85 ? 'text-emerald-400' : 'text-red-400'} drop-shadow-[0_0_15px_rgba(0,0,0,0.5)]`}>
                    {finalGSIScore === 0 ? '0.00%' : `${finalGSIScore.toFixed(2)}%`}
                  </div>
              </div>
           </div>
        </div>

        <div className="table-responsive custom-scrollbar">
          <table className="w-full text-left border-collapse min-w-[800px]">
