import { OT_RATE } from '../constants';

interface StaffRowProps {
  staff: Staff;
  entry: OvertimeEntry;
  onEntryChange: (staffId: string, field: keyof OvertimeEntry, val: number) => void;
}

const StaffRow: React.FC<StaffRowProps> = ({ staff, entry, onEntryChange }) => {
  const [localHours, setLocalHours] = useState<string>(entry.hours?.toString() || '');
  const [localBreak1, setLocalBreak1] = useState<string>(entry.break1?.toString() || '');

  useEffect(() => {
    setLocalHours(entry.hours?.toString() || '');
    setLocalBreak1(entry.break1?.toString() || '');
  }, [entry.hours, entry.break1]);

  const handleBlur = (field: keyof OvertimeEntry, value: string) => {
    const num = Number(value) || 0;
    onEntryChange(staff.id, field, num);
  };

  const net = Math.max(0, (Number(localHours) || 0) - (Number(localBreak1) || 0));
  const totalCost = net * OT_RATE;

  return (
    <tr className="hover:bg-white/5 transition-colors group">
      <td className="p-4">
        <div className="font-black text-white group-hover:text-blue-400 transition-colors uppercase truncate max-w-[120px] md:max-w-none">{staff.name}</div>
        <div className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">{staff.role}</div>
      </td>
      <td className="p-4">
        <div className="flex items-center gap-2 bg-slate-900/50 rounded-xl px-3 py-2 border border-white/5 focus-within:border-blue-500 transition-all min-w-[100px]">
          <input 
            type="number" 
            className="w-full bg-transparent border-none text-center text-sm outline-none font-bold text-white placeholder:text-slate-800"
            value={localHours}
            placeholder="0"
            onChange={(e) => setLocalHours(e.target.value)}
            onBlur={(e) => handleBlur('hours', e.target.value)}
          />
          <span className="text-[10px] text-slate-600 font-bold">h</span>
        </div>
      </td>
      <td className="p-4">
        <div className="flex items-center gap-1 bg-slate-900/50 rounded-xl px-2 py-2 border border-white/5 focus-within:border-pink-500 transition-all min-w-[80px]">
          <input 
            type="number" 
            className="w-full bg-transparent border-none text-center text-sm outline-none font-bold text-white placeholder:text-slate-800"
            value={localBreak1}
            placeholder="0"
            onChange={(e) => setLocalBreak1(e.target.value)}
            onBlur={(e) => handleBlur('break1', e.target.value)}
          />
          <span className="text-[10px] text-slate-600 font-bold">b</span>
        </div>
      </td>
      <td className="p-4 text-center">
        <div className={`text-xs font-black ${net > 0 ? 'text-blue-400' : 'text-slate-600'}`}>{net}h</div>
      </td>
      <td className="p-4 text-right font-black text-white">
        <div className="text-sm whitespace-nowrap">Rp {totalCost.toLocaleString()}</div>
      </td>
    </tr>
  );
};

const OvertimeModule: React.FC<{
  dailyOvertime: Record<string, OvertimeEntry[]>;
  staffList: Staff[];
  filters: { startDate: string };
  onUpdate: (v: Record<string, OvertimeEntry[]>) => void;
}> = ({ dailyOvertime, staffList, filters, onUpdate }) => {
  const [isSaving, setIsSaving] = useState(false);
  const [activeTab, setActiveTab] = useState<'ENTRY' | 'RECAP'>('ENTRY');
  const reportRef = useRef<HTMLDivElement>(null);

  const currentDateEntries = useMemo(() => {
    return dailyOvertime[filters.startDate] || [];
  }, [dailyOvertime, filters.startDate]);

  const handleEntryChange = (staffId: string, field: keyof OvertimeEntry, val: number) => {
    const existingEntries = dailyOvertime[filters.startDate] || [];
    const staffEntry = existingEntries.find(e => e.staffId === staffId);

    let newEntries: OvertimeEntry[];
    if (staffEntry) {
      newEntries = existingEntries.map(e => 
        e.staffId === staffId ? { ...e, [field]: val } : e
      );
    } else {
      newEntries = [...existingEntries, { staffId, hours: 0, break1: 0, [field]: val }];
    }

    onUpdate({
      ...dailyOvertime,
      [filters.startDate]: newEntries
    });
  };

  const calculateTotalOT = (item: OvertimeEntry) => {
    const netHours = Math.max(0, item.hours - item.break1);
    return netHours * OT_RATE;
  };

  const leaders = staffList.filter(s => s.isLeader);
  const crews = staffList.filter(s => !s.isLeader);

  const todayTotalCost = currentDateEntries.reduce((acc, item) => acc + calculateTotalOT(item), 0);
  const todayHoursRaw = currentDateEntries.reduce((acc, item) => acc + (item.hours || 0), 0);
  const todayBreaks = currentDateEntries.reduce((acc, item) => acc + (item.break1 || 0), 0);

  const staffRecap = useMemo(() => {
    const aggregation: Record<string, { gross: number, break: number, net: number, cost: number }> = {};
    Object.values(dailyOvertime).forEach(dayEntries => {
      dayEntries.forEach(entry => {
        if (!aggregation[entry.staffId]) {
          aggregation[entry.staffId] = { gross: 0, break: 0, net: 0, cost: 0 };
        }
        const net = Math.max(0, entry.hours - entry.break1);
        aggregation[entry.staffId].gross += entry.hours;
        aggregation[entry.staffId].break += entry.break1;
        aggregation[entry.staffId].net += net;
        aggregation[entry.staffId].cost += net * OT_RATE;
      });
    });
    return staffList.map(s => {
      const stats = aggregation[s.id] || { gross: 0, break: 0, net: 0, cost: 0 };
      return { ...s, ...stats };
    }).filter(s => s.gross > 0).sort((a, b) => b.cost - a.cost);
  }, [dailyOvertime, staffList]);

  const totalMonthlyCost = staffRecap.reduce((acc, s) => acc + s.cost, 0);

  return (
    <div className="space-y-6 animate-fade-in no-blur pb-10">
      <div className="slide-container px-1 no-print">
        <button 
          onClick={() => setActiveTab('ENTRY')}
          className={`px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center gap-3 border shrink-0 ${
            activeTab === 'ENTRY' ? 'bg-indigo-600 text-white border-white/10 shadow-xl' : 'bg-slate-800 text-slate-500 border-white/5 hover:bg-slate-700'
          }`}
        >
          <i className="fas fa-edit"></i> Entry Hari Ini
        </button>
        <button 
          onClick={() => setActiveTab('RECAP')}
          className={`px-6 py-4 rounded-2xl font-black text-[10px] uppercase tracking-widest transition-all flex items-center gap-3 border shrink-0 ${
            activeTab === 'RECAP' ? 'bg-indigo-600 text-white border-white/10 shadow-xl' : 'bg-slate-800 text-slate-500 border-white/5 hover:bg-slate-700'
          }`}
        >
          <i className="fas fa-list-check"></i> Rekapan Per Crew
        </button>
      </div>

      {activeTab === 'ENTRY' ? (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 glass-card p-4 md:p-6 border-l-4 border-blue-500 shadow-xl overflow-hidden relative">
            <div className="absolute top-0 right-0 p-8 opacity-5">
               <i className="fas fa-clock text-9xl"></i>
            </div>
            <div className="flex justify-between items-center mb-6 relative">
              <div>
                <h2 className="text-xl font-black flex items-center gap-3 text-white uppercase tracking-tighter">
                  <i className="fas fa-business-time text-blue-400"></i>
                  Overtime: {filters.startDate}
                </h2>
                <p className="text-[10px] text-slate-500 font-bold uppercase mt-1">Geser tabel untuk input jam</p>
              </div>
            </div>

            <div className="table-responsive custom-scrollbar">
              <table className="w-full text-left border-collapse min-w-[500px]">
                <thead className="bg-slate-800/80 text-slate-500 text-[10px] uppercase font-black tracking-widest">
                  <tr>
                    <th className="p-4">Staff</th>
                    <th className="p-4 text-center">Gross</th>
                    <th className="p-4 text-center">Break</th>
                    <th className="p-4 text-center">Net</th>
                    <th className="p-4 text-right">Amount</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-white/5">
                  <tr className="bg-blue-500/5"><td colSpan={5} className="p-2 px-4 text-[9px] font-black text-blue-400 uppercase tracking-tighter">Leader Section</td></tr>
                  {leaders.map(staff => (
                    <StaffRow 
                      key={staff.id} 
                      staff={staff} 
                      entry={currentDateEntries.find(d => d.staffId === staff.id) || { staffId: staff.id, hours: 0, break1: 0 }} 
                      onEntryChange={handleEntryChange}
                    />
                  ))}
                  <tr className="bg-purple-500/5"><td colSpan={5} className="p-2 px-4 text-[9px] font-black text-purple-400 uppercase tracking-tighter">Crew Section</td></tr>
                  {crews.map(staff => (
                    <StaffRow 
                      key={staff.id} 
                      staff={staff} 
                      entry={currentDateEntries.find(d => d.staffId === staff.id) || { staffId: staff.id, hours: 0, break1: 0 }} 
                      onEntryChange={handleEntryChange}
                    />
                  ))}
                </tbody>
              </table>
            </div>

            <button 
              onClick={() => { setIsSaving(true); setTimeout(()=>setIsSaving(false), 800); }}
              className={`w-full py-5 rounded-2xl font-black text-xs uppercase tracking-[0.3em] shadow-2xl transition-all flex items-center justify-center gap-3 active:scale-95 border border-white/10 ${
                isSaving ? 'bg-slate-800 text-slate-600 cursor-wait' : 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-500/20'
              }`}
            >
              {isSaving ? <i className="fas fa-circle-notch fa-spin"></i> : <i className="fas fa-save"></i>}
              {isSaving ? 'Saving...' : 'Sync Data Harian'}
            </button>
          </div>

          <div className="space-y-6">
             <div className="glass-card p-6 bg-gradient-to-br from-blue-600 to-indigo-800 text-white shadow-2xl border-none">
                <div className="text-[10px] font-black uppercase opacity-60 mb-1 tracking-widest">OT Cost ({filters.startDate})</div>
                <div className="text-4xl font-black mb-4">Rp {todayTotalCost.toLocaleString()}</div>
                <div className="space-y-2 border-t border-white/10 pt-4">
                   <div className="flex justify-between items-center text-xs">
                      <span className="opacity-70 uppercase font-bold text-[9px]">Gross Hours</span>
                      <span className="font-bold">{todayHoursRaw}h</span>
                   </div>
                   <div className="flex justify-between items-center text-xs border-t border-white/5 mt-2 pt-2 font-black">
                      <span className="uppercase text-[9px]">Net Hours</span>
                      <span className="text-blue-200">{todayHoursRaw - todayBreaks}h</span>
                   </div>
                </div>
             </div>
          </div>
        </div>
      ) : (
        <div className="space-y-6 animate-slide-up" ref={reportRef}>
           <div className="glass-card overflow-hidden border border-white/10 shadow-2xl bg-slate-900/40">
              <div className="table-responsive custom-scrollbar">
                <table className="w-full text-left min-w-[600px]">
                  <thead className="bg-slate-950 text-slate-500 text-[10px] font-black uppercase tracking-widest">
                    <tr>
                      <th className="p-6">Staff Details</th>
                      <th className="p-6 text-center">Gross</th>
                      <th className="p-6 text-center">Net</th>
                      <th className="p-6 text-right">Total Payout</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-white/5">
                    {staffRecap.map(staff => (
                      <tr key={staff.id} className="hover:bg-white/5 transition-colors">
                        <td className="p-6">
                          <div className="font-black text-white uppercase tracking-tight text-sm truncate max-w-[150px]">{staff.name}</div>
                          <div className="text-[9px] font-bold text-slate-500 uppercase tracking-widest">{staff.role}</div>
                        </td>
                        <td className="p-6 text-center font-bold text-slate-300">{staff.gross}h</td>
                        <td className="p-6 text-center">
                          <span className="px-3 py-1 rounded-lg bg-blue-500/10 text-blue-400 text-xs font-black border border-blue-500/20">{staff.net}h</span>
                        </td>
                        <td className="p-6 text-right font-black text-emerald-400">Rp {staff.cost.toLocaleString()}</td>
                      </tr>
                    ))}
                  </tbody>
                  <tfoot className="bg-slate-950/80">
                    <tr>
                      <td colSpan={3} className="p-6 font-black text-slate-500 uppercase tracking-widest text-xs">Total Payout</td>
                      <td className="p-6 text-right font-black text-2xl text-emerald-400">Rp {totalMonthlyCost.toLocaleString()}</td>
                    </tr>
                  </tfoot>
                </table>
              </div>
           </div>
        </div>
      )}
    </div>
  );
};

export default OvertimeModule;
